//******************************************************

var DefaultProfilePictureHandler = (function () {

    var _userAvatars = {};
    var _avatars = [];
    var _avatarIterator = 0;

    function _DefaultProfilePictureHandler() {

    };

    _DefaultProfilePictureHandler.prototype.addAvatars = function (avatars) {

        if (Array.isArray(avatars)) {
            _avatars = _avatars.concat(avatars);
        } else {
            _avatars.push(avatars);
        }

        _avatarIterator = Math.floor(Math.random() * _avatars.length);
    };

    _DefaultProfilePictureHandler.prototype.getForUser = function (rank) {
        var rank = rank || 1; //TODO

        // Create an avatar if not defined
        if (typeof _userAvatars[rank] === 'undefined') {
            var numberCanvas = document.createElement('canvas');
            numberCanvas.width = s_default_profile_image.width;
            numberCanvas.height = s_default_profile_image.height;

            var numberContext = numberCanvas.getContext('2d');

            var oldCanvas = tbGraphics.canvas;
            tbGraphics.setCanvas(numberCanvas);

            tbGraphics.drawRectangle(0, 0, numberCanvas.width, numberCanvas.height, '#fff');
            //fill context

            //draw rank
            var font = f_main_bolditalic.clone();

            font.setFill('#424a4c');
            font.setFontSize(48);

            font.drawSimple('' + rank, numberCanvas.width / 2, numberCanvas.height / 2);

            //clip
            numberContext.globalCompositeOperation = 'destination-in';
            s_default_profile_image.drawSimple(0, 0, 0);
            numberContext.globalCompositeOperation = 'source-over';

            tbGraphics.setCanvas(oldCanvas);

            //faking this canvas being a loaded image;
            numberCanvas.complete = true;

            _userAvatars[rank+''] = tbImageFromImage('s_rank_' + rank, numberCanvas, numberCanvas.width, numberCanvas.height, 0, 0);
        }

        return _userAvatars[rank+''];
    };

    return new _DefaultProfilePictureHandler();
})();
