var BoosterSDK = (function () {
    var _pauseAll = function () {
        tbAudio.pause("master");

        tbGame.clearClickEvents();
        tbGame.clearTouchEvents();
        tbGame.clearKeyboardEvents();

        tbGame.pause();
    };

    var _resumeAll = function (keepEvents) {
        tbAudio.resume("master");
        if (!keepEvents) {
            tbGame.clearClickEvents();
            tbGame.clearTouchEvents();
            tbGame.clearKeyboardEvents();
        }
        tbGame.resume();
    };

    var SDK = function () {

    };

    SDK.prototype.init = function (config) {
        this.adChannel = config["adChannel"];

        this.gameCode = config["gameCode"];

        this.gameName = config["gameName"];
        this.gameVersion = config["gameVersion"];
        this.gameCategory = config["gameCategory"];
        this.developerId = config["developerId"];

        this.enableAds = config["enableAds"];
        this.disableEndScreenAds = config["disableEndScreenAds"];
        this.adFreq = config["adFreq"];
        this.firstAd = config["firstAd"];

        this.moreGames = config["moreGames"];
        this.moreGamesURL = config["moreGamesURL"];

        this.gameAnalyticsId = config["gameAnalyticsId"];

        this.tabIcon = config["tabIcon"];

        var interval = setInterval(function () {

            if (this.ready()) {
                this.setupBoosterSdk();
                clearInterval(interval);
            }

        }.bind(this), 100);
    };

    SDK.prototype.ready = function () {
        return window["Booster"]["ready"] && window["Booster"]["Ad"];
    };

    SDK.prototype.setupBoosterSdk = function () {
        new Booster["Init"]({
            "orientation": 'portrait',
            "splash": true,
            "minimalUI": true,
            "rotationOnHide": function () {
                //TODO resume game
            },
            "rotationOnShow": function () {
                //TODO pause game
            }
        });

        adSense = new Booster["Ad"]({
            "type": "adsense",
            "size": "300x250",
            "channelID": this.adChannel
        });

        community = new Booster["Community"]({
            "position": 1,
            "gameCode": this.gameCode,
            "tabIcon": this.tabIcon
        });

        analytics = new Booster["Analytics"]({
            "gameName": this.gameName,
            "gameId": this.gameVersion,
            "gameCategory": this.gameCategory,
            "developer": this.developerId,
            "gameAnalyticsId": this.gameAnalyticsId
        });

        moregames = new Booster["Moregames"]();

        try {
            freemium = new Booster["Freemium"]();
        } catch (e) {}

        var self = this;

        Booster["onSplashFinishedEvent"] = function () {
            //TODO
        };

        Booster["onOpenTab"] = function () {
            _pauseAll();
        };

        Booster["onCloseTab"] = function () {
            _resumeAll();
        };

        //for dev purposes
        window.BoosterSDK = this;

        this.lastInterstitialTime = Date.now() - (this.adFreq - this.firstAd);
    };

    SDK.prototype.showInterstitial = function (callback, failCallback, context) {
        _pauseAll();
        var self = this;

        try {
            adSense["showAdvertising"]({
                "callback": function () {
                    _resumeAll();
                    if (callback) callback.call(context);
                    self.lastInterstitialTime = Date.now();
                }
            });
        } catch (e) {
            _resumeAll();
            if (failCallback) failCallback.call(context, e);
        }
    };

    SDK.prototype.tryInterstitialWithInterval = function (callback, failCallback, context) {
        var difference = Date.now() - this.lastInterstitialTime;
        if (difference < this.adFreq * 1000) {
            if (callback) callback.call(context);
            return;
        }
        this.showInterstitial(callback, failCallback, context);
    };

    SDK.prototype.showRewarded = function (callback, failCallback, context) {
        _pauseAll();
        var self = this;

        try {
            window["Booster"]["RewardedVideo"]["play"](function () {
                _resumeAll();
                if (callback) callback.call(context);

                self.lastInterstitialTime = Date.now(); //not actually an interstitial, but would still feel bad
            }, this);
        } catch (e) {
            _resumeAll();
            if (failCallback) failCallback.call(context, e);
        }
    };

    SDK.prototype.showBanner = function () {
        if (this.banner) return;

        try {
            var booster = window['Booster'];

            if (!booster) return;
            if (!booster['AdBanner']) return;
            this.banner = new booster['AdBanner']({});
            this.banner['show']();
        } catch (e) {
            //TODO
        }
    };

    SDK.prototype.hideBanner = function () {
        if (!this.banner) return;
        this.banner['hide']();
        this.banner = undefined;
    };

    SDK.prototype.postScore = function (score) {
        try {
            _pauseAll();
            community['submitScore']({
                "score": score, // This is an int value
                //"level": level,
                "callback": function () {
                    _resumeAll();
                }
            });
        } catch (e) {
            _resumeAll();
        }
    };

    return new SDK();
})();
