// ***************************************
// GameInitializationController
//
// Initializes the game. Constructs global references to services.
// ***************************************

//Services
var gamesBackendService = null; // Service to connect to the backend
var leaderboardService = null;
var gameAnalyticsService = null; // GameAnalytics module
var migrationService = null;
var saveDataService = null; //Module used to store player save data.
var gameStateDataService = null;
var messagingPlatformService = null //Module to interface with the messaging platform this game is on
var shopService = null //Module to interface messaging IAP and gamesparks

//The goal is that this global reference will be removed and gameFlowController will only be accessed through events.
var gameFlowController = null;
var ABTestInstance = null

// The constructor for the GameInitializationController game token.
var GameInitializationController = function () {
	"use strict";

	// Let the engine handle the initialize call as soon as it's ready for it.
	this.active = true;
	tbGame.addToken(this);
	tbGame.addSpecial("InitializeGame");
};

GameInitializationController.prototype.handleSpecial = function (tag) {
	"use strict";

	if (tag === "InitializeGame") {
		//No need to listen to any more events after initialization.
		this.active = false;
		tbGame.removeToken(this);

		//Initialize the game.
		this._initializeGame();
	}
};

GameInitializationController.prototype._initializeGame = function () {
	"use strict";
	var self = this;

	this._initializeSettings();
//	MessyAnalytics.start();
	Promise.all([
			self._initializeFramework(),
			self._initializeMessengerPlatform()
		])
		.then(function () {
			//Set default Y based on visible height calculated in initializing the framework
			tgfSettings.dialogDefaults.buttonBox.y = tgfGraphics.visibleHeight / 2;

			return self._pickIAPAB();
		})
		.then(function () {
			//self._sendGameVersionToFacebook();
			if (messagingPlatformService.getPlatformInfo().messagingPlatform === "WEB") {
				desktopSettingsOverride();
			}
			return SudokuAnalytics.init(gameVersion);
		})
		.then(function () {
			return Promise.all([
				self._reportEntryDataAnalytics(),
				self._checkRequiredFeatures()
			]);
		})
		.then(function () {
			saveDataService = new LocalStoragePlayerDataService();
			gameStateDataService = new LocalStoragePlayerDataService();
			return Promise.all([
				TimeManager.initialize(tgfSettings.game.shouldSyncDateWithServer),
				saveDataService.initialize()
			]);
		})
		.then(function () {
			self._startPreloadingMonthData();
			return self._retrieveGameData();
		})
		/*.then(function () {
			return self._showGamebotOptIn();
		})*/
		.then(function () {
			return MigrateSaveDataToVersionOne.migrate();
		})
		.then(function () {
			return MigrateHintsToConsumables.migrate();
		})
		/*.then(function () {
			return self._intitializeShop();
		})*/
		.then(function () {
			return Promise.all([
				self._detectLanguage(),
				WhatIsNewController.initialize(),
				//PlayFriendlyController.initialize(),
				RewardController.initialize(),
				ScoreController.initialize(),
				AdManager.initialize(),
				// LeaderboardManager.initialize(),
				gameStateDataService.initialize(),
				Consumables.initialize(),
				ThemeController.initialize(),
				FreePuzzleLogic.initialize(),
				self._createPlayerTbImage(),
				//VipMembership.initialize()
			]);
		})
		.then(function () {
			return ActiveProductController.initialize()
		})
		.then(function () {
			//Analytics
			SudokuAnalytics.reportLoaderDone();
//			MessyAnalytics.loadStop("general");
			self._reportFacebookPixelTracking();

			VipMembership.setProduct(ActiveProductController.getProductById(gameData.vipMembershipData.activeProductId));

			self._setCssRules();

			//Fix issue where clicks would not get propagated when game ran in iOS in an iframe.
			document.addEventListener('touchstart', {});

			GamebotManager.scheduleMessages();

			//Instantiate the GameFlowController
			gameFlowController = new GameFlowController();

			//Call this to add onboarding to the game
			/*if(ABTestInstance.isFeatureSupported(tgfSettings.abtest.features.ONBOARDING)){
				HowToPlayController.initialize();
			}*/

			self._initBoosterSdk();

			//Calling initialize will start the game flow
			gameFlowController.initialize();
		})
		.catch(function (err) {
			console.error("[GameInitializationController] ran into an error: " + JSON.stringify(err), err.stack);
			errorLoggingService.sendError(err);
		});
};


GameInitializationController.prototype._onStartInitialLoading = function () {
	"use strict";
	SudokuAnalytics.startedLoading();
//	MessyAnalytics.loadStart("general");
	// Start the loading of assets
	tgfFunctions.loadStart({
		moments: tgfSettings.flow.loadMoments,
		required: tgfSettings.flow.loadRequired,
		minTime: tgfSettings.flow.loadMinTime,
		maxTime: tgfSettings.flow.loadMaxTime
	});
};

GameInitializationController.prototype._getLoadingProgress = function () {
	"use strict";
	return tgfFunctions.loadPercentage();
};

GameInitializationController.prototype._initializeSettings = function () {
	"use strict";
	tgfSettings.mergeSettings(flowSettings());
	tgfSettings.mergeSettings(overwriteSettings());
	tgfSettings.mergeSettings(themeSettings());
	tgfSettings.mergeSettings(gameSettings());
	tgfSettings.mergeSettings(consumableSettings());
	tgfSettings.mergeSettings(unlockableThemeSettings());
	tgfSettings.mergeSettings(rewardSettings());
	tgfSettings.mergeSettings(fontSettings());

	// Change the document title if it is specified in the game
	if (tgfSettings.game.documentTitle) {
		document.title = tgfSettings.game.documentTitle;
	}
};

// Wrap the onSuccess call in a promise so we can use it in our initialization promise chain.
GameInitializationController.prototype._initializeFramework = function () {
	"use strict";

	return new Promise(function (resolve, reject) {
		tgfFramework.initialize(tgfSettings.framework, resolve);
	});
};

GameInitializationController.prototype._initializeMessengerPlatform = function () {
	"use strict";
	var self = this;

	SudokuAnalytics.reportSDKStartInitializing();

	return new Promise(function (resolve, reject) {
		var mockMessagingPlatformServiceSettings = new MockMessagingPlatformServiceSettings(tgfSettings.game.mockMessagingPlatformSettingsConfig);
		messagingPlatformService = new MockMessagingPlatformService(mockMessagingPlatformServiceSettings);
		self._onStartInitialLoading();

		messagingPlatformService.initialize({
				startInitialLoading: self._onStartInitialLoading.bind(self),
				getLoadingProgress: self._getLoadingProgress.bind(self)
			})
			.then(function () {

				errorLoggingService.setUserInfo(messagingPlatformService.getPlayer().id, messagingPlatformService.getPlayer().name);

				messagingPlatformService.addPauseListener({
					onMessagingPlatformPaused: function () {
//						MessyAnalytics.setPause();
					}
				});

				SudokuAnalytics.reportSDKIsInitialized();

				resolve();
			})
			.catch(reject);
	});
};


GameInitializationController.prototype._pickIAPAB = function () {
	//TODO this whole bit can probably be stripped out of distribution mode?
    return new Promise(function (resolve, reject) {
        var lastVersion = gameVersion;
//        ABTestInstance = new ABTestManager(tgfSettings.abtest, gameVersion, lastVersion);
        resolve();
    });
};

