GameInitializationController.prototype._sendGameVersionToFacebook = function () {
	FBInstant.logEvent("version", 0, {
		"version_number": gameVersion
	});
};

GameInitializationController.prototype._reportEntryDataAnalytics = function () {
	"use strict";
	//This can be done independently, It doesnt have to be part of the chain.
	return messagingPlatformService.getEntryPointData()
		.then(function (entryData) {
			console.log('FC::entryData', entryData);


			SudokuAnalytics.reportEntryData(entryData.data);
//			MessyAnalytics.setEntryPoint(entryData);


			if (entryData && entryData.type) {

				SudokuAnalytics.reportEntryPoint(entryData.type);

				if (entryData.data && entryData.type == GamePayloadType.GAME_SWITCH) {
					var concept = entryData.data.concept || "NO_CONCEPT_PASSED"
					var location = entryData.data.location || "NO_LOCATION_PASSED"
					var originId = entryData.data.originId || "NO_ID_PASSED"
				}
			}

			if (messagingPlatformService.isFeatureSupported(MessagingPlatformFeature.CONTEXT)) {
				SudokuAnalytics.reportContextType();
				//MessyAnalytics.setContextType();
			}
		});
};

GameInitializationController.prototype._checkRequiredFeatures = function () {
	"use strict";
	return new Promise(function (resolve, reject) {

		//Check for required messaging platform features
		if (!messagingPlatformService.isFeatureSupported(MessagingPlatformFeature.PLAYER_PROFILE)) {
			reject("[GameInitializationController] Player info is not supported by this messaging platform. We can not initialize the current gamesBackendService");
			return;
		}

		//Check for required messaging platform features
		if (!messagingPlatformService.isFeatureSupported(MessagingPlatformFeature.CONNECTED_FRIENDS_LIST)) {
			reject("[GameInitializationController] Connected friends list is not supported by this messaging platform. Leaderboards will not work.");
			return;
		}

		resolve();
	});
};


GameInitializationController.prototype._intitializeShop = function () {
	var messagingService = null;
	var gameBackend = null;

	if (tgfSettings.game.useShopMock) {
		messagingService = ShopMock.getMockMessenger(gamesBackendService);
		gameBackend = gamesBackendService;
	} else {
		messagingService = messagingPlatformService;
		gameBackend = gamesBackendService;
	}

	shopService = new ShopServiceFbGs(messagingService, gameBackend, {
		"appId": tgfSettings.appId,
		"initializePollInterval": 100
	});

	return shopService.initialize();
}

GameInitializationController.prototype._retrieveGameData = function () {
	"use strict";
	var self = this;
	return new Promise(function (resolve, reject) {
		saveDataService.getPlayerData([gameData.identifier])
			.then(function (data) {
				if (data && data[gameData.identifier]) {
					gameData = new GameData(gameData.identifier, data[gameData.identifier]);
				} else {
					gameData = new GameData(gameData.identifier, {});
				}
				resolve();
			})
			.catch(reject);
	});
};

GameInitializationController.prototype._startPreloadingMonthData = function () {

	var date = TimeManager.getDate();
	var thisMonthDataId = date.getFullYear() + '_' + date.getMonth();
	date.setMonth(date.getMonth() - 1);
	var previousMonth = date.getFullYear() + '_' + date.getMonth();

	UnlockDataManager.addUnlockCondition(UnlockDayRules.isToday);
	UnlockDataManager.addUnlockCondition(UnlockDayRules.hasData);
	UnlockDataManager.initialize();
	UnlockDataManager.setDataType(MonthlyUnlockData);
	UnlockDataManager.loadMonthData([thisMonthDataId, previousMonth], null);
}

GameInitializationController.prototype._createPlayerTbImage = function () {
	"use strict";
	var imageUrl = messagingPlatformService.getPlayer().photo;

	//Initialize the default profile pictures.
	if (typeof s_leaderboard_avatar01 != 'undefined' && typeof s_leaderboard_avatar02 != 'undefined' && typeof s_leaderboard_avatar03 != 'undefined') {
		DefaultProfilePictureHandler.addAvatars([
			s_leaderboard_avatar01,
			s_leaderboard_avatar02,
			s_leaderboard_avatar03
		]);
	}

	return new Promise(function (resolve, reject) {
		if (!imageUrl) {
			tgfSettings.player.image = DefaultProfilePictureHandler.getForUser(messagingPlatformService.getPlayer().id);
			resolve();
			return;
		}

		var playerImage = new Image();

		playerImage.onerror = function () {
			tgfSettings.player.image = DefaultProfilePictureHandler.getForUser(messagingPlatformService.getPlayer().id);
			resolve();
		};

		playerImage.onload = function () {
			tgfSettings.player.image = tbImageFromImage("playerImage", playerImage, playerImage["width"], playerImage["height"], 0, 0);
			resolve();
		};

		playerImage.crossOrigin = 'anonymous';
		playerImage.src = imageUrl;
	});
}

GameInitializationController.prototype._reportFacebookPixelTracking = function () {
	"use strict";
	if (typeof fbq !== "undefined") {
		//fbq gets defined by the facebook provided pixel tracking code in the index.html
		fbq('init', '1644767318938136');
		fbq('track', 'ViewContent');
	}
};

GameInitializationController.prototype._detectLanguage = function () {

	var language = gameData.language;

	var languages = tgfSettings.languages || ['en-us', 'fr-fr'];

	if (language == "unassigned") {

		// var fbLocale = messagingPlatformService.getPlatformInfo().locale;

		// language = (fbLocale.indexOf('fr') >= 0) ? 'fr-fr' : 'en-us';
		language = languages[0];
	}

	tgfDictionary.addAvailableLanguages(languages, true);
	tgfDictionary.setLanguage(language);
};

GameInitializationController.prototype._setCssRules = function () {
	document.body["style"]["background-position"] = "center top";
	document.body["style"]["background-repeat"] = "no-repeat";
	document.body["style"]["background-attachment"] = "fixed";
	document.body["style"]["background-size"] = "auto 100%";
};

GameInitializationController.prototype._initBoosterSdk = function () {
    var Booster = window.Booster || {};
    BoosterSDK.init(window["publisher"]);

    //show a banner ad as soon as we can
    var bannerInterval = setInterval(function () {

        if (BoosterSDK.ready()) {
            BoosterSDK.showBanner();
            clearInterval(bannerInterval);
        }

    }.bind(this), 500);
};

