GameFlowController.prototype._resumePreviousGame = function (previousGameState) {

	var self = this;

	var date = new Date(previousGameState.date);
	var monthDataId = date.getFullYear() + "_" + date.getMonth();

	UnlockDataManager.getMonthDataById(monthDataId)
		.then(function () {

			self._startLevel(date, previousGameState.difficulty, previousGameState);

			//If we have an unlocked free day. Show the ingame popup notifying the user of the day that was unlocked.
			if (self._unlockedFreeDayGift) {
				var unlockedDate = self._unlockedFreeDayGift.giftInfo.date;

				var popup = new tgfDialogs.InGameDayUnlockedPopup({
					unlockState: true,
					popUpBackgroundImage: s_popup_default_bg,
					day: DateUtil.getDayLabel(unlockedDate.getDay()),
					dayNumber: unlockedDate.getDate(),
					month: DateUtil.getMonthLabel(unlockedDate.getMonth())
				});

				popup.onCloseWindow = function () {
					popup.hide();
				};

				popup.show();
			}
		})
		.catch(function (err) {
			errorLoggingService.sendError(err);
			console.log("[GameFlowController] ran into an error" + err + "\n" + err.stack);
		});
};

GameFlowController.prototype._checkForRedeemableGifts = function (entryData) {
	var gift = undefined;
	var self = this;

	if (entryData && entryData.data && entryData.data.gift && entryData.data.redeemCode) {
		// This function returns an object like this:
		/*{
			giftType: GiftType.FreeGame,
			giftInfo: {
				Gift specific info
			}
			isRedeemed:true/false
		}*/
		gift = GiftManager.redeemGift(entryData.data.redeemCode, entryData.data.gift);
	}

	if (gift && gift.isRedeemed) {
		switch (parseInt(gift.giftType)) {
			case GiftType.FreeGame:

				//Setting this will show the unlock animation in-game or on the calendar screen depending if there is a game in progress.
				self._unlockedFreeDayGift = gift;
				self._calendar.setAutoOpenDate(self._unlockedFreeDayGift.giftInfo.date);
				break;
			case GiftType.FreeHints:

				//Just check redeemedHints. Apply them on gamestart. Show animation. Should not matter if game is in progress.
				console.log("pending redeemed hints", gameData.queuedHints);
				break;
			case GiftType.ScoreMultiplier:

				//Just set redeemedScoreMultiplier. Apply them on gamestart. Show animation. Should not matter if game is in progress.
				console.log("Redeemed score multiplier", gameData.scoreMultiplier);
				break;
		}
	}
}

GameFlowController.prototype._shouldShowTutorialOnStartup = function () {

	if (gameData.showTutorialAtStartup === true) {
		return true;
	} else if (
		gameData.showTutorialAtStartup === null && //showTutorialAtStartup was never set
		(!ScoreController.hasPoints())
	) {
		gameData.showTutorialAtStartup = true;
		saveDataService.savePlayerData(gameData.getSaveableGameData());
		return true;
	} else { //Player has played sudoku before but has not played the version where the tutorial was implemented yet.
		//Set the variable to false;
		gameData.showTutorialAtStartup = false;
		saveDataService.savePlayerData(gameData.getSaveableGameData());
		return false;
	}
};

GameFlowController.prototype._saveScore = function () {
	this._savePlayerIdentityData();

	LeaderboardManager.sendScore(ScoreController.getCurrentMonthScore().total);
};

GameFlowController.prototype._savePlayerIdentityData = function () {
	LeaderboardManager.updateIdentity();
};

GameFlowController.prototype._exitLevel = function (dontShowInterstitial) {
	"use strict";

	//End current level if one is active
	if (this._currentLevel) {
		EventSystem.Global.dispatchEvent(System_Event.LEVEL_QUIT, this._currentLevel.levelResultPayload.data);
		tbGame.removeToken(this._currentLevel);
		tbGame.removeTokens("game");
		this._currentLevel.handleRemove();
		this._currentLevel = undefined;

		this._inGameUI.hide();
	}

	//Set the score multiplier to 1 again;
	gameData.scoreMultiplier = 1;

	this._showMainMenu();

	saveDataService.savePlayerData(gameData.getSaveableGameData());
};

GameFlowController.prototype._showMainMenu = function () {
	"use strict";
	EventSystem.Global.dispatchEvent(System_Event.SHOW_MAIN_MENU);
};

GameFlowController.prototype._showDifficultySelectDialog = function (date, showUnlockAnimationAtSpawn, tryUnlockImmediately) {

	this._difficultySelectDialog = new tgfDialogs.DifficultySelectDialog(
		date,
		showUnlockAnimationAtSpawn,
		tryUnlockImmediately
	);

	this._difficultySelectDialog.show();
};

GameFlowController.prototype._onCalendarDayClicked = function (date) {

	if (this._unlockedFreeDayGift) {
		this._unlockedFreeDayGift = false;
		this._showDifficultySelectDialog(date, true);
	} else {
		this._showDifficultySelectDialog(date, false);
	}

	//Report the click to analytics.
	var now = TimeManager.getDate();
	var timeDiff = date.getTime() - now.getTime();
	var diffDays = Math.ceil(timeDiff / (1000 * 3600 * 24));

	var dayID = date.getFullYear() + "_" + date.getMonth() + "_" + date.getDate();
	SudokuAnalytics.reportClickedCalendarDay(diffDays);
//	MessyAnalytics.DayClicked(dayID);
}

GameFlowController.prototype._closeDifficultySelect = function () {
	if (this._difficultySelectDialog) {
		this._difficultySelectDialog.hide();
		this._difficultySelectDialog = null;
	} else {
		console.error("[GameFlowController] Trying to clean up a calendar select that we don't have a reference to. Only one should be active at a time.")
	}
}

GameFlowController.prototype._showUnlockErrorDialog = function (unlockMethod) {

	var errorDialogPayload = {};
	if (unlockMethod === Unlock_Method.SOCIAL) {
		errorDialogPayload = {
			overrideText: tgfDictionary.getText("inviteError")
		};
	}

	//MessyAnalytics.popup("error_unlock", true);
	errorDialogPayload.onClose = function () {
//		MessyAnalytics.popup("error_unlock", false);
	}

	this._errorDialog = new tgfDialogs.ErrorDialog(errorDialogPayload);
	this._errorDialog.show();

	SudokuAnalytics.reportShowUnlockPopupError();
}

GameFlowController.prototype._errorDialogConfirmClicked = function () {
	this._errorDialog.hide();
	this._errorDialog = null;
}

GameFlowController.prototype._startLevel = function (date, difficulty, previousGameState) {
	'use strict';

	if (FreePuzzleLogic.hasFreePuzzleAvailable()) {
		FreePuzzleLogic.freePuzzleClaimed();
	}

	if (this._tutorialController && this._tutorialController.shouldReportFirstGame()) {
		this._tutorialController.setHasReportedFirstGameStart(true);
		SudokuAnalytics.reportPostTutorialFirstPlay(difficulty);
	}

	var analyticsString = date.getFullYear() + "_" + date.getMonth() + "_" + date.getDate();
	SudokuAnalytics.reportGameStarted(difficulty, analyticsString);
//	MessyAnalytics.levelStart(difficulty, analyticsString);

	if (this._difficultySelectDialog) {
		this._closeDifficultySelect();
	}

	// new FreezeTimeSystem([System_Event.LEVEL_END, System_Event.LEVEL_QUIT]);
	// new MagicEyeSystem([System_Event.LEVEL_END, System_Event.LEVEL_QUIT]);
	// new MultiHintSystem([System_Event.LEVEL_END, System_Event.LEVEL_QUIT]);
	new HintSystem([System_Event.LEVEL_END, System_Event.LEVEL_QUIT]);
	// new ReplenishLivesSystem([System_Event.LEVEL_END, System_Event.LEVEL_QUIT]);

	new ConsumableUsageSystem([System_Event.LEVEL_END, System_Event.LEVEL_QUIT]);

	// -----

	this._inGameUI = new InGameUIController();

	//Top UI
	//Order of adding is important. First element will be leftmost, last element will be rightmost.
	this._inGameUI.topUI.addBackButton();
	this._inGameUI.topUI.addScoreRenderer(previousGameState ? previousGameState.score : 0);
	this._inGameUI.topUI.addTimeRenderer();
	// this._inGameUI.topUI.addDateRenderer(date);
	// this._inGameUI.topUI.addDifficultyRenderer(difficulty);

	//Bottom UI
	this._consumablesBar = this._inGameUI.bottomUI.addConsumablesBar();

	this._consumablesBar.configureConsumables([
		Consumables.ENUM.HINT,
		// Consumables.ENUM.MAGIC_LAMP,
		// Consumables.ENUM.MAGIC_EYE,
		// Consumables.ENUM.FREEZE
	]);
	this._consumablesBar.configureDeactivationEvents([System_Event.LEVEL_QUIT]);

	var getMoreHintsButton = this._inGameUI.bottomUI.addGetMoreHints();
	new GetMoreHintButtonVisualStateSystem(
		getMoreHintsButton,
		[System_Event.LEVEL_END, System_Event.LEVEL_QUIT]
	);

	this._inGameUI.bottomUI.addSettingsButton();

	// this._inGameUI.addInGameConsumableDialog();

	this._inGameUI.configureDeactivationEvents(
		[System_Event.LEVEL_LOST, System_Event.LEVEL_QUIT, System_Event.LEVEL_SOLVED]
	);

    var self = this;
    var beginLevel = function () {
        self._currentLevel = new LevelController();
        self._currentLevel.configureEvents(null, System_Event.LEVEL_SOLVED);
        self._currentLevel.startlevel(difficulty, date, previousGameState, null);
        self._inGameUI.show();
    };
    BoosterSDK.tryInterstitialWithInterval(beginLevel, beginLevel, this);
}

GameFlowController.prototype._nextPuzzleButtonClicked = function () {

	var currentLevelDate = PlayFriendlyController.isFriendlyMatchActive() ?
		PlayFriendlyController.getCurrentMatchData().getDate() :
		this._currentLevel.getLevelDate();

	var nextDay = new Date(currentLevelDate.getTime());
	nextDay.setDate(currentLevelDate.getDate() + 1);

	this._exitLevel(true);

	// Show difficulty select
	this._showDifficultySelectDialog(nextDay, false, true);
};

GameFlowController.prototype._challengeFriend = function (leaderboardEntryClicked) {

	var self = this;
	var shareImage = null;

	var showChallengeSentDialog = function () {

		leaderboardEntryClicked.hideChallengeButton();

		self.challengeSentDialog = new tgfDialogs.ChallengeSentDialog({
			depth: -1000,
			shareImage: shareImage,
		});
		self.challengeSentDialog.show();
		self.challengeSentDialog.onHide = function () {
			self.challengeSentDialog = null;
		};
	};

	if (messagingPlatformService.isFeatureSupported(MessagingPlatformFeature.SWITCH_CONTEXT)) {

		messagingPlatformService.createContext([leaderboardEntryClicked.getUserId()])
			.then(function () {

				SudokuAnalytics.reportContextSwitch();
//				MessyAnalytics.contextSwitch();

				var template = "leaderboard_invite";
				var strategy = GameUpdateStrategy.IMMEDIATE;
				var payload = {
					analytics: ["custom_update", "leaderboard_invite"]
				}

				InviteService.sendUpdate(template, strategy, payload)
					.then(function () {
						showChallengeSentDialog();
						console.log("[LeaderboardEntryComponent] Game update sent");

						SudokuAnalytics.reportLeaderboardUpdateInvite();
					//	MessyAnalytics.customUpdate("invite");
					})
					.catch(function (err) {
						errorLoggingService.sendError(err);
						console.log("[LeaderboardEntryComponent] There was a problem sending the game update. Error: " + err + "\n" + err.stack);
					});
			})
			.catch(function () {
				console.log("[LeaderboardEntryComponent] Context switch failed.");
			});
	}
}

GameFlowController.prototype._muteButtonClicked = function () {

	if (!gameData.isAudioMuted) {
		tgfAudio.muteEffects();
		tgfAudio.muteMusic();
		gameData.isAudioMuted = true;
		SudokuAnalytics.reportClickedMute(true);
//		MessyAnalytics.muteClick(true);
	} else {
		tgfAudio.unmuteEffects();
		tgfAudio.unmuteMusic();
		gameData.isAudioMuted = false;
		tgfAudio.play(a_select);
		SudokuAnalytics.reportClickedMute(false);
	//	MessyAnalytics.muteClick(false);
	}

	saveDataService.savePlayerData(gameData.getSaveableGameData());
	EventSystem.Global.dispatchEvent(System_Event.AUDIO_MUTE_STATE_CHANGED, gameData.isAudioMuted);
};

GameFlowController.prototype._refreshLeaderboard = function () {
	if (this.screenManager.getCurrentScreen() === mainMenuScreens.LEADERBOARD) {
		this.screenManager.setScreen(mainMenuScreens.LEADERBOARD);
	}
};

/**
 * @todo DEPRECATE CANDIDATE.
 * Only used by LeaderboardTabsDialog.
 *  - The information it's retrieving should be injected with the creation of that dialog.
 *  - The information it's trying to save should go through the event system.
 */
GameFlowController.prototype.getGameStateHandler = function () {
	'use strict';
	return this._gameStateHandler;
};

GameFlowController.prototype.handleDraw = function () {
	"use strict";
	// Clear the dynamic canvasses
	tgfGraphics.clearDynamicCanvasses();
};
