EventSystem.EventActions =  function (context) {
    this._actions = [];
    this._context = context;
}
 
EventSystem.EventActions.prototype.add = function (eventID, callback) {
    var eventAction = new EventSystem.EventAction(eventID, callback, this._context);
    this.addAction(eventAction);
    return eventAction;
}

EventSystem.EventActions.prototype.addAction = function (eventAction) {
    this._actions.push(eventAction);
}

EventSystem.EventActions.prototype.deactivateAll = function () {
    var actionsLength = this._actions.length;
    for (var i = 0; i < actionsLength; i++){
        this._actions[i].deactivate();
    }
}

EventSystem.EventActions.prototype.activateAll = function () {
    var actionsLength = this._actions.length;
    for (var i = 0; i < actionsLength; i++){
        this._actions[i].activate();
    }
}



//******************************************************
//*****    Script Resource: EventAction
//******************************************************


EventSystem.EventAction =  function ( eventId, callback, context, doNotActivate ) {
    this._eventId = eventId;
    this._callback = callback;
    this._context = context;
	if (doNotActivate != true) {
		this.activate();
	} else {
		this._active = false;
	}
}
 
EventSystem.EventAction.prototype.activate = function () {
    if(this._active){
        return;
    }
    this._active = true;
    EventSystem.Global.addEventListener(this._eventId, this._callback, this._context);
}
 
EventSystem.EventAction.prototype.deactivate = function () {
    if(!this._active){
        return;
    }
    this._active = false;
    EventSystem.Global.removeEventListener(this._eventId, this._callback, this._context);
}

EventSystem.EventAction.prototype.IsActive = function () {
    return this._active;
}

