/////////////////////////////////////////////////////////////
// Sudoku_Interface
//
// This script deals with the interface (number selection)
//
// Copyright 2013 Tingly Games
// Last Changed: 22-11-2013
/////////////////////////////////////////////////////////////

var sudokuInterface = {
	markerMode: false, // Whether adding markers
	x: 0, // X-position of the first number selector.
	y: 0, // Y-position of the interface
	dist: 0, //the distance between number selector squares.
	buttonWidth: 0,

	timesCellFirstPopulated: 0,
	timesNumberFirstPopulated: 0,

	numberAnimTimer: 0, // timer that controls the animations of the numbers at the bottom
	numberAnimDuration: 0.3, // timer that controls the animations of the numbers at the bottom
	numberAnimOffset: .08, // time offset per number
	numberAnimUpscale: -10, //

	numberEnabled: [true, true, true, true, true, true, true, true, true],
	tutorialMode: false,

	init: function () {
		"use strict";

		sudokuInterface.timesCellFirstPopulated = 0;
		sudokuInterface.timesNumberFirstPopulated = 0;

		var width = s_ui_game_numpad_btn_pencil_idle.combinedWidth;

		sudokuInterface.buttonWidth = s_ui_game_numpad_btn_pencil_idle.width;

		//the distance between the selector squares.
		sudokuInterface.dist = tgfScale((tgfGraphics.visibleWidth - width) / 11);
		sudokuInterface.buttonOffset = 4;

		sudokuInterface.x = tgfScale(sudokuInterface.dist + sudokuInterface.buttonWidth);

		sudokuInterface.penPosition = s_ui_game_numpad_tab_pen.width * .5;

		sudokuInterface.pencilPosition = s_ui_game_numpad_tab_pencil.width * 1.5;

		sudokuInterface.markerToggleAreaX = sudokuInterface.penPosition - s_ui_game_numpad_tab_pen.width / 2;
		sudokuInterface.markerToggleAreaY = sudokuInterface.getPenY() - s_ui_game_numpad_tab_pen.height / 2;
		sudokuInterface.markerToggleAreaWidth = s_ui_game_numpad_tab_pen.width * 3.5; // big margin
		sudokuInterface.markerToggleAreaHeight = s_ui_game_numpad_tab_pen.height * 2.5;

		sudokuInterface.selectedButton = null;

		sudokuInterface.numberEnabled = [true, true, true, true, true, true, true, true, true];
	},

	getPenY: function() {
		return tgfScale(sudokuInterface.getY() + s_ui_game_numpad_tab_pen.height + 12);
	},

	getY: function() {
		return tgfScale(tgfGraphics.visibleHeight - 237);
	},

	getButtonPosition: function(index) {
		return sudokuInterface.buttonOffset + (sudokuInterface.x * index + sudokuInterface.buttonWidth / 2);
	},

	isCellFirst: function () {
		'use strict';
		return gameData.preferredControls === Preferred_Controls.CELL_FIRST;
	},

	preferredControlsChanged: function () {
		'use strict';

		if (!sudokuInterface.isCellFirst()) {
			sudokuInterface.timesCellFirstButtonActivated++;

			if (sudokuField.selected !== 0) {
				sudokuInterface.selectedButton = sudokuField.selected - 1;
			}
		} else {
			sudokuInterface.timesNumberFirstButtonActivated++;

		}

		sudokuInterface.shown = false;
	},

	endGame: function () {
		'use strict';

		if (sudokuField.countAll() === 81) {
			// Report 'cell first' or 'number first' analytics
			EventSystem.Global.dispatchEvent(System_Event.LEVEL_SOLVED);
		}
	},

	// Handles a click on the field
	onTouchDown: function (xMouse, yMouse) {
		"use strict";

		var sudokuNumber,
			xCell = sudokuDraw.getCellX(xMouse - tgfSettings.game.gameOffsetX),
			yCell = sudokuDraw.getCellY(yMouse - tgfSettings.game.gameOffsetY)

		var yPos = sudokuInterface.getY() + s_ui_game_numpad_btn_pencil_idle.height / 2 - yMouse;

		var tempButtonIndex = sudokuInterface.selectedButton;

		if (yPos >= 0 && yPos <= s_ui_game_numpad_btn_pencil_idle.height) {
			for (var i = 0; i < 9; ++i) {
				if (xMouse >= sudokuInterface.getButtonPosition(i) - sudokuInterface.buttonWidth / 2 &&
					xMouse <= sudokuInterface.getButtonPosition(i) + sudokuInterface.buttonWidth / 2) {

					if (sudokuInterface.isCellFirst()) {
						if (sudokuInterface.shown) {

							if (sudokuInterface.markerMode) {
								sudokuField.toggleMarker(sudokuField.column, sudokuField.row, i + 1);
							} else if (sudokuField.field[sudokuField.column][sudokuField.row]['current'] === 0) {
								sudokuInterface.cellFirstFillInNumber(i + 1);
							}
						} else {
							EventSystem.Global.dispatchEvent(Level_Event.CELL_FIRST_NO_CELL_SELCTED, i);
						}
					} else {
						if (sudokuInterface.selectedButton === i) {
							sudokuInterface.deselect();

						} else if (sudokuInterface.numberEnabled[i]) {

							sudokuInterface.selectedButton = i;

							SudokuAnalytics.reportNumberSelected("bottom", i + 1);

							sudokuField.selected = i + 1;
							tbAudio.play(a_select);
						}
					}

					break;
				}
			}
		} else {
			yPos = sudokuInterface.getPenY() + (s_ui_game_numpad_btn_pencil_idle.height / 2) - yMouse;

			if (yPos >= 0 && yPos <= s_ui_game_numpad_tab_pencil.height) {
				if (tempButtonIndex !== null) {
					sudokuInterface.selectedButton = tempButtonIndex;

					sudokuField.selected = tempButtonIndex + 1;
				}
			}

			//toggle button
			if (yPos <= s_ui_game_numpad_tab_pencil.height &&
				yPos >= -sudokuInterface.markerToggleAreaHeight + s_ui_game_numpad_tab_pencil.height &&
				xMouse >= sudokuInterface.markerToggleAreaX &&
				xMouse <= sudokuInterface.markerToggleAreaX + sudokuInterface.markerToggleAreaWidth) {
				sudokuInterface.markerMode = !sudokuInterface.markerMode;
//				MessyAnalytics.setMarkerMode(sudokuInterface.markerMode);
			}
		}

		if (xCell < 0 || yCell < 0) {
			return;
		}

		// Select it
		sudokuNumber = sudokuField.field[xCell][yCell]['current'];

		if (sudokuInterface.isCellFirst()) {
			sudokuInterface.handleCellFirstTouchDown(sudokuNumber, xCell, yCell);
		} else {
			sudokuInterface.handleNumberFirstTouchDown(sudokuNumber, xCell, yCell);
		}

		if (sudokuNumber === 0) {
			if (sudokuInterface.shown) {
				EventSystem.Global.dispatchEvent(Level_Event.EMPTY_CELL_SELECTED, xCell, yCell);
			} else {
				EventSystem.Global.dispatchEvent(Level_Event.EMPTY_CELL_DESELECTED, xCell, yCell);
			}
		} else {
			if (sudokuInterface.shown) {

				SudokuAnalytics.reportNumberSelected("board", sudokuNumber);

				EventSystem.Global.dispatchEvent(Level_Event.NON_EMPTY_CELL_SELECTED, xCell, yCell);
			} else {
				EventSystem.Global.dispatchEvent(Level_Event.NON_EMPTY_CELL_DESELECTED, xCell, yCell);
			}
		}
	},
	deselect: function () {
		sudokuInterface.selectedButton = null;
		sudokuField.selected = 0;
		tbAudio.play(a_deselect);
	},

	cellFirstFillInNumber: function (number) {
		if (!sudokuInterface.numberEnabled[number - 1] || !sudokuInterface.shown) {
			return;
		}

		var cell = sudokuField.field[sudokuField.column][sudokuField.row];
		if (cell['current'] !== 0 && !cell['wrong']) {
			return;
		}

		sudokuField.selected = number;

		sudokuField.place(sudokuField.column, sudokuField.row, number);

		sudokuInterface.shown = false;

		sudokuDraw.animationStartFly(sudokuField.column, sudokuField.row, sudokuInterface.getButtonPosition(number - 1), sudokuInterface.getY());

		sudokuInterface.endGame();
	},

	handleCellFirstTouchDown: function (sudokuNumber, xCell, yCell) {
		'use strict';
		var touchedCell = sudokuField.field[xCell][yCell];

		if (touchedCell['wrong'] === true) {
			sudokuField.clear(xCell, yCell);
			tgfAudio.play(a_deselect);
		} else {
			if (sudokuField.column === xCell && sudokuField.row === yCell && sudokuInterface.shown === true) {
				sudokuInterface.shown = false;
			} else {
				sudokuInterface.shown = true;
			}

			if (touchedCell['current'] !== 0) {
				if (touchedCell['current'] === sudokuField.selected) {
					sudokuField.selected = 0;
				} else {
					sudokuField.selected = touchedCell['current'];
				}

				sudokuInterface.shown = false;
			} else {
				if (sudokuField.selected) {
					sudokuField.selected = 0;
				}
			}

			// set "blue cross"
			sudokuField.column = xCell;

			sudokuField.row = yCell;
		}
	},

	handleNumberFirstTouchDown: function (sudokuNumber, xCell, yCell) {
		sudokuField.row = yCell;

		sudokuField.column = xCell;

		var touchedCell = sudokuField.field[xCell][yCell];
		var isNumberEnabledInInterface = sudokuInterface.numberEnabled[sudokuInterface.selectedButton];
		var selectedButtonPosition = sudokuInterface.getButtonPosition(sudokuInterface.selectedButton);

		if (sudokuNumber === 0 && sudokuInterface.selectedButton !== null && isNumberEnabledInInterface) {
			if (sudokuInterface.markerMode) {
				sudokuField.toggleMarker(sudokuField.column, sudokuField.row, sudokuInterface.selectedButton + 1);
			} else {
				sudokuField.place(sudokuField.column, sudokuField.row, sudokuInterface.selectedButton + 1);

				sudokuInterface.endGame();

				sudokuDraw.animationStartFly(sudokuField.column, sudokuField.row, selectedButtonPosition, sudokuInterface.getY());
			}
		} else if (touchedCell['wrong'] === true) {
			sudokuField.clear(xCell, yCell);
			tgfAudio.play(a_deselect);
		} else {
			if (sudokuField.selected === sudokuNumber && sudokuNumber !== 0) {
				sudokuField.selected = 0;
				tbAudio.play(a_deselect);

				sudokuInterface.selectedButton = null;
			} else if (sudokuNumber !== 0) {
				tbAudio.play(a_select);

				sudokuField.selected = sudokuNumber;

				sudokuInterface.selectedButton = sudokuNumber - 1;
			} else {
				if (!this.tutorialNumberPlaceMode) {
					this.playNumberReminderAnimation();
				}
				EventSystem.Global.dispatchEvent(Level_Event.NUMBER_FIRST_NO_NUMBER_SELCTED, xCell, yCell);
			}
		}
	},

	// Handles a release on the field
	onTouchUp: function (xMouse, yMouse) {
		"use strict";
	},

	update: function (timePassed) {
		sudokuInterface.numberAnimTimer = sudokuInterface.numberAnimTimer + timePassed / 1000;
	},

	playNumberReminderAnimation: function () {
		sudokuInterface.numberAnimTimer = 0;
	},

	// Draw the interface
	draw: function () {
		"use strict";
		var yy = sudokuInterface.getY();

		s_ui_game_numpad_bg.drawExt(true, (tgfGraphics.visibleWidth / 2)+2, tgfGraphics.visibleHeight -98, 1, 1, 0, 1);
		var offsetPen = { x: -3, y: 0 };
		var offsetPencil = { x: -6, y: 0 };
		if(sudokuInterface.markerMode){
			s_ui_game_numpad_tab_pen.drawExt(0 + sudokuInterface.markerMode, sudokuInterface.penPosition + offsetPen.x, sudokuInterface.getPenY(), 1, 1, 0, 1);
			s_ui_game_numpad_tab_pencil.drawExt(0 + !sudokuInterface.markerMode, sudokuInterface.pencilPosition + offsetPencil.x, sudokuInterface.getPenY(), 1, 1, 0, 1);
		}else{
			s_ui_game_numpad_tab_pencil.drawExt(0 + !sudokuInterface.markerMode, sudokuInterface.pencilPosition + offsetPencil.x, sudokuInterface.getPenY(), 1, 1, 0, 1);
			s_ui_game_numpad_tab_pen.drawExt(0 + sudokuInterface.markerMode, sudokuInterface.penPosition + offsetPen.x, sudokuInterface.getPenY(), 1, 1, 0, 1);
		}

		var numbers_s = sudokuInterface.markerMode ? s_ui_game_numpad_btn_pencil_selected : s_ui_game_numpad_btn_pen_selected;

		var numbers_ns = sudokuInterface.markerMode ? s_ui_game_numpad_btn_pencil_idle : s_ui_game_numpad_btn_pen_idle;

		for (var i = 0; i < numbers_s.number; ++i) {
			var img = i === sudokuInterface.selectedButton ? numbers_s : numbers_ns;
			var alpha = sudokuInterface.numberEnabled[i] ? 1 : 0.25;

			var size = 1;
			var offset = 0;
			var adjustedTimer = Math.max(0, sudokuInterface.numberAnimTimer - i * sudokuInterface.numberAnimOffset);
			if (adjustedTimer <= sudokuInterface.numberAnimDuration) {
				var time;
				if (adjustedTimer <= sudokuInterface.numberAnimDuration / 3) {
					time = adjustedTimer;
					offset = tbEase.easeInOutSine(time, 0, sudokuInterface.numberAnimUpscale, sudokuInterface.numberAnimDuration / 3);
				} else if (adjustedTimer <= sudokuInterface.numberAnimDuration / 3 * 2) {
					offset = 1 + sudokuInterface.numberAnimUpscale;
				} else if (adjustedTimer <= sudokuInterface.numberAnimDuration / 3 * 3) {
					time = adjustedTimer - sudokuInterface.numberAnimDuration / 3 * 2;
					offset = tbEase.easeInOutSine(time,
						1 + sudokuInterface.numberAnimUpscale, -sudokuInterface.numberAnimUpscale, sudokuInterface.numberAnimDuration / 3);
				}
			} else {
				var self = this;
				if (i === numbers_s.number - 1 && this.tutorialNumberPlaceMode) {

					if (this._animationTimeout && sudokuField.selected !== 0) {
						clearTimeout(this._animationTimeout);
						this._animationTimeout = null;
					}
					if (sudokuField.selected === 0 && !this._animationTimeout) {
						this._animationTimeout = setTimeout(function () {
							sudokuInterface.numberAnimTimer = 0;
							self._animationTimeout = null;
						}, 2000);
					}
				}
			}

			img.drawExt(i, sudokuInterface.getButtonPosition(i), yy + offset, size, size, 0, alpha);
		}
	},

	disableNumberButton: function (number) {
		sudokuInterface.numberEnabled[number - 1] = false;
	},

	setTutorialNumberPlaceMode: function (value) {
		this.tutorialNumberPlaceMode = value;
		if (!this.tutorialNumberPlaceMode) {
			sudokuField.selected = 0;
		}
	},
};
