//******************************************************
//*****    Script Resource: LevelScoreController
//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

var LevelScoreController = function (difficulty, initialScore) {
    this._scoreSettings = tgfSettings.game.levels[difficulty].score;
    this._score = initialScore;
    this._eventActions = null;
    this._floatersEnabled = true;
    this._configureEvents();
}

LevelScoreController.prototype._configureEvents = function () {

    this._eventActions = new EventSystem.EventActions(this);
    this._eventActions.add(Level_Event.CORRECT_NUMBER_PLACED, this._handleCorrectNumberPlaced);
    this._eventActions.add(Level_Event.WRONG_NUMBER_PLACED, this._handleIncorrectNumberPlaced);

    //In tech-debt list to be moved to it's own contained class. https://boostermedia.jira.com/wiki/spaces/DS/pages/982745089/Tech+debt+list
    this._eventActions.add(Level_Event.SET_FLOATERS_ENABLED, this._setFloatersEnabled);
};

LevelScoreController.prototype._handleCorrectNumberPlaced = function (numberPlaceEventPayload) {

    SudokuAnalytics.reportNumberPlaced(true, numberPlaceEventPayload.number);

    this._scoreCell(numberPlaceEventPayload.x, numberPlaceEventPayload.y, numberPlaceEventPayload.shouldAffectScore);

    if (numberPlaceEventPayload.blocksCompleteAmount) {
        this._scoreBlocks(numberPlaceEventPayload.blocksCompleteAmount, numberPlaceEventPayload.x, numberPlaceEventPayload.y, numberPlaceEventPayload.shouldAffectScore);
    }
};

LevelScoreController.prototype._handleIncorrectNumberPlaced = function (numberPlaceEventPayload) {
    
    SudokuAnalytics.reportNumberPlaced(false, numberPlaceEventPayload.number);
    SudokuAnalytics.reportMistake();

    this._scoreError(numberPlaceEventPayload.x, numberPlaceEventPayload.y, numberPlaceEventPayload.shouldAffectScore);
};

LevelScoreController.prototype.getScoreResult = function (timeInSeconds) {
    var bonus = this._getBonus(timeInSeconds);

    return new LevelScoreResult(
        this._calculateTotalScore(timeInSeconds),
        this.getScore(),
        bonus
    );
}

LevelScoreController.prototype.getScore = function () {

    return this._score;
};

LevelScoreController.prototype.doubleScore = function () {
    // this.addScore(this.getScore());
    this._score += this.getScore();
}

LevelScoreController.prototype._calculateTotalScore = function (timeInSeconds) {
    var bonus = this._getBonus(timeInSeconds);
    return this.getScore() + bonus;
}

LevelScoreController.prototype._getBonus = function (time) {
    "use strict";

    var maxTime = this._scoreSettings.maxTimeForBonus;

    var bonusFactor = this._scoreSettings.bonusScoreFactor;

    var bonusTime = Math.max(0, 1 - (time / maxTime));

    var bonus = Math.round(this._score * bonusFactor * bonusTime);

    return bonus;
};

LevelScoreController.prototype._scoreCell = function (xCell, yCell, shouldAffectScore) {
    "use strict";

    var scoreMod = shouldAffectScore ? this._scoreSettings.perCell : 0;

    //Apply score multiplier if one is active.
    scoreMod *= gameData.scoreMultiplier ? gameData.scoreMultiplier : 1;

    this._score += scoreMod;
    EventSystem.Global.dispatchEvent(Level_Event.LEVEL_SCORE_CHANGED, this._score);

    //In tech-debt list to be moved to it's own contained class. https://boostermedia.jira.com/wiki/spaces/DS/pages/982745089/Tech+debt+list
    // Create a floater
    var xPosition = sudokuDraw.getX(xCell);
    var yPosition = sudokuDraw.getY(yCell);

    if (this._floatersEnabled && scoreMod > 0) {
        new floaters.Floater("+" + scoreMod.toString(), xPosition, yPosition - tgfSettings.game.floater.offset, 1000 * tgfSettings.game.floater.delay, floaterFontNumberPositive);
    } else {
        EventSystem.Global.dispatchEvent(Level_Event.SCORE_FLOATER_MOMENT, xPosition, yPosition - tgfSettings.game.floater.offset, 1000 * tgfSettings.game.floater.delay, floaterFontNumberPositive);
    }

    // var numberPlaceFeedback = new tgfDialogs.NumberPlaceFeedback({
    //         x: xPosition,
    //         y: yPosition - tgfScale(10)
    //     },
    //     NumberPlaceFeedbackMode.CORRECT
    // );
    // numberPlaceFeedback.show();
};

LevelScoreController.prototype._scoreBlocks = function (blockAmount, xCell, yCell, shouldAffectScore) {
    "use strict";

    var scoreMod = shouldAffectScore ? blockAmount * this._scoreSettings.perBlock : 0;

    //Apply score multiplier if one is active.
    scoreMod *= gameData.scoreMultiplier ? gameData.scoreMultiplier : 1;

    this._score += scoreMod;
    EventSystem.Global.dispatchEvent(Level_Event.LEVEL_SCORE_CHANGED, this._score);

    //In tech-debt list to be moved to it's own contained class. https://boostermedia.jira.com/wiki/spaces/DS/pages/982745089/Tech+debt+list
    // Create a floater
    var xPosition = sudokuDraw.getX(xCell);
    var yPosition = sudokuDraw.getY(yCell);

    if (this._floatersEnabled && scoreMod > 0) {
        new floaters.Floater("+" + scoreMod.toString(), xPosition, yPosition - tgfSettings.game.floater.offset, 1000 * (tgfSettings.game.floater.delay + 1), floaterFontNumberPositive);
    }
};

LevelScoreController.prototype._scoreError = function (xCell, yCell, shouldAffectScore) {
    "use strict";
    var scoreMod = shouldAffectScore ? -this._scoreSettings.perError : 0;

    this._score += scoreMod;
    this._score = this._score < 0 ? 0 : this._score;

    EventSystem.Global.dispatchEvent(Level_Event.LEVEL_SCORE_CHANGED, this._score);

    //In tech-debt list to be moved to it's own contained class. https://boostermedia.jira.com/wiki/spaces/DS/pages/982745089/Tech+debt+list
    // Create a floater
    var xPosition = sudokuDraw.getX(xCell);
    var yPosition = sudokuDraw.getY(yCell);

    if (this._floatersEnabled) {
        if (scoreMod < 0) {
            new floaters.Floater("" + scoreMod.toString(), xPosition, yPosition - tgfSettings.game.floater.offset, 1000 * tgfSettings.game.floater.delay, floaterFontNumberNegative);
        }
    }

    // var numberPlaceFeedback = new tgfDialogs.NumberPlaceFeedback({
    //         x: xPosition,
    //         y: yPosition
    //     },
    //     NumberPlaceFeedbackMode.INCORRECT
    // );
    // numberPlaceFeedback.show();
};

//In tech-debt list to be moved to it's own contained class. https://boostermedia.jira.com/wiki/spaces/DS/pages/982745089/Tech+debt+list
LevelScoreController.prototype._setFloatersEnabled = function (value) {
    this._floatersEnabled = value;
}

LevelScoreController.prototype.remove = function () {
    this._eventActions.deactivateAll();
}

var LevelScoreResult = function (total, score, bonus) {
    this.total = total;
    this.score = score;
    this.bonus = bonus;
}
