tgfDialogs.LevelResultDialog.prototype.handleBeginStep = function (timePassed) {
    "use strict";

    // This matches up the button animation position to the button state
    if (this.nextButton && this.unlockButtonAnimation) {
        if (this.nextButton.state === "down")
            this.unlockButtonAnimation.y = this.unlockButtonAnimationY + 5;
        else this.unlockButtonAnimation.y = this.unlockButtonAnimationY;
    }
};

// Processing required when freeing the dialog from use
tgfDialogs.LevelResultDialog.prototype.doFree = function () {
    "use strict";
    tgfDialogs.LevelResultDialog.uber.doFree.call(this);
    this._rankBar.destroy();
};

tgfDialogs.LevelResultDialog.prototype.doShow = function () {
    "use strict";
    BoosterSDK.postScore(this.points);
    BoosterSDK.tryInterstitialWithInterval();

    tbGame.setAlarm("endScreenRankAnim", this.animationWait * 1000);
    EventSystem.Global.dispatchEvent(Play_Friendly_Events.END_BEFORE_DOUBLE_SCORE, this.points, this.time, this.date, this.difficulty);
};

tgfDialogs.LevelResultDialog.prototype.doHide = function () {
    "use strict";
    //    MessyAnalytics.popup("win", false);
};

tgfDialogs.LevelResultDialog.prototype.handleAlarm = function (alarm) {
    "use strict";
    if (alarm === "endScreenRankAnim") {
        if (this._rankBar.shouldAnimatePoints()) {
            this._rankBar.animateTo(ExperienceController.getExperiencePoints(), 200, -125);
        }
        this.onAnimationComplete();
    }
};
