//*****    Script Resource: LevelTimeController
//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

var LevelTimeController = function (initialTime) {
    this.isPaused = false;
    this._tokenActive = false;
    this._levelTimeInMilliSeconds = initialTime ? initialTime : 0;
    this._secondsCounter = 0;
    this._configureEvents();
    EventSystem.Global.dispatchEvent(Level_Event.LEVEL_TIME_CHANGED, this._levelTimeInMilliSeconds);
}

LevelTimeController.prototype._configureEvents = function () {
    "use strict";
    this._eventActions = new EventSystem.EventActions(this);

    this._eventActions.add(System_Event.LEVEL_END, this._pause);
    this._eventActions.add(System_Event.LEVEL_START, this._start);

    this._eventActions.add(Level_Event.LEVEL_TIME_PAUSE, this._pause);
    this._eventActions.add(Level_Event.LEVEL_TIME_RESUME, this._resume);

    this._eventActions.add(Level_Event.LEVEL_PAUSED, this._pause);
    this._eventActions.add(Level_Event.LEVEL_RESUMED, this._resume);

    this._eventActions.add(UI_Event.EXTERNAL_DIALOG_OPENED, this._pause);
    this._eventActions.add(UI_Event.EXTERNAL_DIALOG_CLOSED, this._resume);
};

LevelTimeController.prototype.handleBeginStep = function (timePassed) {
    "use strict";
    this._levelTimeInMilliSeconds += timePassed;

    this._secondsCounter += timePassed;
    if (this._secondsCounter >= 1000) {
        this._secondsCounter -= 1000;
        EventSystem.Global.dispatchEvent(Level_Event.LEVEL_TIME_CHANGED, this._levelTimeInMilliSeconds);
    }
};

LevelTimeController.prototype._start = function () {
    "use strict";

    // There can be a case where we would like to start the LevelTimeController in a paused state. This check handles that. 
    if (!this.isPaused) {
        tbGame.addToken(this);
        this._tokenActive = true;
    }
};

LevelTimeController.prototype._pause = function () {
    "use strict";
    if (!this.isPaused) {
        this.isPaused = true;

        if (this._tokenActive) {
            tbGame.pauseToken(this);
        }
    }
};

LevelTimeController.prototype._resume = function () {
    "use strict";

    if (this.isPaused) {
        this.isPaused = false;

        if (!this._tokenActive) {
            tbGame.addToken(this);
            this._tokenActive = true;
        }

        tbGame.resumeToken(this);
    }
};

LevelTimeController.prototype.remove = function () {
    tbGame.removeToken(this);
    this._eventActions.deactivateAll();
}

LevelTimeController.prototype.getTimeInMilliSeconds = function () {
    "use strict";
    return this._levelTimeInMilliSeconds;
};

LevelTimeController.prototype.getTimeInSeconds = function () {
    return Math.floor(this._levelTimeInMilliSeconds / 1000);
}
