// Processing required when preparing the dialog for use
tgfDialogs.RewardHintsDialog.prototype.doPrepare = function () {
	"use strict";
	var self = this;

	tgfDialogs.RewardHintsDialog.uber.doPrepare.call(this);


	this.spine = new tgfComponents.SpineComponent({
		spineAnimation: reward,
		animationClips: ["animation"], // The animation names from the spine json
		play: true,
		hasDelay: true,
		delay: -1,
		x: tgfScale(0),
		y: tgfScale(0),

		updateWhileUnactive: false,
		onComplete: function () {
			self.animationEnded();
		}
	});
	this.container.addComponent(this.spine);

	this.hintCount = this.hintCount || 0;

	this.text = new tgfComponents.Label({
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 63,
			fillColor: "#2d2d2d",
			baseline: "middle",
			align: "center",
			strokeColor: "#f7f7f7",
			strokeWidth: 4,
			strokeBehind: true,
			shadow: {
				active: true,
				color: 'rgba(45, 45, 45, 0.6)',
				offsetX: 0,
				offsetY: 8,
				blur: 13
			}
		},

		text: StringUtil.format(tgfDictionary.getText("HintsRewardText"), this.hintCount),
		splitLines: true,
		width: 300
	});
	this.container.addComponent(this.text);

	this.stars = [];
	for (var i = 0; i < this.hintCount; i += 1) {
		this.stars.push(new tgfComponents.Picture({
			image: s_star_effect,
			alpha: 0,
			x: 0,
			y: -200
		}));
		this.container.addComponent(this.stars[i]);
	}

	// Add the additional components
	for (var i = 0; i < this.components.length; i += 1) {
		this.container.addComponent(this.components[i]);
	}
};

tgfDialogs.RewardHintsDialog.prototype.animationEnded = function () {
	this._spineHasEnded = true;

	var self = this;
	this.starAnimators = [];

	var addAnimation = function (animator, variable, fromValue, toValue, delay, duration, ease) {

		var track = null;
		for (var i = 0; i < animator.tracks.length; i++) {
			if (animator.tracks[i].kind !== variable) continue;

			track = animator.tracks[i];
			break;
		}

		if (!track) {
			track = animator.addTrack(variable);
			animator.addKey(track, 0, fromValue, ease);
		}

		if (delay > 0) {
			animator.addKey(track, delay, fromValue, ease);
		}

		var durationFrame = delay + duration;

		animator.addKey(track, durationFrame, toValue, ease);
		animator.setTime(0);
		animator.resumeForced();
	};

	for (var i = 0; i < this.stars.length; i++) {
		var starAnimator = new tbAnimator(this.stars[i]);
		this.starAnimators.push(starAnimator);

		// Rotate for the duration of the animation
		addAnimation(starAnimator, "angle", 0, 600, i * 500, 1000);

		// Move stars up
		addAnimation(starAnimator, "alpha", 0, 1, i * 500, 100);
		addAnimation(starAnimator, "y", -200, -400, i * 500, 300, tbEase.easeOutOvershoot);
		addAnimation(starAnimator, "xScale", 0, 1.5, i * 500, 300, tbEase.easeOutOvershoot);
		addAnimation(starAnimator, "yScale", 0, 1.5, i * 500, 300, tbEase.easeOutOvershoot);

		// Move stars to the left
		addAnimation(starAnimator, "x", 0, -100, (i) * 500 + 500, 500, tbEase.easeOutOvershoot);
		addAnimation(starAnimator, "y", -400, 290, (i) * 500 + 500, 500, tbEase.easeOutOvershoot);
		addAnimation(starAnimator, "alpha", 1, 0, (i) * 500 + 500, 500);
		addAnimation(starAnimator, "xScale", 1.5, 0, (i) * 500 + 500, 300);
		addAnimation(starAnimator, "yScale", 1.5, 0, (i) * 500 + 500, 300);

		starAnimator.addEvent(this, (i + 1) * 600, function () {
			EventSystem.Global.dispatchEvent(UI_Event.HINT_STAR_ARRIVED);
		})

		if (i == this.stars.length - 1 && self.onComplete) {

			starAnimator.addEvent(this, (i + 2) * 500, function () {
				EventSystem.Global.dispatchEvent(UI_Event.HINT_REWARD_ANIMATION_COMPLETE);
			});
		}
	}
};

tgfDialogs.RewardHintsDialog.prototype.onShow = function (timePassed) {
	"use strict";
	var self = this;

	// Show text on animation event 'open' 
	// Can't be in doPrepare because the prepare of the spine component gets created in its own doPrepare, which will only prepare when we call show.
	this.text.alpha = 0.0;
	this.spine.spineClone.setEventCallback("open", function () {
		self.text.alpha = 1.0;
	});
};

tgfDialogs.RewardHintsDialog.prototype.handleEndStep = function (timePassed) {
	"use strict";
	tgfDialogs.RewardHintsDialog.uber.handleEndStep.call(this, timePassed);

	this.updateText(timePassed);
	this.updateStars(timePassed);
};

tgfDialogs.RewardHintsDialog.prototype.updateStars = function (timePassed) {

	if (!this.starAnimators) return;

	for (var i = 0; i < this.starAnimators.length; i++) {
		this.starAnimators[i].updateTime(timePassed);
	}
};

tgfDialogs.RewardHintsDialog.prototype.updateText = function (timePassed) {
	var boneList = this.spine.spineClone.skeleton.bones;

	// Find our bone and move the text to it
	for (var i = 0; i < boneList.length; i++) {
		var bone = boneList[i];
		if (bone.data.name !== "s_text_5hints") continue;

		this.text.x = bone.x;
		this.text.y = -bone.y;
		this.text.xScale = bone.scaleX;
		this.text.yScale = bone.scaleY;
		break;
	}

	if (this._spineHasEnded && this.text.alpha > 0.0) {
		this.text.alpha -= timePassed * 0.001;

		// If text is gone
		if (this.text.alpha <= 0.0) {
			this.text.alpha = 0.0;
		}
	}
}
