var GamebotManager = (function () {
    var _GamebotManager = function () {};

    _GamebotManager.prototype.scheduleMessages = function () {
        if (!this._messagesScheduled) {
            this._messagesScheduled = true;

            var isProduction = tgfSettings.env === 'dist';
            this._imagesPublisherService = new UNOImagesPublisherService(tgfSettings.appId, isProduction);
            this._instantNotificationsService = new GameSparksInstantNotificationsService(gamesBackendService, "", this._imagesPublisherService);
            this._scheduleMessages();
        }
    };

    _GamebotManager.prototype._scheduleMessages = function () {

        var self = this;

        this._instantNotificationsService.getScheduleNotifications(messagingPlatformService.getPlayer().id)
            .then(this._cancelAllButExemptNotifications.bind(this))
            .then(function () {
                if (gameData.veryFirstGamebotMessageScheduled === false) {
                    self._createAndScheduleFirstMessage();
                }
                for (var i = 0; i < tgfSettings.game.gamebotConfig.timings.length; i++) {
                    self._createAndScheduleRandomGiftMessage(tgfSettings.game.gamebotConfig.timings[i], i);
                }
            });
    };

    _GamebotManager.prototype._cancelAllButExemptNotifications = function (notifications) {

        var notificationIds = [];
        for (var j = 0; j < notifications.length; j++) {

            var notification = notifications[j];
            var isExempt = false;

            for (var i = 0; i < gameData.cancelExemptNotificationIds.length; i++) {
                var cancelExemptNotificationId = gameData.cancelExemptNotificationIds[i];
                if (notification.notificationId == cancelExemptNotificationId) {
                    isExempt = true;
                }
            }

            if (!isExempt) {
                notificationIds.push(notification.notificationId);
            }
        }

        return this._instantNotificationsService.cancelScheduledNotifications(messagingPlatformService.getPlayer().id, notificationIds);
    }

    _GamebotManager.prototype._createAndScheduleFirstMessage = function () {

        var targetDate = this._getDateWithOffset(tgfSettings.game.gamebotConfig.immediateMessageTime);

        //Schedule Reminder
        var message = tgfDictionary.getText(tgfSettings.game.gamebotConfig.immediateMessage);
        var buttonMessage1 = tgfDictionary.getText(tgfSettings.game.gamebotConfig.dailyMessageButtonKey);
        var buttonMessage2 = tgfDictionary.getText(tgfSettings.game.gamebotConfig.createShortCutBotMessageButtonText);

        var analytics = [
            "gamebot",
            "daily",
            "immediate_message"
        ];

        this._createImmediateMessage(message, [buttonMessage1, buttonMessage2], targetDate, analytics)
            .then(function (id) {
                gameData.cancelExemptNotificationIds.push(id);
                gameData.veryFirstGamebotMessageScheduled = true;
                saveDataService.savePlayerData(gameData.getSaveableGameData());
            });
    }

    _GamebotManager.prototype._createAndScheduleRandomGiftMessage = function (milisecondsFromNow, scheduleOrder) {

        var scheduleTime = this._getActiveHourScheduleDate(milisecondsFromNow);

        var giftMessageConfig = this._getRandomGiftMessage();
        var analytics = [
            "gamebot",
            giftMessageConfig.analytics,
            scheduleOrder === 0 ? "24h" : scheduleOrder === 1 ? "72h" : "168h"
        ];

        this._createGiftMessage(giftMessageConfig.message, giftMessageConfig.buttonText, scheduleTime, analytics, giftMessageConfig);
    }

    _GamebotManager.prototype._getActiveHourScheduleDate = function (milisecondsFromNow) {

        var targetDate = this._getDateWithOffset(milisecondsFromNow);

        return new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 17);
    }

    _GamebotManager.prototype._getDateWithOffset = function (milisecondsFromNow) {

        var currentDate = TimeManager.getDate();

        return new Date(currentDate.getTime() + milisecondsFromNow);
    }

    _GamebotManager.prototype._createGiftMessage = function (message, buttonMessage, scheduleTime, analytics, giftMessageConfig) {
        var self = this;

        var giftScreen = new tgfDialogs.GiftScreen({
            giftMessageConfig: giftMessageConfig,

            callback: function (dataURL) {
                self._scheduleMessage(message, [buttonMessage], dataURL, scheduleTime, analytics, giftMessageConfig);

                giftScreen = undefined;
            }
        });

        giftScreen.show();
    };

    _GamebotManager.prototype._createImmediateMessage = function (message, buttonMessages, scheduleTime, analytics) {
        var self = this;

        var imageUrl = "https://www.dropbox.com/s/96v0rrc5tvx6l4s/s_customupdate_bot_welcome.png?dl=1";
        return self._scheduleMessage(message, buttonMessages, null, scheduleTime, analytics, null, imageUrl);
    };

    _GamebotManager.prototype._scheduleMessage = function (message, buttonMessages, image, scheduleTime, analytics, gift, imageUrl) {
        var self = this;

        var notification = new InstantNotification();
        notification["reminderMessage"] = message;
        notification["scheduleTime"] = scheduleTime;

        if (image) {
            notification["image"] = image;
        }

        if (imageUrl) {
            notification["imageUrl"] = imageUrl;
        }

        notification["payloads"] = [{
                analytics: analytics,
                redeemCode: scheduleTime.getTime(),
                gift: gift ? (gift.giftType + "_" + gift.giftValue) : ""
            },
            {
                shortCutCreate: true
            }
        ];

        notification["buttons"] = buttonMessages;


        return new Promise(function (resolve, reject) {
            self._instantNotificationsService.scheduleNotification(messagingPlatformService.getPlayer().id, notification).then(
                function (notificationId) {
                    if (!notificationId) {
                        throw Error("Notification id seems empty!");
                    }
                    console.info("notificationId: " + notificationId);
                    resolve(notificationId);
                },
                function (reason) {
                    errorLoggingService.sendError(err);
                    console.error("[GamebotManager] Couldn't schedule the instant message ->", reason);
                }
            );
        });


    };

    _GamebotManager.prototype._getRandomGiftMessage = function () {
        var randomChoice = Math.floor(Math.random() * 3);

        var now = TimeManager.getDate();

        //If this month doesn't have any days left to unlock. 
        if (UnlockDataManager.getAmountOfLockedDaysInMonth(now.getFullYear(), now.getMonth()) <= 0) {
            //Choose at random a number that is non-zero
            randomChoice = Math.floor(Math.random() * 2) + 1;
        }

        return GiftManager.getNewGiftMessage(randomChoice);
    };

    return new _GamebotManager();
}());
