var customEffects = {};

customEffects.scaleHorizontalAndVertical = function (component, effect, time) {
	"use strict";
	var ease = effect.ease === undefined ? tbEase.easeLinear : effect.ease,
		easeArgument = effect.easeArgument === undefined ? undefined : effect.easeArgument,
		startXScale = effect.startXScale === undefined ? 1 : effect.startXScale,
		endXScale = effect.endXScale === undefined ? 1 : effect.endXScale,
		startYScale = effect.startYScale === undefined ? 1 : effect.startYScale,
		endYScale = effect.endYScale === undefined ? 1 : effect.endYScale;

	component.xScale = ease(time, startXScale, endXScale - startXScale, effect.duration, easeArgument);
	component.yScale = ease(time, startYScale, endYScale - startYScale, effect.duration, easeArgument);
};

/**
 * scale effect, but only horizontal scaling
 */
customEffects.scaleHorizontal = function (component, effect, time) {
	"use strict";
	var ease = effect.ease === undefined ? tbEase.easeLinear : effect.ease,
		easeArgument = effect.easeArgument === undefined ? undefined : effect.easeArgument,
		startScale = effect.startScale === undefined ? 1 : effect.startScale,
		endScale = effect.endScale === undefined ? 1 : effect.endScale;
	component.xScale = ease(time, startScale, endScale - startScale, effect.duration, easeArgument);
};

customEffects.scaleVertical = function (component, effect, time) {
	"use strict";
	var ease = effect.ease === undefined ? tbEase.easeLinear : effect.ease,
		easeArgument = effect.easeArgument === undefined ? undefined : effect.easeArgument,
		startScale = effect.startScale === undefined ? 1 : effect.startScale,
		endScale = effect.endScale === undefined ? 1 : effect.endScale;
	component.yScale = ease(time, startScale, endScale - startScale, effect.duration, easeArgument);
};

/**
 * scale effect, but only horizontal scaling
 */
customEffects.scale = function (component, effect, time) {
	"use strict";
	var ease = effect.ease === undefined ? tbEase.easeLinear : effect.ease,
		easeArgument = effect.easeArgument === undefined ? undefined : effect.easeArgument,
		startScale = effect.startScale === undefined ? 1 : effect.startScale,
		endScale = effect.endScale === undefined ? 1 : effect.endScale;
	component.xScale = ease(time, startScale, endScale - startScale, effect.duration, easeArgument);
	component.yScale = ease(time, startScale, endScale - startScale, effect.duration, easeArgument);
};

/**
 * effect for scrolling in a scroll box
 */
customEffects.scrollBoxScroll = function (component, effect, time) {
	"use strict";
	if (!component.scroll) {
		return;
	}
	effect.startScrollX = effect.startScrollX !== undefined ? effect.startScrollX : component.scroll.x;
	effect.startScrollY = effect.startScrollY !== undefined ? effect.startScrollY : component.scroll.y;
	effect.endScrollX = effect.endScrollX !== undefined ? effect.endScrollX : component.scroll.x;
	effect.endScrollY = effect.endScrollY !== undefined ? effect.endScrollY : component.scroll.y;
	var ease = effect.ease === undefined ? tbEase.easeLinear : effect.ease;

	component.scrollBackTimer.x = 0; // this stops the component from performing any animations
	component.scrollBackTimer.y = 0;

	component.scroll.x = ease(time, effect.startScrollX, effect.endScrollX - effect.startScrollX, effect.duration, effect.easeArgument);
	component.scroll.y = ease(time, effect.startScrollY, effect.endScrollY - effect.startScrollY, effect.duration, effect.easeArgument);

	component.container.x = component.scroll.x + component.centerOffset.x; // hack so it also works when deactivated
	component.container.y = component.scroll.y + component.centerOffset.y;
};

/**
 * applies a countup effect for labels
 */
customEffects.countUp = function (component, effect, time) {
	"use strict";
	var ease = effect.ease === undefined ? tbEase.easeLinear : effect.ease,
		easeArgument = effect.easeArgument === undefined ? undefined : effect.easeArgument,
		startNumber = effect.startNumber === undefined ? 0 : effect.startNumber,
		endNumber = effect.endNumber === undefined ? 0 : effect.endNumber,
		prefix = effect.prefix === undefined ? "" : effect.prefix,
		postfix = effect.postfix === undefined ? "" : effect.postfix,
		separator = effect.separator === undefined ? "" : effect.separator, // separator for the 000's
		tickSound = effect.tickSound === undefined ? null : effect.tickSound;

	effect.previousNumber = effect.previousNumber === undefined ? startNumber : effect.previousNumber;

	var currentNumber = Math.round(ease(time, startNumber, endNumber - startNumber, effect.duration, easeArgument));
	var str = currentNumber.toString();
	component.text = "";

	if (separator !== "") {
		// format string with the separator (1000 -> 1,000)
		for (var i = 0; i < str.length; i += 1) {
			if ((str.length - i) % 3 === 0 && i !== 0) {
				component.text += separator;
			}
			component.text += str.charAt(i);
		}
	} else {
		component.text = str;
	}

	component.text = prefix + component.text + postfix;
	component.recreate();

	// ticking sound

	if (effect.previousNumber !== currentNumber && tickSound) {
		tgfAudio.play(tickSound, 0);
	}

	effect.previousNumber = currentNumber;
};

/**
 * patches audio support for effects into an existing component by setting the 
 * onSubEffectStart, onSubEffectEnd and onHide functions.
 * If on of these methods already exists, the old method is preserved.
 */
customEffects.applyAudioToComponent = function (comp) {
	"use strict";
	var oldFunc;

	var onStart = function (component, effect) {
		if (effect.audio) {
			var audio = effect.audio;
			audio.reference = tgfAudio.play(audio.file, audio.appearDelay);

			if (audio.loop) {
				tgfAudio.setLooping(audio.reference, true);
			}
		}
	};
	if (comp.onSubEffectStart) {
		oldFunc = comp.onSubEffectStart;

		comp.onSubEffectStart = function () {
			oldFunc.apply(this, arguments);
			onStart.apply(this, arguments);
		}
	} else {
		comp.onSubEffectStart = onStart;
	}

	var onEnd = function (component, effect) {
		if (effect.audio) {
			var audio = effect.audio;
			if (audio.loop) {
				tgfAudio.stop(audio.reference, audio.disappearDelay);
			}
		}
	};
	if (comp.onSubEffectEnd) {
		oldFunc = comp.onSubEffectEnd;

		comp.onSubEffectEnd = function () {
			oldFunc.apply(this, arguments);
			onEnd.apply(this, arguments);
		}
	} else {
		comp.onSubEffectEnd = onEnd;
	}

	var onHide = function (comp) {
		var index = comp.getSubEffect();
		if (index !== -1) {
			onEnd(comp, comp.effects[index]);
		}
	};

	if (comp.onHide) {
		oldFunc = comp.onHide;

		comp.onHide = function () {
			oldFunc.apply(this, arguments);
			onHide.apply(this, arguments);
		}
	} else {
		comp.onHide = onHide;
	}
};
