function PlayerDataCollection() {
    //Array of PlayerData
    this._data = [];
    this._uninitializedProfilePictures = [];
}

PlayerDataCollection.prototype.getById = function (userId) {
    for (var i = 0; i < this._data.length; i++) {
        if (this._data[i].getID() === userId) {
            return this._data[i];
        }
    }
    return null;
};

/**
 * Checks if the playerdata object for this userId already exists.
 * Otherwise creates a new playerData object and keeps the reference.
 * 
 * @param {number} userId 
 * @param {string} name 
 * @param {string} profilePictureUrl 
 * @param {string} rank 
 * @param {string} locale
 * 
 * @returns {PlayerData} playerData
 */
PlayerDataCollection.prototype.add = function (userId, name, profilePictureUrl, rank, locale, country, isFriend) {
    var playerData = this.getById(userId);
    if (playerData) {
        if (!playerData.isFriend() && isFriend) {
            playerData.setFriend(true);
        }
        return playerData;
    }

    var newPlayerData = new PlayerData(userId, name, profilePictureUrl, rank, locale, country, isFriend);
    this._uninitializedProfilePictures.push(newPlayerData);
    this._data.push(newPlayerData);

    return this._data[this._data.length - 1];
};

PlayerDataCollection.prototype.getUninitializedProfilePictures = function () {
    return this._uninitializedProfilePictures;  
};

PlayerDataCollection.prototype.clearUninitializedProfilePictures = function () {
    this._uninitializedProfilePictures.length = 0;  
};
