/**
 * PlayerData.
 * Data class used to hold leaderboard entry data.
 *
 * @param {number} userId
 * @param {string} name
 * @param {string} profilePictureUrl
 * @param {string} rank
 * @param {string} locale
 * @param {string} country
 * @param {string} vipExpirationDate
 * @param {string} isFriend
 */
function PlayerData(userId, name, profilePictureUrl, rank, locale, country, vipExpirationDate, isFriend) {
    this._userId = userId;
    this._name = name;
    this._profilePictureUrl = profilePictureUrl;
    this._rank = rank;
    this._locale = locale;
    this._country = country;
    this._isVIP = TimeManager.getDate().getTime() < vipExpirationDate;
    this._isFriend = isFriend;

    this._isChallengedThisSession = false;
}

PlayerData.prototype.getID = function () {
    return this._userId;
};

PlayerData.prototype.getName = function (friendsLeaderboard) {
    if (
        !friendsLeaderboard &&
        tgfSettings.leaderboard.nationalAndWorldMasked &&
        (this._userId != messagingPlatformService.getPlayer().id) &&
        !this._isFriend
    ) {
        return this._name.substring(0, 1) + "..." + this._name.substring(this._name.length - 1, this._name.length);
    }
    return this._name;
};

PlayerData.prototype.setProfilePicture = function (profilePicture) {
    this._profilePicture = profilePicture;
}

PlayerData.prototype.getProfilePicture = function (friendsLeaderboard) {
   /* if (
        !friendsLeaderboard &&
        tgfSettings.leaderboard.nationalAndWorldMasked &&
        (this._userId != messagingPlatformService.getPlayer().id) &&
        !this._isFriend
    ) {
        return DefaultProfilePictureHandler.getForUser(this._userId);
    }

    if (!this._profilePicture) {
        console.warn("[PLayerData] No Valid profile image found for this user. Make sure profile pictures are created from url before getting them. This warning might also occur for cases where the profile image url is empty.");
        return DefaultProfilePictureHandler.getForUser(this._userId);
    }*/

    return s_leaderboard_icon_world;

    // /return this._profilePicture;
};

PlayerData.prototype.getProfilePictureURL = function () {
    return this._profilePictureUrl;
}

PlayerData.prototype.getRank = function () {
    return this._rank;
}

PlayerData.prototype.getLocale = function () {
    return this._locale;
}

PlayerData.prototype.getCountry = function () {
    return this._country;
}

PlayerData.prototype.setRank = function (rank) {
    this._rank = rank;
}

PlayerData.prototype.isFriend = function () {
    return this._isFriend;
}

PlayerData.prototype.setFriend = function (value) {
    this._isFriend = value;
}

PlayerData.prototype.registerChallenge = function () {
    this._isChallengedThisSession = true;
}

PlayerData.prototype.isChallengedThisSession = function () {
    return this._isChallengedThisSession;
}

PlayerData.prototype.isVip = function () {
    return this._isVIP;
}

PlayerData.prototype.checkVipStatus = function () {
    this._isVIP = TimeManager.getDate().getTime() < VipMembership.expirationDate;
}
