/**
 * ~~~LeaderboardCollection
 * {
 *      //0 = current, 1 = one back, 2 = two back, etc
 *      this._months = []; //Array of Leaderboard instances
 * }~~~
 */

function LeaderboardCollection() {
    //0 = current, 1 = one back, 2 = two back, etc
    this._months = []; //Array of Leaderboard
}

LeaderboardCollection.prototype.set = function (leaderboard, targetIndex) {
    this._months[targetIndex] = leaderboard;
    return leaderboard;
}

LeaderboardCollection.prototype.refresh = function (index) {
    if (index && this._months.length < index) {
        this._months[index].refresh();
    } else {
        this._months[0].refresh();
    }
}

LeaderboardCollection.prototype.delete = function (index) {
    if (this._months[index]) {
        this._months[index] = undefined;
    }
}

LeaderboardCollection.prototype.getLeaderboard = function (monthsBack) {
    monthsBack = monthsBack || 0;
    return this._months[monthsBack];
};
