/** Class:
 * Leaderboard data class. It's role is to hold and return data. Should be devoid of any other functionality.
 */

function Leaderboard(leaderboardType) {
    this.type = {
        top: "top",
        bottom: "bottom"
    }

    this._leaderboardType = leaderboardType;

    this._leaderboardEntries = {
        top: [],
        bottom: []
    };

    this._associatedTab = null;
}

Leaderboard.tab = {
    friends: "friends",
    local: "local",
    global: "global"
};

/**
 * Add a data entry to the leaderboard.
 * Either to the top part or the bottom part of the leaderboard
 * (for example the top part with the top 10 entries, and the bottom part with the 'around me' entries.)
 * 
 * @param {LeaderboardEntry} leaderboardEntry 
 * @param {Leaderboard.type} leaderboardType 
 */
Leaderboard.prototype.addEntry = function (leaderboardEntry, leaderboardType) {
    this._leaderboardEntries[leaderboardType].push(leaderboardEntry);
};

Leaderboard.prototype.setAssociatedTab = function (tab) {
    this._associatedTab = tab;
};

Leaderboard.prototype.getAssociatedTab = function () {
    return this._associatedTab;
}

Leaderboard.prototype.getPlayerEntry = function () {
    //Search for the player entry in the top leaderboard
    for (var i = 0; i < this._leaderboardEntries.top.length; i++) {
        if (this._leaderboardEntries.top[i].getPlayerData().getID() == messagingPlatformService.getPlayer().id) {
            return this._leaderboardEntries.top[i];
        }
    }

    //Search for the player entry in the bottom leaderboard
    for (var i = 0; i < this._leaderboardEntries.bottom.length; i++) {
        if (this._leaderboardEntries.bottom[i].getPlayerData().getID() == messagingPlatformService.getPlayer().id) {
            return this._leaderboardEntries.bottom[i];
        }
    }
};

Leaderboard.prototype.existsOnTopLeaderboard = function (userId) {
    for (var i = 0; i < this._leaderboardEntries.top.length; i++) {
        if (this._leaderboardEntries.top[i].getPlayerData().getID() == userId) {
            return true;
        }
    }
    return false;
}

Leaderboard.prototype.getTopEntries = function () {
    return this._leaderboardEntries.top;
}

Leaderboard.prototype.getBottomEntries = function () {
    return this._leaderboardEntries.bottom;
}

Leaderboard.prototype.getEntries = function () {
    return this._leaderboardEntries.top.concat(this._leaderboardEntries.bottom);
}

Leaderboard.prototype.getLeaderboardType = function () {
    return this._leaderboardType;
};
