// The constructor for the dialog
/**
 * @constructor
 * @base tgfDialogs.Base
 */
tgfDialogs.LeaderboardDialog = function (properties) {
	"use strict";

	this.name = "LeaderboardDialog"; // The name of the dialog
	// Initialize properties
	this.initialize(tgfSettings.dialogDefaults.popUp);
	this.setProperties(tgfSettings.dialogDefaults.leaderboardDialog);

	this.dividerLabelProperties.font.fillColor = tgfSettings.theme.leaderboard.dividerTextColor;

	// Set user properties
	if (properties !== undefined) {
		this.setProperties(properties);
	}

	if (tgfSettings.theme.leaderboard && tgfSettings.theme.leaderboard.floatingEntryImage) {
		this.floatingPlayerButtonPropertiesTop.backgroundPictureProperties.image = tgfSettings.theme.leaderboard.floatingEntryImage;
		this.floatingPlayerButtonPropertiesBottom.backgroundPictureProperties.image = tgfSettings.theme.leaderboard.floatingEntryImage;
	}

	// custom fields
	this.leaderboardList = []; // list of all entries ({data: ..., component: ...})
	this.currentlyScrolling = false;
	this.disableFloatingPlayer = false;
	this.playerOutsideView = undefined;

	this.leaderboardLoaded = false;

	this.errorButton = null;
	this.errorMessage = null;
	this.errorImage = null;

	this.loadingText = null;
	this.loadingImage = null;

	this.currentErrorPriority = 0;
	this.errorCode = 'none';
};

// Inherit the base dialog
tgfDialogs.inherit(tgfDialogs.LeaderboardDialog, tgfDialogs.Base);

// ***************************************
// Preparing and showing
//      - These can be removed if no processing is required
// ***************************************

// Processing required when preparing the dialog for use
tgfDialogs.LeaderboardDialog.prototype.doPrepare = function () {
	"use strict";

	if (this.x === undefined) {
		this.x = tgfGraphics.visibleWidth / 2;
	}

	if (this.y === undefined) {
		this.y = tgfSettings.graphics.backgroundHeight / 2;
	}

	this.backgroundPictureProperties.image = ThemeController.getLeaderboardBackgroundImage();

	this.background = new tgfComponents.Picture(this.backgroundPictureProperties);
	this.background.y = -this.y + (tgfSettings.graphics.areaHeight / 2);

	this.addComponent(this.background);

	// anchors
	this.bottomAnchor = new tgfComponents.AnchorComponent({
		anchorCoordinates: new tbVector(0.5, 1)
	});
	this.addComponent(this.bottomAnchor);

	// extra container
	this.beforeScrollContainer = new tgfComponents.Container({});
	this.addComponent(this.beforeScrollContainer);

	//leaderboard tabs
	if (new Date(this._calendar.getSelectedYear(), this._calendar.getSelectedMonth(), 1) < tgfSettings.leaderBoardEarliestDate) {
		this.leaderboardErrorTooFarBack();
	} else {
		this.leaderboardTabsDialog = new tgfDialogs.LeaderboardsTabDialog({
			monthsBack: this._calendar.getAmountOfMonthsBack(),
			_selectedMonth: this._calendar.getSelectedMonth(),
			_selectedYear: this._calendar.getSelectedYear(),
			leaderboardsLoaded: this.loadLeaderboards.bind(this),
			leaderboardsCleared: this.clearLeaderboards.bind(this),
			leaderboardsErrorNoNetworkAvailable: this.leaderboardErrorNoNetwork.bind(this),
			leaderboardsErrorNoEntries: this.leaderboardErrorNoEntries.bind(this),
		});
		this.leaderboardTabsDialog.show();
	}

	this._bottomGradient = new tgfComponents.Picture({
		image: s_ui_leaderboard_gradient_bottom,
		y: -s_ui_leaderboard_gradient_bottom.height/2
	});
	this.bottomAnchor.addComponent(this._bottomGradient);

	// scroll component
	this.leaderboardScroll = null; // loads later
};

tgfDialogs.LeaderboardDialog.prototype.leaderboardErrorTooFarBack = function () {
	'use strict';
	if (this.currentErrorPriority > 1) {
		return;
	}
	this.currentErrorPriority = 1;

	this.errorCode = 'too early';

	this.removeLoadingAndStatusText();

	this.displayErrorPicture();

	var msg = tgfDictionary.getText("TooFarBackError");
	this.displayErrorMessage(msg);

	//button that returns the player to the current month.
	var buttonText = tgfDictionary.getText('BackToCurrentMonth');

	this.displayErrorButton(buttonText, function () {
		EventSystem.Global.dispatchEvent(UI_Event.GO_TO_CURRENT_MONTH_BUTTON_CLICKED);
	});
};

tgfDialogs.LeaderboardDialog.prototype.leaderboardErrorNoNetwork = function () {
	'use strict';
	if (this.currentErrorPriority > 1 || this.leaderboardLoaded) {
		return;
	}
	this.currentErrorPriority = 1;

	if (this.errorCode === 'network') {
		return;
	}

	this.errorCode = 'network';

	this.displayErrorPicture();

	var msg = tgfDictionary.getText("TimeoutError");
	this.displayErrorMessage(msg);

	//button that returns the player to the puzzles.
	var buttonText = tgfDictionary.getText("BackToPuzzles");
	this.displayErrorButton(buttonText, this.backToPuzzles);
};

tgfDialogs.LeaderboardDialog.prototype.leaderboardErrorNoEntries = function () {
	'use strict';

	if (this.currentErrorPriority > 1) {
		return;
	}
	this.currentErrorPriority = 1;

	this.errorCode = 'no entries';

	var msg = tgfDictionary.getText("NoEntriesError");
	this.displayErrorMessage(msg);

	if (this.leaderboardScroll) {
		this.leaderboardScroll.scrollVertical = false;
	}

	var now = TimeManager.getDate();
	//show button that either returns to current month (when in previous month) or to challenge a friend (when in current month)
	if (
		now.getMonth() === this._calendar.getSelectedMonth() &&
        now.getFullYear() === this._calendar.getSelectedYear()
	) {
		var buttonText = tgfDictionary.getText('BigChallengeButton');
		this.displayErrorButton(buttonText, this.onInviteFriendsButtonClicked);
	} else {
		var buttonText = tgfDictionary.getText('BackToCurrentMonth');
		this.displayErrorButton(buttonText, this.backToCurrentMonth);
	}
};

tgfDialogs.LeaderboardDialog.prototype.clearLeaderboards = function () {
	'use strict';

	// Make sure all looping audio stops when switching tab.
	tgfAudio.stop(a_score_counter.name);
	tgfAudio.stop(a_scale_up.name);
	tgfAudio.stop(a_scale_down.name);
	tgfAudio.stop(a_entry_move.name);
	tgfAudio.stop(a_score_counter.name);
	tgfAudio.stop(a_entry_update_position.name);

	this.leaderboardLoaded = false;
	this.clearErrorComponents();

	// loading
	this.loadingImage = new tgfComponents.Picture(this.loadingPictureProperties);
	this.loadingImage.effects = {
		effect: tgfEffects.rotate,
		startAngle: 0,
		endAngle: -360,
		duration: 2.0
	};
	this.addComponent(this.loadingImage);
	this.loadingText = new tgfComponents.Label(this.loadingTextProperties);
	this.addComponent(this.loadingText);

	this.loadingImage.activate();
	this.loadingText.activate();
};

tgfDialogs.LeaderboardDialog.prototype.clearErrorComponents = function () {
	"use strict";

	this.removeCurrentEntries();

	this.errorCode = false;

	this.hidePlayerButton();

	this.removeLoadingAndStatusText();

	this.removeErrorMessage();
};

/**
 * set Leaderboard related variables
 */
tgfDialogs.LeaderboardDialog.prototype.loadLeaderboards = function (leaderboardData, positionIndicator, showFlags) {
	"use strict";
	this.clearErrorComponents();

	if (!leaderboardData) {
		this.leaderboardErrorNoEntries();
	} else {
		this.belowLeaderboards = tgfSettings.dialogDefaults.leaderboardDialog.belowLeaderboards; // *sigh*
	}

	var self = this;

	this.positionIndicator = positionIndicator;

	if (leaderboardData) {
		this.leaderboardData = leaderboardData;
	}

	if (this.leaderboardData) {
		self.prepareEntries(this.leaderboardData, showFlags);

		this.leaderboardData.oldPlayerData = null;
		this.leaderboardLoaded = true;
	} else {
		this.leaderboardLoaded = false;
	}

	this.removeLoadingAndStatusText();

	if (this.errorCode !== 'no entries') {
		this.removeErrorMessage();
	}
};

tgfDialogs.LeaderboardDialog.prototype.displayErrorButton = function (message, onClick) {
	'use strict';

	this.belowLeaderboards = 'none';

	this.removeLoadingAndStatusText();

	this.errorButton = new tgfComponents.Button(this.errorButtonProperties);

	this.errorButton.setProperties({
		text: message,
		onClick: onClick
	});

	this.addComponent(this.errorButton);

	this.errorButton.activate();
};

tgfDialogs.LeaderboardDialog.prototype.displayErrorPicture = function () {
	'use strict';

	this.errorImage = new tgfComponents.Picture(this.errorPictureProperties);
	this.addComponent(this.errorImage);

	this.errorImage.activate();
};

tgfDialogs.LeaderboardDialog.prototype.displayErrorMessage = function (message) {
	'use strict';

	this.errorMessageLabelProperties.text = message;
	this.errorMessage = new tgfComponents.Label(this.errorMessageLabelProperties);
	this.addComponent(this.errorMessage);

	this.errorMessage.activate();
};

tgfDialogs.LeaderboardDialog.prototype.removeCurrentEntries = function () {
	'use strict';

	// leaderboard scroll
	if (this.leaderboardScroll !== null) {
		this.removeComponent(this.leaderboardScroll);

		this.leaderboardScroll = undefined;
	}
}

tgfDialogs.LeaderboardDialog.prototype.removeLoadingAndStatusText = function () {
	'use strict';

	if (this.loadingText !== null) {
		// hide loading stuff
		this.removeComponent(this.loadingText);
		this.loadingText.free();
		this.loadingText = null;
	}

	if (this.loadingImage !== null) {
		this.removeComponent(this.loadingImage);
		this.loadingImage.free();
		this.loadingImage = null;
	}
};

tgfDialogs.LeaderboardDialog.prototype.removeErrorMessage = function () {
	'use strict';

	if (this.errorButton !== null) {
		this.removeComponent(this.errorButton);
		this.errorButton.free();
		this.errorButton = null;
	}

	if (this.errorMessage !== null) {
		this.removeComponent(this.errorMessage);
		this.errorMessage.free();
		this.errorMessage = null;
	}

	if (this.errorImage !== null) {
		// hide loading stuff
		this.removeComponent(this.errorImage);
		this.errorImage.free();
		this.errorImage = null;
	}
};

tgfDialogs.LeaderboardDialog.prototype.onInviteFriendsButtonClicked = function () {
	'use strict';

	InviteService.share({
			analytics: ["custom_share", "leaderboard_invite"]
		})
		.then(function(){
			console.log("[LeaderboardDialog] Invite success");

			SudokuAnalytics.reportLeaderboardShareInvite();
			// MessyAnalytics.customShare("invite");
		})
		.catch(function (err) {
			errorLoggingService.sendError(err);
			console.error("[LeaderboardDialog] Invite failed. Error: " + err + "\n" + err.stack);
		});
}

/**
 * Creates components related to the leaderboard data
 * @param list - list of player-data objects
 */
tgfDialogs.LeaderboardDialog.prototype.prepareEntries = function (leaderboardData, showFlags) {
	"use strict";
	var self = this;
	var i, data;

	this.dividers = [];

	//Animation
	var playerEntry = leaderboardData.getPlayerEntry();

	this.isFriendsLeaderboard = leaderboardData.getAssociatedTab() === Leaderboard.tab.friends;

	if (playerEntry) {
		this.playerPosition = playerEntry.getPosition();
	}

	var previousPosition = LeaderboardManager.getPreviousPlayerPositionOnFriendsLeaderboard();
	this.previousScore = LeaderboardManager.getPreviousPlayerScoreOnFriendsLeaderboard();

	var leaderboardEntries = leaderboardData.getEntries();

	if (
		playerEntry &&
		this.showPlayerTransition &&
		previousPosition &&
		this.previousScore &&
		leaderboardData.getAssociatedTab() === Leaderboard.tab.friends &&
		leaderboardData.getLeaderboardType().month === (TimeManager.getDate().getMonth() + 1)
	) {
		//Reset variables to make sure we only attempt to show the animation once.
		this.showPlayerTransition = false;
		LeaderboardManager.setPreviousPlayerPositionOnFriendsLeaderboard(null);
		LeaderboardManager.setPreviousPlayerScoreOnFriendsLeaderboard(null);

		//Save the new score and set the playerEntry to the old score.
		this.newScore = playerEntry.getScore();
		playerEntry.setScore(this.previousScore);

		if (previousPosition > this.playerPosition) {
			// set player to old position
			leaderboardEntries.splice(this.playerPosition - 1, 1); // move player to old position
			leaderboardEntries.splice(previousPosition - 1, 0, playerEntry);

			// remember for later
			this.newPlayerPosition = this.playerPosition;
			this.previousPlayerPostion = previousPosition;

			//intiate animations
			this.startAnimAlarmId = tbGame.addAlarm(this.movePlayerDelay, 1, this);
			this.showingStartAnimation = true;
		} else {
			this.startCountAnimAlarmId = tbGame.addAlarm(this.movePlayerDelay, 1, this);
			this.showingStartAnimation = true;
		}
	}

	// keep track
	this.leaderboardList = [];

	var components = [];

	this.leaderboardScroll = new tgfComponents.ScrollBox(this.leaderboardScrollProperties);
	var scrollPos = 0; // position to scroll to
	var playerData;

	var lastPos = null;
	var currPos = null;
	var divAddedYet = false;

	for (i = 0; i < leaderboardEntries.length; i++) {
		data = leaderboardEntries[i];
		var prevData = i === 0 ? null : leaderboardEntries[i - 1];
		var divider;
		// 0 scores divider
		if (!divAddedYet && data.getScore() === 0 && !data.isPlayer()) {
			// add a divider
			divider = this.addDividerComponent(i, tgfDictionary.getText("LeaderboardChallengeDivider"));
			components.push(divider);

			divAddedYet = true;
		} else
			// jump divider
			if (i == 10 && leaderboardEntries.length > 10 && leaderboardData.getAssociatedTab() !== Leaderboard.tab.friends && !divAddedYet) {
				// add a divider
				divAddedYet = true;
				divider = this.addDividerComponent(i);
				components.push(divider);
			}


		var leaderboardType = leaderboardData.getLeaderboardType();
		var currentDate = TimeManager.getDate();

		// Month + 1 because january = 0 in js
		var isCurrentMonth = currentDate.getMonth() + 1 == leaderboardType.month && currentDate.getFullYear() == leaderboardType.year;




		// add divider manually
		currPos = data._position;

		if (lastPos && !divAddedYet && leaderboardData.getAssociatedTab() !== Leaderboard.tab.friends) {

			if (currPos > (lastPos + 1)) {
				// console.log('move divided here please');
				divAddedYet = true;
				divider = this.addDividerComponent(i);
				components.push(divider);
			}
		}
		lastPos = currPos;
		// console.log(data._position);
		// end add divider manually

		var comp = this.getLeaderboardEntryComponent(data, i, showFlags, isCurrentMonth);

		components.push(comp);
		if (data.isPlayer()) {
			scrollPos = comp.y;
			playerData = data;
		}
		this.leaderboardList.push({
			data: data,
			component: comp
		});
	}

	if (this.belowLeaderboards === "message") {
		var endMessageLabel = new tgfComponents.Label(this.endMessageLabelProperties);
		endMessageLabel.setProperties({
			x: this.leaderboardScrollProperties.width / 2 - this.leaderboardScroll.width / 2,
			y: this.leaderboardEntryDistance / 2 - this.leaderboardScroll.height / 2 + this.getEntryY(i),
		});
		components.push(endMessageLabel);
	} else if (this.belowLeaderboards === "button" && isCurrentMonth && tgfSettings.leaderboard.bigShareButtonEnabled) {
		var endButton = new tgfComponents.Button(this.endButtonProperties);

		endButton.setProperties({
			x: this.leaderboardScrollProperties.width / 2 - this.leaderboardScroll.width / 2,
			y: this.leaderboardEntryDistance / 2 - this.leaderboardScroll.height / 2 + this.getEntryY(i),
			cancelEvents: false,
		});

		endButton.onClick = this.onInviteFriendsButtonClicked;

		components.push(endButton);
	}

	this.leaderboardScroll.components = components;
	this.leaderboardScroll.areaX = -this.leaderboardScroll.width / 2;
	this.leaderboardScroll.areaY = -this.leaderboardScroll.height / 2;
	this.leaderboardScroll.areaWidth = this.leaderboardScroll.width;
	this.leaderboardScroll.areaHeight = components.length * this.leaderboardEntryDistance + this.leaderboardScrollMarginTop + this.leaderboardScrollMarginBottom;
	this.insertComponent(this.leaderboardScrollComponentIndex, this.leaderboardScroll);

	if (leaderboardEntries.length > 1) {
		this.leaderboardScroll.activate();
	} else {
		this.leaderboardScroll.show();
	}

	this.updateScrollComponentDimensions();

	if (this.start === "player" || this.showingStartAnimation) {
		this.leaderboardScroll.scroll.y = Math.min(Math.max(-scrollPos, this.leaderboardScroll.getMinY()), this.leaderboardScroll.getMaxY());
	} else {
		// start at 0
		this.leaderboardScroll.scroll.y = this.leaderboardScroll.getMaxY();

		if (this.start === "scrollToPlayer") {
			this.scrollToPlayer(0.5, 1.0, true);
		}
	}
	this.leaderboardScroll.scrollVertical = true;

	this.currentlyScrolling = false;

	if (this.floatingPlayerButtonBottom) {
		this.bottomAnchor.removeComponent(this.floatingPlayerButtonBottom);
	}
	if (this.floatingPlayerButtonTop) {
		this.beforeScrollContainer.removeComponent(this.floatingPlayerButtonTop);
	}

	// floating player button
	var floatingPlayerData = playerData; //clone the playerData.
	floatingPlayerData.setScore(this.newScore || playerData.getScore());

	this.floatingPlayerButtonTop = this.getFloatingPlayerButton(this.floatingPlayerButtonPropertiesTop, floatingPlayerData, -1);
	this.floatingPlayerButtonBottom = this.getFloatingPlayerButton(this.floatingPlayerButtonPropertiesBottom, floatingPlayerData, 1);

	this.bottomAnchor.addComponent(this.floatingPlayerButtonBottom);
	this.beforeScrollContainer.addComponent(this.floatingPlayerButtonTop);
};

tgfDialogs.LeaderboardDialog.prototype.getFloatingPlayerButton = function (properties, data, directionFactor) {
	"use strict";
	var self = this;

	//do not show flag for player floating entry
	var playerCopy = this.getLeaderboardEntryComponent(data, this.playerPosition, false, false);

	playerCopy.setProperties(this.floatingPlayerButtonProperties);
	playerCopy.setProperties(properties);

	//remember start position
	playerCopy.startX = playerCopy.x;
	playerCopy.startY = playerCopy.y;
	playerCopy.directionFactor = directionFactor;

	if (this.positionIndicator && this.positionIndicator.dif > 0) {
		var updatedPositionImgIndicator = new tgfComponents.Picture(this.floatingPlayerButtonProperties.updatedPositionIndicatorImgProperties);

		updatedPositionImgIndicator.image = this.positionIndicator.img;

		playerCopy.components = [updatedPositionImgIndicator];
	}

	playerCopy.onClick = function (component) {
		if (self.playerOutsideView) {
			// wobble feedback
			if (!self.currentlyScrolling) {
				component.parent.effects = self.fxButtonWobble;
				component.parent.repeatEffect = 1;
				component.parent.restartEffect();
			}
			// scroll
			self.scrollToPlayer();
		}
	};

	return playerCopy;
};

tgfDialogs.LeaderboardDialog.prototype.getEntryY = function (pos) {
	"use strict";

	var offset = 0;

	for (var i = 0; i < this.dividers.length; i++) {
		var divPos = this.dividers[i].position;
		if (divPos <= pos) {
			offset += this.dividerHeight;
		}
	}

	return pos * this.leaderboardEntryDistance + this.leaderboardScrollMarginTop + offset;
};

tgfDialogs.LeaderboardDialog.prototype.handleAlarm = function (alarmId) {
	"use strict";
	if (alarmId === this.startAnimAlarmId) {
		this.movePlayerToNewPosition(this.newPlayerPosition, this.previousPlayerPostion);
	} else if (alarmId === this.startCountAnimAlarmId) {
		var playerPos = this.findPlayerPosition();

		var playerComp = this.leaderboardList[playerPos].component;

		this.setPointLabelAnimation(playerComp, this.movePlayerDelay / 1000, 1);
	}
};

tgfDialogs.LeaderboardDialog.prototype.addDividerComponent = function (pos, text) {
	"use strict";

	text = text || "";

	//remember divider for spacing
	this.dividers.push({
		position: pos,
	});

	var container = new tgfComponents.Container({
		x: tgfScale(0),
		y: this.getEntryY(pos - 1) + this.leaderboardEntryDistance / 2 - this.leaderboardScroll.height / 2 +
			this.leaderboardEntryDistance / 2 + this.dividerHeight / 2, // meh
	});

	this.dividerLabelProperties.text = text;
	var label = new tgfComponents.Label(this.dividerLabelProperties);
	var labelWidth = StringUtil.getTextWidth(text, this.dividerLabelProperties.font);
	var totalDots = this.dividerWidth / this.dividerDotSeparation;

	for(var i = 0; i < totalDots; i++) {
		var x = -(this.dividerWidth * 0.5) + (this.dividerDotSeparation * i);

		if(x < labelWidth * 0.5 && x > -labelWidth * 0.5) {
			continue;
		}

		var dot = new tgfComponents.Picture(this.dividerDotProperties);
		dot.x = x;
		container.addComponent(dot);
	}

	container.addComponent(label);

	return container;
};

tgfDialogs.LeaderboardDialog.prototype.getLeaderboardEntryComponent = function (data, position, showFlag, isCurrentMonth) {
	"use strict";

	var self = this;
	if (!data.getPosition()) {
		data.setPosition(position + 1);
	}
	var entry = new tgfComponents.LeaderboardEntry({
		x: this.leaderboardScrollProperties.width / 2 - this.leaderboardScroll.width / 2,
		y: this.leaderboardEntryDistance / 2 - this.leaderboardScroll.height / 2,
		isCurrentMonth: isCurrentMonth,
		isFriendsLeaderboard: this.isFriendsLeaderboard
	}, data, showFlag, position, this.positionIndicator);
	entry.y = entry.y + this.getEntryY(position);
	return entry;
};

tgfDialogs.LeaderboardDialog.prototype.scrollToPlayer = function (delay, duration, disableFloatingPlayer) {
	"use strict";
	var self = this;
	if (this.currentlyScrolling) {
		return;
	}
	delay = delay !== undefined ? delay : 0;
	duration = duration !== undefined ? duration : this.scrollToPlayerDuration;

	disableFloatingPlayer = disableFloatingPlayer ? true : false;

	var playerPos = this.findPlayerPosition();
	var endY = this.getEntryY(playerPos) + this.leaderboardEntryDistance / 2 - this.leaderboardScroll.height / 2; // meh
	this.scrollTo(endY, delay, duration, disableFloatingPlayer);
};

/**
 * Anim. logic
 */

tgfDialogs.LeaderboardDialog.prototype.findPlayerPosition = function () {
	"use strict";
	return this.leaderboardList.findIndex(function (element) {
		return element.data.isPlayer();
	});
};

tgfDialogs.LeaderboardDialog.prototype.movePlayerToNewPosition = function (newPos, oldPos) {
	"use strict";
	var i, comp;
	// get player position
	//Make leaderboard positions correspond to the indexes in the leaderboardList
	newPos -= 1;
	oldPos -= 1;

	var playerComp = this.leaderboardList[oldPos].component;

	// save old positions
	for (i = 0; i < this.leaderboardList.length; i++) {
		comp = this.leaderboardList[i].component;
		comp.leaderboardOldPos = i;
	}

	// move player in array
	this.leaderboardList.splice(oldPos, 1);
	this.leaderboardList.splice(newPos, 0, {
		component: playerComp,
		data: playerComp.data
	});

	// figure out some timing
	var pointDifference = this.newScore - this.previousScore;
	var countUpDuration = this.playerPointsCounterDurationBase + this.playerPointsCounterDurationFactor * Math.abs(pointDifference);

	if (newPos < oldPos) {
		// start effects for all individual components, based on their position change
		for (i = 0; i < this.leaderboardList.length; i++) {
			comp = this.leaderboardList[i].component;
			this.setMoveEntryEffect(comp, comp.leaderboardOldPos, i, countUpDuration);
		}
	}
	var waitDuration = newPos < oldPos ? this.fxPopUp.duration + this.playerMoveDelay1 : 0;
	this.setPointLabelAnimation(playerComp, waitDuration, countUpDuration);
};

tgfDialogs.LeaderboardDialog.prototype.playAnimationSounds = function (comp) {
	// more sound
	comp.onSubEffectStart = function (component, effect) {
		if (effect.audio) {
			var audio = effect.audio;
			audio.reference = tgfAudio.play(audio.file, audio.appearDelay);

			if (audio.loop) {
				tgfAudio.setLooping(audio.reference, true);
			}
		}
	};

	comp.onSubEffectEnd = function (component, effect) {
		if (effect.audio) {
			var audio = effect.audio;
			if (audio.loop) {
				tgfAudio.stop(audio.reference, audio.disappearDelay);
			}
		}
	};
};

tgfDialogs.LeaderboardDialog.prototype.setPointLabelAnimation = function (playerComp, waitDuration, countUpDuration) {
	"use strict";

	if (playerComp.pointsLabel) {
		// independent player effects// label count up effect
		var pointsLabel = playerComp.pointsLabel;
		pointsLabel.effects = [];
		if (waitDuration > 0) {
			pointsLabel.effects.push({
				effect: tgfEffects.nothing,
				duration: waitDuration
			});
		}

		this.fxCountUp.duration = countUpDuration;
		this.fxCountUp.startNumber = this.previousScore;
		this.fxCountUp.endNumber = this.newScore;

		pointsLabel.effects.push(this.fxCountUp);

		customEffects.applyAudioToComponent(pointsLabel);

		pointsLabel.repeatEffect = 1;
		pointsLabel.restartEffect();
	}
};

/**
 * sets a effect or series of effects for a component
 * that moves it to position newPos, assuming it's at position oldPos
 */
tgfDialogs.LeaderboardDialog.prototype.setMoveEntryEffect = function (comp, oldPos, newPos, countUpDuration) {
	"use strict";
	var self = this;
	// if (oldPos === newPos) {
	// 	return; // for now, exception for player might apply
	// }

	// reset effects for the entry
	comp.effects = [];
	comp.repeatEffect = 1;

	var moveDuration = this.moveDurationBase + this.moveDurationFactor * Math.abs(newPos - oldPos);

	if (comp.data.isPlayer()) {
		// accomodate for player counter
		if (newPos < oldPos) {
			// generate the array of effects
			var endY = comp.y + this.getEntryY(newPos) - this.getEntryY(oldPos);
			this.bringComponentToFront(comp);
			comp.effects.push(this.fxPopUp);
			comp.effects.push({
				effect: tgfEffects.nothing,
				duration: this.playerMoveDelay1 + countUpDuration + this.playerMoveDelay2
			});

			this.fxMoveEntry.duration = moveDuration;
			this.fxMoveEntry.startX = comp.x;
			this.fxMoveEntry.startY = comp.y;
			this.fxMoveEntry.endX = comp.x;
			this.fxMoveEntry.endY = endY;

			comp.effects.push(this.fxMoveEntry);

			comp.effects.push({
				effect: tgfEffects.nothing,
				duration: this.playerMoveDelay3
			});
			comp.effects.push(this.fxPopDown);

			// weird parallel effects magic
			comp.effects.push([{
					effect: tgfEffects.nothing,
					duration: this.fxHorizontalWobble.reduce(function (a, b) {
						return a.duration + b.duration;
					}),
					audio: this.hurraySounds[newPos],
				},
				this.fxHorizontalWobble
			]);

			customEffects.applyAudioToComponent(comp);

			// scroll
			this.scrollTo(endY, this.fxPopUp.duration + this.playerMoveDelay1 + countUpDuration + this.playerMoveDelay2, moveDuration, true);
		}
	} else {
		// non-player transition
		// generate array of effects
		comp.effects.push({
			effect: tgfEffects.nothing,
			duration: 0.1
		});

		comp.effects.push({
			effect: tgfEffects.move,
			duration: 0.4,
			startX: comp.x,
			startY: comp.y,
			endX: comp.x,
			endY: comp.y + this.getEntryY(newPos) - this.getEntryY(oldPos) // meh
		});
	}

	// start the effects for the entry
	comp.restartEffect();

	// add an extra effect for the position labels (fade from old number to new number)
	var positionLabel = comp.positionLabel;
	positionLabel.effects = [];
	var fadeEffects = [];
	// fade effect
	fadeEffects.push({
		effect: tgfEffects.nothing,
		duration: comp.data.isPlayer ? this.fxPopUp.duration + this.playerMoveDelay1 + countUpDuration + this.playerMoveDelay2 + moveDuration : 0.2
	});
	fadeEffects.push({
		effect: tgfEffects.fadeOut,
		duration: comp.data.isPlayer ? 0.2 : 0.1
	});
	fadeEffects.push({
		effect: tgfEffects.fadeIn,
		duration: comp.data.isPlayer ? 0.2 : 0.1
	});

	if (!comp.data.isPlayer) {
		positionLabel.effects = fadeEffects;

		positionLabel.onSubEffectStart = function (component, effect) {
			if (effect.effect === tgfEffects.fadeIn) {
				comp.data.position = newPos + 1;
				comp.updateLabel();
			}
		};
	} else {
		// label count up effect
		positionLabel.effects.push({
			effect: tgfEffects.nothing,
			duration: this.fxPopUp.duration + this.playerMoveDelay1 + countUpDuration + this.playerMoveDelay2,
		});
		positionLabel.effects.push({
			effect: customEffects.countUp,
			duration: moveDuration,
			startNumber: oldPos + 1,
			endNumber: newPos + 1,
			postfix: ".",
			tickSound: a_entry_update_position
		});
	}

	positionLabel.repeatEffect = 1;
	positionLabel.restartEffect();

	// add effect for top three markers
	var marker = comp.topThreeMarker;
	marker.effects = fadeEffects;
	marker.onSubEffectStart = function (component, effect) {
		if (effect.effect === tgfEffects.fadeIn) {
			comp.position = newPos;
			comp.updateMarker();
		}
	};

	marker.repeatEffect = 1;
	marker.restartEffect();
};

tgfDialogs.LeaderboardDialog.prototype.scrollTo = function (yPosition, waitDuration, scrollDuration, disableFloatingPlayer) {
	"use strict";
	var self = this;

	if (scrollDuration <= 0) {
		return;
	}

	if (!this.leaderboardScroll) {
		console.warn("Tried to scroll a non-existant leaderboard element");
		return;
	}

	this.currentlyScrolling = true;
	if (disableFloatingPlayer) {
		this.disableFloatingPlayer = true;
	}
	this.leaderboardScroll.cancelTouches();

	this.leaderboardScroll.effects = [];

	if (waitDuration > 0) {
		this.leaderboardScroll.effects.push({
			effect: tgfEffects.nothing,
			duration: waitDuration
		});
	}

	this.leaderboardScroll.effects.push({
		effect: customEffects.scrollBoxScroll,
		duration: scrollDuration,
		ease: tbEase.easeInOutQuadratic,
		endScrollY: Math.min(Math.max(-yPosition, this.leaderboardScroll.getMinY()), this.leaderboardScroll.getMaxY())
	});

	this.leaderboardScroll.onEffectEnd = function () {
		self.currentlyScrolling = false;
		self.disableFloatingPlayer = false;
	};

	this.leaderboardScroll.repeatEffect = 1;
	this.leaderboardScroll.restartEffect();
};

tgfDialogs.LeaderboardDialog.prototype.handleEndStep = function (timePassed) {
	"use strict";
	tgfDialogs.LeaderboardDialog.uber.handleEndStep.apply(this, arguments);

	this.updateScrollComponentDimensions();

	this.updatePlayerEntry();

	var self = this;
};

tgfDialogs.LeaderboardDialog.prototype.updateScrollComponentDimensions = function () {
	"use strict";
	if (!this.leaderboardLoaded) {
		return;
	}
	// calculate scroll box height & position
	var h = tgfGraphics.visibleHeight / 2 - this.leaderboardScrollTop;

	if (this.leaderboardScroll.height !== h) {
		this.leaderboardScroll.setWidthHeight(this.leaderboardScroll.width, h);
		this.leaderboardScroll.y = this.leaderboardScrollTop + this.leaderboardScroll.height / 2;
	}
};

tgfDialogs.LeaderboardDialog.prototype.updatePlayerEntry = function () {
	"use strict";
	var self = this;
	if (this.disableFloatingPlayer || !this.leaderboardLoaded) {
		return;
	}

	var parent = null;
	var playerPos = this.findPlayerPosition();
	var playerComp = this.leaderboardList[playerPos].component;
	var minY = -this.getEntryY(playerPos);
	var maxY = -this.getEntryY(playerPos) + this.leaderboardScroll.height - this.leaderboardEntryDistance;

	var scroll = this.leaderboardScroll.scroll;

	var scrollY = Math.max(Math.min(this.leaderboardScroll.getMaxY(), scroll.y), this.leaderboardScroll.getMinY());

	if (scrollY < minY || scrollY > maxY) {
		// floating player
		if (!this.playerOutsideView || this.playerOutsideView === undefined) {
			this.playerOutsideView = true;

			// which button to use
			this.floatingPlayerButton = scrollY < minY ? this.floatingPlayerButtonTop : this.floatingPlayerButtonBottom;

			// show and activate
			this.floatingPlayerButton.show();
			this.floatingPlayerButton.activate();

			// move to avoid flicker
			this.floatingPlayerButton.x = this.floatingPlayerButton.startX;
			this.floatingPlayerButton.y = this.floatingPlayerButton.startY + this.leaderboardEntryDistance * this.floatingPlayerButton.directionFactor;
			this.floatingPlayerButton.alpha = 0;
			// effect
			this.floatingPlayerButton.effects = {
				effect: tgfEffects.transform,
				duration: this.floatingPlayerButtonAppearDuration,
				ease: tbEase.easeOutOvershoot,
				startX: this.floatingPlayerButton.startX,
				startY: this.floatingPlayerButton.startY + this.leaderboardEntryDistance * this.floatingPlayerButton.directionFactor,
				endX: this.floatingPlayerButton.startX,
				endY: this.floatingPlayerButton.startY,
				startAlpha: 0,
				endAlpha: 1
			};
			this.floatingPlayerButton.repeatEffect = 1;
			this.floatingPlayerButton.restartEffect();
			this.floatingPlayerButton.onEffectEnd = undefined;
		}
	} else {
		// normal player
		if (this.playerOutsideView) {
			this.playerOutsideView = false;
			// effect
			this.floatingPlayerButton.effects = {
				effect: tgfEffects.transform,
				duration: this.floatingPlayerButtonDisappearDuration,
				ease: tbEase.easeInCubic,
				startX: this.floatingPlayerButton.startX,
				startY: this.floatingPlayerButton.startY,
				endX: this.floatingPlayerButton.startX,
				endY: this.floatingPlayerButton.startY + this.leaderboardEntryDistance * this.floatingPlayerButton.directionFactor - tgfScale(10),
				startAlpha: 1,
				endAlpha: 0
			};
			this.floatingPlayerButton.repeatEffect = 1;
			this.floatingPlayerButton.restartEffect();
			this.floatingPlayerButton.onEffectEnd = function (component) {
				component.hide();
			};

			// entry effect:
			playerComp.yScale = 1;
			playerComp.effects = this.fxHorizontalStrongWobble;
			playerComp.repeatEffect = 1;
			playerComp.restartEffect();
			playerComp.onEffectEnd = undefined;
		}
	}
};

tgfDialogs.LeaderboardDialog.prototype.hidePlayerButton = function () {
	'use strict';

	this.playerOutsideView = undefined;

	if (this.floatingPlayerButtonTop) {
		this.floatingPlayerButtonTop.hide();
	}
	if (this.floatingPlayerButtonBottom) {
		this.floatingPlayerButtonBottom.hide();
	}
};

/**
 * makes it so the component is drawn last (relative to it's siblings)
 */
tgfDialogs.LeaderboardDialog.prototype.bringComponentToFront = function (component) {
	"use strict";
	component.parent.removeComponent(component);
	component.parent.addComponent(component);
};

tgfDialogs.LeaderboardDialog.prototype.doActivate = function () {
	"use strict";
	// hide stuff
	this.hidePlayerButton();
};

tgfDialogs.LeaderboardDialog.prototype.doHide = function () {
	"use strict";

	if (this.leaderboardTabsDialog) {
		this.leaderboardTabsDialog.hide();

		this.leaderboardTabsDialog = undefined;
	}
};
