// The constructor for the component
/**
 * @constructor
 * @base tgfComponents.Base
 */
tgfComponents.LeaderboardEntry = function (properties, data, showFlag, position, positionIndicator, isCurrentMonth) {
	"use strict";
	this.name = "LeaderboardEntry"; //The name of the component

	// Initialize properties
	this.initialize(tgfSettings.componentDefaults.picture);
	this.setProperties(tgfSettings.componentDefaults.leaderboardEntry);

	this._rankId = data.getPlayerData().getRank();

	this.challengeButtonProperties.fontUp.fontWeight = tgfSettings.theme.leaderboardEntry.challengeButton.font.weight;

	if (data.isPlayer() && this.playerProperties) {
		if (positionIndicator && positionIndicator.dif > 0) {
			var updatedPositionImgIndicator = new tgfComponents.Picture(this.updatedPositionIndicatorImgProperties);

			updatedPositionImgIndicator.image = positionIndicator.img;

			this.components.push(updatedPositionImgIndicator);
		}
		this.setProperties(this.playerProperties);
	}
	// Set user properties
	if (properties !== undefined) {
		this.setProperties(properties);
	}

	this.data = data;
	this.showFlag = showFlag;
	this.position = position;
	this.countryCode = data.getPlayerData().getCountry();
};

// Inherit the base component
tgfComponents.inherit(tgfComponents.LeaderboardEntry, tgfComponents.Base);

// ***************************************
// Preparing, showing and activating
//      - These can be removed if no processing is required
// ***************************************

// Processing required when preparing the component for use
tgfComponents.LeaderboardEntry.prototype.doPrepare = function () {
	"use strict";
	var data = this.data;
	var self = this;

	// background
	if (this.backgroundPictureProperties) {
		this.backgroundPicture = new tgfComponents.Picture(this.backgroundPictureProperties);
		this.addComponent(this.backgroundPicture);

		this.width = this.backgroundPicture.image.width;
		this.height = this.backgroundPicture.image.height;
	}

	//invisible button
	if (this.onClick !== undefined) {
		this.invisButton = new tgfComponents.Button({
			width: this.width,
			height: this.height,
			x: 0,
			y: 0,
			onClick: this.onClick,
			cancelEvents: false,
			image: undefined
		});
		this.addComponent(this.invisButton);
	}

	// top three marker
	this.topThreeMarker = new tgfComponents.Picture(this.topThreeMarkerProperties);
	this.updateMarker();
	this.addComponent(this.topThreeMarker);

	// position
	var fontSize = this.getPositionFontSize(data.getPosition());

	this.positionLabel = new tgfComponents.Label({
		font: {
			fontFace: f_main_font.fontFace,
			fontWeight: tgfSettings.theme.leaderboardEntry.positionLabel.font.weight,
			fontSize: fontSize,
			fillColor: tgfSettings.theme.leaderboardEntry.positionLabel.font.color,
			baseline: "middle",
			align: "center"
		},
		x: tgfScale(tgfSettings.theme.leaderboardEntry.positionLabel.position.x),
		y: tgfScale(tgfSettings.theme.leaderboardEntry.positionLabel.position.y),
	});
	this.positionLabel.text = data.getPosition() > 0 ? this.createPositionLabel(data.getPosition()) : "-";
	this.addComponent(this.positionLabel);

	var rankUtility = new RankUtility();

	var rank = rankUtility.getRankDataForRank(this._rankId);

	this._profile = new tgfComponents.ProfileComponent({
		x: tgfScale(-129),
		y: tgfScale(-6)
	}, rank, 0.7);

	this._profile.profileImage = data.getPlayerData().getProfilePicture(this.isFriendsLeaderboard);

	this.addComponent(this._profile);

	// name
	this.nameLabel = new tgfComponents.Label({
		font: {
			fontFace: f_main_font.fontFace,
			fontWeight: tgfSettings.theme.leaderboardEntry.nameLabel.font.weight,
			fontSize: tgfSettings.theme.leaderboardEntry.nameLabel.font.size,
			fillColor: tgfSettings.theme.leaderboardEntry.nameLabel.font.color,
			baseline: "middle",
			align: "left"
		},
		x: tgfScale(tgfSettings.theme.leaderboardEntry.nameLabel.position.x),
		y: tgfScale(tgfSettings.theme.leaderboardEntry.nameLabel.position.y),
		// custom
		maxWidth: tgfScale(220),
	});
	this.nameLabel.text = data.getPlayerData().getName(this.isFriendsLeaderboard);
	this.nameLabel.prepare(); // to get the width

	if (this.nameLabel.getWidth() > this.nameLabel.maxWidth) {
		this.nameLabel.width = this.nameLabel.maxWidth;
		this.nameLabel.recreate();
	}
	this.addComponent(this.nameLabel);

	// handle showing the (correct) flag
	if (this.showFlag && this.countryCode && window[this.countryCode]) {
		this.flagPicture = new tgfComponents.Picture(this.flagPictureProperties);
		this.flagPicture.image = window[this.countryCode];
		this.addComponent(this.flagPicture);
	}

	// rank
	this.rankLabel = new tgfComponents.Label({
		font: {
			fontFace: f_main_font.fontFace,
			fontWeight: tgfSettings.theme.leaderboardEntry.rankLabel.font.weight,
			fontSize: tgfSettings.theme.leaderboardEntry.rankLabel.font.size,
			fillColor: tgfSettings.theme.leaderboardEntry.rankLabel.font.color,
			baseline: "middle",
			align: "right"
		},
		x: tgfScale(tgfSettings.theme.leaderboardEntry.rankLabel.position.x), // absolute, right align
		y: tgfScale(tgfSettings.theme.leaderboardEntry.rankLabel.position.y)
	});

	this.rankLabel.text = StringUtil.format(
		tgfDictionary.getText("RankOnLeaderboard"),
		data.getPlayerData().isVip() ? data.getPlayerData().getRank() : Math.min(data.getPlayerData().getRank(), 25)
	);
	this.addComponent(this.rankLabel);

	if (data.getPlayerData().isVip()) {
		this.vipIcon = new tgfComponents.Picture({
			image: s_icon_leaderboard_vip,
			x: (this.backgroundPictureProperties.image.width / 2) - (s_icon_leaderboard_vip.width / 2),
			y: (-this.backgroundPictureProperties.image.height / 2) + (s_icon_leaderboard_vip.height / 2) - 1,
		});
		this.addComponent(this.vipIcon);
	}

	if (data.getScore() === 0 && !data.isPlayer()) {
		this.positionLabel.text = "-";
	}

	if (data.getScore() === 0 && !data.isPlayer() && this.data.getPlayerData().getID() && this.isCurrentMonth) {

		if (!data.getPlayerData().isChallengedThisSession()) {

			this.challengeButton = new tgfComponents.Button(this.challengeButtonProperties);

			this.challengeButton.onClick = function () {
				EventSystem.Global.dispatchEvent(UI_Event.LEADERBOARD_CHALLENGE_BUTTON_CLICKED, self);
			};
			this.addComponent(this.challengeButton);
		}
	} else {
		// points
		this.pointsLabel = new tgfComponents.Label({
			font: {
				fontFace: "ff_open_sans_bold",
				fontSize: tgfSettings.theme.leaderboardEntry.pointsLabel.font.size,
				fontWeight: tgfSettings.theme.leaderboardEntry.pointsLabel.font.weight,
				fillColor: tgfSettings.theme.leaderboardEntry.pointsLabel.font.color,
				baseline: "middle",
				align: "left"
			},
			x: tgfScale(tgfSettings.theme.leaderboardEntry.pointsLabel.position.x),
			y: tgfScale(tgfSettings.theme.leaderboardEntry.pointsLabel.position.y),
			separator: ","
		});
		//calculate string
		var str = data.getScore().toString();
		for (i = 0; i < str.length; i += 1) {
			if ((str.length - i) % 3 === 0 && i !== 0) {
				this.pointsLabel.text += this.pointsLabel.separator;
			}
			this.pointsLabel.text += str.charAt(i);
		}
		this.addComponent(this.pointsLabel);
	}

	if (this.showDifficultyMarker) {
		// difficulty marker
		this.difficultyMarker = new tgfComponents.Picture(this.difficultyMarkerProperties);
		this.difficultyMarker.startSubImage = data.difficulty;
		this.addComponent(this.difficultyMarker);
	}

	var i;
	// Add the child components
	if (this.components) {
		for (i = 0; i < this.components.length; i += 1) {
			this.addComponent(this.components[i]);
		}
	}
};

tgfComponents.LeaderboardEntry.prototype.hideChallengeButton = function () {

	this.data.getPlayerData().registerChallenge();
	this.removeComponent(this.challengeButton);
}

tgfComponents.LeaderboardEntry.prototype.getPositionFontSize = function (position) {
	'use strict';

	var positionText = position.toString();

	switch (positionText.length) {
		case 1:
		case 2:
			return 34;
		case 3:
			return 28;
		case 4:
			return 22;
		case 5:
			return 18;
		case 6:
			return 16;
		case 7:
		case 8:
			return 12;
		default:
			return 8;
	}
};

tgfComponents.LeaderboardEntry.prototype.createPositionLabel = function (position) {
	'use strict';
	try {
		var trailing = Math.round(parseInt(position)) === parseInt(position) ? "." : '';

		return StringUtil.thousandsSeparator(position.toString(), ',') + trailing;
	} catch (e) {
		return (+position).toString();
	}
};

tgfComponents.LeaderboardEntry.prototype.updateLabel = function () {
	"use strict";
	this.positionLabel.text = this.createPositionLabel(this.data.position);
	this.positionLabel.recreate();
};

tgfComponents.LeaderboardEntry.prototype.updateMarker = function () {
	"use strict";
	if (this.position < this.topThreeMarkerImages.length && this.data.getScore() > 0) {
		// this.topThreeMarker.image = this.topThreeMarkerProperties.image;        // alternative stategy: use subimages
		// this.topThreeMarker.subImage = this.position;
		// this.topThreeMarker.startSubImage = this.position;
		this.topThreeMarker.image = this.topThreeMarkerImages[this.position];
	} else {
		this.topThreeMarker.image = null;
	}
};

/**
 * add effect to child components to match a different position
 */
tgfComponents.LeaderboardEntry.prototype.morphToComp = function (target, duration, easeFunction) {
	"use strict";
	var self = this;

	var compNames = ["avatar", "positionLabel", "nameLabel", "pointsLabel"];

	for (var i = 0; i < compNames.length; i++) {
		var name = compNames[i];
		var comp = this[name];
		if (!comp) {
			continue;
		}
		comp.effects = [{
			effect: this.propertyMorphEffect,
			targetComponent: target[name],
			duration: duration,
			ease: easeFunction,
			recreate: true
		}];
		comp.repeatEffect = 1;
		comp.restartEffect();
	}
};

tgfComponents.LeaderboardEntry.prototype.propertyMorphEffect = function (component, effect, time) {
	"use strict";
	var target = effect.targetComponent;
	var ease = effect.ease === undefined ? tbEase.easeLinear : effect.ease;
	if (effect.startProperties === undefined) {
		effect.startProperties = {
			width: component.width,
			height: component.height,
			x: component.x,
			y: component.y,
			xScale: component.xScale,
			yScale: component.yScale
		};
	}

	if (component instanceof tgfComponents.ProfileComponent) {
		component.xScale = ease(time, effect.startProperties.xScale, target.xScale - effect.startProperties.xScale, effect.duration, effect.easeArgument);
		component.yScale = ease(time, effect.startProperties.yScale, target.yScale - effect.startProperties.yScale, effect.duration, effect.easeArgument);
	} else {
		component.width = ease(time, effect.startProperties.width, target.width - effect.startProperties.width, effect.duration, effect.easeArgument);
		component.height = ease(time, effect.startProperties.height, target.height - effect.startProperties.height, effect.duration, effect.easeArgument);
	}

	component.x = ease(time, effect.startProperties.x, target.x - effect.startProperties.x, effect.duration, effect.easeArgument);
	component.y = ease(time, effect.startProperties.y, target.y - effect.startProperties.y, effect.duration, effect.easeArgument);

	if (component.recreate !== undefined && effect.recreate) {
		component.recreate();
	}
};

/**
 * changes the parent, keeping the position on screen
 */
tgfComponents.LeaderboardEntry.prototype.changeParent = function (newParent) {
	"use strict";
	var screenX = this.componentToScreenX(0, 0);
	var screenY = this.componentToScreenY(0, 0);
	var oldParent = this.parent;

	this.parent.removeComponent(this);
	// custom remove, because of weird scroll box implementation
	if (this.parent instanceof tgfComponents.ScrollBox) {
		this.parent._drawComponents.splice(this.parent._drawComponents.indexOf(this), 1);
	}
	newParent.addComponent(this);

	oldParent.deactivate();
	newParent.deactivate();
	oldParent.activate();
	newParent.activate();

	this.x = this.parent.screenToComponentX(screenX, screenY);
	this.y = this.parent.screenToComponentY(screenX, screenY);
};

