// The constructor for the dialog
/** @constructor
 *  @base tgfDialogs.Base
 */
tgfDialogs.LeaderboardsTabDialog = function (properties) {
    "use strict";

    this.name = "LeaderboardsTabDialog";

    // Initialize properties
    this.initialize(tgfSettings.dialogDefaults.Base);

    this.setProperties(tgfSettings.dialogDefaults.LeaderboardsTabDialog);

    // Set user properties
    if (properties !== undefined) {
        this.setProperties(properties);
    }

    //Theme dependent font settings.
    this.activeStateLabelProperties.font.fillColor = tgfSettings.theme.fontColor.dark;
    this.lbFriendsTabProperties.textProperties.font.fillColor = tgfSettings.theme.fontColor.dark;
    this.lbNationalTabProperties.textProperties.font.fillColor = tgfSettings.theme.fontColor.dark;
    this.lbWorldTabProperties.textProperties.font.fillColor = tgfSettings.theme.fontColor.dark;

    this.activeStateLabelProperties.font.fontWeight = tgfSettings.theme.leaderboard.leaderboardCloseMessageFontWeight;
    this.activeStateLabelProperties.font.fillColor = tgfSettings.theme.fontColor.leaderboardMessageText;
    this.activeStateLabelProperties.y += tgfScale(tgfSettings.theme.leaderboard.leaderboardCloseMessageYOffset);

    if (tgfSettings.theme.leaderboard) {
        if (tgfSettings.theme.leaderboard.lbFriendsTabProperties) {
            this.lbFriendsTabProperties.imgProperties = tgfSettings.theme.leaderboard.lbFriendsTabProperties.imgProperties;
        }
        if (tgfSettings.theme.leaderboard.lbNationalTabProperties) {
            this.lbNationalTabProperties.imgProperties = tgfSettings.theme.leaderboard.lbNationalTabProperties.imgProperties;
        }
        if (tgfSettings.theme.leaderboard.lbWorldTabProperties) {
            this.lbWorldTabProperties.imgProperties = tgfSettings.theme.leaderboard.lbWorldTabProperties.imgProperties;
        }
    }

    this._selectedMonthYear = this._selectedMonth + '_' + this._selectedYear;
};

// Inherit the base dialog
tgfDialogs.inherit(tgfDialogs.LeaderboardsTabDialog, tgfDialogs.Base);

/**
 * makes it so the component is drawn last (relative to it's siblings)
 */
tgfDialogs.LeaderboardsTabDialog.prototype.bringComponentToFront = function (component) {
    "use strict";

    component.parent.removeComponent(this.topBarMessagePicture);
    component.parent.removeComponent(this.activeStateLabel);
    component.parent.addComponent(this.topBarMessagePicture);
    component.parent.addComponent(this.activeStateLabel);

    component.parent.removeComponent(component);
    component.parent.addComponent(component);
};

tgfDialogs.LeaderboardsTabDialog.prototype.compareToPreviousPosition = function (currentPosition, leaderboardType) {
    'use strict';

    var stateHandler = gameFlowController.getGameStateHandler();

    var lastPosition = stateHandler.getLeaderboardLastPosition(this._selectedMonthYear, leaderboardType);

    var positionIndicatorImg = null;

    var dif = 0;

    if (lastPosition) {
        dif = lastPosition - currentPosition;
        if (currentPosition < lastPosition) {
            positionIndicatorImg = this.arrowUp;

            stateHandler.saveLeaderboardLastSeen(this._selectedMonthYear, leaderboardType, lastPosition);

            stateHandler.saveLeaderboardShowNotification(this._selectedMonthYear, leaderboardType, true);
        } else if (currentPosition > lastPosition) {
            positionIndicatorImg = this.arrowDown;

            stateHandler.saveLeaderboardLastSeen(this._selectedMonthYear, leaderboardType, lastPosition);

            stateHandler.saveLeaderboardShowNotification(this._selectedMonthYear, leaderboardType, true);
        } else {
            var lastSeen = stateHandler.getLeaderboardLastSeen(this._selectedMonthYear, leaderboardType);

            if (lastSeen) {
                if (lastPosition < lastSeen) {
                    positionIndicatorImg = this.arrowUp;
                } else if (lastPosition > lastSeen) {
                    positionIndicatorImg = this.arrowDown;
                }
                dif = lastSeen - currentPosition;
            }
        }
    }

    stateHandler.saveLeaderboardLastPosition(this._selectedMonthYear, leaderboardType, currentPosition);

    return {
        img: positionIndicatorImg,
        dif: Math.abs(dif)
    };
};

tgfDialogs.LeaderboardsTabDialog.prototype.checkNationalIndicator = function (callback) {
    'use strict';

    var self = this;

    LeaderboardManager.getLocalLeaderboardData(self.monthsBack)
        .then(function (lbData) {
            self.nationalPosition = 1;
            var playerEntry = lbData.getPlayerEntry()

            if (playerEntry) {
                self.nationalPosition = playerEntry.getPosition();

                if (self.getNationalPositionCb) {
                    self.getNationalPositionCb(self.nationalPosition);
                }

            }
            callback(self.compareToPreviousPosition(self.nationalPosition, 'national'));
        })
        .catch(function (err) {
            self.nationalPosition = -1;

            if (self.getNationalPositionCb) {
                self.getNationalPositionCb(self.nationalPosition);
            }
        });
};

tgfDialogs.LeaderboardsTabDialog.prototype.checkWorldIndicator = function (callback) {
    'use strict';

    var self = this;

    LeaderboardManager.getGlobalLeaderboardData(self.monthsBack)
        .then(function (lbData) {
            var playerEntry = lbData.getPlayerEntry();
            self.worldPosition = 1;
            if (playerEntry) {

                self.worldPosition = playerEntry.getPosition();

                if (self.getWorldPositionCb) {
                    self.getWorldPositionCb(self.worldPosition);
                }
            }

            callback(self.compareToPreviousPosition(self.worldPosition, 'world'));
        })
        .catch(function (err) {
            self.worldPosition = -1;

            if (self.getWorldPositionCb) {
                self.getWorldPositionCb(self.worldPosition);
            }
        });
};

tgfDialogs.LeaderboardsTabDialog.prototype.setPositionIndicator = function (tabButton, indicator) {
    'use strict';

    var showNotification = gameFlowController.getGameStateHandler().getLeaderboardShowNotification(this._selectedMonthYear, tabButton.leaderboardType);

    if (showNotification) {
        tabButton.findComponent('positionIndicator').image = indicator.img;
    } else {
        tabButton.findComponent('positionIndicator').image = null;
    }
};

tgfDialogs.LeaderboardsTabDialog.prototype.handleEnterLeaderboards = function () {
    'use strict';

    var n = 0,
        self = this;

    this.leaderboardsCleared();

    //
    var selectedTab = LeaderboardManager.getSelectedTab();
    if (selectedTab != null) {
        switch (selectedTab) {
            case 1:
                this.fetchLeaderboardFunction = this.fetchNationalLeaderboard;
                break;

            case 2:
                this.fetchLeaderboardFunction = this.fetchWorldLeaderboard;
                break;
            default:
                this.fetchLeaderboardFunction = this.fetchFriendsLeaderboard;
                break;
        }
        self.handleTabsSelection(selectedTab, true);
    } else {
        this.fetchLeaderboardFunction = this.fetchFriendsLeaderboard;
    }

    //TODO: Get the local leaderboards rank.
    this.checkNationalIndicator(function (indicator) {
        self.positionIndicator['national'] = indicator;

        self.setPositionIndicator(self.tabButtons[1], indicator);
    });

    this.checkWorldIndicator(function (indicator) {
        self.positionIndicator['world'] = indicator;

        self.setPositionIndicator(self.tabButtons[2], indicator);
    });
};

/**
 * Calls the callback with this parameter:
 *     postion:  position in national leaderboard, undefined if no position set
 */
tgfDialogs.LeaderboardsTabDialog.prototype.getNationalPosition = function (callback) {
    'use strict';

    if (this.nationalPosition !== null) {
        callback(this.nationalPosition);
    } else {
        this.getNationalPositionCb = callback;
    }
};

/**
 * Calls the callback with this parameter:
 *     postion:  position in world leaderboard, undefined if no position set
 */
tgfDialogs.LeaderboardsTabDialog.prototype.getWorldPosition = function (callback) {
    'use strict';

    if (this.worldPosition !== null) {
        callback(this.worldPosition);
    } else {
        this.getWorldPositionCb = callback;
    }
};

tgfDialogs.LeaderboardsTabDialog.prototype.handleTabsSelection = function (index, loadLeaderboards) {
    'use strict';

    LeaderboardManager.setSelectedTab(index);

    if (loadLeaderboards) {
        this.didFetchLeaderboards = false;

        this.leaderboardsCleared();
    }

    if (this.handleResponseTimeout) {
        clearTimeout(this.handleResponseTimeout);
    }

    for (var i = 0; i < 3; ++i) {
        this.tabButtons[i].isSelected = index === i;

        this.setPositionIndicator(this.tabButtons[i], this.positionIndicator[this.tabButtons[i].leaderboardType]);

        if (this.tabButtons[i].isSelected) {
            gameFlowController.getGameStateHandler().saveLeaderboardShowNotification(this._selectedMonthYear, this.tabButtons[i].leaderboardType, false);
        }

        this.tabButtons[i].image = index === i ? s_leaderboard_tab_selected : s_leaderboard_tab_unselected;
    }


    switch (index) {
        case this.tabIndices.friends:
			SudokuAnalytics.reportShowingFriendsLeaderboard();
			// MessyAnalytics.screenChange("leaderboard_friends");
            break;

        case this.tabIndices.national:
			SudokuAnalytics.reportShowingNationalLeaderboard();
			// MessyAnalytics.screenChange("leaderboard_national");
            break;

        case this.tabIndices.world:
			SudokuAnalytics.reportShowingWorldLeaderboard();
			// MessyAnalytics.screenChange("leaderboard_world");
            break;
    };

    this.bringComponentToFront(this.tabButtons[index]);
};

tgfDialogs.LeaderboardsTabDialog.prototype.doPrepare = function () {
    "use strict";

    this.hasInitialized = false;

    this.worldPosition = null;
    this.nationalPosition = null;
    this.getWorldPositionCb = null;
    this.getNationalPositionCb = null;

    this.localPosition = null;
    this.getLocalPositionCb = null;

    if (this.lbNationalTabProperties.imgProperties) {
        this.lbNationalTabProperties.imgProperties.image = window[tgfSettings.player.countryCode];
    }

    // set tabs dictionary text
    this.lbFriendsTabProperties.textProperties.text = tgfDictionary.getText("LeaderboardFriends");
    this.lbNationalTabProperties.textProperties.text = tgfDictionary.getText("LeaderboardNational");
    this.lbWorldTabProperties.textProperties.text = tgfDictionary.getText("LeaderboardWorld");

    // top bar
    this.topBarPicture = new tgfComponents.Picture(this.topBarPictureProperties);
    this.addComponent(this.topBarPicture);

    this.topBarMessagePicture = new tgfComponents.Picture(this.topBarMessagePictureProperties);
    this.addComponent(this.topBarMessagePicture);


    // title
    this.activeStateLabel = new tgfComponents.Label(this.activeStateLabelProperties);
    this.addComponent(this.activeStateLabel);

    if (tgfSettings.theme.leaderboard.lockImageEnabled) {
        this.topBarMessageLockPicture = new tgfComponents.Picture(this.topBarMessageLockPictureProperties);
        this.addComponent(this.topBarMessageLockPicture);
    }

    var now = TimeManager.getDate();
    this.updateIsLeaderboardActive();
    if (
        now.getMonth() === this._selectedMonth &&
        now.getFullYear() === this._selectedYear
    ) {
        this.updateActiveLeaderboard = setInterval(this.updateIsLeaderboardActive.bind(this), 300000); //update the message every 5 seconds.
    }

    this.tabButtons = [
        this.createTabButton(this.lbFriendsTabProperties, function () {
            this.handleTabsSelection(this.tabIndices.friends, true);
            this.fetchLeaderboardFunction = this.fetchFriendsLeaderboard;
        }.bind(this)),

        this.createTabButton(this.lbNationalTabProperties, function () {
            this.handleTabsSelection(this.tabIndices.national, true);

            this.fetchLeaderboardFunction = this.fetchNationalLeaderboard;
        }.bind(this)),

        this.createTabButton(this.lbWorldTabProperties, function () {
            this.handleTabsSelection(this.tabIndices.world, true);

            this.fetchLeaderboardFunction = this.fetchWorldLeaderboard;
        }.bind(this))
    ];

    for (var a = 0; a < this.tabButtons.length; a++) {

        if (this.tabButtons[a].isSelected) this.bringComponentToFront(this.tabButtons[a]);
    }
};

tgfDialogs.LeaderboardsTabDialog.prototype.updateIsLeaderboardActive = function () {
    'use strict';

    var now = TimeManager.getDate();
    if (
        now.getMonth() === this._selectedMonth &&
        now.getFullYear() === this._selectedYear
    ) {
        var hoursToNextMonth = DateUtil.getHoursUntilNextMonth();

        var days = Math.floor(hoursToNextMonth / 24);

        var hours = hoursToNextMonth % 24;

        var hoursString = '';

        var hourFormat = hours > 1 ? tgfDictionary.getText("HoursText") : tgfDictionary.getText("HourText");

        var dayFormat = days > 1 ? tgfDictionary.getText("DaysText") : tgfDictionary.getText("DayText");

        if (hours === 0) {
            if (days > 0) {
                //show days only.
                hoursString = StringUtil.format('{0} {1}.', days.toString(), dayFormat);
            } else {
                //less than one hour.
                hoursString = tgfDictionary.getText("LessThanOneHour");
            }
        } else if (days === 0) {
            //show hours only.
            hoursString = StringUtil.format('{0} {1}.', hours.toString(), hourFormat);
        } else {
            //show days and hours.
            hoursString = StringUtil.format(tgfDictionary.getText("DaysAndHours"), days.toString(), dayFormat, hours.toString(), hourFormat);
        }

        this.activeStateLabel.text = StringUtil.format(tgfDictionary.getText("LeaderboardTimerLabel"), hoursString);
    } else {
        this.activeStateLabel.text = tgfDictionary.getText("LeaderboardClosedLabel");
    }
    this.activeStateLabel.recreate();
};

tgfDialogs.LeaderboardsTabDialog.prototype.doShow = function () {
    'use strict';

    this.handleEnterLeaderboards();
};

tgfDialogs.LeaderboardsTabDialog.prototype.createTabButton = function (properties, callback) {
    'use strict';

    var tabButton = new tgfComponents.Picture(properties);

    var self = this;

    tabButton.onClick = callback;

    var tabButtonText = new tgfComponents.Label(properties.textProperties);

    tabButton.addComponent(tabButtonText);

    if (properties.imgProperties) {
        var tabButtonImg = new tgfComponents.Picture(properties.imgProperties);

        tabButton.addComponent(tabButtonImg);
    }

    var tabButtonIndicatorImg = new tgfComponents.Picture(properties.posIndicatorProperties);

    tabButton.addComponent(tabButtonIndicatorImg);

    this.addComponent(tabButton);
    return tabButton;
};

tgfDialogs.LeaderboardsTabDialog.prototype.onLeaderboardsLoaded = function (leaderboardData, positionIndicator, showFlags) {
    'use strict';

    if (this.handleResponseTimeout) {
        clearTimeout(this.handleResponseTimeout);
    }

    this.leaderboardLoaded = true;

    this.leaderboardsLoaded(leaderboardData, positionIndicator, showFlags);
};

tgfDialogs.LeaderboardsTabDialog.prototype.onLeaderboardNoEntries = function () {
    this.leaderboardLoaded = false;
    this.leaderboardsErrorNoEntries();

    if (this.handleResponseTimeout) {
        clearTimeout(this.handleResponseTimeout);
    }
};

tgfDialogs.LeaderboardsTabDialog.prototype.handleEndStep = function (timePassed) {
    'use strict';

    tgfDialogs.LeaderboardsTabDialog.uber.handleEndStep.apply(this, arguments);

    if (!this.didFetchLeaderboards) {
        var self = this;

        this.leaderboardLoaded = false;

        this.fetchLeaderboardFunction();

        this.handleResponseTimeout = window.setTimeout(function () {
            if (!self.leaderboardLoaded) {
                self.didFetchLeaderboards = false;

                self.leaderboardsErrorNoNetworkAvailable();
            }
        }, 10000);

        self.didFetchLeaderboards = true;

        this.didFetchLeaderboards = true;
    }
};

tgfDialogs.LeaderboardsTabDialog.prototype.fetchFriendsLeaderboard = function () {
    'use strict';
    var self = this;

    LeaderboardManager.getFriendsLeaderboardData(self.monthsBack)
        .then(function (lbData) {
            if (!self.tabButtons[0].isSelected) {
                return;
            }

            var playerPosition = lbData.getPlayerEntry().getPosition();

            self.positionIndicator['friends'] = self.compareToPreviousPosition(playerPosition, 'friends');

            self.onLeaderboardsLoaded(lbData, self.positionIndicator['friends'], false);
        })
        .catch(function (err) {
            console.error("[LeaderboardTabsDialog] ran into an error: "+err + "\n" + err.stack);
            errorLoggingService.sendError(err);
        });
};

tgfDialogs.LeaderboardsTabDialog.prototype.fetchNationalLeaderboard = function () {
    'use strict';

    var self = this;

    this.getNationalPosition(function (nationalPosition) {

        LeaderboardManager.getLocalLeaderboardData(self.monthsBack)
            .then(function (lbData) {
                if (!self.tabButtons[1].isSelected) {
                    return;
                }
                self.onLeaderboardsLoaded(lbData, self.positionIndicator['national'], false);
            })
            .catch(function (err) {
                console.error("[LeaderboardTabsDialog] ran into an error: "+err + "\n" + err.stack);
                errorLoggingService.sendError(err);
            });
    });
};

tgfDialogs.LeaderboardsTabDialog.prototype.fetchWorldLeaderboard = function () {
    'use strict';

    //TODO: wait for the world position.

    var self = this;

    this.getWorldPosition(function (worldPosition) {
        LeaderboardManager.getGlobalLeaderboardData(self.monthsBack)
            .then(function (lbData) {
                if (!self.tabButtons[2].isSelected) {
                    return;
                }

                self.onLeaderboardsLoaded(lbData, self.positionIndicator['world'], true);
            })
            .catch(function (err) {
                console.error("[LeaderboardTabsDialog] ran into an error: "+err + "\n" + err.stack);
                errorLoggingService.sendError(err);
            });
    });
};

tgfDialogs.LeaderboardsTabDialog.prototype.doHide = function () {
    'use strict';

    // Make sure all looping audio stops.
    tgfAudio.stop(a_score_counter.name);
    tgfAudio.stop(a_scale_up.name);
    tgfAudio.stop(a_scale_down.name);
    tgfAudio.stop(a_entry_move.name);
    tgfAudio.stop(a_score_counter.name);
    tgfAudio.stop(a_entry_update_position.name);

    if (this.updateActiveLeaderboard) {
        clearInterval(this.updateActiveLeaderboard);
    }

    gameFlowController.getGameStateHandler().saveLeaderboardShowNotification(this._selectedMonthYear, 'friends', false);
    gameFlowController.getGameStateHandler().saveLeaderboardShowNotification(this._selectedMonthYear, 'national', false);
    gameFlowController.getGameStateHandler().saveLeaderboardShowNotification(this._selectedMonthYear, 'world', false);
};
