// *********************************
// CoolGames Builder JavaScript file
// *********************************

var Calendar = function () {
	var now = TimeManager.getDate();
	this._selectedMonth = now.getMonth();
	this._selectedYear = now.getFullYear();
	this._selectedID = this.getSelectedYear() + "_" + this.getSelectedMonth();
	this.initialized = false;

	var selectedData = UnlockDataManager.getCachedMonthDataById(this._selectedID);
	this._selectedData = selectedData !== null ? selectedData : null;

	this._autoOpenDate = null;
	this.loadRequiredMonths();
}

Calendar.prototype.configureEvents = function (monthUp, monthDown, toCurrentMonth, dataAvailable) {

	EventSystem.Global.addEventListener(monthUp, this._changeMonthUp, this);
	EventSystem.Global.addEventListener(monthDown, this._changeMonthDown, this);
	EventSystem.Global.addEventListener(toCurrentMonth, this._changeToCurrentMonth, this);
	EventSystem.Global.addEventListener(dataAvailable, this._onNewDataAvailable, this);

	EventSystem.Global.addEventListener(UI_Event.RETRY_BUTTON_CLICKED, this.setAutoOpenDate, this, true);
}

Calendar.prototype.setAutoOpenDate = function (date) {
	this._autoOpenDate = date;
	EventSystem.Global.dispatchEvent(System_Event.AUTO_OPEN_DATE_CHANGED);
}

Calendar.prototype.getAutoOpenDate = function () {
	return this._autoOpenDate;
}

Calendar.prototype.getAmountOfMonthsBack = function () {
	"use strict";
	var now = TimeManager.getDate();
	var monthsBack = (((now.getFullYear() - this._selectedYear) * 12) - this._selectedMonth) + now.getMonth();
	return monthsBack;
}

Calendar.prototype._changeToCurrentMonth = function () {
	"use strict";
	var now = TimeManager.getDate();
	this._selectedMonth = now.getMonth();
	this._selectedYear = now.getFullYear();

	this._onDateChange();
}

Calendar.prototype._changeMonthUp = function () {
	"use strict";

	this.setAutoOpenDate(null);

	var now = TimeManager.getDate();

	if (this._selectedMonth < 11) {
		this._selectedMonth++;
	} else {
		if (tgfSettings.game.calendarConfig.yearLimitFront === this._selectedYear + 1) {
			return;
		}
		this._selectedMonth = 0;

		this._selectedYear++;
	}
	this._onDateChange();
}

Calendar.prototype._changeMonthDown = function () {
	"use strict";

	this.setAutoOpenDate(null);

	if (this._selectedMonth > 0) {
		this._selectedMonth--;
	} else {
		if (tgfSettings.game.calendarConfig.yearLimitBack === this._selectedYear - 1) {
			return;
		}
		this._selectedMonth = 11;

		this._selectedYear--;
	}

	this._onDateChange();
}

Calendar.prototype._onDateChange = function () {

	this._selectedID = this.getSelectedYear() + "_" + this.getSelectedMonth();
	this._selectedData = null;
	this._refreshSelectedMonthData();

	EventSystem.Global.dispatchEvent(System_Event.SELECTED_MONTH_CHANGED, this._selectedYear, this._selectedMonth);
}

Calendar.prototype._onNewDataAvailable = function () {
	if (this._selectedData == null) {
		this._refreshSelectedMonthData();
	}
}

Calendar.prototype._getNameOfDifficulty = function (difficulty) {
	return ObjectUtil.getKeyByValue(tgfSettings.game.difficulties, difficulty).toLowerCase();
};

Calendar.prototype.getDifficultiesCompleteInCurrentMonth = function () {

	var firstDayOfMonth = new Date(this._selectedYear, this._selectedMonth + 1, 1);
	var difficultiesInThisMonth = DifficultyUtil.getDifficulties(firstDayOfMonth);

	var difficultiesComplete = {
		total: 0
	};

	for (var difficultyKey in difficultiesInThisMonth) {
		difficultiesComplete[this._getNameOfDifficulty(difficultiesInThisMonth[difficultyKey])] = 0;
	}

	if (!this._selectedData) {
		return difficultiesComplete;
	}

	var daysLength = this._selectedData.unlockedDays.length;
	for (var i = 0; i < daysLength; i++) {
		var currentDayData = this._selectedData.unlockedDays[i];

		for (var difficultyKey in difficultiesInThisMonth) {
			if (currentDayData.scores[this._getNameOfDifficulty(difficultiesInThisMonth[difficultyKey])] > 0 || 
				currentDayData.scoresVip[this._getNameOfDifficulty(difficultiesInThisMonth[difficultyKey])] > 0) {
				difficultiesComplete[this._getNameOfDifficulty(difficultiesInThisMonth[difficultyKey])]++;
				difficultiesComplete.total++;
			}
		}
	}
	
	return difficultiesComplete;
}

Calendar.prototype.amountOfDaysInCurrentMonth = function () {
	var lastDayOfTheMonthDate = new Date(this._selectedYear, this._selectedMonth + 1, 0).getDate();
	return lastDayOfTheMonthDate;
}

Calendar.prototype._refreshSelectedMonthData = function () {
	var currentSelectedMonthData = UnlockDataManager.getCachedMonthDataById(this._selectedID);
	if (currentSelectedMonthData && currentSelectedMonthData != "pending") {
		this._selectedData = currentSelectedMonthData;
		EventSystem.Global.dispatchEvent(System_Event.SELECTED_MONTH_LOADED);
	}
}

//Request month data for this calendar month and pre-load the one before that.
Calendar.prototype.loadRequiredMonths = function () {
	var previousMonthsYear = this.getSelectedYear();
	var previousMonth = this.getSelectedMonth() - 1;

	if (previousMonth < 0) {
		previousMonth = 11;
		previousMonthsYear -= 1;
	}

	var monthDataId = this.getSelectedYear() + "_" + this.getSelectedMonth();
	var prevMonthId = previousMonthsYear + '_' + previousMonth;
	UnlockDataManager.loadMonthData([monthDataId, prevMonthId], null);
}


Calendar.prototype.getSelectedData = function () {
	"use strict";
	return this._selectedData;
}

Calendar.prototype.isCurrentMonth = function () {
	"use strict";
	var now = TimeManager.getDate();
	var nowInCurrentMonth = this._selectedYear === now.getFullYear() && this._selectedMonth === now.getMonth();
	return nowInCurrentMonth;
}

Calendar.prototype.getSelectedMonth = function () {
	"use strict";
	return this._selectedMonth;
}

Calendar.prototype.getSelectedYear = function () {
	"use strict";
	return this._selectedYear;
}
