// ***************************************
// tgfDialogs.CalendarDialog
//
// ***************************************

// Directives for jslint
/*global tgfSettings, tgfDialogs, tgfComponents */

tgfSettings.dialogDefaults.calendarDialog = {
	depth: 10,
	_calendar: null,
	_horizontalSpacing: 83,
	_verticalSpacing: 81,
	_calendarYOrigin: -134,
	_calendarXOrigin: -267,
	components: [],
	_minY: 570
};

// The constructor for the dialog
/**
 * @constructor
 * @base tgfDialogs.Base
 */
tgfDialogs.CalendarDialog = function (properties) {
	"use strict";
	this.name = "CalendarDialog";
	this.active = true;

	this.initialize(tgfSettings.dialogDefaults.calendarDialog);

	this.dayOneX = tgfScale(this._calendarXOrigin);
	this.dayOneY = tgfScale(this._calendarYOrigin);

	if (properties !== undefined) {
		this.setProperties(properties);
	}

	this.x = tgfGraphics.visibleWidth / 2;
	this.y = Math.max(tgfGraphics.visibleHeight / 2, this._minY);

	this._activeDayComponents = [];

	EventSystem.Global.addEventListener(System_Event.SELECTED_MONTH_LOADED, this._showMonth, this);
	EventSystem.Global.addEventListener(System_Event.DAY_UNLOCKED, this._showMonth, this);
	EventSystem.Global.addEventListener(System_Event.AUTO_OPEN_DATE_CHANGED, this._clearAutoOpenDateTimeout, this);

	EventSystem.Global.addEventListener(UI_Event.CALENDAR_DAY_BUTTON_CLICKED, this._clearAutoOpenDateTimeout, this);
	EventSystem.Global.addEventListener(UI_Event.SETTINGS_BUTTON_CLICKED, this._clearAutoOpenDateTimeout, this);

	if (this._calendar.getSelectedData()) {
		this._showMonth();
	}

	this._calendar.loadRequiredMonths();
};

// Inherit the base dialog
tgfDialogs.inherit(tgfDialogs.CalendarDialog, tgfDialogs.Base);

// ***************************************
// Preparing and showing
//      - These can be removed if no processing is required
// ***************************************

tgfDialogs.CalendarDialog.prototype._showMonth = function () {

	if (gameFlowController.screenManager.getCurrentScreen() === mainMenuScreens.CALENDAR) {
		this._monthData = this._calendar.getSelectedData()
		this._selectedYear = this._calendar.getSelectedYear();
		this._selectedMonth = this._calendar.getSelectedMonth();

		//Remove the protip container so we can re-add it later so we can handle the z-index
		if (this.protipContainer) {
			this.removeComponent(this.protipContainer);
		}
		
		this._clearMonth();
		this._createMonth();

		//Remove the protip container so we can re-add it later so we can handle the z-index
		if (this.protipContainer) {
			this.addComponent(this.protipContainer);
		}
		
		var self = this;
		var openDate = this._calendar.getAutoOpenDate();
		if (openDate) {
			this._delayedAutoOpen = setTimeout(function () {
				this._delayedAutoOpen = null;
				this._calendar.setAutoOpenDate(null);
				if (self.isActive) {
					EventSystem.Global.dispatchEvent(UI_Event.CALENDAR_DAY_BUTTON_CLICKED, openDate);
				}
			}.bind(this), 1300);
		}
	}
}

tgfDialogs.CalendarDialog.prototype._clearAutoOpenDateTimeout = function () {
	if (this._delayedAutoOpen) {
		clearTimeout(this._delayedAutoOpen);
		this._delayedAutoOpen = null;
		this._calendar.setAutoOpenDate(null);
	}
}

// Processing required when preparing the dialog for use
tgfDialogs.CalendarDialog.prototype.doPrepare = function () {
	"use strict";

	if (tgfSettings.themeSettings.backgroundTarget === tgfSettings.themeSettings.backgroundTargets.CANVAS) {
		tgfGraphics.setBackgroundColor(tgfSettings.theme.calendar.backgroundColor);
	} else {
		tgfGraphics.setBackgroundImage(tgfSettings.theme.calendar.backgroundImagePath);
	}

	if (ThemeController.getCalendarBackgroundImage()) {
		this._backgroundImageDialog = new tgfDialogs.BackgroundImageDialog({
			_backgroundImage: ThemeController.getCalendarBackgroundImage(),
		});
	}

	this.protipContainer = new tgfComponents.Base({
		x: tgfScale(140),
		y: tgfScale(301)
	});
	this.protipBackground = new tgfComponents.Picture({
		image: s_ui_calendar_pro_tip,
	});
	this.protipDecoration = new tgfComponents.Picture({
		image: s_ui_calendar_pro_tip_whomp,
		x: tgfScale(-118 - 20),
		y: tgfScale(-2)
	});
	this.protipLabel = new tgfComponents.Label({
		// dictionaryKey: "ProTip",
		x: tgfScale(-56 - 35),
		y: tgfScale(0),
		width: 250,
		height: 100,
		splitLines: true,
		fitToBox: true,
		text: tgfDictionary.getText("ProTip"),
		font: tgfSettings.fonts.proTip,
	});

	this.protipContainer.addComponent(this.protipBackground);
	this.protipContainer.addComponent(this.protipLabel);
	this.protipContainer.addComponent(this.protipDecoration);

	this.protipContainer.animator = new tbAnimator(this.protipContainer);
	this._animateProTip(this.protipContainer.animator, "x", 600, 140, 2000, 1000, tbEase.easeOutExponential);
	this.addComponent(this.protipContainer);
}

tgfDialogs.CalendarDialog.prototype._animateProTip = function (animator, variable, fromValue, toValue, delay, duration, ease) {
	var track = null;
	for (var i = 0; i < animator.tracks.length; i++) {
		if (animator.tracks[i].kind !== variable) continue;

		track = animator.tracks[i];
		break;
	}

	if (!track) {
		track = animator.addTrack(variable);
		animator.addKey(track, 0, fromValue, ease);
	}

	if (delay > 0) {
		animator.addKey(track, delay, fromValue, ease);
	}

	var durationFrame = delay + duration;

	animator.addKey(track, durationFrame, toValue, ease);
	animator.setTime(0);
}

tgfDialogs.CalendarDialog.prototype._clearMonth = function () {
	"use strict";
	var activeDays = this._activeDayComponents.length;
	for (var i = 0; i < activeDays; i++) {
		var current = this._activeDayComponents[i];
		this.removeComponent(current);
	}
	this._activeDayComponents.length = 0;
}

tgfDialogs.CalendarDialog.prototype._createMonth = function () {
	"use strict";

	var now = TimeManager.getDate();
	//Set the day of the week of the first day of this month.
	var start = 6;
	var daysInMonth = new Date(this._selectedYear, this._selectedMonth + 1, 0).getDate();

	var gap = 6;
	var dayPosition = 0;

	dayPosition = start;

	//Set the initX to offset of first day of the month
	var initX = this.dayOneX;
	var initY = this.dayOneY;

	var todaysDayComponent = null;

	for (var i = 0; i < daysInMonth; i++) {

		dayPosition++;
		dayPosition = dayPosition % 7;

		var targetDay = i + 1;
		var targetDate = new Date(this._selectedYear, this._selectedMonth, targetDay);
		var dayComponent = new tgfComponents.DayComponent({}, now, targetDate, this._monthData);

		initX += gap + tgfScale(this._horizontalSpacing);

		if ((i + 1 + start) % 7 === 0) {
			initY += gap + tgfScale(this._verticalSpacing);
			initX = this.dayOneX;
		}

		dayComponent.x = initX;
		dayComponent.y = initY;
		this.addComponent(dayComponent);
		dayComponent.show();
		dayComponent.activate();
		this._activeDayComponents.push(dayComponent);

		if (dayComponent.isToday) {
			todaysDayComponent = dayComponent;
		} else {
			//Delay adding the current day if it's in this month to sort the order of drawing. So the "today indication" animation is layered correctly
			this.addComponent(dayComponent);
			dayComponent.show();
		}
	}

	//Delay adding the current day if it's in this month to sort the order of drawing. So the "today indication" animation is layered correctly
	if (todaysDayComponent !== null) {
		this.addComponent(todaysDayComponent);
		todaysDayComponent.show();
	}
};

tgfDialogs.CalendarDialog.prototype.isPopupOpen = function () {
	var allTokens = tbGame.findAllTokens();
	for (var i = 0; i < allTokens.length; i++) {
		if (allTokens[i].isPopup) {
			return true;
		}
	}
	return false;
};

tgfDialogs.CalendarDialog.prototype.handleBeginStep = function (timePassed) {
	"use strict";

	if (this.protipContainer && this.protipContainer.animator && !this.isPopupOpen()) {
		this.protipContainer.animator.updateTime(timePassed);
	}
};

// Processing required when freeing the dialog from use
tgfDialogs.CalendarDialog.prototype.doFree = function () {
	"use strict";
	this.removeAllComponents();
	EventSystem.Global.removeEventListener(System_Event.SELECTED_MONTH_LOADED, this._showMonth, this);
	EventSystem.Global.removeEventListener(System_Event.DAY_UNLOCKED, this._showMonth, this);
	EventSystem.Global.removeEventListener(System_Event.AUTO_OPEN_DATE_CHANGED, this._clearAutoOpenDateTimeout, this);

	EventSystem.Global.removeEventListener(UI_Event.CALENDAR_DAY_BUTTON_CLICKED, this._clearAutoOpenDateTimeout, this);
	EventSystem.Global.removeEventListener(UI_Event.SETTINGS_BUTTON_CLICKED, this._clearAutoOpenDateTimeout, this);

	this._clearAutoOpenDateTimeout();

	this._backgroundImageDialog.free();
};

// Processing required when showing the dialog
tgfDialogs.CalendarDialog.prototype.doShow = function () {
	"use strict";
	EventSystem.Global.dispatchEvent(UI_Event.CALENDAR_SHOW, this._selectedYear, this._selectedMonth);

	if(!this.isRefreshed) {
		//Report the month offset to analytics.
		var today = TimeManager.getDate();
		var yearDiff =  this._selectedYear - today.getFullYear();
		var monthDiff = this._selectedMonth - today.getMonth() + yearDiff * 12;
		// Should show previous month as -1, 2 months ago as -2, etc
		SudokuAnalytics.reportShowingCalendarScreen(monthDiff);
	}
	
	this._backgroundImageDialog.show();
};

// Processing required when hiding the dialog
tgfDialogs.CalendarDialog.prototype.doHide = function () {
	"use strict";
	EventSystem.Global.dispatchEvent(UI_Event.CALENDAR_HIDE);
};
//******************************************************
//*****    Script Resource: DayComponent
//******************************************************

tgfSettings.dialogDefaults.dayComponent = {

	unlockableImage: s_ui_calendar_upcoming,
	unlockedImage: s_ui_calendar_previous,
	currentDayImage: s_ui_calendar_current,
	buttonStars: s_ui_calendar_difficulty,
	font: {
		fontFace: f_main_font.fontFace,
		fontSize: 34,
		baseline: "middle",
		align: "center"
	},
	components: [] // The additional components to add
};

// The constructor for the dialog
/**
 * @constructor
 * @base tgfDialogs.Base
 */
tgfComponents.DayComponent = function (properties, currentDate, targetDate, monthData) {
	"use strict";
	this.initialize(tgfSettings.dialogDefaults.dayComponent);

	this._monthData = monthData;
	this._currentDate = currentDate;
	this._date = targetDate;
	this.dayId = targetDate.getFullYear() + "_" + targetDate.getMonth() + "_" + targetDate.getDate();
	this.dailyData = monthData.getDailyDataById(this.dayId);
	this.isToday = this.isSameDay(currentDate);

	this.locked = !UnlockDataManager.isDayUnlocked(targetDate) && !VipMembership.isActive;

	// show unlock if we have no savedate but are unlocked
	if (!this.dailyData && this.isToday) {
		this.dailyData = this.unlock();
		this.unlockedToday = true;
	}
}

// Inherit the base dialog
tgfComponents.inherit(tgfComponents.DayComponent, tgfComponents.Base);

// Processing required when preparing the dialog for use
tgfComponents.DayComponent.prototype.doPrepare = function () {
	"use strict";
	var image = null;

	if (this.isToday) {
		image = this.currentDayImage;
	} else if (this.locked) {
		image = this.unlockableImage;
	} else {
		image = this.unlockedImage;
	}
	this._starContainer = new tgfComponents.Base({});

	this.button = new tgfComponents.Button({
		image: image,
		text: this._date.getDate().toString(),
		fontUp: this.locked ? tgfSettings.fonts.calendarDayNumberLocked : tgfSettings.fonts.calendarDayNumberUnlocked,
		marginTop: tgfScale(0),
		onClick: this.onClick.bind(this)
	});

	//Disabled until the onboarding gets implemented
	// if (this.unlockedToday) {
	// 	this.showUnlockAnimation();
	// 	this.button.alpha = 0;
	// 	this._starContainer.alpha = 0;
	// }

	this.addComponent(this.button);
	this.addComponent(this._starContainer);

	if (this.locked) {
		this._lockImage = new tgfComponents.Picture({
			image: s_icon_calendar_lock,
			x: 0,
			y: 20,
		});
		this.addComponent(this._lockImage);
	} else {

		var stars = this._totalDifficultiesCompleted() === 0 ? 
			this._createPlayButton() :
			this._createStars();

		this._starContainer.addComponent(stars);
	}

	if (this.isToday) {
		var targetX = (tgfSettings.graphics.areaWidth / 2) + this.x - (this.button.image.width / 2);
		var targetY = (tgfSettings.graphics.areaHeight / 2) + this.y - (this.button.image.height / 2);
		EventSystem.Global.dispatchEvent(UI_Event.CURRENT_DAY_BUTTON_CREATED, targetX - 5, targetY - 25, this.button.image.width + 10, this.button.image.height + 40);
	}
}

tgfComponents.DayComponent.prototype.onClick = function () {
	EventSystem.Global.dispatchEvent(UI_Event.CALENDAR_DAY_BUTTON_CLICKED, this._date);
}

tgfComponents.DayComponent.prototype.showUnlockAnimation = function () {
	this.animationContainer = new tgfComponents.Base({
		x: 0,
		y: 0
	});
	var emptyDayImage = new tgfComponents.Picture({
		image: s_day_previous_empty,
		x: 0,
		y: 0,
	});

	var self = this;
	var unlockButtonAnimation = new tgfComponents.SpineComponent({
		spineAnimation: unlock_calendarday,
		animationClips: ["animation_small lock on button_blue"], // The animation names from the spine json
		play: false,
		repeat: false,
		hasDelay: true,
		delay: 350,
		x: 0,
		y: 25,
		updateWhileUnactive: true,
		onComplete: self.onUnlockAnimationComplete.bind(this)
	});

	this.animationContainer.addComponent(emptyDayImage);
	this.animationContainer.addComponent(unlockButtonAnimation);
	this.addComponent(this.animationContainer);
}

tgfComponents.DayComponent.prototype.onUnlockAnimationComplete = function () {
	this.button.effects = [{
		effect: tgfEffects.fadeIn,
		duration: 1,
		onEffectEnd: this.onUnlockAnimationFadeInComplete.bind(this)
	}];

	this.button.repeatEffect = 1;
	this.button.restartEffect();

	this._starContainer.effects = [{
		effect: tgfEffects.nothing,
		duration: .6
	}, {
		effect: tgfEffects.fadeIn,
		duration: 1,
		onEffectEnd: this.onUnlockAnimationFadeInComplete.bind(this)
	}];
	this._starContainer.repeatEffect = 1;
	this._starContainer.restartEffect();
}

tgfComponents.DayComponent.prototype.onUnlockAnimationFadeInComplete = function () {
	this.removeComponent(this.animationContainer);
}

tgfComponents.DayComponent.prototype.unlock = function () {
	"use strict";
	// ILLEGAL change of outside object, dailyData should be prepared outside of this scope.
	var dailyData = this._monthData.unlockDailyDataById(this.dayId);
	this.locked = false;
	return dailyData;
}

tgfComponents.DayComponent.prototype.isSameDay = function (otherDate) {
	"use strict";
	var sameYear = this._date.getFullYear() === otherDate.getFullYear();
	var sameMonth = this._date.getMonth() === otherDate.getMonth();
	var sameday = this._date.getDate() === otherDate.getDate();
	return (sameYear && sameMonth && sameday);
}

tgfComponents.DayComponent.prototype._totalDifficultiesCompleted = function () {
	var difficulties = DifficultyUtil.getDifficulties(this._date);

	var difficultiesCompleted = 0;
	for (var difficultyKey in difficulties) {
		if (this.dailyData && this.dailyData.hasPointsForDifficulty(difficulties[difficultyKey])) {
			difficultiesCompleted++;
		}
	}

	return difficultiesCompleted;
};

tgfComponents.DayComponent.prototype._createPlayButton = function () {
	var playButton = new tgfComponents.Picture({
		image: s_btn_calendar_play,
		y: tgfScale(22)
	});

	return playButton;
};

tgfComponents.DayComponent.prototype._getDifficultiesReversed = function () {

	var difficulties = DifficultyUtil.getDifficulties(this._date);
	var keys = [];
	var reversed = {}

	for (var difficultyKey in difficulties) {
		keys.push(difficultyKey);
	}

	for (var i = keys.length - 1; i >= 0; i--) { 
		reversed[keys[i]] = difficulties[keys[i]];
	}

	return reversed;
};

tgfComponents.DayComponent.prototype._createStars = function () {

	var difficulties = this._getDifficultiesReversed();
	var totalDifficulties = ObjectUtil.getTotalProperties(difficulties);
	var subImage = totalDifficulties < 5 ? 3 : 4;
	var starWidth = 20;
	var xPos = starWidth;
	var yPos = 26;

	var container = new tgfComponents.Container({
		y: totalDifficulties < 5 ? -10 : 0
	});

	for (var difficultyKey in difficulties) {

		var isDifficultyCompleted = this.dailyData.hasPointsForDifficulty(difficulties[difficultyKey]);

		var star = new tgfComponents.Picture({
			image: this.buttonStars,
			x: xPos,
			y: yPos,
			startSubImage: isDifficultyCompleted ? subImage : 5
		});

		container.addComponent(star);

		subImage--;
		xPos-= starWidth;

		if(xPos <= -starWidth * 2) {
			xPos = starWidth * 0.5;
			yPos-= (starWidth - 3);
		}
	}

	return container;
};

tgfComponents.DayComponent.prototype.doShow = function () {
	this.alpha = 0;
	this.y += 20;
	this.effects = [{
			effect: tgfEffects.nothing,
			duration: (((this._date.getDate() - 1) % 7) / 7) + (this._date.getDate() / 80)
		},
		{
			effect: tgfEffects.transform,
			duration: 0.9 - (this._date.getDate() / 100),
			ease: tbEase.easeOutQuadratic,
			startX: this.x,
			endX: this.x,
			startY: this.y,
			endY: this.y - 20,
			startAlpha: 0,
			endAlpha: 1
		}
	];

	this.repeatEffect = 1;
	this.restartEffect();
}
