tgfDialogs.CalendarThemePreviewDialog = function (properties, calendar) {
    "use strict";
    this.name = "CalendarThemePreviewDialog";
    this.active = true;
    this._calendar = calendar;
    this._bar = null;

    this.initialize(tgfSettings.dialogDefaults.calendarThemePreviewDialog);
    this._prepareAssets();

    if (properties !== undefined) {
        this.setProperties(properties);
    }

    EventSystem.Global.addEventListener(System_Event.SELECTED_MONTH_LOADED, this._showRewards, this);
    EventSystem.Global.addEventListener(UI_Event.CALENDAR_SHOW, this._showRewards, this);
    EventSystem.Global.addEventListener(Theme_Event.ACTIVE_THEME_CHANGED, this._refreshCurrentCheckpointView, this);
    EventSystem.Global.addEventListener(Theme_Event.THEME_COLLECTED, this._onThemeCollection, this);

    EventSystem.Global.addEventListener(UI_Event.CALENDAR_SHOW, this._showTooltipForSelectedCheckpoint, this);
    EventSystem.Global.addEventListener(UI_Event.DIFFICULTY_SELECT_CLOSED, this._showTooltipForSelectedCheckpoint, this);

    this.barX += this.x;
    this.barY += this.y;
}

tgfDialogs.inherit(tgfDialogs.CalendarThemePreviewDialog, tgfDialogs.Base);

tgfDialogs.CalendarThemePreviewDialog.prototype.configureEvents = function (showEvent, hideEvent) {
    this._eventActions = new EventSystem.EventActions(this);
    this._eventActions.add(showEvent, this.showElements);
    this._eventActions.add(hideEvent, this.hideElements);
}

tgfDialogs.CalendarThemePreviewDialog.prototype.hideElements = function () {
    this.hide();
    if (this._bar) this._bar.hide();
}

tgfDialogs.CalendarThemePreviewDialog.prototype.showElements = function () {
    this.show();
    if (this._bar) this._bar.show();
}

