tgfDialogs.CalendarThemePreviewDialog.prototype._totalDifficultiesThisMonth = function () {

    var firstDayOfTheMonth = new Date(this._calendar.getSelectedYear(), this._calendar.getSelectedMonth(), 1);

    return DifficultyUtil.getTotalDifficultiesThisDay(firstDayOfTheMonth);
};

tgfDialogs.CalendarThemePreviewDialog.prototype._showRewards = function () {

    this._monthData = this._calendar.getSelectedData();

    this._monthLabel.text = (DateUtil.getMonthLabel(this._calendar.getSelectedMonth()) + " " + this._calendar.getSelectedYear()).toUpperCase();
    this._monthLabel.recreate();

    var completed = this._calendar.getDifficultiesCompleteInCurrentMonth().total;
    var totalPuzzlesInMonth = this._calendar.amountOfDaysInCurrentMonth() * this._totalDifficultiesThisMonth();

    this._completedLabel.text = (tgfDictionary.getText("puzzles_completed_in_month") + completed + "/" + totalPuzzlesInMonth).toUpperCase();
    this._completedLabel.recreate();

    this._checkPoints = this._makeCheckpoints(this._calendar.getSelectedMonth());
    var amount = this._checkPoints.length;

    var barCurrent = this._calendar.getDifficultiesCompleteInCurrentMonth().total;
    var barMax = this._getMaxCheckpointProgress();

    if (this._bar) this._bar.free();
    this._bar = null;
    this._bar = new GiftBarProgressController(this.barX, this.barY, this.barWidth, this.barHeight);
    this._bar.initialize(0, barMax, barCurrent);

    for (var i = 0; i < amount; i++) {
        var checkPoint = this._checkPoints[i];
        this._bar.addCheckpoint(checkPoint);
    }

    var nextCheckPoint = this.getNextCheckpoint();
    if (nextCheckPoint == null) {
        nextCheckPoint = this._checkPoints[amount - 1];
    }

    this._background.show();
    this._banner.show();
    this._completedLabel.show();
    this._monthLabel.show();
    this._currentUnlockLabel.show();
    this._activateThemeButton.show();
    this._logo.show();
    this._lock.show();
    this._themeName.show();
    this._activateThemeButton.isActive = true; //Buttons in the framework need to be manually set to active when they were disabled in the past. 
    this._checkBox.isActive = true;

    if (this._justUnlockedTheme) {
        this._selectCheckpoint(this._justUnlockedTheme);
        this._justUnlockedTheme = null;
    } else {
        this._selectCheckpoint(nextCheckPoint);
    }   
}

tgfDialogs.CalendarThemePreviewDialog.prototype._makeCheckpoints = function (currentMonth) {
    var awardsThisMonth = RewardController.getByCondition(REWARD_CONDITIONS.MONTHLY_PUZZLE);
    var amount = awardsThisMonth.length;
    var maxProgress = 0;
    var checkpoints = [];
    for (var i = 0; i < amount; i++) {
        var current = awardsThisMonth[i];
        if (current.getMonth() != currentMonth) continue;

        var progress = current.getPuzzles();
        if (progress > maxProgress) {
            maxProgress = progress;
        }
        var checkPoint = new BarCheckpointIcon(current.getPuzzles(), current.getIcon(), true, current);
        checkPoint.onClickedEvent.listen(this._onCheckPointClick.bind(this));
        checkpoints.push(checkPoint);
    }
    return checkpoints;
}

tgfDialogs.CalendarThemePreviewDialog.prototype._getMaxCheckpointProgress = function () {
    var amount = this._checkPoints.length;
    var maxProgress = 0;
    for (var i = 0; i < amount; i++) {
        var current = this._checkPoints[i];

        var progress = current.getProgress();
        if (progress > maxProgress) {
            maxProgress = progress;
        }
    }
    return maxProgress;
}

tgfDialogs.CalendarThemePreviewDialog.prototype.getNextCheckpoint = function () {
    var firstToUnlock = null;
    var position = 0;
    
    for (var i = 0; i < this._checkPoints.length; i++) {
        var checkPoint = this._checkPoints[i];
        if (checkPoint.payload.isUnlocked() == false) {
            if (firstToUnlock == null) {
                firstToUnlock = checkPoint;
                position = checkPoint.getProgress();
            } else {

                if (position > checkPoint.getProgress()) {
                    firstToUnlock = checkPoint;
                    position = checkPoint.getProgress();
                }
            }
        }
    }
    return firstToUnlock;
}

tgfDialogs.CalendarThemePreviewDialog.prototype._onThemeCollection = function (theme) {

    for (var i = 0; i < this._checkPoints.length; i++) {
        var checkPoint = this._checkPoints[i];
        if (checkPoint.payload.getUnlockId() === theme.getId()) {
            this._justUnlockedTheme = checkPoint;
        }
    }
};

tgfDialogs.CalendarThemePreviewDialog.prototype.setPreview = function (previewImage) {
    this.addComponent(previewImage);
    previewImage.show();

    this._themeUnlockTooltip.hide();
    // refresh dislpay index of other components
    this.removeComponent(this._background);
    this.removeComponent(this._completedLabel);
    this.removeComponent(this._currentUnlockLabel);
    this.removeComponent(this._monthLabel);
    this.removeComponent(this._banner);
    this.removeComponent(this._lock);
    this.removeComponent(this._activateThemeButton);
    this.removeComponent(this._checkBox);
    this.removeComponent(this._checkMark);
    this.removeComponent(this._themeUnlockTooltip);
    this.removeComponent(this._logo);
    this.removeComponent(this._themeName);
    this.addComponent(this._background);
    this.addComponent(this._completedLabel);
    this.addComponent(this._currentUnlockLabel);
    this.addComponent(this._monthLabel);
    this.addComponent(this._banner);
    this.addComponent(this._lock);
    this.addComponent(this._activateThemeButton);
    this.addComponent(this._checkBox);
    this.addComponent(this._checkMark);
    this.addComponent(this._themeUnlockTooltip);
    this.addComponent(this._logo);
    this.addComponent(this._themeName);
    this._banner.show();
}

tgfDialogs.CalendarThemePreviewDialog.prototype._onCheckPointClick = function (checkpoint) {
    this._selectCheckpoint(checkpoint);
    this._showTooltipForSelectedCheckpoint();
}

tgfDialogs.CalendarThemePreviewDialog.prototype._refreshCurrentCheckpointView = function () {

    var reward = this._selectedCheckPoint.payload;
    var themeID = reward.getUnlockId();
    var theme = ThemeController.getById(themeID);
    var isRewardUnlocked = reward.isUnlocked();
    this._lock.image = isRewardUnlocked ? this.lockOpen : this.lockClosed;

    this._setActivationButtonState(theme, reward);
    this._setCheckBoxState(theme, reward);
}

tgfDialogs.CalendarThemePreviewDialog.prototype._selectCheckpoint = function (checkpoint) {

    this.removeComponent(this._previewImage);

    if (!checkpoint) {
        return;
    }

    this._selectedCheckPoint = checkpoint;

    var reward = checkpoint.payload;
    var themeID = reward.getUnlockId();
    var theme = ThemeController.getById(themeID);
    var isRewardUnlocked = reward.isUnlocked();
    this._lock.image = isRewardUnlocked ? this.lockOpen : this.lockClosed;

    this._themeName.text = theme.getTitle();
    this._themeName.recreate();

    this._setActivationButtonState(theme, reward);
    this._setCheckBoxState(theme, reward);

    this._previewImage = new tgfComponents.Picture({
        image: theme.getPreviewImage(),
        x: tgfScale(s_ui_theme_progress_panel.width / 2),
        y: tgfScale(150)
    });

    var puzzlesComplete = this._calendar.getDifficultiesCompleteInCurrentMonth().total;
    var checkpointTarget = checkpoint.getProgress();

    if (puzzlesComplete >= checkpointTarget) {
        this._currentUnlockLabel.text = tgfDictionary.getText("checkpoint_target_reached");
    } else {
        this._currentUnlockLabel.text = this._calendar.getDifficultiesCompleteInCurrentMonth().total + "/" + checkpoint.getProgress();
    }
    this._currentUnlockLabel.recreate();

    this.setPreview(this._previewImage);


    this.addComponent(this._selectArrow);
    this.addComponent(this._currentUnlockLabel);
    this._selectArrow.show();

    this._selectArrow.x = checkpoint.getIconX() + 50;
    this._selectArrow.y = 243;
}

tgfDialogs.CalendarThemePreviewDialog.prototype._setActivationButtonState = function (theme, reward) {
    var self = this;
    if (gameData.activeThemeId == theme.getId()) {
        this._activateThemeButton.text = tgfDictionary.getText("currently_active_theme_button_text");
        this._activateThemeButton.fontUp = tgfSettings.fonts.activationButtonBlue;
        this._activateThemeButton.image = s_button_default_blue;
        this._activateThemeButton.x = tgfGraphics.visibleWidth - 190;
        this._activateThemeButton.onClick = function () {
            EventSystem.Global.dispatchEvent(Theme_Event.THEME_ACTIVATION_REQUEST, ThemeController.getDefault().getId());
        };
    } else if (reward.isUnlocked()) {
        this._activateThemeButton.text = tgfDictionary.getText("activate_theme_button_text");
        this._activateThemeButton.fontUp = tgfSettings.fonts.activationButtonGreen;
        this._activateThemeButton.image = s_button_default_green;
        this._activateThemeButton.x = tgfGraphics.visibleWidth - 190;
        this._activateThemeButton.onClick = function () {
            EventSystem.Global.dispatchEvent(Theme_Event.THEME_ACTIVATION_REQUEST, theme.getId());
        }
    } else {
        this._activateThemeButton.text = tgfDictionary.getText("locked_theme_button_text");
        this._activateThemeButton.fontUp = tgfSettings.fonts.activationButtonGrey;
        this._activateThemeButton.image = s_btn_default_gray;
        this._activateThemeButton.x = tgfGraphics.visibleWidth - 175;
        this._activateThemeButton.onClick = function () {
            self._themeUnlockTooltip.displayTooltip(reward.getRarity(), self._selectedCheckPoint.getProgress() - self._calendar.getDifficultiesCompleteInCurrentMonth().total);
        };
    }
    this._activateThemeButton.recreate();
}

tgfDialogs.CalendarThemePreviewDialog.prototype._checkboxClicked = function () {

    this._checkboxCheckState = !this._checkboxCheckState;
    this._checkboxCheckState ? this._checkMark.show() : this._checkMark.hide();
    this._activateThemeButton.onClick();
    this._refreshCurrentCheckpointView();
}

tgfDialogs.CalendarThemePreviewDialog.prototype._setCheckBoxState = function (theme, reward) {

    if (gameData.activeThemeId == theme.getId()) {
        this._checkboxCheckState = true;
        this._checkBox.show();
        this._checkMark.show();
    } else if (reward.isUnlocked()) {
        this._checkboxCheckState = false;
        this._checkBox.show();
        this._checkMark.hide();
    } else {
        this._checkboxCheckState = false;
        this._checkBox.hide();
        this._checkMark.hide();
    }
}

tgfDialogs.CalendarThemePreviewDialog.prototype._showTooltipForSelectedCheckpoint = function () {
    if(this._selectedCheckPoint.isLocked()){
        this._themeUnlockTooltip.displayTooltip(this._selectedCheckPoint.getRarity(), this._selectedCheckPoint.getProgress() - this._calendar.getDifficultiesCompleteInCurrentMonth().total);
    }
}
