/** 
 * ScoreMetaData. 
 */

var ScoreMetaData = (function () {
    var _ScoreMetaData = function () {
        // gameData.meta = [] with the following objects
        // {   Object structure
        //     aa: 20181,           // yearmonth (to correlate to leaderboard)
        //     bb: [0,0,0],         // amount of multipliers per difficulty (cumulative)
        //     crypto: "7hFHk234"   // red herring value to throw off people trying to modify values with a proxy (this._genRedHerring())
        // }
    }

    /**
     * saveMultiplierUsage
     * Save the usage of a multiplier for a puzzle. To be used in the max score caluclation that filters cheaters.
     */
    _ScoreMetaData.prototype.saveMultiplierUsage = function (difficulty, multiplier) {
        if (difficulty == null || typeof difficulty != "number") {
            console.error("Unexpected value for parameter 'difficulty': " + difficulty);
            return;
        }
        if (multiplier == null || typeof multiplier != "number") {
            console.error("Unexpected value for parameter 'multiplier': " + multiplier);
            return;
        }

        var entry = this._getEntry();

        entry.bb[difficulty] += multiplier - 1;

        saveDataService.savePlayerData(gameData.getSaveableGameData())
    };

    _ScoreMetaData.prototype._getEntry = function () {
        var now = TimeManager.getDate();
        //Save under year and month so we know which month this is aplicable to. (month +1 because gamesparks leaderboardType months are not zero based)
        var yearMonth = parseInt(now.getFullYear().toString() + (now.getMonth() + 1).toString());

        var entry;
        for (var index = 0; index < gameData.meta.length; index++) {
            if (gameData.meta[index].aa == yearMonth) {
                entry = gameData.meta[index];
            }
        }
        if (!entry) {
            entry = {
                aa: yearMonth,
                bb: [0, 0, 0],
                crypto: this._genRedHerring()
            }

            gameData.meta.push(entry);
        }

        return entry;
    };

    /**
     * overwriteMultiplierUsage
     * Function used to make the shadowban system more easily QA'able 
     * @param {Array[number]} multipliers 
     */
    _ScoreMetaData.prototype.overwriteMultiplierUsage = function (multipliers) {
        if (!multipliers || multipliers.length <= 0) {
            console.error("Unexpected input. Expected an array.");
            return;
        }

        var entry = this._getEntry();

        //Make sure the multipliers array is capped at 3. 
        if (multipliers.length > 3) {
            multipliers.length = 3;
        }

        for (var difficulty = 0; difficulty < multipliers.length; difficulty++) {
            entry.bb[difficulty] = parseInt(multipliers[difficulty]);
        }

        saveDataService.savePlayerData(gameData.getSaveableGameData())
    };

    /**
     * _genRedHerring
     * Function that returns a string of 8 random characters to throw cheaters off.
     */
    _ScoreMetaData.prototype._genRedHerring = function () {
        var text = "";
        var possible = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";

        for (var i = 0; i < 9; i++) {
            text += possible.charAt(Math.floor(Math.random() * possible.length));
        }

        return text;
    };


    return new _ScoreMetaData();
}());
