var gameStateHandler = function () {
    this._gameStateStorageKey = this._generateStorageKey('gameState');

    //version number as of which the gameStateStorage has been fixed.
    this._lastVersionStorageKey = this._generateStorageKey('lastVersion');

    this._leaderboardPosStorageKey = this._generateStorageKey('lb_pos');

    this._randomKey = defaultRandom.iRandomRange(10000, 20000);

    this._storage = tgfStatus.storage;

    this._leaderboardPosition = this._loadData(this._leaderboardPosStorageKey) || {};

    this.gameStateDataService = null;

    this._addListeners();
}

gameStateHandler.prototype.initialize = function () {
    var self = this;
    return new Promise(function (resolve, reject) {
        self.gameStateDataService = new LocalStoragePlayerDataService();

        self.gameStateDataService.initialize().then(function () {
			console.log("[gameStateDataService] complete");
			resolve();
        }).catch(function (err) {
            // MessyAnalytics.setStorageNotAvailable(err.message);
            self.gameStateDataService = null;
			console.error("[gameStateDataService] Did not initialize: " + JSON.stringify(err), err.stack);
			resolve();
        });
    });

}

gameStateHandler.prototype._addListeners = function () {
    EventSystem.Global.addEventListener(System_Event.SAVE_GAMESTATE, this._saveGameState, this);
    EventSystem.Global.addEventListener(System_Event.LEVEL_SOLVED, this._wipeGameState, this);
    EventSystem.Global.addEventListener(System_Event.LEVEL_QUIT, this._wipeGameState, this);
};

/**
 * saves the current state of the game.
 */
gameStateHandler.prototype._saveGameState = function (date, difficulty, time, score, fieldInfo, mistakesLeft) {
    'use strict';

    if (difficulty === "tutorial") {
        console.warn("[GamestateHandler] Tutorial is active. Saving of the gamestate is disabled");
        return;
    }

    if (
        date === undefined ||
        difficulty === undefined ||
        time === undefined ||
        score === undefined ||
        fieldInfo === undefined
    ) {
        console.error("[GamestateHandler] There is an undefined value in the passed parameters.", date, difficulty, time, score, fieldInfo);
    }

    var gameState = {
        'date': date.getTime(),
        'difficulty': difficulty,
        'time': time,
        'score': score,
        'fieldInfo': fieldInfo,
        'mistakesLeft': mistakesLeft
    };

    this._saveData(this._gameStateStorageKey, gameState);
};

gameStateHandler.prototype.loadGameState = function () {
    'use strict';
    var self = this;



    return new Promise(function (resolve, reject) {

        self._loadData(self._gameStateStorageKey)
            .then(function (gameStateData) {

                if (gameStateData) {
                    if (!('fieldInfo' in gameStateData)) {
                        console.warn("[GameStateHandler] 'fieldInfo' could not be found in gamestateData: returning null");
                        resolve(null);
                        return;
                    }
                    if (!('date' in gameStateData)) {
                        console.warn("[GameStateHandler] 'date' could not be found in gamestateData: returning null");
                        resolve(null);
                        return;
                    }
                    if (!('difficulty' in gameStateData)) {
                        console.warn("[GameStateHandler] 'difficulty' could not be found in gamestateData: returning null");
                        resolve(null);
                        return;
                    }
                    if (!('time' in gameStateData)) {
                        console.warn("[GameStateHandler] 'time' could not be found in gamestateData: returning null");
                        resolve(null);
                        return;
                    }
                    if (!('score' in gameStateData)) {
                        console.warn("[GameStateHandler] 'score' could not be found in gamestateData: returning null");
                        resolve(null);
                        return;
                    }
                }

                resolve(gameStateData);

            }).catch(function (err) {
                reject(err);
            });
    });
}

gameStateHandler.prototype._wipeGameState = function () {
    'use strict';

    this._saveData(this._gameStateStorageKey, {});
};

gameStateHandler.prototype._createLeaderboardType_ID_Entry = function (leaderboardId, leaderboardType) {
    'use strict';

    if (!this._leaderboardPosition[leaderboardId]) {
        this._leaderboardPosition[leaderboardId] = {};
    }
    if (!this._leaderboardPosition[leaderboardId][leaderboardType]) {
        this._leaderboardPosition[leaderboardId][leaderboardType] = {};
    }
};

gameStateHandler.prototype.saveLeaderboardLastPosition = function (leaderboardId, leaderboardType, lastPosition) {
    'use strict';

    this._createLeaderboardType_ID_Entry(leaderboardId, leaderboardType);

    this._leaderboardPosition[leaderboardId][leaderboardType]['lastPosition'] = lastPosition;

    this._saveData(this._leaderboardPosStorageKey, this._leaderboardPosition);
};

gameStateHandler.prototype.saveLeaderboardLastSeen = function (leaderboardId, leaderboardType, lastSeen) {
    'use strict';

    this._createLeaderboardType_ID_Entry(leaderboardId, leaderboardType);

    this._leaderboardPosition[leaderboardId][leaderboardType]['lastSeen'] = lastSeen;

    this._saveData(this._leaderboardPosStorageKey, this._leaderboardPosition);
};

gameStateHandler.prototype.saveLeaderboardShowNotification = function (leaderboardId, leaderboardType, showNotification) {
    'use strict';

    this._createLeaderboardType_ID_Entry(leaderboardId, leaderboardType);

    this._leaderboardPosition[leaderboardId][leaderboardType]['showNotification'] = showNotification;

    this._saveData(this._leaderboardPosStorageKey, this._leaderboardPosition);
};

gameStateHandler.prototype.getLeaderboardLastPosition = function (leaderboardId, leaderboardType) {
    'use strict';

    this._createLeaderboardType_ID_Entry(leaderboardId, leaderboardType);

    return this._leaderboardPosition[leaderboardId][leaderboardType]['lastPosition'];
};

gameStateHandler.prototype.getLeaderboardLastSeen = function (leaderboardId, leaderboardType) {
    'use strict';

    this._createLeaderboardType_ID_Entry(leaderboardId, leaderboardType);

    return this._leaderboardPosition[leaderboardId][leaderboardType]['lastSeen'];
};

gameStateHandler.prototype.getLeaderboardShowNotification = function (leaderboardId, leaderboardType) {
    'use strict';

    this._createLeaderboardType_ID_Entry(leaderboardId, leaderboardType);

    return this._leaderboardPosition[leaderboardId][leaderboardType]['showNotification'];
};

/**
 * Encodes the data and then saves it to gamestate data service.
 * @param {String} storageKey the unique identifier for the gamestate data service entry. Use _generateStorageKey to generate one.
 * @param {Object} data the data you want to store, represented as an object.
 */
gameStateHandler.prototype._saveData = function (storageKey, data) {
    'use strict';

    if (!this.gameStateDataService) {
        console.warn("[GamestateHandler] Save data service not available");
        return;
    }
    var encodedData = this._storage._hexEncode(this._randomKey, JSON.stringify(data));

    /**playerData module expects an object following the following scheme:
     * {
     *      identifier: "gameState",
     *      data: { ... }
     * }
     */
    this.gameStateDataService.savePlayerData(
            [{
                identifier: storageKey,
                data: {
                    data: encodedData
                }
            }]
        ).then(function () {
            console.log("[GamestateHandler] Success saving data");
        })
        .catch(function (err) {
            errorLoggingService.sendError(err);
            console.error("[GamestateHandler] There was an error saving the data for key: '" + storageKey + "'. Error: " + err + "\n" + err.stack);
        });
};

/**
 * Loads the data from gamestate data service, decodes it and returns it.
 * @param {String} storageKey the unique identifier for the gamestate data service entry. Use _generateStorageKey to generate one.
 */
gameStateHandler.prototype._loadData = function (storageKey) {
    'use strict';

    if (!this.gameStateDataService) {

        console.warn("[GamestateHandler] Save data service not available");
        return Promise.resolve();
    }

    var self = this;
    return new Promise(function (resolve, reject) {
        self.gameStateDataService.getPlayerData([storageKey])
            .then(function (data) {
                var decodedData = {};

                if (data[storageKey] && data[storageKey].data) {
                    decodedData = JSON.parse(self._storage._hexDecode(data[storageKey].data));
                }

                resolve(decodedData);
            })
            .catch(function (err) {
                console.warn("[GamestateHandler] No data was returned for key: '" + storageKey + "'. The following reason was provided:" + err);
                resolve({});
            });
    });
};

/**
 * generates a key for the specific facebook user with an additional label.
 * @param {String} label the unique identifier for the localStorage entry.
 */
gameStateHandler.prototype._generateStorageKey = function (label) {
    'use strict';

    return StringUtil.format('dailySudoku_{0}', label);
};
