//******************************************************

UnlockDayRules = {};
 
UnlockDayRules.isToday = function (date, dayData) {
    var now = TimeManager.getDate();
    var sameYear = date.getFullYear() === now.getFullYear();
	var sameMonth = date.getMonth() === now.getMonth();
	var sameday = date.getDate() === now.getDate();
	return (sameYear && sameMonth && sameday);
}

UnlockDayRules.isBeforeToday = function (date, dayData) {
    var now = TimeManager.getDate();
    
    var yearDifference = date.getFullYear() - now.getFullYear();
    if (yearDifference < 0) return true; 
    if (yearDifference > 0) return false; 

    var monthDifference = date.getMonth() - now.getMonth();
    if (monthDifference < 0) return true; 
    if (monthDifference > 0) return false; 

    var dayDifference = date.getDate() - now.getDate();
    if (dayDifference < 0) return true; 
    return false; 

}

UnlockDayRules.hasData = function (date, dayData) {
    return !!dayData;
}
