var StringUtil = {};

StringUtil.getTextHeight = function (text, font) {
    var vectorFont = new tbVectorFont();

    vectorFont.setProperties(font);

    return vectorFont.textHeight(text);
};

StringUtil.getTextWidth = function (text, font) {
    var vectorFont = new tbVectorFont();

    vectorFont.setProperties(font);

    return vectorFont.textWidth(text);
};

StringUtil.format = function () {
    // The string containing the format items (e.g. "{0}")
    // will and always has to be the first argument.
    var theString = arguments[0];

    // start with the second argument (i = 1)
    for (var i = 1; i < arguments.length; i++) {
        // "gm" = RegEx options for Global search (more than one instance)
        // and for Multiline search
        var regEx = new RegExp("\\{" + (i - 1) + "\\}", "gm");

        theString = theString.replace(regEx, arguments[i]);
    }

    return theString;
};

StringUtil.thousandsSeparator = function (string, separator) {
    return string.replace(/\B(?=(\d{3})+(?!\d))/g, separator);
};

StringUtil.pad = function (targetValue, width, padCharacter) {
    padCharacter = padCharacter || '0';
    targetValue = targetValue + '';

    if (targetValue.length < width) {
        var paddingLeft = width - targetValue.length ;
        while (paddingLeft--) {
            targetValue = padCharacter + targetValue;
        }
    }

    return targetValue;
};

StringUtil.milliSecondsToHHMMSS = function (milliseconds) {

    var seconds = milliseconds / 1000;
    var hours = parseInt(seconds / 3600);
    seconds = seconds % 3600;
    var minutes = parseInt(seconds / 60);
    seconds = seconds % 60;
    seconds = parseInt(seconds);

    if (hours > 0) {
        return StringUtil.pad(hours, 2) + ":" + StringUtil.pad(minutes, 2) + ":" + StringUtil.pad(seconds, 2);
    } else {
        return StringUtil.pad(minutes, 2) + ":" + StringUtil.pad(seconds, 2);
    }
};
