var DateUtil = {};

DateUtil.getDayLabel = function (day) {
	"use strict";

	// -1 because js day 0 = sunday, ours is monday.
	day = day - 1 < 0 ? 6 : day - 1;

    // if (!this.dayStrings) {
        this.dayStrings = JSON.parse(tgfDictionary.getText("Days"));
    // }

    return this.dayStrings[day];
};

DateUtil.getMonthLabel = function (month) {
    "use strict";
    // if (!this.monthStrings) {
        this.monthStrings = JSON.parse(tgfDictionary.getText("Months"));
    // }

    return this.monthStrings[month];
};

DateUtil.getHoursUntilNextMonth = function () {

    'use strict';

    var now = TimeManager.getDate();
    var nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    var hoursToNextMonth = (nextMonth - now) / 36e5;

    return Math.floor(hoursToNextMonth);
};

/**
 * dateToLevelIndex
 * 
 * Gets the level index (also called 'puzzleId' in some instances) for the selected day.
 * The logic behind the level index is that the [1st of January 2016 is level 1].
 * Every day the puzzleIndex goes up by 1
 * 
 * @param {number} year 
 * @param {number} month 
 * @param {number} day 
 * 
 * @returns {number} levelIndex
 */
DateUtil.dateToLevelIndex = function (year, month, day) {

	"use strict";
	var levelIndex = DateUtil.getDayOfYear(year, month, day) + 1;

	if (year > 2016) {
		var yearDifference = year - 2016;

		for (var i = 0; i < yearDifference; i++) {
			levelIndex += DateUtil.getDayOfYear(year - (i + 1), 11, 31) + 1;
		}
	}

	return levelIndex;
};

/**
 * get the day of the year
 * 
 * @param {number} year 
 * @param {number} month 
 * @param {number} day 
 * 
 * @returns {number} what day of the year the provided day is.
 */
DateUtil.getDayOfYear = function (year, month, day) {
	"use strict";
	var date = new Date(year, month, day);
	var start = new Date(date.getFullYear(), 0, 0);
	var diff = (date - start) + ((start.getTimezoneOffset() - date.getTimezoneOffset()) * 60 * 1000);
	var oneDay = 1000 * 60 * 60 * 24;
	var dayOfYear = Math.floor(diff / oneDay);

	return dayOfYear;
};

/**
 * return if the two dates are from the same day
 * 
 * @param {date} a 
 * @param {date} b 
 * 
 * @returns {boolean} if the two dates are from the same day
 */
DateUtil.isSameDay = function (a, b) {
	return (
		a.getFullYear() === b.getFullYear() &&
		a.getMonth() === b.getMonth() &&
		a.getDate() === b.getDate()
	);
};
