// *********************************
// CoolGames Builder JavaScript file
// *********************************

var RewardUnlockResponse = Object.freeze({
    SUCCESS: "SUCCESS",
    FAIL: "FAIL",
    CANCELLED: "CANCELLED"
});

var Unlock_Method = Object.freeze({
    ADS: "ADS",
    SOCIAL: "SOCIAL",
    IAP: "IAP",
    FREE: "FREE",
    CONSUMABLE: "CONSUMABLE"
});

var ConditionalUnlockController = function (unlockMethodPriorityConfig) {
    this._unlockMethodPriorityConfig = unlockMethodPriorityConfig;
    this._currentUnlockMethodIndex = 0;
    this._currentUnlockMethod = this._unlockMethodPriorityConfig[this._currentUnlockMethodIndex];
    this._popupThrobber = new tgfDialogs.ThrobberDialog({});

    this.onUnlock = new EventSystem.Local();
    this.onUnlockMethodChanged = new EventSystem.Local();
};

/**
 * Attempts to unlock a reward with the currently selected unlockMethod
 *
 * @return {Promise<RewardUnlockResponse>} that resolves with a response RewardUnlockResponse
 */
ConditionalUnlockController.prototype.unlock = function () {
    switch (this._currentUnlockMethod) {
        case Unlock_Method.ADS:
            return this._adUnlock();
        case Unlock_Method.SOCIAL:
            return this._socialUnlock();
        case Unlock_Method.CONSUMABLE:
            return this._consumableUnlock();
        case Unlock_Method.FREE:
            return Promise.resolve(RewardUnlockResponse.SUCCESS);
        default:
            return Promise.reject("[ConditionalUnlockController] _currentUnlockMethod not recognised. (" + this._currentUnlockMethod + ")");
    }
};

ConditionalUnlockController.prototype._adUnlock = function () {
    this._activateThrobber(true);

    var self = this;
    return new Promise(function (resolve, reject) {
        BoosterSDK.showRewarded(function () {
            self.onUnlock.trigger();
            self._activateThrobber(false);
            resolve(RewardUnlockResponse.SUCCESS);
        }, function () {
            self._setNextUnlockMethod();
            self._activateThrobber(false);
            resolve(RewardUnlockResponse.FAIL);
        });
    });
};

ConditionalUnlockController.prototype._socialUnlock = function () {
    this._activateThrobber(true);

    var self = this;
    return new Promise(function (resolve, reject) {
        messagingPlatformService.selectContext()
            .then(function () {
                SudokuAnalytics.reportContextSwitch();
//                MessyAnalytics.contextSwitch();
                GiftManager.postRewardedCustomUpdate();

                self.onUnlock.trigger();
                self._activateThrobber(false);
                resolve(RewardUnlockResponse.SUCCESS);
            })
            .catch(function (reason) {

                if (reason.code === "SAME_CONTEXT") {
                    resolve(RewardUnlockResponse.FAIL);
                    self._activateThrobber(false);
                    return;
                }

                if (reason.code === "USER_INPUT") {
                    resolve(RewardUnlockResponse.CANCELLED);
                    self._activateThrobber(false);
                    return;
                }

                self._setNextUnlockMethod();
                resolve(RewardUnlockResponse.FAIL);
                self._activateThrobber(false);
            });
    });
};

ConditionalUnlockController.prototype._consumableUnlock = function () {
    var self = this;
    return new Promise(function (resolve, reject) {
        self._consumableUnlockMethod.unlock()
            .then(function () {
                self.onUnlock.trigger();
                resolve(RewardUnlockResponse.SUCCESS);
            }).catch(function (err) {
                resolve(RewardUnlockResponse.FAIL);
                self.retryUnlockMethod();
            });
    });
};

ConditionalUnlockController.prototype._activateThrobber = function (shouldActivate) {
    if (shouldActivate) {
        this._popupThrobber.show();
        EventSystem.Global.dispatchEvent(Level_Event.LEVEL_PAUSED);
    } else {
        this._popupThrobber.hide();
        EventSystem.Global.dispatchEvent(Level_Event.LEVEL_RESUMED);
    }
};

ConditionalUnlockController.prototype.setConsumableUnlockMethod = function (method) {
    this._consumableUnlockMethod = method;
}

ConditionalUnlockController.prototype._setNextUnlockMethod = function () {
    this._currentUnlockMethodIndex++;
    if (this._currentUnlockMethodIndex < this._unlockMethodPriorityConfig.length) {
        this._currentUnlockMethod = this._unlockMethodPriorityConfig[this._currentUnlockMethodIndex];
        this.onUnlockMethodChanged.trigger();
    } else {
        this._currentUnlockMethod = null;
        EventSystem.Global.dispatchEvent(UI_Event.SHOW_UNLOCK_ERROR_NOTIFICATION, this._currentUnlockMethod);
    }
};

/**
 * getNextUnlockMethod
 * @returns {Unlock_Method} the currently selected unlock method
 */
ConditionalUnlockController.prototype.getNextUnlockMethod = function () {
    return this._currentUnlockMethod;
};

/**
 * retryUnlockMethod
 * Sets the current unlock method to the previous one that failed.
 */
ConditionalUnlockController.prototype.retryUnlockMethod = function () {

    this._currentUnlockMethodIndex--;
    this._currentUnlockMethod = this._unlockMethodPriorityConfig[this._currentUnlockMethodIndex];
};

/**
 * getNextUnlockMethod
 * @returns {Unlock_Method} the previous unlock method
 */
ConditionalUnlockController.prototype.getPreviousUnlockMethod = function () {
    if (this._unlockMethodPriorityConfig.length >= this._currentUnlockMethodIndex - 1) {
        return this._unlockMethodPriorityConfig[this._currentUnlockMethodIndex - 1];
    } else {
        return null;
    }
}
