tgfSettings.dialogDefaults.maskableOverlayDialog = {};

tgfDialogs.MaskableOverlayDialog = function (properties) {
    "use strict";
    this.name = "MaskableOverlayDialog";
    this.initialize(tgfSettings.dialogDefaults.maskableOverlayDialog);

    if (properties !== undefined) {
        this.setProperties(properties);
    }
    this.overlayContainer = new tgfComponents.Base({});
    this.overlayContainer.onSubEffectStart = this.onContainerSubEffectStart.bind(this);
    this._masks = {};
    this.overlayContainer.alpha = 0;
};

tgfDialogs.inherit(tgfDialogs.MaskableOverlayDialog, tgfDialogs.Base);

tgfDialogs.MaskableOverlayDialog.prototype.handleDraw = function () {
    "use strict";
    var val = tgfDialogs.MaskableOverlayDialog.uber.handleDraw.call(this);
    this._renderMaskers();
    return val;
}

tgfDialogs.MaskableOverlayDialog.prototype.setAnimations = function (animations) {
    "use strict";
    this.overlayContainer.effects = null;
    if (animations == undefined) return;
    this.overlayContainer.repeatEffect = 1;
    this.overlayContainer.effects = animations;
}

tgfDialogs.MaskableOverlayDialog.prototype.startAnimation = function () {
    this.overlayContainer.restartEffect();
}

tgfDialogs.MaskableOverlayDialog.prototype.onContainerSubEffectStart = function (component, effect) {

    if (effect.type == "mask") {
        this.setMask(effect.id, effect);
    }
}

tgfDialogs.MaskableOverlayDialog.prototype.handleEndStep = function (timePassed) {
    "use strict";
    tgfDialogs.MaskableOverlayDialog.uber.handleEndStep.call(this, timePassed);

    for (var key in this._masks) {
        this._masks[key].update(timePassed);
    }
}

tgfDialogs.MaskableOverlayDialog.prototype._isMaskAt = function (x, y) {
    var pixel = this._getPixelAt(x, y);
    return pixel[3] >= 128;
}

tgfDialogs.MaskableOverlayDialog.prototype._isMaskAnimationTargetAt = function (x, y) {
    for (var key in this._masks) {
        if ( this._masks[key].pointInAnimationTarget(x,y) ) return true;
    }
    return false;
}

tgfDialogs.MaskableOverlayDialog.prototype._isInNoninteractableMask = function (x, y) {
    for (var key in this._masks) {
        var currentMask = this._masks[key];
        if (currentMask.interactive == false && currentMask.pointInAnimationTarget(x, y)) return true;
        
    }
    return false;
}

tgfDialogs.MaskableOverlayDialog.prototype._getPixelAt = function (x, y) {
    var imgData = this.ctx.getImageData(x, y, 1, 1);
    return imgData.data;
}

tgfDialogs.MaskableOverlayDialog.prototype._animateMask = function (shape, maskSettings) {
    shape.animateTo(maskSettings.x, maskSettings.y, maskSettings.width, maskSettings.height, maskSettings.duration, maskSettings.ease);
}

tgfDialogs.MaskableOverlayDialog.prototype.doPrepare = function () {
    this.updateIndex = 0;

    var size = {
        x: tgfSettings.graphics.areaWidth,
        y: tgfSettings.graphics.areaHeight
    };
    this.overlay = new tbSurface(size.x, size.y);
    var ctx = this.overlay.canvas.getContext("2d");
    this.ctx = ctx;
    this.addComponent(this.overlayContainer);


    this._renderMaskers();
    this.picture = new tgfComponents.Picture({
        image: this.overlay,
        x: size.x / 2,
        y: size.y / 2
    });

    this.overlayContainer.addComponent(this.picture);
}

tgfDialogs.MaskableOverlayDialog.prototype.setMask = function (id, maskSettings) {

    var mask = this._masks[id];

    this._validateMaskSettings(maskSettings);

    if (mask === undefined) {

        var mask = Object.create(OverlayMask);
        this._masks[id] = mask;
        mask.image = maskSettings.image;
        mask.set(maskSettings.x, maskSettings.y, maskSettings.width, maskSettings.height);
        mask.interactive = maskSettings.interactive;
        mask.alpha = maskSettings.alpha ? maskSettings.alpha : 1;
        mask.hidden = false;
        mask.init();
    } else {

        mask.hidden = false;
        this._animateMask(mask, maskSettings);
    }

    return mask;
}

tgfDialogs.MaskableOverlayDialog.prototype._renderMaskers = function () {
    this._mask(s_pixel_darkoverlay, this._masks, this.overlay);
}

tgfDialogs.MaskableOverlayDialog.prototype._mask = function (imageOne, _masks, outSurface) {

    var outputSurface = outSurface;
    if (outputSurface == null) {
        outputSurface = new tbSurface(mask.width, mask.height);
    }

    outputSurface.clear();
    outputSurface.setTarget();

    //(number, sx, sy, sw, sh, dx, dy, dw, dh, alpha
    imageOne.drawPartStretched(0, 1, 1, 1, 1, 0, 0, 640, 1024);

    tbGraphics.context.globalCompositeOperation = "destination-out";
    for (var key in this._masks) {
        var currentMask = _masks[key];
        currentMask.draw();
    }
    tbGraphics.context.globalCompositeOperation = "source-over";

    outputSurface.resetTarget();

    return outputSurface;
}

tgfDialogs.MaskableOverlayDialog.prototype.hideShape = function (id) {
    var mask = this._masks[id];

    if (mask == null) {
        throw ("Shape not found for id: " + id);
    }

    mask.hidden = true;
    return mask;
}

tgfDialogs.MaskableOverlayDialog.prototype.showShape = function (id) {
    var mask = this._masks[id];

    if (mask == null) {
        throw ("Shape not found for id: " + id);
    }

    mask.hidden = false;
    return mask;
}

tgfDialogs.MaskableOverlayDialog.prototype.removeAll = function () {
    for (var key in this._masks) {
        this.removeShape(key);
    }
}

tgfDialogs.MaskableOverlayDialog.prototype.removeShape = function (id) {
    var mask = this._masks[id];

    if (mask == null) {
        throw ("Shape not found for id: " + id);
    }

    mask.deleted = true;
    mask.image = null;

    delete this._masks[id];
}

tgfDialogs.MaskableOverlayDialog.prototype._validateMaskSettings = function (settings) {
    if (
        settings.image == undefined ||
        settings.x == undefined ||
        settings.y == undefined ||
        settings.width == undefined ||
        settings.height == undefined) {
        throw "[MaskableOverlayDialog] Invalid mask settings. Required property not defined. /n" + JSON.stringify(settings);
    }
}

tgfDialogs.MaskableOverlayDialog.prototype.handleTouchDown = function (finger, x, y) {
    "use strict";
    return !this._isMaskAnimationTargetAt(x, y); // This makes sure we can't click something in the background
};

tgfDialogs.MaskableOverlayDialog.prototype.handleTouchUp = function (finger, x, y) {
    "use strict";
    var hitNonInteractive = this._isInNoninteractableMask(x, y);
    if (hitNonInteractive == false) {
        EventSystem.Global.dispatchEvent(UI_Event.TUTORIAL_CLICK_ANYWHERE_CLICKED);
    }
    return !this._isMaskAnimationTargetAt(x, y); // This makes sure we can't click something in the background
};

tgfDialogs.MaskableOverlayDialog.prototype.handleImmediateTouchUp = function (finger, x, y) {
    "use strict";
    return !this._isMaskAnimationTargetAt(x, y); // This makes sure we can't click something in the background
};

tgfDialogs.MaskableOverlayDialog.prototype.handleImmediateTouchDown = function (finger, x, y) {
    "use strict";
    return !this._isMaskAnimationTargetAt(x, y); // This makes sure we can't click something in the background
};
//******************************************************
//*****    Script Resource: OverlayMask
//******************************************************

var OverlayMask = {

    _x: 0,
    _y: 0,
    _width: 0,
    _height: 0,
    image: null,
    alpha: 1,
    hidden: false,
    _animator: null,
    _animationTarget: null,
    interactive: true,
    
    set: function (x, y, width, height) {
        this._animationTarget = {};
        this._x = x;
        this._width = width;
        this._height = height;
        this._y = y;
        
        this._animationTarget.x = x;
        this._animationTarget.width = width;
        this._animationTarget.height = height;
        this._animationTarget.y = y;
    },

    draw: function () {
        if (this.hidden) return;
        this.image.drawNineSlice(0, this._x, this._y, this._width, this._height, this.alpha, 50, 50, 50, 50);
    },

    init: function () {
        this._animator = new tbAnimator(this);

        this._animatorPopupTrackX = this._animator.addTrack('_x');
        this._animatorPopupTrackY = this._animator.addTrack('_y');
        this._animatorPopupTrackWidth = this._animator.addTrack('_width');
        this._animatorPopupTrackHeight = this._animator.addTrack('_height');
        this._animatorPopupTrackAlpha = this._animator.addTrack('_alpha');

    },

    update: function (timePassed) {
        this._animator.updateTime(timePassed);
    },

    pointInAnimationTarget: function (x, y) {
        if (x >= this._animationTarget.x && x <= this._animationTarget.x + this._animationTarget.width) {
            return y >= this._animationTarget.y && y <= this._animationTarget.y + this._animationTarget.height;
        } return false;
    },

    animateTo: function (x, y, width, height, duration, ease) {
        
        var time = duration ? (duration * 1000) : 1000;
        var ease = ease ? ease : tbEase.easeOutSine;
        
        this._animationTarget.x = x;
        this._animationTarget.y = y;
        this._animationTarget.width = width;
        this._animationTarget.height = height;

        this._animationToTarget(time, ease );

    },
     
    _animationToTarget: function (duration, ease) {
        
        this._animator.pause();
        this._animator.removeAllKeys();
        this._animator.removeEvents();
        
        this._animator.addKey(this._animatorPopupTrackX, 0, this._x, ease);
        this._animator.addKey(this._animatorPopupTrackX, duration, this._animationTarget.x,ease);
        this._animator.addKey(this._animatorPopupTrackY, 0, this._y, ease);
        this._animator.addKey(this._animatorPopupTrackY, duration, this._animationTarget.y, ease);

        this._animator.addKey(this._animatorPopupTrackWidth, 0, this._width, ease);
        this._animator.addKey(this._animatorPopupTrackWidth, duration, this._animationTarget.width, ease);
        this._animator.addKey(this._animatorPopupTrackHeight, 0, this._height, ease);
        this._animator.addKey(this._animatorPopupTrackHeight, duration, this._animationTarget.height, ease);

        
        this._animator.setTime(0);
        this._animator.resumeForced();
    }
}
//******************************************************
//*****    Script Resource: TimeUtil
//******************************************************

var TimeUtil = {}

/**
 * Timer settings used to create a new timer
 *
 * @param {EventSystem.Local} onStart
 * @param {EventSystem.Local} onEnd
 * @param {EventSystem.Local} onInterval
 * @param {number} interval
 * @param {number} duration
 */
TimeUtil.TimerSettings = function (onStart, onEnd, onInterval, interval, duration) {
    this.onStart = onStart;
    this.onEnd = onEnd;
    this.onInterval = onInterval;
    this.interval = interval;
    this.duration = duration;
};

/**
 * TimeUtil.Timer
 * Create a timer with methods to pause resume or stop 
 *
 * @param {TimeUtil.TimerSettings} timerSettings
 */
TimeUtil.Timer = function (timerSettings) {

    this._onStart = timerSettings.onStart;
    this._onEnd = timerSettings.onEnd;
    this._onInterval = timerSettings.onInterval;
    this._intervalFrequency = timerSettings.interval;

    this._initialDuration = timerSettings.duration;

    this._timer = null;
    this._interval = null;
    this._started = null;
    this._timeoutValue = this._initialDuration;
    this._totalTimePassed = 0;
    this._isPaused = true;
    this._time = 0;

    this.resume();
    tbGame.addToken(this);
    this._onStart.trigger();
}

TimeUtil.Timer.prototype.pause = function () {

    this._isPaused = true;

    window.clearTimeout(this._timer);
    this._timeoutValue -= new Date() - this._started;
};

TimeUtil.Timer.prototype.resume = function () {
    var self = this;

    this._isPaused = false;
    this._started = new Date();
    window.clearTimeout(this._timer);

    this._timer = window.setTimeout(function () {
        self.stop();
        self._onEnd.trigger();
    }, this._timeoutValue);
};

TimeUtil.Timer.prototype.stop = function () {

    tbGame.removeToken(this);
    window.clearTimeout(this._timer);
    window.clearInterval(this._interval);
}

TimeUtil.Timer.prototype.handleBeginStep = function (timePassed) {
    "use strict";
    if (!this._isPaused) {
        this._time += timePassed;
        this._totalTimePassed += timePassed;
        if (this._time >= this._intervalFrequency) {
            this._time = 0;
            this._onInterval.trigger(this._intervalFrequency);
        }
    }
};

TimeUtil.Timer.prototype.getTimeRemaining = function () {
    return this._initialDuration - this._totalTimePassed;
}
