ImageUtil = {};

ImageUtil.htmlImageLoad = function (path) {

    return new Promise(function (resolve, reject) {
        var img = new Image();
        
        img.crossOrigin = 'anonymous';
        img.src = path;

        img.onerror = function (e) {     
            reject(e);
        };

        img.onload = function () {
            resolve(img);
        };
    });
}
//******************************************************
//*****    Script Resource: DataUtil
//******************************************************

var DataUtil = {}
DataUtil.createEnforcedStructure = function (keysToEnforce, data) {
    keysToEnforce = keysToEnforce || {};
    var enforcedData = {};
    //Check for enforced and optional keys
    for (var indexKey in keysToEnforce) {
        var isKeyRequired = keysToEnforce[indexKey];
        if (isKeyRequired) {
            if (typeof data[indexKey] === "undefined") {
                throw new Error("The object key '" + indexKey + "' is required but its value is not set");
            }
        } else {
            data[indexKey] = typeof data[indexKey] === "undefined" ? null : data[indexKey];
        }
        enforcedData[indexKey] = data[indexKey];
    }

    //Check for data structure integrity by looking for keys not declared
    for (var indexKey in data) {
        var isKeyRequired = keysToEnforce[indexKey];
        if (typeof isKeyRequired === "undefined") {
            throw new Error("You are trying to set the key '" + indexKey + "' that doesn't exist in the enforced data structure");
        }
    }

    return enforcedData;
}

DataUtil.shallowObjectClone = function (objectToClone) {
    var copy = objectToClone.constructor();
    for (var attribute in objectToClone) {
        if (objectToClone.hasOwnProperty(attribute)) copy[attribute] = objectToClone[attribute];
    }
    return copy;
};
