tgfSettings.componentDefaults.rectMask = {};

tgfComponents.RectMask = function (properties, disableMasking) {
	"use strict";
	this.name = "RectMask";
	var canvas = tgfGraphics.mainCanvas;
	var context = canvas.getContext("2d");
	this.context = context;

	// this.image = s_popup_icon_lives;
	this._cornerSharpness = 50;
	this.radius = 16;
	this.radiusXMod = 1.3;
	this.radiusYMod = 1;

	this.initialize(tgfSettings.componentDefaults.rectMask);
	if (properties !== undefined) {
		this.setProperties(properties);
	}
	this.disableMasking = disableMasking;

}

tgfComponents.inherit(tgfComponents.RectMask, tgfComponents.Base);

tgfComponents.RectMask.prototype.setup = function (width, heigth, picture) {
	this.picture = picture;
	this.picture.show();

	this._rectWidth = width;
	this._rectHeight = heigth;
	this.drawPoints = this._createShapeData();
}

tgfComponents.RectMask.prototype.resize = function (width, heigth) {
	this._rectWidth = width;
	this._rectHeight = heigth;
	this.drawPoints = this._createShapeData();
}

tgfComponents.RectMask.prototype._createShapeData = function () {

	var widthWithoutCorners = this._rectWidth - (this.radius * 2);
	var heightWithoutCorners = this._rectHeight - (this.radius * 2);

	var corners = this._generateCirclePoints(this.x, this.y, widthWithoutCorners, heightWithoutCorners, this.radius);
	return this._generateRenderPoints(corners, this.radius);
}

tgfComponents.RectMask.prototype._generateRenderPoints = function (circlePoints, radius) {
	var allPoints = [];
	for (var i = 0; i < 4; i++) {
		var currentPoints = this._createArcPoints(circlePoints[i], radius, this._cornerSharpness);
		allPoints = allPoints.concat(currentPoints);
	}
	return allPoints;
}

tgfComponents.RectMask.prototype._createArcPoints = function (circlePoint, radius, samplingPoints) {
	var positionPoints = [];
	var angleStep = (circlePoint.angles.end - circlePoint.angles.start) / (samplingPoints - 1);
	for (var i = 0; i < samplingPoints; i++) {
		var angleOffset = circlePoint.angles.start + (angleStep * i);
		var posx = circlePoint.position.x + Math.floor(Math.cos(angleOffset) * (radius * this.radiusXMod));
		posx -= 4;
		var posy = circlePoint.position.y + Math.floor(-Math.sin(angleOffset) * radius * this.radiusYMod);
		positionPoints.push({
			x: posx,
			y: posy
		});
	}
	return positionPoints;
}


tgfComponents.RectMask.prototype.doDraw = function () {
	var context = this.context;
	var drawPoints = this.drawPoints;
	var offsetMaskX = 0;
	var offsetMaskY = 0;

	context.save();
	context.beginPath();

	var containerAnchorX = 0;
	var containerAnchorY = this._rectHeight * 0.5;
	if (!this.disableMasking) {
		for (var i = 0; i < drawPoints.length; i++) {
			context.lineTo(drawPoints[i].x - containerAnchorX + (offsetMaskX * 0.5), drawPoints[i].y - containerAnchorY + (offsetMaskY * 0.5));
		}
		context.lineTo(drawPoints[1].x - containerAnchorX + (offsetMaskX * 0.5), drawPoints[1].y - containerAnchorY + (offsetMaskY * 0.5));
		context.clip();
	}


	this.picture.doDraw();
	context.restore();
}

/**
 * Circles are used to calculate the corners
 * this generates the origin of the circles and the angle it curves to on the rect
 */
tgfComponents.RectMask.prototype._generateCirclePoints = function (x, y, width, height, radius) {
	return [{
		position: {
			x: x + radius,
			y: y + radius
		},
		angles: {
			start: Math.PI * 0.5,
			end: Math.PI
		}
	}, {
		position: {
			x: x + radius,
			y: y + radius + height
		},
		angles: {
			start: Math.PI,
			end: Math.PI * 1.5
		}
	}, {
		position: {
			x: x + radius + width,
			y: y + radius + height
		},
		angles: {
			start: Math.PI * 1.5,
			end: Math.PI * 2
		}
	}, {
		position: {
			x: x + radius + width,
			y: y + radius
		},
		angles: {
			start: 0,
			end: Math.PI * 0.5
		}
	}];
}
