var LocalizationUtil = {};

/**
 * Get object in the format that facebook wants for localizable contents
 * 
 * @param {String} dictionaryKey 
 * @param {Array} stringReplacements 
 * @returns {Object} content 
 */
LocalizationUtil.getLocalizableContent = function (dictionaryKey, stringReplacements) {

    this.content = {
        default: tgfDictionary.getText(dictionaryKey, "undefined", "en-us"),
        fr_CA: tgfDictionary.getText(dictionaryKey, "undefined", "fr-fr"),
        fr_FR: tgfDictionary.getText(dictionaryKey, "undefined", "fr-fr")
    }

    var _getFormattableArguments = function(string, stringReplacements){
        var returnArray = stringReplacements.slice();
        returnArray.unshift(string);
        return returnArray;
    }

    if (stringReplacements) {
        for (var language in this.content) {
            if (this.content.hasOwnProperty(language)) {
                this.content[language] = StringUtil.format.apply(null, _getFormattableArguments(this.content[language], stringReplacements));
            }
        }
    }

    return this.content;
}
