//******************************************************
//*****    Script Resource: ObjectUtil
//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

var ObjectUtil = {};

ObjectUtil.hasValueInObject = function(object, value) {
    for (var prop in object) {
        if(object[prop] === value) {
            return true;
        }
    }

    return false;
};

ObjectUtil.getTotalProperties = function(object) {
    var total = 0;

    for (var prop in object) {

        if(!object.hasOwnProperty(prop)) {
            continue;
        }

        total++;
    }

    return total;
};

ObjectUtil.getKeyByValue = function(object, value) {
    for (var prop in object) {
        if(object[prop] === value) {
            return prop;
        }
    }

    return null;
};
//******************************************************
//*****    Script Resource: DifficultyUtil
//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

var DifficultyUtil = {};

DifficultyUtil.getDifficulties = function(day) {

    var difficulties = {};
    
    for (var difficultyKey in tgfSettings.game.difficulties) {
        if(day >= tgfSettings.game.levels[tgfSettings.game.difficulties[difficultyKey]].beginDate) {
            difficulties[difficultyKey] = tgfSettings.game.difficulties[difficultyKey];
        }
    }

    return difficulties;
};

DifficultyUtil.doesDifficultyExistInThisDay = function (day, difficulty) {

    var difficultiesInThisMonth = DifficultyUtil.getDifficulties(day);

    return ObjectUtil.hasValueInObject(difficultiesInThisMonth, difficulty);
};

DifficultyUtil.getTotalDifficultiesThisDay = function (day) {

    var difficultiesInThisMonth = DifficultyUtil.getDifficulties(day);

    return ObjectUtil.getTotalProperties(difficultiesInThisMonth);
};
