// Processing required when hiding the dialog
tgfDialogs.DisconnectPopupDialog.prototype.hide = function () {
	"use strict";
	tgfDialogs.DisconnectPopupDialog.uber.hide.call(this);

	this.reconnectTimer = this.reconnectDelay;
	this.reconnectAttempt = 1;
	this.reconnecting = false;
	this.reconnected = false;
};

tgfDialogs.DisconnectPopupDialog.prototype.reconnect = function () {
	"use strict";

	var self = this;
	if (this.reconnecting === false) {
		this.reconnecting = true;

		console.log("calling disconnectionHandler reconnect");
		this.disconnectionHandler.reconnect(function () {
				self.reconnectAttempt = self.reconnectMaxAttempt;
				self.reconnecting = false;
				self.reconnected = true;
			},
			function (e) {

				if (self.reconnecting === false) return;

				console.log("Reconnecting failed: " + e)
				self.reconnectTimer = self.reconnectDelay;
				self.reconnectAttempt++;
				self.reconnecting = false;
				self.reconnected = false;
			});
	}
};
