tgfDialogs.ExitDialog.prototype.disappear = function () {
    "use strict";
    this.free();
};

// ***************************************
// Internal methods
// ***************************************


// ***************************************
// Preparing and showing
//      - These can be removed if no processing is required
// ***************************************

// Processing required when preparing the dialog for use
tgfDialogs.ExitDialog.prototype.doPrepare = function () {
    "use strict";
    var self = this,
        i, darkener;

    //tgfDialogs.ExitDialog.uber.doPrepare.call(this);

    this.x = tgfGraphics.visibleWidth / 2;
    this.y = tgfGraphics.visibleHeight / 2;

    darkener = this._addComponent(this, tgfComponents.Darkener, {
        width: tgfGraphics.visibleWidth,
        height: tgfGraphics.visibleHeight
    }, this.darkenerProperties);

    this.container = this._addComponent(this, tgfComponents.Picture, {
        image: this.popUpBackgroundImage,
        y: tgfScale(-150),
        createFromSlices: true,
        width: this.width === 0 ? this.popUpBackgroundImage.width : this.width,
        height: this.height === 0 ? this.popUpBackgroundImage.height : this.height,
        effects: [this.appearEffect, {
            effect: "show",
            duration: this.lifeTime
        }, this.disappearEffect],
        onSubEffectStart: function (component, effect) {
            if (effect === self.disappearEffect && self.darken) {
                darkener.makeLight(darkener.duration, self.container.effects[2].duration - darkener.duration);
            }
        },
        onEffectEnd: function (component) {
            self.hide();
        }
    });

    var bigButton = new tgfComponents.Button({
        image: s_pen,
        alpha: 0
    });

    this.container.addComponent(bigButton);

    var warningComponent = new tgfComponents.Label({
        font: {
            fontFace: f_main_font.fontFace,
            fontSize: 28,
            fillColor: tgfSettings.theme.fontColor.dark,
            baseline: "middle",
            align: "center"
        },
        dictionaryKey: "ExitWarning",
        y: tgfScale(-70),
        splitLines: true,
        width: this.popUpBackgroundImage.width - tgfScale(150),
        height: this.popUpBackgroundImage.height / 2
    });

    this.container.addComponent(warningComponent);

    var buttonsWidth = 255;

    var stayButtonComponent = new tgfComponents.Button({
        width: buttonsWidth,
        fontUp: tgfSettings.fonts.greyButton,
        image: s_button_default_gray,
        fitToBox: false,
        text: tgfDictionary.getText("StayButton"),
        x: tgfScale(-145),
        y: tgfScale(65),
        onClick: function () {
            SudokuAnalytics.reportStay();
            self.disappear();
        }
    });

    this.container.addComponent(stayButtonComponent);

    var quitButtonComponent = new tgfComponents.Button({
        width: buttonsWidth,
        fontUp: tgfSettings.fonts.greyButton,
        image: s_button_default_gray,
        fitToBox: false,
        text: tgfDictionary.getText("QuitButton"),
        x: tgfScale(145),
        y: tgfScale(65),
        onClick: function () {
            EventSystem.Global.dispatchEvent(UI_Event.EXIT_LEVEL_BUTTON_CLICKED);
            //MessyAnalytics.quitClicked();
            //MessyAnalytics.levelQuit();
            BoosterSDK.tryInterstitialWithInterval();
            SudokuAnalytics.reportQuit();
            self.disappear();
        }
    });

    this.container.addComponent(quitButtonComponent);

    // Add the additional components
    if (this.components) {
        for (i = 0; i < this.components.length; i += 1) {
            this.container.addComponent(this.components[i]);
        }
	}
//	MessyAnalytics.popup("quit", true);
};

tgfDialogs.ExitDialog.prototype.onShow = function () {
    SudokuAnalytics.reportScreenQuit();
};

tgfDialogs.ExitDialog.prototype.doShow = function () {
	EventSystem.Global.dispatchEvent(Level_Event.LEVEL_PAUSED);
}

// Processing required when freeing the dialog from use
tgfDialogs.ExitDialog.prototype.doFree = function () {
    "use strict";
    tgfDialogs.ExitDialog.uber.doFree.call(this);
    this.removeAllComponents();
};

// Processing required when hiding the dialog
tgfDialogs.ExitDialog.prototype.doHide = function () {
    "use strict";
//    MessyAnalytics.popup("quit", false);
    EventSystem.Global.dispatchEvent(Level_Event.LEVEL_RESUMED);
};

tgfDialogs.ExitDialog.prototype.handleTouchDown = function (finger, x, y) {
	"use strict";

	tgfDialogs.ExitDialog.uber.handleTouchDown.call(this, finger, x, y);
	return true; // This makes sure we can't click something in the background
};

tgfDialogs.ExitDialog.prototype.handleTouchUp = function (finger, x, y) {
	"use strict";

	tgfDialogs.ExitDialog.uber.handleTouchUp.call(this, finger, x, y);
	return true; // This makes sure we can't click something in the background
};
