//Initialize About Screen
tgfDialogs.WhatsNewUIDialog.prototype.initPopUp = function () {
    'use strict';

    var self = this;

    this.currentPage = 0;
    this.pageComponents = [{}];

    var pages = [{
        title: tgfDictionary.getText("WhatsNewTitle"),
        body: tgfDictionary.getText("WhatsNewBody"),
        screenshot: s_whatsnew_invitefriendsforhints
    }, ];

    var whatsNewHeader = new tgfComponents.Label({
        font: {
            fontFace: f_main_font.fontFace,
            fontSize: 40,
            fillColor: tgfSettings.theme.fontColor.dark,
            baseline: "middle",
            align: "center"
        },
        x: tgfScale(0),
        y: tgfScale(-325),
        text: tgfDictionary.getText("WhatsNewHeader")
    });
    this.container.addComponent(whatsNewHeader);

    var onOK = function () {
        tgfDialogs.WhatsNewUIDialog.prototype.hide.call(self);

        if (self.onOkButtonPressed !== null) {
            self.onOkButtonPressed();
        }
    };

    var onNext = function () {

        // Hide current page
        this.pageComponents[this.currentPage].whatsNewSubheader.isVisible = false;
        this.pageComponents[this.currentPage].whatsNewBody.isVisible = false;
        this.pageComponents[this.currentPage].uiImprovementsScreenshot.isVisible = false;
        this.pageComponents[this.currentPage].gotItButton.isVisible = false;

        this.currentPage++;
        this.pageComponents[this.currentPage].whatsNewSubheader.isVisible = true;
        this.pageComponents[this.currentPage].whatsNewBody.isVisible = true;
        this.pageComponents[this.currentPage].uiImprovementsScreenshot.isVisible = true;
        this.pageComponents[this.currentPage].gotItButton.isVisible = true;
    }.bind(this)

    for (var i = 0; i < pages.length; i++) {

        var isFirstPage = i == 0;
        var isLastPage = i == pages.length - 1;

        this.pageComponents[i].whatsNewSubheader = new tgfComponents.Label({
            width: tgfScale(s_popup_default_bg.width - 50),
            height: tgfScale(400),
            font: {
                fontFace: f_main_font.fontFace,
                weight: 'bold',
                fontSize: 26,
                fillColor: tgfSettings.theme.fontColor.dark,
                baseline: "middle",
                align: "center"
            },
            x: tgfScale(0),
            y: tgfScale(-240),
            text: pages[i].title,
        });
        this.container.addComponent(this.pageComponents[i].whatsNewSubheader);
        if (!isFirstPage) {
            this.pageComponents[i].whatsNewSubheader.show = function () {
                tgfComponents.Base.prototype.show.call(this);
                this.isVisible = false;
            };
        }

        this.pageComponents[i].whatsNewBody = new tgfComponents.Label({
            splitLines: true,
            width: tgfScale(s_popup_default_bg.width - 150),
            height: tgfScale(400),
            font: {
                fontFace: f_main_font.fontFace,
                fontSize: 25,
                fillColor: tgfSettings.theme.fontColor.dark,
                baseline: "middle",
                align: "center"
            },
            x: tgfScale(0),
            y: tgfScale(140),

            text: pages[i].body,
        });
        this.container.addComponent(this.pageComponents[i].whatsNewBody);
        if (!isFirstPage) {
            this.pageComponents[i].whatsNewBody.show = function () {
                tgfComponents.Base.prototype.show.call(this);
                this.isVisible = false;
            };
        }

        this.pageComponents[i].uiImprovementsScreenshot = new tgfComponents.Picture({
            image: pages[i].screenshot,
            x: tgfScale(0),
            y: tgfScale(-80)
        });
        this.container.addComponent(this.pageComponents[i].uiImprovementsScreenshot);
        if (!isFirstPage) {
            this.pageComponents[i].uiImprovementsScreenshot.show = function () {
                tgfComponents.Base.prototype.show.call(this);
                this.isVisible = false;
            };
        }

        this.pageComponents[i].gotItButton = new tgfComponents.Button({
            image: s_button_default_gray,
            fontUp: {
                fontFace: f_main_font.fontFace,
                fontSize: 50,
                fillColor: tgfSettings.theme.fontColor.dark,
                baseline: "middle",
                align: "center"
            },
            x: tgfScale(0),
            y: tgfScale(300),
            width: tgfScale(300),
            onClick: !isLastPage ? onNext : onOK,
            text: !isLastPage ? tgfDictionary.getText("WhatsNewNext") : tgfDictionary.getText("WhatsNewConfirm")
        });
        this.container.addComponent(this.pageComponents[i].gotItButton);
        if (!isFirstPage) {
            this.pageComponents[i].gotItButton.show = function () {
                tgfComponents.Base.prototype.show.call(this);
                this.isVisible = false;
            };
        }
    }


    tgfDialogs.WhatsNewUIDialog.prototype.disappear = function () {
        'use strict';

        this.hide.call(this);

        if (this.onOkButtonPressed !== null) {
            this.onOkButtonPressed();
        }
    };
}
