//******************************************************
//*****    Script Resource: ToolTip
//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

tgfSettings.dialogDefaults.toolTip = {

    dictionaryKey: "expert_tooltip_txt",

    pointX: 0,

    pointY: 0,

    isBelowPoint: false,

    duration: 6,

    depth: -999,

    _width: 450,

    _margin: 20
}

tgfDialogs.ToolTip = function (properties) {
    
    this.initialize(tgfSettings.componentDefaults.Base);
    this.setProperties(tgfSettings.dialogDefaults.toolTip);

    this._setCenter();

    if (properties !== undefined) {
        this.setProperties(properties);
    }
};

tgfDialogs.inherit(tgfDialogs.ToolTip, tgfDialogs.Base);

tgfDialogs.ToolTip.prototype._setCenter = function () {
    this.x = tgfGraphics.visibleWidth * 0.5;
    this.y = tgfGraphics.visibleHeight * 0.5;
};

tgfDialogs.ToolTip.prototype._getFont = function () {
    return tgfSettings.fonts.toolTip;
};

tgfDialogs.ToolTip.prototype._getText = function () {
    return tgfDictionary.getText(this.dictionaryKey);
};

tgfDialogs.ToolTip.prototype._calculateTextHeight = function () {

    var textWidth = StringUtil.getTextWidth(this._getText(), this._getFont());
    var textHeight = StringUtil.getTextHeight(this._getText(), this._getFont());

    return (Math.ceil(textWidth / this._width) * textHeight);
};

tgfDialogs.ToolTip.prototype._calculateTextWidth = function () {

    var textWidth = StringUtil.getTextWidth(this._getText(), this._getFont());

    return textWidth > this._width ? this._width : textWidth;
};

tgfDialogs.ToolTip.prototype._createPointer = function (x, y, flip) {
    return new tgfComponents.Picture({
        image: s_ui_tooltip_tip,
        x: x,
        y: y,
        angle: flip ? 180 : 0
    });
};

tgfDialogs.ToolTip.prototype._getYPosition = function() {

    var height = this._calculateTextHeight() + (this._margin * 2);

    var offset = (height * 0.5) + (s_ui_tooltip_tip.height * 0.5);

    return this.isBelowPoint ? 
        this.pointY + (offset - 5) : 
        this.pointY - (offset - 10);
};

tgfDialogs.ToolTip.prototype._createBackground = function (x, y, width, height) {
    return new tgfComponents.Picture({
        image: s_ui_tooltip_body,
        x: x,
        y: y,
        createFromSlices: true,
        width: width,
        height: height
    });
};

tgfDialogs.ToolTip.prototype._createLabel = function (x, y, width, height) {
    return new tgfComponents.Label({
        x: x,
        y: y,
        width: width,
        height: height,
        splitLines: true,
        fitToBox: false,
        font: this._getFont(),
        text: this._getText()
    });
};

tgfDialogs.ToolTip.prototype.onPrepare = function () {

    this.container = new tgfComponents.Container({
        alpha: 0,
        effects: [
            {
                effect: tgfEffects.nothing,
                duration: 9999999
            },
            {
                effect: tgfEffects.fadeIn,
                duration: 0.5,
            }, 
            {
                effect: tgfEffects.nothing,
                duration: this.duration
            }, 
            {
                effect: tgfEffects.fadeOut,
                duration: 0.5,
            },
            {
                effect: tgfEffects.nothing,
                duration: 9999999
            }
        ]
    });

    var background = this._createBackground(0, 
        this._getYPosition(), 
        this._width + (this._margin * 2), 
        this._calculateTextHeight() + (this._margin * 2));

    this.container.addComponent(background);

    var pointer = this._createPointer(this.pointX, 
        this.pointY, 
        !this.isBelowPoint);

    this.container.addComponent(pointer);

    var label = this._createLabel(0, 
        this._getYPosition(), 
        this._width, 
        this._calculateTextHeight());

    this.container.addComponent(label);

    this.addComponent(this.container);
};

tgfDialogs.ToolTip.prototype.showToolTip = function () {

    if(this.container.getSubEffect() === 1 || this.container.getSubEffect() === 2) {
        return;
    }

    this.container.startSubEffect(1);
};

tgfDialogs.ToolTip.prototype.hideToolTip = function () {

    if(this.container.getSubEffect() === 3 || this.container.getSubEffect() === 4 || this.container.getSubEffect() === 0) {
        return;
    }

    this.container.startSubEffect(3);
};
//******************************************************
//*****    Script Resource: Reward
//******************************************************

var Reward = function ( rawData ) {
	"use strict";
    this._raw = rawData;
    this._id = this._raw.id;
    
    // whether the user is allowed to have this reward. either; allready has this reward or still needs to collect it
    this._isUnlocked = false;
    
    // whether the user processed the reward after is has been unlocked 
    this._isCollected = false;

    this.changedEvent = new EventSystem.Local(this);
}

Reward.prototype.collect = function () {
    this._isCollected = true;
    this.changedEvent.trigger();
}

Reward.prototype.unlock = function () {
    this._isUnlocked = true;
    this.changedEvent.trigger();
    EventSystem.Global.dispatchEvent(Reward_Event.REWARD_UNLOCK, this);
}

Reward.prototype.isUnlocked = function () {
    return this._isUnlocked;
}

Reward.prototype.isCollected = function () {
    return this._isCollected
}

Reward.prototype.getType = function () {
    return this._raw.rewardType;
}

Reward.prototype.getUnlockId = function () {
    return this._raw.unlockID;
}

Reward.prototype.getRarity = function () {
    return this._raw.rarity;
}

Reward.prototype.getMonth = function () {
    return this._raw.month;
}

Reward.prototype.getUnlockCondition = function () {
    return this._raw.unlockCondition;
}

Reward.prototype.getIcon = function () {
    return this._raw.icon;
}
Reward.prototype.getPuzzles = function () {
    return this._raw.puzzles;
}

Reward.prototype.getID = function () {
    return this._raw.id;
}

Reward.prototype.exportSaveData = function () {
    if (this._isUnlocked == false) return null;
    this._cashedData = this._cashedData || {};
    this._cashedData.id = this._id;
    this._cashedData.unlocked = this._isUnlocked;
    this._cashedData.collected = this._isCollected;
    return this._cashedData;
    
}

Reward.prototype.importSaveData = function (saveData) {
    if (this._id != saveData.id) {
        debugger;
    }
    this._isUnlocked = saveData.unlocked;
    this._isCollected = saveData.collected;
}
//******************************************************
//*****    Script Resource: RewardsController
//******************************************************



var RewardController = (function () {
    var _RewardController = function () {
        "use strict";
        this._rewards = [];
        this._saveDataIdentifier = "rewardSaveData";
    }
        
    _RewardController.prototype.initialize = function () {

        var self = this;
        return new Promise(function (resolve, reject) {

            
            var rewardData = rewardSettings().rewards;
            var rewardDataLength = rewardData.length;
            
            for (var i = 0; i < rewardDataLength; i++){
                var currentRewardData = rewardData[i];
                var existing = self._getById(currentRewardData.id);
                if (existing !== null) {
                    // DUPLICATE ID IN REWARD DATA
                    debugger
                    continue
                }
                self._add( new Reward(currentRewardData));
            }

            saveDataService.getPlayerData([self._saveDataIdentifier])
                .then(function (data) {
                    if (data) {
                        self.importSaveData(data);
                    }
                    resolve();
                })
                .catch(function (err) {
                    reject(err);
                });
        });
    }

    _RewardController.prototype._add = function (reward) {
        this._rewards.push(reward);
        reward.changedEvent.listen(this._save, this);
    }

    _RewardController.prototype._getById = function (id) {
        var rewardsLength = this._rewards.length;
        
        for (var i = 0; i < rewardsLength; i++){
            if (id == this._rewards[i].getID()) return this._rewards[i];
        }
        return null
    }

    _RewardController.prototype.getByType = function (type) {
        var rewardsFound = [];
        var rewardsLength = this._rewards.length;
        
        for (var i = 0; i < rewardsLength; i ++){
            var currentType = this._rewards[i].getRewardType();
            if (currentType == type) rewardsFound.push(this._rewards[i]);
        }
        return rewardsFound;
    }

    _RewardController.prototype.getByCondition = function (condition) {
        var rewardsFound = [];
        var rewardsLength = this._rewards.length;
        
        for (var i = 0; i < rewardsLength; i ++){
            var currentCondition = this._rewards[i].getUnlockCondition();
            if (currentCondition == condition) rewardsFound.push(this._rewards[i]);
        }
        return rewardsFound;
    }

    _RewardController.prototype.getAllUnlockedUncollected = function () {
        var rewardsFound = [];
        var rewardsLength = this._rewards.length;
        
        for (var i = 0; i < rewardsLength; i++){
            var reward = this._rewards[i];
            if (reward.isUnlocked() && !reward.isCollected()) {
                rewardsFound.push(reward);
            }
        }
        return rewardsFound;
    }

    _RewardController.prototype._save = function () {
        saveDataService.savePlayerData(this.exportSaveData());
    }

    _RewardController.prototype.exportSaveData = function () {
        var rewardsLength = this._rewards.length;
        var rewardsSavedata = [];
        
        for (var i = 0; i < rewardsLength; i ++){
            var currentSave = this._rewards[i].exportSaveData(); 
            if (currentSave !== null) {
                rewardsSavedata.push(currentSave);
            }
        }

        return [{ 
            "identifier": this._saveDataIdentifier,
            "data": {
                "rewards": rewardsSavedata
            }
        }];
    }
    _RewardController.prototype.getEmptySave = function () {
        return { 
            "identifier": this._saveDataIdentifier,
            "data": {}
        };
    }
    _RewardController.prototype.importSaveData = function (saveData) {
        
        if (saveData.rewardSaveData &&  saveData.rewardSaveData.rewards) {
            var rewardData = saveData.rewardSaveData.rewards;

            var rewardsLength = rewardData.length;
            
            for (var i = 0; i < rewardsLength; i ++){
                var currentRewardData = rewardData[i];
                var reward = this._getById(currentRewardData.id);
                if (reward) {
                    reward.importSaveData(currentRewardData);    
                }
            }
        }
    }

    _RewardController.prototype.getByUnlockID = function (id) {
        var rewardsLength = this._rewards.length;
        
        for (var i = 0; i < rewardsLength; i++){
            if (id == this._rewards[i].getUnlockId()) return this._rewards[i];
        }
        return null
    }

    return new _RewardController();
}());








