//*****    Script Resource: RewardUnlockController
//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

var RewardUnlockController = function (calendar) {

    this._calendar = calendar;
}

RewardUnlockController.prototype.configureEvents = function (possibleThemeUnlockEvents, possibleCollectionEvents) {

    for (var i = 0; i < possibleThemeUnlockEvents.length; i++) {
        var event = possibleThemeUnlockEvents[i];
        EventSystem.Global.addEventListener(event, this._checkIfThemeUnlockedInCurrentMonth, this);
    }
    
    for (var i = 0; i < possibleCollectionEvents.length; i++) {
        var event = possibleCollectionEvents[i];
        EventSystem.Global.addEventListener(event, this._collectRewards, this);
    }
}

RewardUnlockController.prototype._checkIfThemeUnlockedInCurrentMonth = function () {

    var completedPuzzles = this._calendar.getDifficultiesCompleteInCurrentMonth().total;
    var monthlyUnlockRewards = RewardController.getByCondition(REWARD_CONDITIONS.MONTHLY_PUZZLE);

    for (var i = 0; i < monthlyUnlockRewards.length; i++) {
        var reward = monthlyUnlockRewards[i];

        if (
            reward.getMonth() === this._calendar.getSelectedMonth() &&
            completedPuzzles >= reward.getPuzzles() &&
            !reward.isUnlocked()
        ) {
            reward.unlock();
        }
    }
}

RewardUnlockController.prototype._collectRewards = function () {

    var uncollectedRewards = RewardController.getAllUnlockedUncollected();
    for (var i = 0; i < uncollectedRewards.length; i++) {
        var reward = uncollectedRewards[i];
        if (reward.getType() === REWARD_TYPES.THEME) {
            reward.collect();
            EventSystem.Global.dispatchEvent(Theme_Event.THEME_COLLECTED, ThemeController.getById(reward.getUnlockId()));
        }
        break; //We break so we only trigger one theme collected at a time.
    }
}
