//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

var GiftType = {
    FreeGame: 0,
    FreeHints: 1,
    ScoreMultiplier: 2,
};

var GiftManager = (function () {
    var _GiftManager = function () {
        //Doublecheck if giftconfig chances are valid.
        for (var giftConfig in tgfSettings.game.giftConfig) {
            if (tgfSettings.game.giftConfig.hasOwnProperty(giftConfig)) {
                var giftConfiguration = tgfSettings.game.giftConfig[giftConfig];
                if (giftConfiguration.rewardOptions) {
                    var sumOfChances = 0;

                    for (var i = 0; i < giftConfiguration.rewardOptions.length; i++) {
                        sumOfChances += giftConfiguration.rewardOptions[i].value;
                    }

                    if (sumOfChances > 1) {
                        console.error("Chances of gift reward should add up to 1");
                    } else {
                        console.log("Valid gift config.");
                    }
                }
            }
        }
    };

	_GiftManager.prototype.redeemGift = function (code, giftInfo) {
        var redeemedGifts = gameData.redeemedGifts;
        var codeAlreadyRedeemed = false;

        if (redeemedGifts) {
            for (var i = 0; i < redeemedGifts.length; i++) {

                var redeemedCode = redeemedGifts[i];

                if (redeemedGifts[i] == code.toString()) {
                    codeAlreadyRedeemed = true;
                }
            }
        }

        if (!codeAlreadyRedeemed || tgfSettings.env === "dev") {
            //Apply gift
            giftInfo = giftInfo.split("_");

            if (giftInfo.length !== 2) {
                console.log("Invalid GiftInfo: " + giftInfo);
                return;
            }

            var response = undefined;

            var giftType = parseInt(giftInfo[0]);

            switch (giftType) {
                case GiftType.FreeGame:
                    //giftInfo[1] = day to unlock (if defined)
                    response = this._redeemFreeGame(giftInfo);
                    break;
                case GiftType.FreeHints:
                    //giftInfo[1] = amount of free hints
                    response = this._redeemFreeHints(giftInfo);
                    break;
                case GiftType.ScoreMultiplier:
                    //giftInfo[1] = score multiplier value.
                    response = this._redeemScoreMultiplier(giftInfo);
                    break;
            }

            console.log("GiftManager.redeemGift()", response);

            if (response.isRedeemed) {
                if (!redeemedGifts) {
                    redeemedGifts = [];
                }

                redeemedGifts.push(code.toString());
				gameData.redeemedGifts = redeemedGifts;

				console.log("Code sucessfully redeemed");

                saveDataService.savePlayerData(gameData.getSaveableGameData());
            }

            console.log("GiftManager response:", response);

            return response;
        } else {
            // Code already redeemed. Show popup??
            console.log("Code already redeemed");
        }
    };

    _GiftManager.prototype._redeemFreeGame = function (giftInfo) {

        if (parseInt(giftInfo[1]) === 0) //If target unlock day is 0, we should unlock a random day.
        {
            //Random day
            var currentDate = TimeManager.getDate();
            var currentYear = currentDate.getFullYear();
            var currentMonth = currentDate.getMonth();

            var availableLockedDays = this._getAvailableLockedDays(currentYear, currentMonth);

            var randomAvailableDayDataIndex = Math.floor(Math.random() * availableLockedDays.length);

            var monthDataId = availableLockedDays[randomAvailableDayDataIndex].giftInfo.date.getFullYear() + '_' + availableLockedDays[randomAvailableDayDataIndex].giftInfo.date.getMonth();

            UnlockDataManager.getMonthDataById(monthDataId)
                .then(function (monthData) {
                    var availabeleDayDate = availableLockedDays[randomAvailableDayDataIndex].giftInfo.date;
                    var dayDataId = availabeleDayDate.getFullYear() + "_" + availabeleDayDate.getMonth() + "_" + availabeleDayDate.getDate();
                    monthData.unlockDailyDataById(dayDataId);
                });

            return availableLockedDays[randomAvailableDayDataIndex];
        } else {
            var dayToUnlock = new Date(parseInt(giftInfo[1]));

            UnlockDataManager.getMonthDataById(dayToUnlock.getFullYear() + '_' + dayToUnlock.getMonth())
                .then(function (monthData) {
                    //Unlock the day
                    var dayDataId = dayToUnlock.getFullYear() + "_" + dayToUnlock.getMonth() + "_" + dayToUnlock.getDate();
                    monthData.unlockDailyDataById(dayDataId);
                });

            return {
                giftType: GiftType.FreeGame,
                giftInfo: {
                    date: dayToUnlock
                },
                isRedeemed: true
            };
        }
	};

	_GiftManager.prototype._getAvailableLockedDays = function (year, month) {

		var returnArray = [];
		var daysInMonth = new Date(year, month + 1, 0).getDate();
		for (var i = 0; i < daysInMonth; i++) {
			var isDayUnlocked = UnlockDataManager.isDayUnlocked(new Date(year, month, i));

			if (!isDayUnlocked) {
				returnArray.push({
					giftType: GiftType.FreeGame,
					giftInfo: {
						date: new Date(year, month, i)
					},
					isRedeemed: true
				});
			}
		}
		if (returnArray.length === 0) {
			month--;
			if (month < 0) {
				year--;
				month = 11;
			}
			return this._getAvailableLockedDays(year, month)
		} else {
			return returnArray;
		}
	}

    _GiftManager.prototype._redeemFreeHints = function (giftInfo) {

        var consumable = Consumables.get(ConsumableSettings.ENUM.HINT);
        var inventoryItem = consumable.getInventoryItem();
        inventoryItem.redeemedGiftAmount += parseInt(giftInfo[1]);

		saveDataService.savePlayerData(gameData.getSaveableGameData());
		consumable.setRemainingUses(inventoryItem.quantity);

        return {
            giftType: GiftType.FreeHints,
            isRedeemed: true
        };
    };

    _GiftManager.prototype._redeemScoreMultiplier = function (giftInfo) {
		var currentScoreMultiplier = gameData.scoreMultiplier;

        //If we don't have a current score multiplier, or the one we are trying to unlock is better. Redeem it.
        if (!currentScoreMultiplier || currentScoreMultiplier < giftInfo[1]) {
            gameData.scoreMultiplier = giftInfo[1];

            return {
                giftType: GiftType.ScoreMultiplier,
                isRedeemed: true
            };
        } else {
            return {
                giftType: GiftType.ScoreMultiplier,
                isRedeemed: false
            };
        }
    };

    _GiftManager.prototype.postRewardedCustomUpdate = function () {
        "use strict";
        //POST CUSTOM UPDATE
        var rewardedCustomUpdate = new tgfDialogs.RewardedCustomUpdate({
            callback: function (dataURL) {
                var redeemCode = Date.now();

                //Redeem the code immediately so that this person cannot redeem it.
                var redeemedGifts = gameData.redeemedGifts;
                if (redeemedGifts) {
                    redeemedGifts.push(redeemCode.toString());
                } else {
                    redeemedGifts = [];
                }

                gameData.redeemedGifts = redeemedGifts;
                saveDataService.savePlayerData(gameData.getSaveableGameData());

                var bodyText = LocalizationUtil.getLocalizableContent("RewardedCustomUpdateText", [messagingPlatformService.getPlayer().name]);
                var buttonText = LocalizationUtil.getLocalizableContent("RewardedCustomUpdateCTA");

                messagingPlatformService.sendGameUpdate({
                        text: bodyText,
                        buttonText: buttonText,
                        image: dataURL,
                        template: "redeem_gifts",
                        strategy: GameUpdateStrategy.IMMEDIATE,
                        payload: {
                            analytics: ["custom_update", "rewarded_share"],
                            redeemCode: redeemCode,
                            gift: GiftType.FreeHints + "_" + 3
                        }
                    })
                    .then(function () {
                        SudokuAnalytics.reportUpdateRewardedShare();
//                        MessyAnalytics.customUpdate("rewarded", "redeem_gifts");
                        console.log("[GiftManager] Game update sent");
                    })
                    .catch(function (err) {
                        errorLoggingService.sendError(err);
                        console.log("[GiftManager] There was a problem sending the game update. Error: " + err + "\n" + err.stack);
                    });
            }
        });

        rewardedCustomUpdate.show();
    }

    _GiftManager.prototype.getNewGiftMessage = function (giftType) {
        var giftConfig = tgfSettings.game.giftConfig[giftType];

        // use keys here instead of text, get text from dictionary
        var gift = {
            message: tgfDictionary.getText(giftConfig.messageKey), // giftConfig.message,
            buttonText: tgfDictionary.getText(giftConfig.buttonKey), //giftConfig.button,
            imageHeader: tgfDictionary.getText(giftConfig.imageHeaderKey), //giftConfig.imageHeader,
            imageText: tgfDictionary.getText(giftConfig.imageTextKey), //giftConfig.imageText,
            analytics: giftConfig.analytics,
            giftValue: 0,
            giftType: giftType
        }

        //If there is a chance for different reward options configured.
        if (giftConfig.rewardOptions) {
            //Generate a random value
            var randomValue = Math.random();

            var lowerbound = 0;

            //Loop over the chances
            for (var i = 0; i < giftConfig.rewardOptions.length; i++) {
                var configuration = giftConfig.rewardOptions[i];


                if (randomValue >= lowerbound && randomValue < (lowerbound + configuration.chance)) {
                    gift.giftValue = configuration.value;
                }

                lowerbound += configuration.chance;
            }

            if (!gift.giftValue) {
                console.log("Break");
            }
        }

        //If this gift has a variable value set the messages correctly.
        if (gift.giftValue > 0) {
            gift.message = StringUtil.format(gift.message, gift.giftValue);
            gift.imageText = StringUtil.format(gift.imageText, gift.giftValue);
        }

        return gift;
    };

    return new _GiftManager();
}());
