// Processing required when preparing the dialog for use
tgfDialogs.RewardScoreMultiplierDialog.prototype.doPrepare = function () {
	"use strict";
	var self = this;

	tgfDialogs.RewardScoreMultiplierDialog.uber.doPrepare.call(this);


	this.spine = new tgfComponents.SpineComponent({
		spineAnimation: reward,
		animationClips: ["animation"], // The animation names from the spine json
		play: true,
		hasDelay: true,
		delay: -1,
		x: tgfScale(0),
		y: tgfScale(0),

		updateWhileUnactive: false,
		onComplete: function () {
			self._spineHasEnded = true;
			self.onComplete();
		}
	});
	this.container.addComponent(this.spine);

	this.multiplier = this.multiplier || 0;

	this.text = new tgfComponents.Label({
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 63,
			fillColor: "#2d2d2d",
			baseline: "middle",
			align: "center",
			strokeColor: "#f7f7f7",
			strokeWidth: 4,
			strokeBehind: true,
			shadow: {
				active: true,
				color: 'rgba(45, 45, 45, 0.6)',
				offsetX: 0,
				offsetY: 8,
				blur: 13
			}
		},

		text: StringUtil.format(tgfDictionary.getText("ScoreRewardText"), this.multiplier), //this.multiplier + "X SCORE!",
		splitLines: true,
		width: 300
	});
	this.container.addComponent(this.text);

	// Add the additional components
	for (var i = 0; i < this.components.length; i += 1) {
		this.container.addComponent(this.components[i]);
	}
};

tgfDialogs.RewardScoreMultiplierDialog.prototype.onShow = function (timePassed) {
	"use strict";
	var self = this;

	// Show text on animation event 'open' 
	// Can't be in doPrepare because the prepare of the spine component gets created in its own doPrepare, which will only prepare when we call show.
	this.text.alpha = 0.0;
	this.spine.spineClone.setEventCallback("open", function () {
		self.text.alpha = 1.0;
	});
};

tgfDialogs.RewardScoreMultiplierDialog.prototype.handleEndStep = function (timePassed) {
	"use strict";
	tgfDialogs.RewardScoreMultiplierDialog.uber.handleEndStep.call(this, timePassed);

	this.updateText(timePassed);
};

tgfDialogs.RewardScoreMultiplierDialog.prototype.updateText = function (timePassed) {
	var boneList = this.spine.spineClone.skeleton.bones;

	// Find our bone and move the text to it
	for (var i = 0; i < boneList.length; i++) {
		var bone = boneList[i];
		if (bone.data.name !== "s_text_5hints") continue;

		this.text.x = bone.x;
		this.text.y = -bone.y;
		this.text.xScale = bone.scaleX;
		this.text.yScale = bone.scaleY;
		break;
	}

	if (this._spineHasEnded && this.text.alpha > 0.0) {
		this.text.alpha -= timePassed * 0.001;

		// If text is gone
		if (this.text.alpha <= 0.0) {
			this.text.alpha = 0.0;
		}
	}
}
