//Initialize About Screen
tgfDialogs.InGameDayUnlockedPopup.prototype.initPopUp = function () {
	"use strict";

	var self = this;
	var nullScore = 0;

	this.animation = new tgfComponents.SpineComponent({
		spineAnimation: popup_unlock_big,
		animationClips: ["unlocked puzzle"], // The animation names from the spine json
		play: false,
		hasDelay: true, // This plays the unlock animation only when we've already unlocked it
		delay: 1000,
		x: tgfScale(0),
		y: tgfScale(90),
		updateWhileUnactive: true,
	});

	// Because the spine isn't initialised yet, we have to overwrite the doPrepare
	var self = this;
	this.animation.doPrepare = function () {
		tgfComponents.SpineComponent.prototype.doPrepare.call(this);

		// When the lock opens, jump to a white circle image
		this.spineClone.setEventCallback("lock_open", function () {
			self.circle.image = s_popup_date_bg;
		});
	};

	this.container.addComponent(this.animation);

	// Increase delay of the first (empty) animation until unlock animation is done
	this.continueButtonSpawnEffect[0].duration += 3;
	// this.messageSpawnEffect[0].duration += 3;

	this.container.onSubEffectStart = function (component, effect) {
		if (effect === component.effects[0]) { //"show"){
			self.startAnimation();
		}
		if (effect === self.disappearEffect && self.darken) {
			darkener.makeLight(darkener.duration, self.container.effects[2].duration - darkener.duration);
		}
	};

	this.subContainer = new tgfComponents.Base({});
	// this.postUnlockMessage = new tgfComponents.Base({});

	var circleImage = s_popup_date_bg; // Make the circle gray when it's locked in any shape or form

	circleImage = s_popup_circle_gray;

	this.circle = new tgfComponents.Picture({
		image: circleImage,
		x: tgfScale(0),
		y: tgfScale(-170)
	});
	this.subContainer.addComponent(this.circle);

	this.dayComponent = new tgfComponents.Label({
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 26,
			fillColor: tgfSettings.theme.fontColor.dark,
			baseline: "middle",
			align: "center"
		},
		x: tgfScale(0),
		y: tgfScale(-250),
		text: this.day
	});

	this.subContainer.addComponent(this.dayComponent);

	this.dayNumComponent = new tgfComponents.Label({
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 144,
			fillColor: tgfSettings.theme.fontColor.dark,
			baseline: "middle",
			align: "center"
		},
		x: tgfScale(0),
		y: tgfScale(-150),
		text: this.dayNumber.toString()
	});

	this.subContainer.addComponent(this.dayNumComponent);

	this.monthComponent = new tgfComponents.Label({
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 26,
			fillColor: tgfSettings.theme.fontColor.dark,
			baseline: "middle",
			align: "center"
		},
		x: tgfScale(0),
		y: tgfScale(-80),
		text: this.month
	});

	this.subContainer.addComponent(this.monthComponent);

	this.exit = new tgfComponents.Picture({
		image: s_btn_popup_close,
		x: tgfScale(240),
		y: tgfScale(-350),
	});

	this.subContainer.addComponent(this.exit);

	this.message = new tgfComponents.Label({
		effects: this.continueButtonSpawnEffect,
		xScale: 0,
		yScale: 0,
		repeatEffect: 1,
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 26,
			fillColor: tgfSettings.theme.fontColor.dark,
			baseline: "middle",
			align: "center"
		},
		x: tgfScale(0),
		y: tgfScale(120),
		width: tgfScale(450),
		height: tgfScale(90),
		splitLines: true,
		fitToBox: true,
		text: tgfDictionary.getText("IngameDayUnlockedLabel")
	});

	this.subContainer.addComponent(this.message);

	this.continuePuzzleButton = new tgfComponents.Button({
		effects: this.continueButtonSpawnEffect,
		repeatEffect: 1,
		xScale: 0,
		yScale: 0,
		fontUp: {
			fontFace: f_main_font.fontFace,
			fontSize: 34,
			fillColor: "#ffffff",
			baseline: "middle",
			align: "center"
		},
		image: this.buttonImage,
		x: this.continueButtonX,
		y: this.continueButtonY,
		width: tgfScale(450),
		height: tgfScale(90),
		createFromSlices: this.createFromSlices,
		id: 0,
		text: tgfDictionary.getText("IngameDayUnlockedButton"),
		onClick: function (comp) {
			tgfDialogs.InGameDayUnlockedPopup.prototype.playDisappear.call(self);
		}
	});

	// this.postUnlockMessage.addComponent(this.continuePuzzleButton);
	// this.buttonComponents.push(this.continuePuzzleButton);
	this.subContainer.addComponent(this.continuePuzzleButton);

	// this.container.addComponent(this.unlockContainer);
	this.container.addComponent(this.subContainer);

	console.log(this);
};

