tgfComponents.UiToggleDialog.prototype.doPrepare = function () {
    "use strict";

    this.header = new tgfComponents.Label({
        text: "TextNotSet",
        x: tgfScale(145),
        y: tgfScale(-20),
        fitToBox: false,
        font: tgfSettings.fonts.settingsGameMode,
    });

    this.body = new tgfComponents.Label({
        text: "TextNotSet",
        splitLines: true,
        fitToBox: false,
        width: 350,
        // height: 250,
        x: tgfScale(145),
        y: tgfScale(13),
        font: tgfSettings.fonts.settingsGameModeBody,
    });

    this.addComponent(this.header);
    this.addComponent(this.body);

    this.createToggleButton();
    this.updateLabels(gameData.preferredControls);
}



tgfComponents.UiToggleDialog.prototype.createToggleButton = function () {
    'use strict';

    var self = this;
    this.toggle = new tgfComponents.Picture({
        image: s_btn_settings_toggle,
        startSubImage: gameData.preferredControls === Preferred_Controls.CELL_FIRST ? 0 : 1,
        x: 70,
        y: 0,
        onClick: function (component) {

            sudokuInterface.deselect();
            var newControls = gameData.preferredControls === Preferred_Controls.CELL_FIRST ? Preferred_Controls.NUMBER_FIRST : Preferred_Controls.CELL_FIRST;

            gameData.preferredControls = newControls;
            sudokuInterface.preferredControlsChanged();
            // MessyAnalytics.preferredControlsChanged(newControls);
            SudokuAnalytics.preferredControlsChanged(newControls);
            saveDataService.savePlayerData(gameData.getSaveableGameData())
            component.subImage = newControls === Preferred_Controls.CELL_FIRST ? 0 : 1;

            self.updateLabels(gameData.preferredControls);
        }
    });
    this.addComponent(this.toggle);
};

tgfComponents.UiToggleDialog.prototype.updateLabels = function (newControls) {
    'use strict';
    if (newControls === Preferred_Controls.CELL_FIRST) {
        this.header.text = tgfDictionary.getText("settings_cellfirst_header");
        this.body.text = tgfDictionary.getText("settings_cellfirst_body");

    } else {
        this.header.text = tgfDictionary.getText("settings_numberfirst_header");
        this.body.text = tgfDictionary.getText("settings_numberfirst_body");
    }
    this.body.recreate();
    this.header.recreate();
    if (tgfDictionary.getLanguage() == "fr-fr") {
        this.header.y = tgfScale(-30);
    }
};
