// ***************************************
// Specific methods for this component
// ***************************************



// ***************************************
// Internal methods
// ***************************************



// ***************************************
// Preparing, showing and activating
//      - These can be removed if no processing is required
// ***************************************

// Processing required when preparing the component for use
tgfComponents.SettingsButton.prototype.select = function () {

	if (this._selectImage) {

		this._selectImage.show();
	} else {
		this._selectImage = new tgfComponents.Picture({
			x: -199,
			y: -3,
			image: s_button_settings_checkmark
		})
		this.addComponent(this._selectImage);

		this._selectImage.show();
	}
}

tgfComponents.SettingsButton.prototype.deselect = function () {

	if (this._selectImage) {

		this._selectImage.hide();
	}
}

tgfComponents.SettingsButton.prototype.doPrepare = function () {
	"use strict";

	tgfComponents.SettingsButton.uber.doPrepare.call(this);

	if (this.subIcon && this.subIcon.image) {

		this._subIconBG = new tgfComponents.Picture({
			x: this.subIcon.x || 0,
			y: this.subIcon.y || 0,
			image: s_btn_icon_bg,
		});

		this.addComponent(this._subIconBG);

		this._subIcon = new tgfComponents.Picture({
			x: this.subIcon.x || 0,
			y: this.subIcon.y || 0,
			image: this.subIcon.image,
		});
		this.subIcon.x = this._subIcon.x;
		this.subIcon.y = this._subIcon.y;

		this.addComponent(this._subIcon);
	}


	var i;
	// Add the child components
	if (this.components) {
		for (i = 0; i < this.components.length; i += 1) {
			this.addComponent(this.components[i]);
		}
	}
};

