tgfDialogs.ButtonBar = function () {
    "use strict";
    this.name = "ButtonBar";

    this.initialize(tgfSettings.dialogDefaults.base);

    this._buttonheight = 90;
    this._inactiveButtonY = (-this._buttonheight / 2) + 10;
    this._activeButtonY = (-this._buttonheight / 2);
    this._buttons = [];

    EventSystem.Global.addEventListener(UI_Event.SCREEN_ACTIVATED, this._changeSelected, this);
}

tgfDialogs.inherit(tgfDialogs.ButtonBar, tgfDialogs.Base);

tgfDialogs.ButtonBar.prototype.configureEvents = function (hideEvent, showEvent) {
    EventSystem.Global.addEventListener(hideEvent, this.hide, this);
    EventSystem.Global.addEventListener(showEvent, this.show, this);
}

tgfDialogs.ButtonBar.prototype.addButton = function (image, id, isActive) {
    "use strict";

    var self = this;

    if (isActive) {
        this._selectedIconId = id;
    }

    var button = new tgfComponents.Button({
        image: s_btn_tab_inactive,
        iconPosition: "center",
        height: this._buttonheight,
        id: id,
        onClick: function () {
            self._onButtonClick(this.id);
        }
    });

    var icon = new tgfComponents.Picture({
        name: "icon",
        image: image,
        y: -5,
        startSubImage: isActive ? 1 : 0,
    });

    button.addComponent(icon);

    this._buttons.push(button);
}

tgfDialogs.ButtonBar.prototype._onButtonClick = function (id) {
    "use strict";
    if (this._selectedIconId == id) {
        // "Same icon clicked"
    } else {
        EventSystem.Global.dispatchEvent(Icon_Bar_Events.ICON_SELECT, id);
    }
}

tgfDialogs.ButtonBar.prototype._handleButtonVisuals = function () {

    for (var i = 0; i < this._buttons.length; i++) {
        var button = this._buttons[i];
        var icon = button.findComponent("icon");

        if (this._selectedIconId === button.id) {
            icon.subImage = 1;
            button.image = s_btn_tab_active;
            button.recreate();

            if (button.y != this._activeButtonY) {
                button.effects = [{
                    effect: tgfEffects.move,
                    ease: tbEase.easeOutCircular,
                    duration: 0.3,
                    startY: button.y,
                    endY: this._activeButtonY
                }];

                button.repeatEffect = 1;
                button.restartEffect();
            }
        } else {
            icon.subImage = 0;
            button.image = s_btn_tab_inactive;
            button.recreate();

            if (button.y != this._inactiveButtonY) {
                button.effects = [{
                    effect: tgfEffects.move,
                    ease: tbEase.easeOutCircular,
                    duration: 0.4,
                    startY: button.y,
                    endY: this._inactiveButtonY
                }];

                button.repeatEffect = 1;
                button.restartEffect();
            }
        }
    }
};

tgfDialogs.ButtonBar.prototype.doPrepare = function () {
    "use strict";

    this.y = tgfGraphics.visibleHeight;
    this.y = tgfGraphics.visibleHeight;

    var amountOfButtons = this._buttons.length;
    var deltaPerSlot = tgfGraphics.visibleWidth / amountOfButtons;
    for (var i = 0; i < amountOfButtons; i++) {
        var current = this._buttons[i];
        current.width = deltaPerSlot;
        current.x = (deltaPerSlot * i) + (deltaPerSlot / 2);
        current.y = this._inactiveButtonY;
        this.addComponent(current);
    }
    this._handleButtonVisuals();
}

tgfDialogs.ButtonBar.prototype._changeSelected = function (id) {
    this._selectedIconId = id;
    this._handleButtonVisuals();
}
