var MonthNavigationBar = function (calendarModel) {
    "use strict";

    this.imageLeft = s_btn_calendar_left;
    this.imageRight = s_btn_calendar_right;

    this._calendarModel = calendarModel;

    this.initialize({});
}

tgfDialogs.inherit(MonthNavigationBar, tgfDialogs.Base);


MonthNavigationBar.prototype.configureEvents = function (updateButtons, hideEvent, showEvent, updateYEvents) {

    EventSystem.Global.addEventListener(updateButtons, this._updateButtons, this);
    EventSystem.Global.addEventListener(hideEvent, this.hide, this);
    EventSystem.Global.addEventListener(showEvent, this.show, this);

    for (var i = 0; i < updateYEvents.length; i++) {
        EventSystem.Global.addEventListener( updateYEvents[i], this._updateY, this);
    }
}

MonthNavigationBar.prototype.doPrepare = function () {

    this.y = 155;

    this._prevButton = new tgfComponents.Button({
        image: this.imageLeft,
        x: 44,
        touchMargin: 30
    });
    this._nextButton = new tgfComponents.Button({
        image: this.imageRight,
        x: tgfGraphics.visibleWidth - 44,
        touchMargin: 30
    });

    this._prevButton.onClick = function () {
        EventSystem.Global.dispatchEvent(UI_Event.PREVIOUS_MONTH_BUTTON_CLICKED);
    };
    this._nextButton.onClick = function () {
        EventSystem.Global.dispatchEvent(UI_Event.NEXT_MONTH_BUTTON_CLICKED);
    };

    this.addComponent(this._prevButton);
    this.addComponent(this._nextButton);
}

MonthNavigationBar.prototype.doShow = function () {
    this._updateButtons();
}

MonthNavigationBar.prototype._updateButtons = function () {

    if (this._calendarModel.isCurrentMonth()) {
        // button grayed-out
        this._nextButton.alpha = 0;
        this._nextButton.isCurrentMonth = true;
        this._nextButton.deactivate();
    } else {
        // button normal
        this._nextButton.alpha = 1;
        this._nextButton.isCurrentMonth = false;
        this._nextButton.activate();
    }

    var currentMonth = this._calendarModel.getSelectedMonth();
    var currentyear = this._calendarModel.getSelectedYear();
    
    if (currentMonth == 0 && tgfSettings.game.calendarConfig.yearLimitBack == (currentyear - 1)) {
        this._prevButton.alpha = 0;
        this._prevButton.deactivate();
    } else {
        this._prevButton.alpha = 1;
        this._prevButton.activate();
    }
}

MonthNavigationBar.prototype._updateY = function (screen) {
    
    switch (screen) {
        case mainMenuScreens.CALENDAR:
            this.y = 155;
            break;
        case mainMenuScreens.LEADERBOARD:
            this.y = 40;
            break;
        default:
            this.y = -9001;
            break;
    }
}
