var TopMenuUiDialog = function (calendarModel) {
    "use strict";

    this._calendarModel = calendarModel;

    this.initialize({});
}


tgfDialogs.inherit(TopMenuUiDialog, tgfDialogs.Base);

TopMenuUiDialog.prototype.configureEvents = function (hideEvents, showEvents) {

    this._eventActions = new EventSystem.EventActions(this);

    for (var i = 0; i < showEvents.length; i++) {
        this._eventActions.add(showEvents[i], this.show);
    }

    for (var i = 0; i < hideEvents.length; i++) {
        this._eventActions.add(hideEvents[i], this.hide);
    }
}

TopMenuUiDialog.prototype.doShow = function () {
    if (!this._rankBar) {
        this._createRankbar();
    }
    this._rankBar.show();
    this._rankBar.refresh();
    EventSystem.Global.addEventListener(UI_Event.SETTINGS_BUTTON_CLICKED, this._openSettingsPopup, this);
}

TopMenuUiDialog.prototype.doHide = function () {
    this._rankBar.destroy();
    this._rankBar = null;
    EventSystem.Global.removeEventListener(UI_Event.SETTINGS_BUTTON_CLICKED, this._openSettingsPopup, this);
}

TopMenuUiDialog.prototype._openSettingsPopup = function () {
    this._settingsPopup = new tgfDialogs.SettingsDialog({
        showCalendarButton: false
    });
    this._settingsPopup.show();
}

TopMenuUiDialog.prototype.doPrepare = function () {

    this._backgroundImage = new tgfComponents.Picture({
        image: s_bg_calendar_profile,
        x: s_bg_calendar_profile.width / 2,
        y: s_bg_calendar_profile.height / 2
    });

    var settingsButtonOffset = 100;
    this._settingsButton = new tgfComponents.Button({
        x: tgfGraphics.visibleWidth - (settingsButtonOffset / 2) - (s_btn_settings.width / 2),
        y: settingsButtonOffset - (s_btn_settings.height / 2),
        image: s_btn_settings,
        onClick: function () {
            EventSystem.Global.dispatchEvent(UI_Event.SETTINGS_BUTTON_CLICKED);
        }
    });

    this.addComponent(this._backgroundImage);
    this.addComponent(this._settingsButton);
};

TopMenuUiDialog.prototype._createRankbar = function () {
    this._rankBar = new AvatarRankDialog(30, 20, 500, 100, {
        image: s_ui_rank_calendar_progress_bar_middle_background,
        backgroundWidthOffset: 36
    }, "#ffffff");
};
