var MonthDisplayDialog = function (calendarModel) {
    "use strict";

    this._calendarModel = calendarModel;

    this.initialize({});
}

tgfDialogs.inherit(MonthDisplayDialog, tgfDialogs.Base);


MonthDisplayDialog.prototype.configureEvents = function (updateValueEvent) {
    this._eventActions = new EventSystem.EventActions(this);

    this._eventActions.add(updateValueEvent, this._updateValue);
    this._eventActions.add(UI_Event.SCREEN_ACTIVATED, this._checkScreen);
}

MonthDisplayDialog.prototype.doPrepare = function () {
    this.x = tgfGraphics.visibleWidth / 2;
    this.y = 40;
    this._monthYearLabel = new tgfComponents.Label({
        text: DateUtil.getMonthLabel(this._calendarModel.getSelectedMonth()) + " " + this._calendarModel.getSelectedYear(),
        font: tgfSettings.fonts.monthDisplayDialog
    });

    this.addComponent(this._monthYearLabel);
}

MonthDisplayDialog.prototype.configureActiveScreens = function (screens) {
    this._activeOnScreens = screens;
}

MonthDisplayDialog.prototype._checkScreen = function (screen) {
    var shouldShow = false;

    for (var i = 0; i < this._activeOnScreens.length; i++) {
        if (screen === this._activeOnScreens[i]) {
            shouldShow = true;
        }
    }
    if (shouldShow) {
        this.show();
    } else {
        this.hide();
    }
}

MonthDisplayDialog.prototype._updateValue = function () {
    if (this.isPrepared) {
        this._monthYearLabel.text = DateUtil.getMonthLabel(this._calendarModel.getSelectedMonth()) + " " + this._calendarModel.getSelectedYear();
        this._monthYearLabel.recreate();
    }
}
//******************************************************
//*****    Script Resource: PercentagesDialog
//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************


var PercentagesDialog = function (calendarModel) {
    "use strict";

    this._calendarModel = calendarModel;

    this.initialize({});

    this._percentages = {};

    for (var difficultyKey in tgfSettings.game.difficulties) {
        this._percentages[difficultyKey] = this._doesDifficultyExistInThisMonth(tgfSettings.game.difficulties[difficultyKey]) ? "0%" : "- - -";
    }
}

tgfDialogs.inherit(PercentagesDialog, tgfDialogs.Base);

PercentagesDialog.prototype._doesDifficultyExistInThisMonth = function (difficulty) {

    var firstDayOfTheMonth = new Date(this._calendarModel.getSelectedYear(), this._calendarModel.getSelectedMonth(), 1);

    return DifficultyUtil.doesDifficultyExistInThisDay(firstDayOfTheMonth, difficulty);
};

PercentagesDialog.prototype.configureEvents = function (updateValueEvents) {
    this._eventActions = new EventSystem.EventActions(this);

    for (var index = 0; index < updateValueEvents.length; index++) {
        
        this._eventActions.add(updateValueEvents[index], this._updateValue);
    }
    this._eventActions.add(UI_Event.SCREEN_ACTIVATED, this._checkScreen);
}

PercentagesDialog.prototype.doPrepare = function () {
    this.x = tgfGraphics.visibleWidth / 2;
    this.y = 105;

    this._labels = {};
    var x = -258;

    for (var difficultyKey in tgfSettings.game.difficulties) {
        this._labels[difficultyKey] = new tgfComponents.Label({
            text: this._percentages[difficultyKey],
            font: {
                fontFace: f_main_font.fontFace,
                fontSize: 23,
                fillColor: "#fff",
                baseline: "bottom",
                align: "left"
            },
            x: x,
        });

        this.addComponent(this._labels[difficultyKey]);

        x+= 124;
    }
}

PercentagesDialog.prototype.configureActiveScreens = function (screens) {
    this._activeOnScreens = screens;
}

PercentagesDialog.prototype._checkScreen = function (screen) {
    var shouldShow = false;

    for (var i = 0; i < this._activeOnScreens.length; i++) {
        if (screen === this._activeOnScreens[i]) {
            shouldShow = true;
        }
    }
    if (shouldShow) {
        this.show();
    } else {
        this.hide();
    }
}

PercentagesDialog.prototype._getNameOfDifficulty = function (difficulty) {
	return ObjectUtil.getKeyByValue(tgfSettings.game.difficulties, difficulty).toLowerCase();
};

PercentagesDialog.prototype._updateValue = function () {

    var daysInMonth = new Date(this._calendarModel.getSelectedYear(), this._calendarModel.getSelectedMonth() + 1, 0).getDate();
    var difficultiesComplete = this._calendarModel.getDifficultiesCompleteInCurrentMonth();

    for (var difficultyKey in tgfSettings.game.difficulties) {

        var percentage = Math.round(((difficultiesComplete[this._getNameOfDifficulty(tgfSettings.game.difficulties[difficultyKey])] / daysInMonth) * 100)) + "%";

        this._percentages[difficultyKey] = this._doesDifficultyExistInThisMonth(tgfSettings.game.difficulties[difficultyKey]) ? percentage : "- - -";

        if (this.isPrepared) {
            this._labels[difficultyKey].text = this._percentages[difficultyKey];
            this._labels[difficultyKey].recreate();
        }
    }
};
