tgfDialogs.LanguageSelectDialog = function (properties) {
	"use strict";
	this.name = "LanguageSelectDialog";

	this.initialize(tgfSettings.dialogDefaults.buttonBox);

	this.setProperties(tgfSettings.dialogDefaults.languageSelectDialog);

	if (properties !== undefined) {
		this.setProperties(properties);
	}
};

tgfDialogs.inherit(tgfDialogs.LanguageSelectDialog, tgfDialogs.ButtonBox);

tgfDialogs.LanguageSelectDialog.prototype.initPopUp = function () {
	"use strict";

	var self = this;

	this.subContainer = new tgfComponents.Base({});
	this.buttonContainer = new tgfComponents.Base({
		y: 0
	});

	this._buttonBackSmall = new tgfComponents.Button({
		x: -this.width / 2 + 80,
		y: -this.height / 2 + 80,
		image: s_button_settings_backtiny,
		onClick: function () {
			self.hide();
			EventSystem.Global.dispatchEvent(UI_Event.SETTINGS_BUTTON_CLICKED);
		}
	})

	this.subContainer.addComponent(this._buttonBackSmall);


	var posY = 0;

	this._labelHeader = new tgfComponents.Label({
		x: 0,
		y: posY,
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 32,
			fillColor: "#666666",
			baseline: "bottom",
			align: "center"
		},
		text: tgfDictionary.getText("LanguageSelect")
	})
	this.buttonContainer.addComponent(this._labelHeader);


	posY += 40;
	this._labelSubHeader = new tgfComponents.Label({
		x: 0,
		y: posY,
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 24,
			fillColor: "#666666",
			baseline: "bottom",
			align: "center"
		},
		text: tgfDictionary.getText("LanguageSelectSub")
	})
	this.buttonContainer.addComponent(this._labelSubHeader);

	posY += 78;
	this._buttonEnglish = new tgfComponents.SettingsButton({
		x: 0,
		y: posY,
		image: s_button_settings_iconright,
		fontUp: {
			fontFace: f_main_font.fontFace,
			fontSize: 28,
			fillColor: "#666666",
			baseline: "middle",
			align: "center"
		},
		text: tgfDictionary.getText("LanguageEnglish"),
		language: 'en-us',
		subIcon: {
			x: 169,
			y: -3,
			image: s_button_settings_flag_english,
		},
		onClick: function () {
			self._updateSelectedLanguage(this);
		}
	});
	this.buttonContainer.addComponent(this._buttonEnglish);


	posY += 94;
	this._buttonFrench = new tgfComponents.SettingsButton({
		x: 0,
		y: posY,
		image: s_button_settings_iconright,
		fontUp: {
			fontFace: f_main_font.fontFace,
			fontSize: 28,
			fillColor: "#666666",
			baseline: "middle",
			align: "center"
		},
		text: tgfDictionary.getText("LanguageFrench"),
		language: 'fr-fr',
		subIcon: {
			x: 169,
			y: -3,
			image: s_button_settings_flag_french,
		},
		onClick: function () {
			self._updateSelectedLanguage(this);
		}
	});
	this.buttonContainer.addComponent(this._buttonFrench);

	posY += 126;
	this._buttonConfirm = new tgfComponents.Button({
		x: 0,
		y: posY,
		width: 503,
		image: s_button_default_green,
		fontUp: {
			fontFace: f_main_font.fontFace,
			fontSize: 28,
			fillColor: "#ffffff",
			baseline: "middle",
			align: "center"
		},
		text: tgfDictionary.getText("ConfirmSelection"),
		onClick: this._onConfirmClicked.bind(this),
	});
	this.buttonContainer.addComponent(this._buttonConfirm);


	var savedLanguage = gameData.language;
	if (!savedLanguage) savedLanguage = 'en-us';

	switch (savedLanguage) {
		case 'en-us':
			{
				this._setSelectedLanguage(this._buttonEnglish);
				break;
			}
		case 'fr-fr':
			{
				this._setSelectedLanguage(this._buttonFrench);
				break;
			}
		default:
			{
				this._setSelectedLanguage(this._buttonEnglish);
			}
	}

	this.container.onSubEffectStart = function (component, effect) {
		if (effect === component.effects[0]) { //"show"){
			self.startAnimation();
		}
	};

	this.buttonContainer.y = -posY / 2 - 20;


	this.subContainer.addComponent(this.buttonContainer);
	this.container.addComponent(this.subContainer);
};

tgfDialogs.LanguageSelectDialog.prototype._onConfirmClicked = function () {

	if (this._selectedLanguage.language != tgfDictionary.getLanguage()) {

		tgfDictionary.setLanguage(this._selectedLanguage.language);
		EventSystem.Global.dispatchEvent(Localisation_Event.LANGUAGE_CHANGED);

		this.hide();
		EventSystem.Global.dispatchEvent(UI_Event.SETTINGS_BUTTON_CLICKED);

	} else {

		this.hide();
		EventSystem.Global.dispatchEvent(UI_Event.SETTINGS_BUTTON_CLICKED);
	}
}

tgfDialogs.LanguageSelectDialog.prototype._setSelectedLanguage = function (ref) {

	this._selectedLanguage = ref;
	this._selectedLanguage.select();
}

tgfDialogs.LanguageSelectDialog.prototype._updateSelectedLanguage = function (ref) {

	console.log('_updateSelectedLanguage', ref.language, ref);
	if (this._selectedLanguage) {

		if (this._selectedLanguage == ref) return;
		else {
			this._selectedLanguage.deselect();
		}
	}

	this._setSelectedLanguage(ref);

	gameData.language = ref.language;
	saveDataService.savePlayerData(gameData.getSaveableGameData());
}

tgfDialogs.LanguageSelectDialog.prototype.startAnimation = function () {
	"use strict";
	this.startAnim = true;
	this.time = 0;
};

// ***************************************
// Preparing and showing
// ***************************************

// Processing required when preparing the dialog for use
tgfDialogs.LanguageSelectDialog.prototype.doPrepare = function () {
	"use strict";
	var self = this;

	tgfDialogs.LanguageSelectDialog.uber.doPrepare.call(this);

	this.initPopUp();

	this.container.onHide = function () {
		if (self.onEnableCall) {
			self.onEnableCall();
		}
	};

	// Add the additional components
	for (var i = 0; i < this.components.length; i += 1) {
		this.container.addComponent(this.components[i]);
	}
};

tgfDialogs.LanguageSelectDialog.prototype.handleTouchDown = function (finger, x, y) {
	"use strict";
	tgfDialogs.LanguageSelectDialog.uber.handleTouchDown.call(this, finger, x, y);
	return true; // This makes sure we can't click something in the background
};

tgfDialogs.LanguageSelectDialog.prototype.handleTouchUp = function (finger, x, y) {
	"use strict";
	tgfDialogs.LanguageSelectDialog.uber.handleTouchUp.call(this, finger, x, y);
	return true; // This makes sure we can't click something in the background
};
