// Inherit the base dialog
tgfComponents.inherit(tgfComponents.CalendarCircleComponent, tgfComponents.Base);

tgfComponents.CalendarCircleComponent.prototype._createDateLabels = function (date, x, y) {
    'use strict';

    var container = new tgfComponents.Container({
        x: x,
        y: y
    });

    var dayComponent = new tgfComponents.Label({
        font: {
            fontFace: f_main_font.fontFace,
            fontSize: tgfSettings.theme.levelResultDialog.day.font.size,
            fontWeight: tgfSettings.theme.levelResultDialog.day.font.weight,
            fillColor: tgfSettings.theme.levelResultDialog.day.font.color,
            baseline: "middle",
            align: "center"
        },
        x: 0,
        y: -81,
        text: DateUtil.getDayLabel(date.getDay())
    });

    container.addComponent(dayComponent);

    var dayNumComponent = new tgfComponents.Label({
        font: {
            fontFace: f_main_font.fontFace,
            fontSize: tgfSettings.theme.levelResultDialog.dayNumber.font.size,
            fontWeight: tgfSettings.theme.levelResultDialog.dayNumber.font.weight,
            fillColor: tgfSettings.theme.levelResultDialog.dayNumber.font.color,
            baseline: "middle",
            align: "center"
        },
        x: 0,
        y: 18,
        text: date.getDate().toString()
    });

    container.addComponent(dayNumComponent);

    var monthComponent = new tgfComponents.Label({
        font: {
            fontFace: f_main_font.fontFace,
            fontSize: tgfSettings.theme.levelResultDialog.month.font.size,
            fontWeight: tgfSettings.theme.levelResultDialog.month.font.weight,
            fillColor: tgfSettings.theme.levelResultDialog.month.font.color,
            baseline: "middle",
            align: "center"
        },
        x: 0,
        y: 84,
        text: DateUtil.getMonthLabel(date.getMonth())
    });

    container.addComponent(monthComponent);

    return container;
};

tgfComponents.CalendarCircleComponent.prototype._getDifficultiesPlayed = function() {

    if(!this.includeCheckmark) {
        return [];
    }

    var difficultiesPlayed = [];

    for(var difficultyKey in tgfSettings.game.difficulties) {
        difficultiesPlayed.push(tgfSettings.game.difficulties[difficultyKey]);
    }

    return difficultiesPlayed;
};

tgfComponents.CalendarCircleComponent.prototype._createDifficultyIndicator = function(difficulty, x, y) {
    return new tgfComponents.DifficultyIndicatorComponent({
        startAlpha: 1,
        startDifficulty: difficulty,
        x: x,
        y: y,
        difficultiesPlayed: this._getDifficultiesPlayed()
    });
}

tgfComponents.CalendarCircleComponent.prototype.doPrepare = function() {

    var whiteCircle = new tgfComponents.Picture({
        image: s_popup_date_bg,
    });

    this.addComponent(whiteCircle);

    var dateComponent = this._createDateLabels(this.date, 0, 0);

    this.addComponent(dateComponent);

    if(this.difficulty != null) {
         var difficultyIndicator = this._createDifficultyIndicator(this.difficulty, 0, s_popup_date_bg.height * 0.5);

         this.addComponent(difficultyIndicator);
    }
};
