// ***************************************

// Directives for jslint
/*global tbEase, tbVectorFont, tbGraphics, tbImage, tbSurface, tbGame */
/*global tgfComponents, tgfScale, tgfEffects, tgfDictionary, tgfAudio, tgfSettings, f_tgf_text */

tgfSettings.componentDefaults.uiValue = {
	backgroundImage: undefined,             // Background image for the component
	backgroundProperties: undefined,        // Additional properties for the background
	width: tgfScale(100),                   // Width of the text box (when 0 or undefined the width of the image)
	height: tgfScale(80),                   // Height of the text box (when 0 or undefined the height of the image)
	margin: tgfScale(8),                    // Horizontal margin that should remain emtpy of text
	iconImage: undefined,                   // Optional icon image
	iconX: 0,                               // X-position of the icon
	iconY: tgfScale(-16),                   // Y-position of the icon
	iconProperties: undefined,              // Additional properties for the icon
	nameText: "",                           // Text for the name (if any)
	nameDictionaryKey: "",                  // Dictionary key for the name
	nameX: 0,                               // X-position of the name
	nameY: tgfScale(-16),                   // Y-position of the name
	nameFont: f_tgf_text,                   // Font for the name
	nameProperties: undefined,              // Additional properties for the name
	valueType: "number",                    // Type of value ("number", "time", "text")
	valueStart: 0,                          // Value at the start
	valueX: 0,                              // X-position of the value
	valueY: tgfScale(16),                   // Y-position of the value
	valueFont: f_tgf_text,                  // Font for the value
	valueProperties: undefined,             // Additional properties for the value
	valueSeparator: ",",                    // Separator between 1000's or minutes and seconds
	autoIncrementInterval: 1,               // The interval between automatic changes of the value
	autoIncrementValue: 0,                  // How much to increment the value after each interval
	allowNegative: false,                   // Whether the value is allowed to be negative
	easeFunction: tbEase.easeLinear,        // Ease function to use for progress (undefined for no ease)
	easeDuration: 1,                        // Duration of an ease
	easeInterval: 0.1,                      // Interval between ease updates (to avoid too many text redraws)
	easeMinimum: 0,                         // Minimum value change before an ease is used

	lineValue: false,
	invertValues: false,

	alwaysShowHours : false,                // Always show the hours if this is a time based component, even if the value is 0 (only applies if always show minutes is also true)
	alwaysShowMinutes : false,              // Always show the minutes if this is a time based component, even if the value is 0

	accurateTimingEnabled : false,          // If this is a time based ccmponent, the value will run down to 'endTime'
	endTime : 0,                            // The time that the component should run down to
	
	onValueChange: undefined,               // Callback when the visible value changes
	onValueChangeEnd: undefined,            // Callback when the visible value change has been completed
	
	components: []                          // Components to add as children
};

// The constructor for the component
/**
 * @constructor
 * @base tgfComponents.Base
 */
tgfComponents.UiValue = function(properties) {
	"use strict";
	this.name = "UiValue";          // The name of the component
	// Initialize properties
	this.initialize(tgfSettings.componentDefaults.uiValue);
	// Set user properties
	if (properties !== undefined) { this.setProperties(properties); }
};

// Inherit the base component
tgfComponents.inherit(tgfComponents.UiValue, tgfComponents.Base);


// ***************************************
// Specific methods for this component
// ***************************************

// Set the value for the component
tgfComponents.UiValue.prototype.setValue = function(value, force) {
	"use strict";
	this._setValue(value, force);
};

// Add to the value for the component
tgfComponents.UiValue.prototype.addValue = function(value, force) {
	"use strict";
	this._setValue(this.getValue() + value, force);
};

// Returns the value for the component
tgfComponents.UiValue.prototype.getValue = function() {
	"use strict";
	return this.valueNew;
};

// Pause the auto incrementing
tgfComponents.UiValue.prototype.pauseAutoIncrement = function() {
	"use strict";
	this.autoIncrementEnabled = false;
};

// Resume the auto incrementing
tgfComponents.UiValue.prototype.resumeAutoIncrement = function() {
	"use strict";
	this.autoIncrementEnabled = true;
};


// ***************************************
// Internal methods
// ***************************************

// Initializes the value
tgfComponents.UiValue.prototype._initValue = function() {
	"use strict";
	this.valueOld = this.valueStart;
	this.valueNew = this.valueStart;
	this.value = this.valueStart;
	this.valueTime = 0;
	this.valueChanged = false;
	// Adapt the label in the component
	this._valueToString();
};

// Set the value for the component
tgfComponents.UiValue.prototype._setValue = function(value, force) {
	"use strict";
	// Avoid negative values if not allowed
	if ((this.valueType === "number" || this.valueType === "time") && value < 0 && !this.allowNegative) { value = 0; }
	// When no change, noting needs to be done
	if (this.valueNew === value) { return; }
	// Set the new value
	this.valueOld = this.value;
	this.valueNew = value;
	this.valueTime = 0;
	// Immediately update in various cases
	if (force || this.easeFunction === undefined || (this.valueType !== "number" && this.valueType !== "time") ||
		Math.abs(value - this.valueOld) <= this.easeMinimum) {
		this.valueOld = this.valueNew;
	}
	// Adapt the label in the component
	this._valueToString();
};

// Update the value, using the ease function
tgfComponents.UiValue.prototype._updateValue = function(timePassed) {
	"use strict";
	var value = this.value, oldTime = this.valueTime;
	if (this.valueType !== "number" && this.valueType !== "time") { return; }
	// Update the time
	this.valueTime += timePassed;
	if (this.valueTime >= this.easeDuration) {
		this.valueOld = this.valueNew;
		this.value = this.valueOld;
	} else {
		// Only update after interval
		if (Math.floor(this.easeInterval !== 0 && this.valueTime/this.easeInterval) ===  Math.floor(oldTime/this.easeInterval)) { return; }
		// Update the progress
		if (this.easeFunction === undefined) { return; }
		if (this.value === this.valueNew) { return; }
		this.value = this.easeFunction(this.valueTime, this.valueOld, this.valueNew - this.valueOld, this.easeDuration);
	}
	// Now make the actual change, if required
	if (Math.round(this.value) !== Math.round(value)) {
		this._valueToString();
	}
};

// Converts the current value to the string in the label
tgfComponents.UiValue.prototype._valueToString = function() {
	"use strict";
	var oldString = this.valueComponent.text,
		value = Math.round(this.value),
		str, i, val;
	// Adapt the value string
	switch (this.valueType) {
		case "number":
			str = value.toString();
			this.valueComponent.text = "";
			for (i = 0; i < str.length; i += 1) {
				if ((str.length - i) % 3 === 0 && i !== 0) { this.valueComponent.text += this.valueSeparator; }
				this.valueComponent.text += str.charAt(i);
			}
			if(this.lineValue){
				if(this.invertValues){
					this.lineComponent.text = this.nameComponent.text + " " + this.valueComponent.text;
				} else {
					this.lineComponent.text = this.valueComponent.text + " " + this.nameComponent.text;
				}
				this.lineComponent.recreate();
			}

			break;
		case "time":
			val = value;
			this.valueComponent.text = "";
			//hours
			if (value >= 3600) {
				this.valueComponent.text += Math.floor(val/3600).toString() + this.valueSeparator;
				val = val % 3600;
			} else if (this.alwaysShowHours && this.alwaysShowMinutes){
				this.valueComponent.text += "0" + this.valueSeparator;
			}
			//tens of minutes
			if (value >= 600) {
				this.valueComponent.text += Math.floor(val/600).toString();
				val = val % 600;
			} else if (this.alwaysShowHours && this.alwaysShowMinutes){
				this.valueComponent.text += "0";
			}
			//minutes
			if (value >= 60) {
				this.valueComponent.text += Math.floor(val/60).toString() + this.valueSeparator;
				val = val % 60;
			 } else if (this.alwaysShowMinutes){
				this.valueComponent.text += "0" + this.valueSeparator;
			}
			//tens of seconds
			if (value >= 10) {
				this.valueComponent.text += Math.floor(val/10).toString();
				val = val % 10;
			} else if (this.alwaysShowMinutes){
				this.valueComponent.text += "0";
			}
			//seconds
			this.valueComponent.text += val.toString();
			break;
		default:
			this.valueComponent.text = value;
	}
	if (oldString !== this.valueComponent.text ) { 
		this.valueComponent.recreate(); 
		// Call the callback if required
		if (this.onValueChange) { this.onValueChange(this, value); }
	}
};

// Initialize the auto increment
tgfComponents.UiValue.prototype._initAutoIncrement = function() {
	"use strict";
	this.autoIncrementTime = 0;
	this.autoIncrementEnabled = true;
};

// Update the auto increment
tgfComponents.UiValue.prototype._updateAutoIncrement = function(timePassed) {
	"use strict";
	if (!this.autoIncrementEnabled) { return; }

	if (this.autoIncrementValue === 0) { return; }
	this.autoIncrementTime += timePassed;
	if (this.autoIncrementTime > this.autoIncrementInterval) {
		this.addValue(this.autoIncrementValue);
		this.autoIncrementTime -= this.autoIncrementInterval;
	}       
};

// Update the accurate timing
tgfComponents.UiValue.prototype._updateAccurateTiming = function() {
	"use strict";
	if (!this.accurateTimingEnabled){ return; }

	var currentTime = tbGame.lastTime;
	var timeLeft = this.endTime - currentTime;
	//this.setValue(timeLeft/1000, true);
	var value = Math.max(0, Math.ceil(timeLeft/1000) )

	this.valueOld = this.value;
	this.valueNew = value;
	this.value = value;

	this._valueToString();
};

//Checks when value count has ended
tgfComponents.UiValue.prototype._updateValueChangeEnd = function(){
	"use strict";
	if (!this.valueChanged && this.valueOld === this.valueNew) {
		if (this.onValueChangeEnd) {
			this.onValueChangeEnd(this, this.valueNew);
		}
		this.valueChanged = true;
	} else if (this.valueOld !== this.valueNew) {
		this.valueChanged = false;
	}
};


// ***************************************
// Preparing, showing and activating
// ***************************************

// Processing required when preparing the component for use
tgfComponents.UiValue.prototype.doPrepare = function() {
	"use strict";
	var i;
	if (!this.width && this.backgroundImage) { this.width = this.backgroundImage.width; } 
	if (!this.height && this.backgroundImage) { this.height = this.backgroundImage.height; } 
	// Add the background image
	if (this.backgroundImage) {
		this.backgroundComponent = new tgfComponents.Picture( {
			x: 0, y: 0, width: this.width, height: this.height,
			image: this.backgroundImage, createFromSlices: true
		} );
		this.backgroundComponent.setProperties(this.backgroundProperties);
		this.addComponent(this.backgroundComponent);
	}
	// Add the icon image
	if (this.iconImage) {
		this.iconComponent = new tgfComponents.Picture( {
			x: this.iconX, y: this.iconY, image: this.iconImage
		} );
		this.iconComponent.setProperties(this.iconProperties);
		this.addComponent(this.iconComponent);
	}

	var str = "";
	if(this.invertValues){
		str = this.name + " " + this.value;
	} else {
		str = this.value + " " + this.name;
	}

	this.lineComponent = new tgfComponents.Label({
		x: this.valueX, y: this.valueY, width: this.width - 2* this.margin, height: this.height/2,
		text: str, dictionaryKey: this.nameDictionaryKey,
		font: this.valueFont, fitToBox: true
	});

	if(this.lineValue){
		this.addComponent(this.lineComponent);
	}

	// Add the name label
	if (this.nameText !== "" || this.nameDictionaryKey !== "") {
		this.nameComponent = new tgfComponents.Label( {
			x: this.nameX, y: this.nameY, width: this.width - 2* this.margin, height: this.height/2,
			text: this.nameText, dictionaryKey: this.nameDictionaryKey,
			font: this.nameFont, fitToBox: true, align: "center", baseline: "middle"
		} );

		this.nameComponent.setProperties(this.nameProperties);
		if(!this.lineValue) {
			this.addComponent(this.nameComponent);
		}
	}
	// Add the value label
	this.valueComponent = new tgfComponents.Label( {
		x: this.valueX, y: this.valueY, width: this.width - 2* this.margin, height: this.height/2,
		text: "", dictionaryKey: "",
		font: this.valueFont, fitToBox: true, align: "center", baseline: "middle"
	} );
	this.valueComponent.setProperties(this.valueProperties);
	if(!this.lineValue) {
		this.addComponent(this.valueComponent);
	}

	// Add the child components
	if (this.components) {
		for (i = 0; i < this.components.length; i += 1) {
			this.addComponent(this.components[i]);
		}
	}
};

// Processing required when freeing the component from use
tgfComponents.UiValue.prototype.doFree = function() {
	"use strict";
	this.backgroundComponent = undefined;
	this.iconComponent = undefined;
	this.valueComponent = undefined;
	this.nameComponent = undefined;
};

// Processing required when showing the component
tgfComponents.UiValue.prototype.doShow = function() {
	"use strict";
	this._initValue();
	this._initAutoIncrement();
};


// ***************************************
// Methods called when events must be processed
// ***************************************

// Called at the end of each step
tgfComponents.UiValue.prototype.doEndStep = function(timePassed) { 
	"use strict";
	this._updateValue(timePassed/1000);
	this._updateAutoIncrement(timePassed/1000);
	this._updateAccurateTiming();
	this._updateValueChangeEnd();
};




//******************************************************
//*****    Script Resource: TextBox
//******************************************************


var gameui = gameui || {};

/**
 * @constructor
 * @base gameui.Component
 */
gameui.TextBox = function(parent, x, y, width, height, font) {
	"use strict";
	tgfComponents.Base.call(this, parent, x, y);
	this.width = width;
	this.height = height;
	this.surfaceMargin = 4;
	this.alpha = 1;
	this.text = "";
	this.font = font ? font : fonts.game.f_default;
	this.surface = new tbSurface(width + this.surfaceMargin * 2, height + this.surfaceMargin * 2);
	this.setText("LOREM IPSUM");
};

tgfComponents.inherit(gameui.TextBox, tgfComponents.Base);

gameui.TextBox.prototype.setText = function (text) {
	"use strict";
	if (this.text === text) {
		return;
	}
	this.dirty = true;
	this.text = text;
	this.surface.clear();
	this.surface.setTarget();
	var fontScale = 1;
	var textWidth = this.font.textWidth(this.text) + (this.font.getStroke() ? this.font.getStrokeWidth() : 0);
	var textHeight = this.font.textHeight(this.text) + (this.font.getStroke() ? this.font.getStrokeWidth() : 0);
	var oldFontSize = this.font.getFontSize();
	if (textWidth > this.width) {
		fontScale = this.width / textWidth;
	}
	if (textHeight > this.height) {
		fontScale = Math.min(fontScale, this.height / textHeight);
	}
	this.font.setFontSize(Math.floor(oldFontSize * fontScale));
	switch (this.font.getAlign()) {
		case alignLeft:
			this.font.drawSimple(this.text, this.surfaceMargin, this.surface.height / 2 + this.surface.height * 0.085);
			break;
		case alignCenter:
			this.font.drawSimple(this.text, this.surface.width / 2, this.surface.height / 2 + this.surface.height * 0.085);
			break;
		case alignRight:
			this.font.drawSimple(this.text, this.surface.width - this.surfaceMargin, this.surface.height / 2 + this.surface.height * 0.085);
			break;
	}
	this.font.setFontSize(oldFontSize);
	this.surface.resetTarget();
};

gameui.TextBox.prototype.draw = function () {
	"use strict";
	if (tgfComponents.drawDebug) {
		tbGraphics.drawRectangle(this.x, this.y, this.width, this.height, "red", true);
	}
	if (this.alpha !== 1) {
		tbGraphics.context.save();
		tbGraphics.context.globalAlpha *= this.alpha;
	}
	this.surface.drawSimple(this.x - this.surfaceMargin, this.y - this.surfaceMargin);
	if (this.alpha !== 1) {
		tbGraphics.context.restore();
	}
};

/**
 * @constructor
 * @base gameui.TextBox
 */
 gameui.TextBoxToken = function(x, y, width, height, font, depth, layer, callback, canvas) {
	"use strict";
	gameui.TextBox.call(this, null, x, y, width, height, font);
	 this.canvas = canvas;
	this.depth = depth ? depth : -900;
	this.layer = layer ? layer : -901;
	this.active = true;
	this.visible = true;
	 this.onClose = callback;
	tbGame.addToken(this);
};

tgfComponents.inherit(gameui.TextBoxToken, gameui.TextBox);

gameui.TextBoxToken.prototype.handleDraw = function() {
	"use strict";
	this.draw();
};




//******************************************************
//*****    Script Resource: Floater
//******************************************************

/* global
	gameui
 */

var floaters = floaters || {};

/**
 * @constructor
 */
floaters.Floater = function(text, x, y, delay, font, scaleFactor, fillColor, strokeColor, depth , layer, callback, canvas) {
	"use strict";
	if (delay === void 0) {
		delay = 0;
	}
	if (font === void 0) {
		font = OpenSansBold;
	}
	/*
	if (fillColor === void 0) {
		fillColor = "#FFF3C1";
	}
	if (strokeColor === void 0) {
		strokeColor = "#421700";
	}
	if (scaleFactor === void 0) {
		scaleFactor = 1;
	}
	*/
	var workingFont = font.clone();
	
	if (fillColor !== void 0) {
		workingFont.setFillColor(fillColor);
	}
	if (strokeColor !== void 0) {
		workingFont.setStrokeColor(strokeColor);
	}
	if (scaleFactor !== void 0) {
		workingFont.setFontSize(workingFont.getFontSize() * scaleFactor);
	}

	
	
	
	workingFont.setBaseline("middle");

	gameui.TextBoxToken.call(this, x, y, workingFont.textWidth(text) + (workingFont.getStroke() ? workingFont.getStrokeWidth() : 0), workingFont.textHeight(text) + 50
			+ (workingFont.getStroke() ? workingFont.getStrokeWidth() : 0), workingFont, depth, layer, callback, canvas);

	this.timer = 0;
	this.duration = 2200;
	this.easeY = tbEase.easeCreateCombined([tbEase.easeConstant, tbEase.easeConstant, tbEase.easeInCubic], [false, false, false], [0.2, 0.0, 1.3]);
	this.easeAlpha = tbEase.easeCreateCombined([tbEase.easeConstant, tbEase.easeConstant, tbEase.easeInOutCubic], [false, false, false], [0.2, 0.4, 0.9]);
	this.easeScale = tbEase.easeCreateCombined([tbEase.easeOutOvershoot, tbEase.easeConstant, tbEase.easeConstant], [false, false, false], [0.2, 0.4, 0.9]);
	this.x = x;
	this.y = y;
	this.timer = -delay;
	this.setText(text);
	this.from_y = y;
	this.to_y = y - tgfScale(50);
	this.active = true;
	this.scale = 0;
	this.alpha = 1;
};

tgfComponents.inherit(floaters.Floater, gameui.TextBoxToken);

floaters.Floater.prototype.handleBeginStep = function(timePassed) {
	"use strict";
	this.timer += timePassed;
	if (this.timer > 0) {
		if (this.timer >= this.duration) {
			tbGame.removeToken(this);
		}
		else {
			this.y = this.easeY(this.timer, this.from_y, this.to_y - this.from_y, this.duration);
			this.alpha = this.easeAlpha(this.timer, 1, -1, this.duration);
			this.scale = this.easeScale(this.timer, 0, 1, this.duration);
		}
	}
};

floaters.Floater.prototype.draw = function() {
	"use strict";
	if (this.timer > 0) {
		this.surface
				.drawExt(this.x - this.surface.width / 2 * this.scale, this.y - this.surface.height / 2 * this.scale, this.scale, this.scale, 0, this.alpha);
	}
};

floaters.Floater.prototype.handleRemove = function(){
	"use strict";
	if(this.onClose){
		this.onClose();
	}
};




//******************************************************
//*****    Script Resource: AnchorComponent
//******************************************************

/* global
	tgfComponents,
	tbVector
 */

/**
 * @constructor
 * @base tgfComponents.Base
 */

tgfComponents.AnchorComponent = function(properties) {
	"use strict";

	this.initialize();

	this.ini

	this.width  = tgfScale(200);
	this.height = tgfScale(200);

	// Set user properties
	if (properties !== undefined) {
		this.setProperties(properties);
	}

	if( !this.anchorCoordinates ) {
		this.anchorCoordinates = new tbVector(0,0);
	}
};

tgfComponents.inherit(tgfComponents.AnchorComponent, tgfComponents.Base);

tgfComponents.AnchorComponent.prototype.setPosition = function () {
	"use strict";
	var anchorX = tgfGraphics.visibleLeft + tgfGraphics.visibleWidth  * this.anchorCoordinates.x;
	var anchorY = tgfGraphics.visibleTop  + tgfGraphics.visibleHeight * this.anchorCoordinates.y;

	if(this.parent) {
		this.x = this.parent.screenToComponentX(anchorX, anchorY);
		this.y = this.parent.screenToComponentY(anchorX, anchorY);
	}
	else {
		this.x = anchorX;
		this.y = anchorY;
	}
};

tgfComponents.AnchorComponent.prototype.doBeginStep = function (timepassed) {
	"use strict";
	this.setPosition();
};

tgfComponents.AnchorComponent.prototype.doPrepare = function (timepassed) {
	"use strict";
	this.setPosition();
};

