// *********************************
// CoolGames Builder JavaScript file
// *********************************

var tbLazyImage = function (path, anchorX, anchorY, amountOfImages, imagesPerRow, placeholderImage) {

    this._isLoaded = false;

    var name = path;
    this._loadMoment = name;

    this._anchorFactorX = placeholderImage ? placeholderImage.xOrigin / placeholderImage.width : anchorX;
    this._anchorFactorY = placeholderImage ? placeholderImage.yOrigin / placeholderImage.height : anchorY;
    this._amountOfImages = amountOfImages;
    this._imagesPerRow = placeholderImage ? placeholderImage.perRow : imagesPerRow;

    this.onTextureLoadedEvent = new EventSystem.Local();

    this._lazyLoadedTexture = new tbTexture(name + "_Texture", 1, name);
    this._lazyLoadedTexture.addBitmap(0, path);

    if (placeholderImage) {
        tbImage.apply(this, [name, placeholderImage.texture, amountOfImages, placeholderImage.width, placeholderImage.height, placeholderImage.xOrigin, placeholderImage.yOrigin, placeholderImage.combinedWidth, placeholderImage.combinedHeight, this._imagesPerRow]);
        this.subTexIndex = placeholderImage.subTexIndex;
        this.subX = placeholderImage.subX;
        this.subY = placeholderImage.subY;
        this.subW = placeholderImage.subW;
        this.subH = placeholderImage.subH;
        this.subXOff = placeholderImage.subXOff;
        this.subYOff = placeholderImage.subYOff;
    } else {
        tbImage.apply(this, [name, this._lazyLoadedTexture, this._amountOfImages, 0, 0, 0, 0, 0, 0, this._imagesPerRow]);
        this.addImage(0, 0, 0, 0, 0, 0, 0, 0);
    }
}

tgfComponents.inherit(tbLazyImage, tbImage);

tbLazyImage.prototype.handleSpecial = function (id, args) {
    if (id == "Load Complete") {
        if (args.moment == this._loadMoment) {

            this._setTexture(this._lazyLoadedTexture);

            this.onTextureLoadedEvent.trigger();

            this._isLoaded = true;
            tbGame.removeToken(this);
        }
    }
}

tbLazyImage.prototype.load = function () {
    if (!this._isLoaded) {
        tbGame.addToken(this);
        tbLoader.startLoading(this._loadMoment);
    } else {
        console.log("[tbLazyImage] Already loaded.")
    }
};

tbLazyImage.prototype._setTexture = function (targetTexture) {

    var rows = this._amountOfImages / this._imagesPerRow;

    this.name = this._loadMoment;
    this.texture = targetTexture;
    this.number = this._amountOfImages;
    this.width = targetTexture.bitmaps[0].width;
    this.height = targetTexture.bitmaps[0].height;

    var subImageWidth = targetTexture.bitmaps[0].width / this._imagesPerRow;
    var subImageHeight = targetTexture.bitmaps[0].height / rows;

    this.xOrigin = subImageWidth * this._anchorFactorX;
    this.yOrigin = subImageHeight * this._anchorFactorY;

    this.combinedWidth = targetTexture.bitmaps[0].width;
    this.combinedHeight = targetTexture.bitmaps[0].height;
    this.perRow = this._imagesPerRow;
    this.subTexIndex = [0];
    this.subX = [];
    this.subY = [];
    this.subW = [];
    this.subH = [];
    this.subXOff = [];
    this.subYOff = [];

    var rows = this._amountOfImages / this._imagesPerRow;

    for (var i = 0; i < rows; i++) {
        for (var j = 0; j < this._imagesPerRow; j++) {

            var imageNumber = (i * this._imagesPerRow) + j;
            
            var subImageX = imageNumber * subImageWidth;
            var subimageY = i * subImageHeight;
            this.addImage(imageNumber, 0, subImageX, subimageY, subImageWidth, subImageHeight, 0, 0);
        }
    }
};
