tgfDialogs.TutorialSlideDialog.prototype.addTextBox = function (textBoxConfig) {

	this._textBoxConfig = textBoxConfig;
	this._container = new tgfComponents.Base({});

	this._container.width = tgfSettings.graphics.areaWidth;
	this._container.height = tgfSettings.graphics.areaHeight;

	if (textBoxConfig.alpha != null) {
		this._container.alpha = textBoxConfig.alpha;
	}

	if (textBoxConfig.doNotOverlap != null) {

		var targetX = tgfScale(textBoxConfig.x);
		var targetY = tgfScale(textBoxConfig.y);

		this.objectToAvoid = this._itemsOfInterest[textBoxConfig.doNotOverlap];
		var isoverlapping = !(this.objectToAvoid.x > targetX + (textBoxConfig.width / 2) ||
			this.objectToAvoid.x + this.objectToAvoid.width < targetX - (textBoxConfig.width / 2) ||
			this.objectToAvoid.y > targetY + textBoxConfig.height + (textBoxConfig.height / 2) ||
			this.objectToAvoid.y + this.objectToAvoid.height < targetY - (textBoxConfig.height / 2)
		);

		if (isoverlapping) {
			textBoxConfig.x = textBoxConfig.alternative.x;
			textBoxConfig.y = textBoxConfig.alternative.y;
			textBoxConfig.width = textBoxConfig.alternative.width;
			textBoxConfig.height = textBoxConfig.alternative.height;
		}
	}

	this._background = new tgfComponents.Picture({
		width: textBoxConfig.width,
		height: textBoxConfig.height,
		createFromSlices: true,
		image: s_popup_tutorial_9slice,
		x: tgfScale(textBoxConfig.x),
		y: tgfScale(textBoxConfig.y)
	});
	this._container.addComponent(this._background);

	if (textBoxConfig.header) {
		this._header = new tgfComponents.Label({
			font: {
				fontFace: f_main_font.fontFace,
				fontSize: 24,
				fillColor: textBoxConfig.header.fontColor ? textBoxConfig.header.fontColor : tgfSettings.theme.fontColor.dark,
				baseline: "middle",
				align: "left"
			},
			x: textBoxConfig.header.x ? tgfScale(textBoxConfig.header.x) : tgfScale(textBoxConfig.x - (textBoxConfig.width / 2)) + tgfScale(38),
			y: textBoxConfig.header.y ? tgfScale(textBoxConfig.header.y) : tgfScale(textBoxConfig.y - (textBoxConfig.height / 2) + tgfScale(30)),
			text: textBoxConfig.header.text
		});
		this._container.addComponent(this._header);
	}

	if (textBoxConfig.body) {
		this._body = new tgfComponents.Label({
			font: {
				fontFace: f_main_font.fontFace,
				fontSize: 24,
				fillColor: textBoxConfig.body.fontColor ? textBoxConfig.body.fontColor : tgfSettings.theme.fontColor.dark,
				baseline: "middle",
				align: "left",
				spacing: 10
			},
			x: textBoxConfig.body.x ? tgfScale(textBoxConfig.body.x) : tgfScale(textBoxConfig.x),
			y: textBoxConfig.body.y ? tgfScale(textBoxConfig.body.y) : tgfScale(textBoxConfig.y) + tgfScale(20),
			width: textBoxConfig.body.width ? textBoxConfig.body.width : textBoxConfig.width - tgfScale(100),
			height: textBoxConfig.body.height ? textBoxConfig.body.height : textBoxConfig.height - this._header.height,
			splitLines: true,
			text: textBoxConfig.body.text
		});
		this._body.x -= this._body.width / 2;
		this._container.addComponent(this._body);
	}

	if (textBoxConfig.checkbox) {
		this._checkBox = new tgfComponents.Picture({
			image: s_checkmark_box,
			x: textBoxConfig.checkbox.x ? tgfScale(textBoxConfig.checkbox.x) : tgfScale(textBoxConfig.x) - (textBoxConfig.width / 2) + s_checkmark_box.width + tgfScale(35),
			y: textBoxConfig.checkbox.y ? tgfScale(textBoxConfig.checkbox.y) : tgfScale(textBoxConfig.y),
		});

		this._checkBoxText = new tgfComponents.Label({
			font: {
				fontFace: f_main_font.fontFace,
				fontSize: 24,
				fillColor: textBoxConfig.checkbox.fontColor ? textBoxConfig.checkbox.fontColor : tgfSettings.theme.fontColor.dark,
				baseline: "middle",
				align: "left"
			},
			x: textBoxConfig.checkbox.x ? tgfScale(textBoxConfig.checkbox.x) : this._checkBox.x + this._checkBox.width + tgfScale(35),
			y: textBoxConfig.checkbox.y ? tgfScale(textBoxConfig.checkbox.y) : this._checkBox.y + this._checkBox.height / 2 + tgfScale(5),
			width: textBoxConfig.checkbox.width ? textBoxConfig.checkbox.width : textBoxConfig.width - tgfScale(100) - (s_checkmark_box.width),
			height: textBoxConfig.checkbox.height ? textBoxConfig.checkbox.height : textBoxConfig.height - tgfScale(100),
			splitLines: true,
			text: textBoxConfig.checkbox.text
		});

		this._checkBox.y = this._body.y + this._body.height / 2 - tgfScale(75);
		this._checkBoxText.y = this._checkBox.y + this._checkBox.height / 2 + tgfScale(5);
		this._body.y -= tgfScale(35);

		if (textBoxConfig.callToAction) {
			this._checkBox.y -= tgfScale(40);
			this._checkBoxText.y -= tgfScale(40);
			this._body.y -= tgfScale(20);
		}

		this._container.addComponent(this._checkBox);
		this._container.addComponent(this._checkBoxText);
	}

	if (textBoxConfig.callToAction) {

		this._callToAction = new tgfComponents.Label({
			font: {
				fontFace: f_main_font.fontFace,
				fontSize: 24,
				fillColor: textBoxConfig.callToAction.fontColor ? textBoxConfig.callToAction.fontColor : tgfSettings.theme.fontColor.grey,
				baseline: "middle",
				align: "right"
			},
			alpha: textBoxConfig.callToAction.alpha != null ? textBoxConfig.callToAction.alpha : 1,
			effects: textBoxConfig.callToAction.effects ? textBoxConfig.callToAction.effects : null,
			x: textBoxConfig.callToAction.x ? tgfScale(textBoxConfig.callToAction.x) : textBoxConfig.x + textBoxConfig.width / 2 - tgfScale(70),
			y: textBoxConfig.callToAction.y ? tgfScale(textBoxConfig.callToAction.y) : tgfScale(textBoxConfig.y + (textBoxConfig.height / 2) - tgfScale(40 + 4)),
			text: textBoxConfig.callToAction.text
		});


		this._ctaIcon = new tgfComponents.Picture({
			image: s_icon_taptocontinue,
			alpha: textBoxConfig.callToAction.alpha != null ? textBoxConfig.callToAction.alpha : 1,
			effects: textBoxConfig.callToAction.effects ? textBoxConfig.callToAction.effects : null,
			x: textBoxConfig.callToAction.x ? tgfScale(textBoxConfig.callToAction.x) : textBoxConfig.x + textBoxConfig.width / 2 - tgfScale(50),
			y: textBoxConfig.callToAction.y ? tgfScale(textBoxConfig.callToAction.y) : tgfScale(textBoxConfig.y + (textBoxConfig.height / 2) - tgfScale(43 + 4)),
		});
		this._container.addComponent(this._callToAction);
		this._container.addComponent(this._ctaIcon);
	}

	this.addComponent(this._container);
};


