// Preparing and showing
// ***************************************


// Processing required when freeing the dialog from use
tgfDialogs.TutorialSlideDialog.prototype.doFree = function () {
	"use strict";
	this.removeAllComponents();
	if (this._progressStepsDialog) {
		this._progressStepsDialog.free();
	}

	if (this._cellHighlight) {
		this._cellHighlight.free();
	}
	this._container = undefined;
};

tgfDialogs.TutorialSlideDialog.prototype.checkCheckBox = function (callback) {
	var self = this;
	setTimeout(function () {
		if (self._feedbackPositionX && self._feedbackPositionY) {
			self._correctFeedback = new tgfComponents.SpineComponent({
				spineAnimation: tutorial_feedback_correct,
				animationClips: ["animation"], // The animation names from the spine json
				play: true,
				hasDelay: true,
				delay: 500,
				x: tgfScale(self._feedbackPositionX),
				y: tgfScale(self._feedbackPositionY),
				updateWhileUnactive: true
			});
			self._container.addComponent(self._correctFeedback);
			self._correctFeedback.show();
		}

		self.checkMark = new tgfComponents.Picture({
			image: s_popup_connectionlost_check,
			x: self._checkBox.x - tgfScale(2),
			y: self._checkBox.y - tgfScale(5),
			width: 40,
			height: 40,
			animationSpeed: 12,
			loopAnimation: false
		});
		self._container.addComponent(self.checkMark);

        self.checkMark.onAnimationComplete = function () {
            setTimeout(function () {
                callback();
            }, 500);
        }

		self.checkMark.show();
		tbAudio.play(a_checkbox);
	}, this._checkMarkDelay);
};

tgfDialogs.TutorialSlideDialog.prototype.setFeedbackPosition = function (position) {
	this._feedbackPositionX = position.x;
	this._feedbackPositionY = position.y;
}

tgfDialogs.TutorialSlideDialog.prototype.setCheckMarkDelay = function (delay) {
	this._checkMarkDelay = delay;
}

// Processing required when showing the dialog
tgfDialogs.TutorialSlideDialog.prototype.doPrepare = function () {
	"use strict";
	var self = this;

	if (this._textBoxConfig) {
		if (this._textBoxConfig.callToAction && this._textBoxConfig.callToAction.onShowEffect) {

			this._callToAction.effects = this._textBoxConfig.callToAction.onShowEffect;
			this._ctaIcon.effects = this._textBoxConfig.callToAction.onShowEffect;

			self._callToAction.repeatEffect = 1;
			self._ctaIcon.repeatEffect = 1;

			if (self._textBoxConfig.callToAction.effects) {
				this._callToAction.onEffectEnd = function (component, effect) {

					self._callToAction.effects = self._textBoxConfig.callToAction.effects;
					self._callToAction.repeatEffect = Infinity;
					self._callToAction.restartEffect();
					self._callToAction.onEffectEnd = null;
				};


				this._ctaIcon.onEffectEnd = function (component, effect) {

					self._ctaIcon.effects = self._textBoxConfig.callToAction.effects;
					self._ctaIcon.repeatEffect = Infinity;
					self._ctaIcon.restartEffect();
					self._ctaIcon.onEffectEnd = null;
				};
			}
		}

		if (this._textBoxConfig.onShowEffect) {
			this._container.repeatEffect = 1;
			this._container.effects = this._textBoxConfig.onShowEffect;
			var self = this;
			
			this._container.onEffectEnd = function () {
				self.onShowEffectEndEvent.trigger();
			}
		}
	}
};

tgfDialogs.TutorialSlideDialog.prototype.addProgressStepsDialog = function (totalSteps) {
	this._progressStepsDialog = new tgfDialogs.ProgressStepsDialog({
		_totalSteps: totalSteps,
		x: tgfScale(this._textBoxConfig.x) + this._background.width / 2,
		y: tgfScale(this._textBoxConfig.y) - this._background.height / 2 + tgfScale(23)
	});

	if (this._textBoxConfig && this._textBoxConfig.onShowEffect) {
		this._progressStepsDialog.prepare();
		this._progressStepsDialog.passEffect(this._textBoxConfig.onShowEffect);
	}
	
	this._progressStepsDialog.show();
};

tgfDialogs.TutorialSlideDialog.prototype.setProgressStep = function (step) {
	this._progressStepsDialog.setProgressStep(step);
};

tgfDialogs.TutorialSlideDialog.prototype.setProgressStepCompleted = function (step) {
	this._progressStepsDialog.setProgressStepCompleted(step);
}

tgfDialogs.TutorialSlideDialog.prototype.exitAnimation = function (callback) {

	if (this._textBoxConfig) {
		if (this._textBoxConfig.onHideEffect) {

			if (this._progressStepsDialog) {
				this._progressStepsDialog.passEffect(this._textBoxConfig.onHideEffect);
			}

			this._container.repeatEffect = 1;
			this._container.effects = this._textBoxConfig.onHideEffect;
			this._container.restartEffect();

			this._container.onEffectEnd = function () {
				callback();
			}
		} else {
			callback();
		}
	} else {
		callback();
	}
}
