// The constructor for the dialog
/**
 * @constructor
 * @base tgfDialogs.Base
 */
tgfDialogs.ProgressStepsDialog = function (properties) {
	"use strict";
	this.name = "ProgressStepsDialog";
	this.initialize(tgfSettings.dialogDefaults.progressStepsDialog);
	if (properties !== undefined) {
		this.setProperties(properties);
	}

	this.width = tgfSettings.graphics.areaWidth;
	this.height = tgfSettings.graphics.areaHeight;
};

tgfDialogs.inherit(tgfDialogs.ProgressStepsDialog, tgfDialogs.Base);

// Processing required when freeing the dialog from use
tgfDialogs.ProgressStepsDialog.prototype.doFree = function () {
	"use strict";
	this.removeAllComponents();
};

// Processing required when showing the dialog
tgfDialogs.ProgressStepsDialog.prototype.doPrepare = function () {
	"use strict";

	this._container = new tgfComponents.Base({});

	var width = this._totalSteps * this._spacing + s_progression_circle.width;

	this._line = new tgfComponents.Picture({
		image: s_pixel_progressionline,
		x: (-width/2) - (s_progression_circle.width) - tgfScale(6),
		y: 0,
		width: width,
		height: 4,
		createFromSlices: true
	});
	this._container.addComponent(this._line);

	this._progressStepComponents = []; // array of objects like this {circle: tgfComponents.Picture, number: string}

	for (var i = 0; i < this._totalSteps; i++) {

		var progressionCircle = new tgfComponents.Picture({
			image: s_progression_circle,
			x: tgfScale(this._line.x + (i * (this._spacing + s_progression_circle.width/2)))- (this._line.width/2),
			y: tgfScale(this._line.y)
		});
		this._container.addComponent(progressionCircle);

		var numberLabel = new tgfComponents.Label({
			font: {
				fontFace: f_main_font.fontFace,
				fontSize: 24,
				fillColor: "#7c3f29",
				baseline: "middle",
				align: "center"
			},
			x: progressionCircle.x,
			y: progressionCircle.y + tgfScale(4),
			text: (i + 1).toString()
		});
		this._container.addComponent(numberLabel);

		this._progressStepComponents.push({
			circle: progressionCircle,
			number: numberLabel
		})
	}

	this.addComponent(this._container);
};

tgfDialogs.ProgressStepsDialog.prototype.setProgressStep = function (step) {
	
	for (var i = 1; i < this._totalSteps+1; i++) {
		if (i < step) {
			this.setProgressStepCompleted(i);
		}
		else if (i === step) {
			this._setCurrentStep(i);
		}
		else {
			this._setProgressStepTodo(i);
		}
	}
};

tgfDialogs.ProgressStepsDialog.prototype.passEffect = function (effect) {
	this._container.repeatEffect = 1;
	this._container.effects = effect;
	this._container.restartEffect();
};

tgfDialogs.ProgressStepsDialog.prototype.setProgressStepCompleted = function (step) {

	this._progressStepComponents[step - 1].number.font.fillColor = "#fff";
	this._progressStepComponents[step - 1].number.recreate();
	this._progressStepComponents[step - 1].circle.subImage = 2;
};

tgfDialogs.ProgressStepsDialog.prototype._setCurrentStep = function (step) {
	this._progressStepComponents[step - 1].number.font.fillColor = "#7c3f29";
	this._progressStepComponents[step - 1].number.recreate();
	this._progressStepComponents[step - 1].circle.subImage = 1;
};

tgfDialogs.ProgressStepsDialog.prototype._setProgressStepTodo = function (step) {
	this._progressStepComponents[step - 1].number.font.fillColor = "#7c3f29";
	this._progressStepComponents[step - 1].number.recreate();
	this._progressStepComponents[step - 1].circle.subImage = 0;
};

tgfDialogs.ProgressStepsDialog.prototype._getNumberLabel = function (color, x, y, text) {
	
}
