var TutorialSlide = function (configuration, maskableOverlay, currentProgressStep, itemsOfInterest, previousSlideConfig) {
    this._slideConfig = configuration;
    this._currentProgressStep = currentProgressStep;
    this._itemsOfInterest = itemsOfInterest;
    this._maskableOverlay = maskableOverlay;
    this.previousSlideConfig = previousSlideConfig;

    this.completeEvent = new EventSystem.Local();
    this.failEvent = new EventSystem.Local();

    if (!this._slideConfig.fulfillmentCondition || !this._slideConfig.fulfillmentCondition.event) {

        console.error("[TutorialSlide] This tutorial slide does not define a fulfillment condition. Check the configuration for this slide");
        return;
    }

    

    this._isSlideConditionFulfilled = false;
    if (this._slideConfig.cannotContinueBeforeShow !== true) {
        this._addEventListeners();
    }
    this._started = false;
};

TutorialSlide.prototype.start = function () {
    this._started = true;

    EventSystem.Global.dispatchEvent(Level_Event.SET_FLOATERS_ENABLED, !this._slideConfig.customFloater);
    
    if (this._slideConfig.maskAreas) {
        this._replaceItemsOfInterestIn(this._slideConfig.maskAreas);
        this._applyMasks(this._maskableOverlay, this._slideConfig.maskAreas);
    }

    if (this._slideConfig.maskdialog != undefined) {
        this._maskableOverlay.setAnimations(this._slideConfig.maskdialog.onShowEffect)
    }

    this._maskableOverlay.show();
    this._cellHighlightDialog = new tgfDialogs.CellHighlightDialog({});
    this._createSlideDialog();

    if (this._slideConfig.customFloater) {
        EventSystem.Global.addEventListener(Level_Event.SCORE_FLOATER_MOMENT, this._showTutorialFeedbackFloater, this);
    }
};

TutorialSlide.prototype._replaceItemsOfInterestIn = function (items) {
    var amt = items.length;
    for (var i = 0; i < amt; i++) {
        if (items[i].copyFrom) {
            var source = this._itemsOfInterest[items[i].copyFrom];
            items[i].x = source.x;
            items[i].y = source.y;
            items[i].width = source.width;
            items[i].height = source.height;
        }
    }
}

TutorialSlide.prototype._addEventListeners = function () {
    EventSystem.Global.addEventListener(this._slideConfig.fulfillmentCondition.event, this._slideConditionReceived, this);

    if (this._slideConfig.failCondition) {
        EventSystem.Global.addEventListener(this._slideConfig.failCondition.event, this._slideFailConditionMet, this);
    }



    if (this._slideConfig.fulfillmentCondition.event === Level_Event.CORRECT_NUMBER_PLACED) {
        EventSystem.Global.addEventListener(Level_Event.EMPTY_CELL_SELECTED, this._emptyCellSelected, this);
        EventSystem.Global.addEventListener(Level_Event.EMPTY_CELL_DESELECTED, this._enableHighlight, this);
        EventSystem.Global.addEventListener(Level_Event.NON_EMPTY_CELL_SELECTED, this._enableHighlight, this);
        EventSystem.Global.addEventListener(Level_Event.NON_EMPTY_CELL_DESELECTED, this._enableHighlight, this);
    }
};

TutorialSlide.prototype._removeEventListeners = function () {
    EventSystem.Global.removeEventListener(this._slideConfig.fulfillmentCondition.event, this._slideConditionReceived, this);
    if (this._slideConfig.failCondition) {
        EventSystem.Global.removeEventListener(this._slideConfig.failCondition.event, this._slideFailConditionMet, this);
    }

    if (this._slideConfig.customFloater) {
        EventSystem.Global.removeEventListener(Level_Event.SCORE_FLOATER_MOMENT, this._showTutorialFeedbackFloater, this);
    }

    if (this._slideConfig.fulfillmentCondition.event === Level_Event.CORRECT_NUMBER_PLACED) {
        EventSystem.Global.removeEventListener(Level_Event.EMPTY_CELL_SELECTED, this._emptyCellSelected, this);
        EventSystem.Global.removeEventListener(Level_Event.EMPTY_CELL_DESELECTED, this._enableHighlight, this);
        EventSystem.Global.removeEventListener(Level_Event.NON_EMPTY_CELL_SELECTED, this._enableHighlight, this);
        EventSystem.Global.removeEventListener(Level_Event.NON_EMPTY_CELL_DESELECTED, this._enableHighlight, this);
    }
};

TutorialSlide.prototype._applyMasks = function (maskableOverlay, maskSettings) {

    for (var index = 0; index < maskSettings.length; index++) {
        var maskSetting = maskSettings[index];

        maskableOverlay.setMask(maskSetting.id, maskSetting)
    }
};

TutorialSlide.prototype._emptyCellSelected = function (xCell, yCell) {
    if (
        this._slideConfig.fulfillmentCondition.validationArguments[0] === xCell &&
        this._slideConfig.fulfillmentCondition.validationArguments[1] === yCell) {
        EventSystem.Global.dispatchEvent(Level_Event.CLEAR_ALL_HIGHLIGHTS);
    } else {
        this._enableHighlight();
    }
};

TutorialSlide.prototype._enableHighlight = function (xCell, yCell) {

    EventSystem.Global.dispatchEvent(Level_Event.HIGHLIGHT_CELL, sudokuDraw.getX(this._slideConfig.fulfillmentCondition.validationArguments[0]), sudokuDraw.getY(this._slideConfig.fulfillmentCondition.validationArguments[1]));
}

TutorialSlide.prototype._totorialSlideShown = function () {
    if (this._slideConfig.cannotContinueBeforeShow) {
        this._addEventListeners();
    }
}

TutorialSlide.prototype._createSlideDialog = function () {

    this._slideDialog = new tgfDialogs.TutorialSlideDialog({}, this._itemsOfInterest);
    this._slideDialog.onShowEffectEndEvent.listen(this._totorialSlideShown, this);

    if (this._slideConfig.textBox) {
        this._slideDialog.addTextBox(this._slideConfig.textBox)
    }

    this._cellHighlightDialog.show();

    if (this._slideConfig.fulfillmentCondition.event === Level_Event.CORRECT_NUMBER_PLACED) {
        setTimeout(function () {
            this._enableHighlight();
        }.bind(this), TutorialConfig.TutorialSettings.numberPlaceHighlightDelay);
    }

    if (this._slideConfig.correctFeedbackPosition) {
        this._slideDialog.setFeedbackPosition(this._slideConfig.correctFeedbackPosition);
    }

    if (typeof this._slideConfig.customCheckMarkDelay !== 'undefined') {
        this._slideDialog.setCheckMarkDelay(this._slideConfig.customCheckMarkDelay);
    }

    this._slideDialog.show();

    if (this._slideConfig.showProgress) {
        this._slideDialog.addProgressStepsDialog(TutorialConfig.TutorialSettings.progressPhases);
        this._slideDialog.setProgressStep(this._currentProgressStep);
    }
};

TutorialSlide.prototype._slideConditionReceived = function () {
    if (this._isSlideConditionFulfilled) return;

    EventSystem.Global.dispatchEvent(Level_Event.CLEAR_ALL_HIGHLIGHTS);

    if (this._slideConfig.fulfillmentCondition.validationArguments) {
        throw new Error("This is broken due to the introduction of NumberPlaceEventPayload. When porting or merging the onboarding feature, take this into account");

        var valid = true;
        for (var index = 0; index < arguments.length; index++) {
            if (this._slideConfig.fulfillmentCondition.validationArguments[index] !== arguments[index]) {
                valid = false;
                break;
            }
        }

        if (valid) {
            this._slideConditionFullfilled();
        }
    } else {
        this._slideConditionFullfilled();
    }
}

TutorialSlide.prototype._slideConditionFullfilled = function () {
    this._slideFailed = false;
    this._isSlideConditionFulfilled = true;
    if (this._started == false) {
        // if the condition is fullfilled before we start with this popup
        this.completeEvent.trigger(this);
        return;
    }


    if (this._slideConfig.fulfillmentCondition === Level_Event.CORRECT_NUMBER_PLACED) {
        this._slideDialog.removeCellHighlight();
    }

    //Animate checkbox here.
    if (this._slideConfig.textBox && this._slideConfig.textBox.checkbox) {
        if (this._slideConfig.progressWeight > 0) {
            EventSystem.Global.dispatchEvent(UI_Event.TUTORIAL_PROGRESS_STEP_COMPLETED, this._slideConfig.progressWeight);
            this._slideDialog.setProgressStepCompleted(this._currentProgressStep);
        }
    }
    this.completeEvent.trigger(this);
};

TutorialSlide.prototype._showTutorialFeedbackFloater = function (x, y, delay, font) {
    // text, x, y, delay, font, scaleFactor, fillColor, strokeColor, depth , layer, callback, canvas
    new floaters.Floater(this._slideConfig.customFloater, x, y, delay, font, undefined, undefined, undefined, 99999999, -99999999);
};

TutorialSlide.prototype._slideFailConditionMet = function () {
    this._isSlideConditionFulfilled = true;
    this._slideFailed = true;
    this.failEvent.trigger(this);
    if (this._slideConfig.fulfillmentCondition === Level_Event.CORRECT_NUMBER_PLACED) {
        this._slideDialog.removeCellHighlight();
    }
}

TutorialSlide.prototype.playExitAnimation = function () {
    var shouldPlayCheckBoxAnimation = false;
    if (
        this._slideConfig.textBox &&
        this._slideConfig.textBox.checkbox &&
        this._slideConfig.textBox.checkbox.playCheckAnimationOnExit &&
        this._slideFailed == false
    ) {
        shouldPlayCheckBoxAnimation = true;
    }

    if (shouldPlayCheckBoxAnimation) {
        return this.playCheckboxAnimation().then(this.playOutAnimation.bind(this));
    } else {
        return this.playOutAnimation();
    }
}

TutorialSlide.prototype.playOutAnimation = function () {
    var self = this;

    if (self._slideConfig.maskdialog != undefined) {
        self._maskableOverlay.setAnimations(self._slideConfig.maskdialog.onHideEffect);
        self._maskableOverlay.startAnimation();
    }

    return new Promise(function (resolve, reject) {

        self._slideDialog.exitAnimation(function () {
            self.destroy();
            resolve();
        });
    });
}

TutorialSlide.prototype.playCheckboxAnimation = function () {
    var self = this;
    return new Promise(function (resolve, reject) {
        self._slideDialog.checkCheckBox(function () {
            resolve();
        });
    });
}

TutorialSlide.prototype.destroy = function () {
    this._removeEventListeners();

    if (this._cellHighlightDialog) {
        this._cellHighlightDialog.free();
        this._cellHighlightDialog = null;
    }

    if (this._slideDialog) {
        this._slideDialog.onShowEffectEndEvent.stopListening(this._totorialSlideShown, this);
        this._slideDialog.free();
        this._slideDialog = null;
    }
}
