var TutorialController = function () {
    this._tutorialLevel = null;
    this._currentSlideConfig = null;
    this._previousSlideConfig = null;
    this._isActive = false;
    this._itemsOfInterest = {};
    this._lastStepTime = null;
    this._hasReportedFirstGameStart = false;
    this._currentProgressStep = null;

    this._slideQueue = [];
    this._configurationQueue = [];

}

TutorialController.prototype.startTutorial = function () {

    this._isActive = true;
    this._currentProgressStep = 1;

    SudokuAnalytics.reportTutorialStarted();

    this._tutorialLevel = new LevelController();
    this._tutorialLevel.startlevel("tutorial", TimeManager.getDate());

    tbGame.addToken(this);
    tbGame.addTokenTags(this, ["game"]);

    this._addEventListeners();
    this._addMaskableOverlay();
    TutorialConfig.initializeSettings();

    this._lastStepTime = Date.now();
    this._addSlide(TutorialConfig.TutorialSettings.firstSlide, "NONE");
    this._playNextSlide();
}

TutorialController.prototype._addEventListeners = function () {
    EventSystem.Global.addEventListener(UI_Event.TUTORIAL_EXIT_POPUP_OPEN, this.pause, this);
    EventSystem.Global.addEventListener(UI_Event.CURRENT_DAY_BUTTON_CREATED, this._addCurrentDayToItems, this, true);
    EventSystem.Global.addEventListener(Level_Event.NUMBER_FIRST_NO_NUMBER_SELCTED, this._switchToCellFirstAndSelectCell, this);
    EventSystem.Global.addEventListener(UI_Event.CALENDAR_BUTTON_CLICKED, this._cleanupTutorialLevel, this);
    EventSystem.Global.addEventListener(UI_Event.TUTORIAL_PROGRESS_STEP_COMPLETED, this._increaseProgressStep, this);
}

TutorialController.prototype._removeEventListeners = function () {
    EventSystem.Global.removeEventListener(UI_Event.TUTORIAL_EXIT_POPUP_OPEN, this.pause, this);
    EventSystem.Global.removeEventListener(UI_Event.CURRENT_DAY_BUTTON_CREATED, this._addCurrentDayToItems, this);
    EventSystem.Global.removeEventListener(Level_Event.NUMBER_FIRST_NO_NUMBER_SELCTED, this._switchToCellFirstAndSelectCell, this);
    EventSystem.Global.removeEventListener(UI_Event.CALENDAR_BUTTON_CLICKED, this._cleanupTutorialLevel, this);
    EventSystem.Global.removeEventListener(UI_Event.TUTORIAL_PROGRESS_STEP_COMPLETED, this._increaseProgressStep, this);
}

TutorialController.prototype.isActive = function () {
    return this._isActive;
}

TutorialController.prototype.pause = function () {
    this._paused = true;
    this._removeEventListeners();
    EventSystem.Global.addEventListener(UI_Event.EXIT_TUTORIAL_BUTTON_CLICKED, this._exitTutorial, this);
    EventSystem.Global.addEventListener(UI_Event.TUTORIAL_EXIT_POPUP_CLOSE, this.unpause, this);
}

TutorialController.prototype.unpause = function () {
    this._paused = false;
    this._addEventListeners();
    EventSystem.Global.removeEventListener(UI_Event.EXIT_TUTORIAL_BUTTON_CLICKED, this._exitTutorial, this);
    EventSystem.Global.removeEventListener(UI_Event.TUTORIAL_EXIT_POPUP_CLOSE, this.unpause, this);

    if (this._nextSlideIsPaused == true) {
        this._nextSlideIsPaused = false;
        this._playNextSlide();
    }

}

TutorialController.prototype._addCurrentDayToItems = function (x, y, width, height) {
    this._itemsOfInterest["currentDay"] = {
        "x": x,
        "y": y,
        "width": width,
        "height": height
    };
}

TutorialController.prototype._addMaskableOverlay = function () {
    this._maskableOverlayDialog = new tgfDialogs.MaskableOverlayDialog({});
}

TutorialController.prototype._increaseProgressStep = function (weight) {
    this._currentProgressStep += weight;
}


TutorialController.prototype._startSlide = function (slide, configuration) {
    this._reportSlideStart(configuration);
    this._currentSlideConfig = configuration;

    var nextSlideFullfillmentCondition = this._currentSlideConfig.fulfillmentCondition.event;
    if (
        nextSlideFullfillmentCondition === Level_Event.CORRECT_NUMBER_PLACED ||
        nextSlideFullfillmentCondition === Level_Event.WRONG_NUMBER_PLACED) {
        sudokuInterface.setTutorialNumberPlaceMode(true);
    } else {
        sudokuInterface.setTutorialNumberPlaceMode(false);
    }

    this._currentSlide = slide;
    slide.start();
}

TutorialController.prototype._onSlideFail = function (failedSlide) {
    this.handleSlideCompleted(failedSlide, true);
}

TutorialController.prototype._onSlideComplete = function (completedSlide) {
    this.handleSlideCompleted(completedSlide, false);
}

TutorialController.prototype.handleSlideCompleted = function (slide, failed) {
    var slideName = null;
    var currentConfig = null;
    var targetCondition = null;
    var queueIndex = this._slideQueue.indexOf(slide);

    var currentSlideMustClose = true;

    slide.completeEvent.stopListening(this._onSlideComplete, this);
    slide.failEvent.stopListening(this._onSlideFail, this);

    if (queueIndex != -1) { //Do we want to skip the slide and remove it before it is shown?
        targetCondition = failed ? this._configurationQueue[queueIndex].failCondition : this._configurationQueue[queueIndex].fulfillmentCondition;
        currentConfig = this._configurationQueue[queueIndex];

        slideName = targetCondition.nextSlide;
        currentSlideMustClose = false;
        this._removeSlideAt(queueIndex);
        slide.destroy();
    } else {
        targetCondition = failed ? this._currentSlideConfig.failCondition : this._currentSlideConfig.fulfillmentCondition;
        slideName = targetCondition.nextSlide;
        currentConfig = this._currentSlideConfig;
    }

    if (targetCondition.nextSlide == TutorialConfig.SlideOperation.PREVIOUS_SLIDE) {
        slideName = this._getConfigKeyFor(slide.previousSlideConfig);
        if (slideName === null) {
            throw new Error("[TutorialController] slideName can not be null here, but it is.");
        }
    }

    if (slideName != null) {
        this._addSlide(slideName, currentConfig);
    }

    if (currentSlideMustClose) {
        this._closeCurrentSlide();
    }
}


TutorialController.prototype._removeSlideAt = function (index) {
    this._slideQueue.splice(index, 1);
    this._configurationQueue.splice(index, 1);
}

TutorialController.prototype._addSlide = function (slideName, previousSlideConfig) {
    var configuration = TutorialConfig.SlideSettings[slideName];
    var slide = new TutorialSlide(configuration, this._maskableOverlayDialog, this._currentProgressStep, this._itemsOfInterest, previousSlideConfig);
    slide.name = slideName + Math.random();

    slide.completeEvent.listen(this._onSlideComplete, this);
    slide.failEvent.listen(this._onSlideFail, this);

    this._slideQueue.push(slide);
    this._configurationQueue.push(configuration);
}

TutorialController.prototype._closeCurrentSlide = function () {
    var self = this;
    this._currentSlide.playExitAnimation()
        .then(function () {
            self._onSlideExit();
        }).catch(function (err) {
            errorLoggingService.sendError(err);
            console.error("[TutorialController] ran into an error: " + err + "\n" + err.stack);
        });
}

TutorialController.prototype._onSlideExit = function () {
    if (this._slideQueue.length > 0) {
        this._playNextSlide();
    } else {
        var tutorialComplete = true;
        this._exitTutorial(tutorialComplete);
    }
}

TutorialController.prototype._playNextSlide = function () {
    if (this._paused) {
        this._nextSlideIsPaused = true;
        return;
    }
    var nextSlide = this._slideQueue[0];
    var nextConf = this._configurationQueue[0];
    this._slideQueue.splice(0, 1);
    this._configurationQueue.splice(0, 1);

    this._startSlide(nextSlide, nextConf);
}

TutorialController.prototype._exitTutorial = function (tutorialCompleted) {

    this._isActive = false;
    this._removeEventListeners();
    EventSystem.Global.removeEventListener(UI_Event.EXIT_TUTORIAL_BUTTON_CLICKED, this._exitTutorial, this);
    EventSystem.Global.removeEventListener(UI_Event.TUTORIAL_EXIT_POPUP_CLOSE, this.unpause, this);
    sudokuInterface.setTutorialNumberPlaceMode(false);

    this._maskableOverlayDialog.free();
    this._currentSlide.destroy();
    this._maskableOverlayDialog = null;
    
    EventSystem.Global.dispatchEvent(Level_Event.SET_FLOATERS_ENABLED, true);

    if (this._tutorialLevel) {
        this._cleanupTutorialLevel();
    }

    gameData.showTutorialAtStartup = false;
    saveDataService.savePlayerData(gameData.getSaveableGameData());

    if (!tutorialCompleted) {
        SudokuAnalytics.reportSkipTutorial();
    } else {
        SudokuAnalytics.reportTutorialCompleted(this._currentProgressStep - 1, Date.now() - this._lastStepTime);
    }

    EventSystem.Global.dispatchEvent(UI_Event.EXIT_LEVEL_BUTTON_CLICKED);
}

TutorialController.prototype._cleanupTutorialLevel = function () {
    tbGame.removeToken(this._tutorialLevel);
    tbGame.removeTokens("game");
    this._tutorialLevel = undefined;
}

TutorialController.prototype._switchToCellFirstAndSelectCell = function (x, y) {

    if (gameData.preferredControls !== Preferred_Controls.NUMBER_FIRST) {
        throw "Attempt to switch to cell first but the current control scheme is: " + gameData.preferredControls;
    }

    //Remove listener so we don't switch back once the toggle button is back
    EventSystem.Global.removeEventListener(Level_Event.NUMBER_FIRST_NO_NUMBER_SELCTED, this._switchToCellFirstAndSelectCell, this);

    gameData.preferredControls = Preferred_Controls.CELL_FIRST;
    saveDataService.savePlayerData(gameData.getSaveableGameData());

    sudokuInterface.preferredControlsChanged();
    sudokuInterface.handleCellFirstTouchDown(null, x, y);
}


TutorialController.prototype.setHasReportedFirstGameStart = function (value) {
    gameData.reportedFirstGame = value
    saveDataService.savePlayerData(gameData.getSaveableGameData());
}

TutorialController.prototype.shouldReportFirstGame = function () {
    return !gameData.reportedFirstGame && gameData.tutorialFinished;
}

TutorialController.prototype._reportSlideStart = function (configuration) {

    var slideKey = null;
    for (var key in TutorialConfig.SlideSettings) {
        if (TutorialConfig.SlideSettings.hasOwnProperty(key)) {
            if (configuration === TutorialConfig.SlideSettings[key]) {
                slideKey = key;
            }
        }
    }
    if (slideKey === null) {
        throw "[TutorialController] config passed does not match any defined key in TutorialConfig.SlideSettings" + configuration;
    }

    SudokuAnalytics.reportTutorialStep(slideKey, Date.now() - this._lastStepTime);
    this._lastStepTime = Date.now();
}

TutorialController.prototype._getConfigKeyFor = function (config) {
    for (var key in TutorialConfig.SlideSettings) {
        if (TutorialConfig.SlideSettings.hasOwnProperty(key)) {
            if (TutorialConfig.SlideSettings[key] === config) {
                return key;
            }
        }
    }
}
