var ScreenManager = function () {
    "use strict";

    this._currentScreen = null;
    this._currentScreenName = null;
    this._nextScreen = null;
    this._defaultScreenName = null;

    this._screens = {};

    EventSystem.Global.addEventListener(System_Event.SHOW_MAIN_MENU, this.setScreen, this);
    EventSystem.Global.addEventListener(Icon_Bar_Events.ICON_SELECT, this.setScreen, this);
    EventSystem.Global.addEventListener(System_Event.LEVEL_START, this.clear, this);
    EventSystem.Global.addEventListener(Localisation_Event.LANGUAGE_CHANGED, this.refreshScreen, this);
    // VipMembership.changeEvent.listen(this.refreshScreen, this);
    EventSystem.Global.addEventListener(UI_Event.GO_TO_SCREEN_CLICKED, this.setScreen, this);
}

ScreenManager.prototype.setDefault = function (screenName) {
    this._defaultScreenName = screenName;
}

ScreenManager.prototype.addScreen = function (name, screen, properties) {
    this._screens[name] = {
        "screen": screen,
        "properties": properties
    };
}

ScreenManager.prototype.clear = function () {
    if (this._currentScreen) {
        this._currentScreen.free();
        this._currentScreen = null;
        this._currentScreenName = null;
    }
}

ScreenManager.prototype.refreshScreen = function () {
    if (this._currentScreen) {
        var screen = this._currentScreenName;
        this.clear();
        this.setScreen(screen, true);
    }
}

ScreenManager.prototype._isScreenAdded = function (name) {
    for(var n in this._screens) {
        if(n === name) {
            return true;
        }
    }

    return false;
}

ScreenManager.prototype.setScreen = function (name, isRefreshed) {
    "use strict";

    name = name || this._defaultScreenName;

    if(!this._isScreenAdded(name)) {
        return;
    }

    if (this._currentScreen) {
        this.clear();
    }

    if(!isRefreshed) {
//        MessyAnalytics.screenChange(name);
    }

    var screenData = this._screens[name];
    var screenDefaultProperties = screenData.properties;
    screenData.properties["isRefreshed"] = isRefreshed;

    var screenConstructor = screenData.screen;
    this._currentScreenName = name;
    this._currentScreen = new screenConstructor(screenDefaultProperties);

    this._currentScreen.show();

    EventSystem.Global.dispatchEvent(UI_Event.SCREEN_ACTIVATED, this._currentScreenName);
    return screen;
}

ScreenManager.prototype.getCurrentScreen = function () {
    return this._currentScreenName;
}
