// *********************************
// CoolGames Builder JavaScript file
// *********************************

var MigrateSaveDataToVersionOne = (function () {

    var _MigrateSaveDataToVersionOne = function () {};

    _MigrateSaveDataToVersionOne.prototype.migrate = function () {

        var self = this;

        return new Promise(function (resolve, reject) {

            if (gameData.saveFileVersion >= 1) {
                resolve();
                return;
            }

            var migrationComplete = function () {
                gameData.saveFileVersion = 1;
                saveDataService.savePlayerData(gameData.getSaveableGameData());
                resolve();
            }

            FBInstant.player.getDataAsync(["saveState"])
                .then(function (data) {
                    if (!data || !data["saveState"]) {
                        migrationComplete();
                        return;
                    }

                    var oldSaveData = self._parseOldSaveData(data);

                    Promise.all([
                            self._migrateCalendarData(oldSaveData),
                            self._migrateGameData(oldSaveData),
                        ])
                        .then(migrationComplete)
                        .catch(reject);
                });
        });
    };

    _MigrateSaveDataToVersionOne.prototype._parseOldSaveData = function (data) {

        //BRRWWWWAAAAAAAp. https://inception.davepedu.com/
        var inceptionLevelOne = JSON.parse(data["saveState"]);
        var inceptionLevelTwo = JSON.parse(inceptionLevelOne);
        var inceptionLevelThree = JSON.parse(inceptionLevelTwo.data);

        return inceptionLevelThree;
    }

    _MigrateSaveDataToVersionOne.prototype._migrateCalendarData = function (oldSaveData) {

        var preparedData = this._prepareForConversion(oldSaveData);
        var convertedData = this._convertSaveData(preparedData);
        var saveableSaveData = this._appendScoreDataToSaveData(convertedData);

        return saveDataService.savePlayerData(saveableSaveData);
    };

    /**
     * This function prepares the savedata for conversion by:
     * - Removing redundant data
     * - Grouping the data under months
     * - Appends the date to get rid of levelIndex
     */
    _MigrateSaveDataToVersionOne.prototype._prepareForConversion = function (saveData) {

        var dataToSave = {};

        for (var key in saveData) {
            if (saveData.hasOwnProperty(key) && !isNaN(parseInt(key))) {

                var oldDayData = saveData[key];
                var levelIndex = parseInt(key);
                var date = this._getDateByLevel(levelIndex);

                if (oldDayData.unlocked === true) {

                    var monthDataId = date.getFullYear() + "_" + date.getMonth();
                    if (!dataToSave[monthDataId]) {
                        dataToSave[monthDataId] = [];
                    }

                    //Append date so we can get rid of the levelIndex alltogether
                    oldDayData.date = date;
                    dataToSave[monthDataId].push(oldDayData);
                }
            }
        };

        return dataToSave;
    };

    _MigrateSaveDataToVersionOne.prototype._convertSaveData = function (dataToMigrate) {

        var saveData = [];

        for (var monthId in dataToMigrate) {
            if (dataToMigrate.hasOwnProperty(monthId)) {

                var monthData = new MonthlyUnlockData(monthId);
                UnlockDataManager.levelData[monthId] = monthData;

                var monthDataToMigrate = dataToMigrate[monthId];

                for (var i = 0; i < monthDataToMigrate.length; i++) {

                    var oldDayData = monthDataToMigrate[i];
                    var dayDataId = monthId + "_" + oldDayData.date.getDate();

                    var skipSaving = true;
                    var dayData = monthData.unlockDailyDataById(dayDataId, {}, skipSaving);

                    for (var difficulty = 0; difficulty < 3; difficulty++) {
                        var scorePerDifficutly = oldDayData[difficulty];
                        dayData.setScoreByDifficulty(difficulty, scorePerDifficutly.points);
                    }
                }

                saveData.push(monthData.getSaveableData());
            }
        }
        
        return saveData;
    };

    _MigrateSaveDataToVersionOne.prototype._appendScoreDataToSaveData = function (saveData) {

        var monthScores = [];

        for (var key in saveData) {
            if (saveData.hasOwnProperty(key)) {
                var monthSaveData = saveData[key];
                var scoreData = monthSaveData.data.getMonthScore();
                monthScores.push({
                    id: monthSaveData.identifier,
                    score: scoreData.score,
                    vipScore: scoreData.vipScore
                })
            }
        }

        saveData.push({
            identifier: "score",
            data: {
                monthScores: monthScores
            }
        })

        return saveData;
    };

    _MigrateSaveDataToVersionOne.prototype._migrateGameData = function (saveData) {

        return new Promise(function (resolve, reject) {
            gameData.veryFirstGamebotMessageScheduled = saveData.VeryFirstMessageScheduled;
            gameData.isAudioMuted = saveData.dailySudokuMuted == "muted";
            gameData.globalHintCounter = saveData.globalHintCount;
            gameData.lastVersionSeenMajor = saveData.lastSeenVersionMajor;
            gameData.lastVersionSeenMinor = saveData.lastSeenVersionMinor;
            gameData.preferredControls = saveData.preferredControls;
            gameData.queuedHints = saveData.queuedHints;
            gameData.redeemedGifts = saveData.redeemedGifts;
            gameData.scoreMultiplier = saveData.scoreMultiplier;

            saveDataService.savePlayerData(gameData.getSaveableGameData())
                .then(resolve)
                .catch(reject);
        });
    };

    _MigrateSaveDataToVersionOne.prototype._getDateByLevel = function (level) {

        var firstDayInMS = new Date(2016, 0, 0).getTime(); // Level 1
        var dateOffset = level * 24 * 60 * 60 * 1000; // One level per day, in ms

        return new Date(firstDayInMS + dateOffset);
    };

    return new _MigrateSaveDataToVersionOne();
}());
