//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

var MigrateHintsToConsumables = (function () {

    var _MigrateHintsToConsumables = function () {};

    _MigrateHintsToConsumables.prototype.migrate = function () {

        return new Promise(function (resolve, reject) {
            if (gameData.saveFileVersion >= 2) {
                resolve();
                return;
            }

            // var hintInventoryItem = Consumables.get(ConsumableSettings.ENUM.HINT).getInventoryItem();
            var hintInventoryItem = null;
            for (var indexKey in gameData.consumableInventory) {
                var inventoryItem = gameData.consumableInventory[indexKey];
                if (inventoryItem.id === ConsumableSettings.ENUM.HINT) {
                    hintInventoryItem = inventoryItem;
                }
            }
            
            if (gameData.globalHintCounter > 0) {
                hintInventoryItem.quantity += gameData.globalHintCounter
            }
            if (gameData.globalHintCount > 0) {
                hintInventoryItem.quantity += gameData.globalHintCount
            }

            gameData.saveFileVersion = 2;
            saveDataService.savePlayerData(gameData.getSaveableGameData());
            resolve();
        });
    };


    return new _MigrateHintsToConsumables();
}());
