var LevelMistakeManager = function ( maxMistakes ) {
    this._maxMistakes = maxMistakes;
    this._mistakes = 0;
}
 
LevelMistakeManager.prototype.configureEvents = function (startEvent, stopEvent, mistakeChangeEvent) {
    this._eventActions = new EventSystem.EventActions(this);
    this._startEvent = 	this._eventActions.add(startEvent, this.start);
    this._eventActions.add(stopEvent, this.stop);
    this._eventActions.add(mistakeChangeEvent, this.setMistakes);
    this._eventActions.add(Level_Event.WRONG_NUMBER_PLACED, this.onMistakeMade);
}

LevelMistakeManager.prototype.start = function () {
    this._mistakes = 0;
    this._eventActions.activateAll();
}

LevelMistakeManager.prototype.onMistakeMade = function () {
    this.setMistakes(this._mistakes + 1);
    if (this.getMistakesLeft() <= 0) {
        EventSystem.Global.dispatchEvent(Fail_Condition_Event.NO_MISTAKES_LEFT, this);
    }
}

LevelMistakeManager.prototype.getMistakesLeft = function () {
    return this._maxMistakes - this._mistakes;
}

LevelMistakeManager.prototype.setMistakesLeft = function (mistakesLeft) {
    this.setMistakes(this._maxMistakes - mistakesLeft);
}

LevelMistakeManager.prototype.getMistakes = function () {
    return this._mistakes;
}

LevelMistakeManager.prototype.setMistakes = function (mistakes) {
    this._mistakes = mistakes;
    if(this._mistakes > this._maxMistakes){
        this._mistakes = this._maxMistakes;
    }
    sudokuField.saveState();
    EventSystem.Global.dispatchEvent(Fail_Condition_Event.MISTAKES_LEFT_CHANGE, this);
}

LevelMistakeManager.prototype.stop = function () {
    this._mistakes = 0;
    this._eventActions.deactivateAll();
    this._startEvent.activate();
}
