//******************************************************
//*****    Script Resource: Consumable
//******************************************************

/**
 * Constructor the for the Consumable class
 * @param {number} usesLeft 
 * @param {object} info 
 */
var Consumable = function (usesLeft, info) {
    this._name = info.name;
    this._description = info.description;
    this._id = info.id;
    this._usesLeft = usesLeft;
    this._icons = info.icons;
    this._duration = info.duration;
    this._type = info.type;
    this._analyticsKey = info.analyticsKey;
    this._settings = ConsumableSettings.settings[info.id] || {};

    this._activationTimer = null;
    this._eventActions = null;

    this.onActivationStart = new EventSystem.Local();
    this.onActivatedTimerChanged = new EventSystem.Local();
    this.onActivationEnd = new EventSystem.Local();
    this.onActivationRejected = new EventSystem.Local();

    if (info.pauseTimerEvents || info.resumeTimerEvents || info.removeTimerEvents) {

        this._eventActions = new EventSystem.EventActions(this);

        if (info.pauseTimerEvents) {
            this._configureTimerEvents(info.pauseTimerEvents, this._pauseTimer);
        }
        if (info.resumeTimerEvents) {
            this._configureTimerEvents(info.resumeTimerEvents, this._resumeTimer);
        }
        if (info.removeTimerEvents) {
            this._configureTimerEvents(info.removeTimerEvents, this._removeTimer);
        }
    }

    var self = this;
    this.onActivationEnd.listen(function () {
        self._removeTimer();
        EventSystem.Global.dispatchEvent(Consumable_Event.CONSUMABLE_ACTIVATION_END, self);
    });
}

Consumable.prototype._configureTimerEvents = function (events, boundFunction) {
    for (var i = 0; i < events.length; i++) {
        this._eventActions.add(events[i], boundFunction);
    }
}

Consumable.prototype.consume = function () {
    
    if (this.canConsume()) {
        this.setRemainingUses(this.getRemainingUses() - 1);
        this.getInventoryItem().quantity--;
        saveDataService.savePlayerData(gameData.getSaveableGameData());

        EventSystem.Global.dispatchEvent(Consumable_Event.CONSUMABLE_ACTIVATION_START, this._id);
        if (this._duration > 0) {
            this._startTimer();
        } else {
            this.onActivationStart.trigger();
        }
    } else {
        this.onActivationRejected.trigger();
        console.error("Can't consume consumable " + this._id);
    }
}

Consumable.prototype.canConsume = function () {
    return !this._activationTimer && this._usesLeft > 0;
}

Consumable.prototype._startTimer = function () {
    var self = this;
    this._activationTimer = new TimeUtil.Timer(new TimeUtil.TimerSettings(
        self.onActivationStart,
        self.onActivationEnd,
        self.onActivatedTimerChanged,
        tgfSettings.game.consumables.timerChangedInterval,
        self._duration
    ));
}

Consumable.prototype._pauseTimer = function () {
    if (this._activationTimer) {
        this._activationTimer.pause();
    }
}

Consumable.prototype._resumeTimer = function () {
    if (this._activationTimer) {
        this._activationTimer.resume();
    }
}

Consumable.prototype._removeTimer = function () {
    if (this._activationTimer) {
        this._pauseTimer();
        this._activationTimer = null;
    }
}

Consumable.prototype.getRemainingUses = function () {
    return this._usesLeft;
}

Consumable.prototype.getInventoryItem = function () {

    for (var indexKey in gameData.consumableInventory) {
        var inventoryItem = gameData.consumableInventory[indexKey];
        if (inventoryItem.id === this._id) {
            return inventoryItem;
        }
    }
}

Consumable.prototype.setRemainingUses = function (uses) {
    if (typeof uses !== "number") {
        throw new Error("Can't set remaining uses for consumable " + this._name);
    }

    this._usesLeft = uses;
    EventSystem.Global.dispatchEvent(Consumable_Event.CONSUMABLE_INVENTORY_CHANGE);
}

Consumable.prototype.getName = function () {
    return this._name;
}

Consumable.prototype.getDescription = function () {
    return this._description;
}

Consumable.prototype.getIcons = function () {
    return this._icons;
}

Consumable.prototype.getType = function () {
    return this._type;
}

Consumable.prototype.getId = function () {
    return this._id;
}

Consumable.prototype.getDuration = function () {
    return this._duration;
}

Consumable.prototype.getActivationTimer = function () {
    if (this._activationTimer) {
        return this._activationTimer;
    } else {
        console.warn("[Consumable] No activation timer active for this consumable (" + this.getId() + ")");
    }
}

Consumable.prototype.getSettings = function () {
    return this._settings;
}

Consumable.prototype.getAnalyticsKey = function () {
    return this._analyticsKey;
}
//******************************************************
//*****    Script Resource: Consumables
//******************************************************

var Consumables = ConsumableSettings;
Consumables._list = {};
Consumables._isInitialized = false;

Consumables.initialize = function () {
    return new Promise(function (resolve, reject) {
        if (!Consumables._isInitialized) {
            ConsumableEffects.initialize();
            var consumableCollection = {};
            for (var consumableIndex in Consumables.DATA) {
                var consumableData = Consumables.DATA[consumableIndex];
                consumableData.description = tgfDictionary.getText(consumableData.dictionaryKeys.description);
                consumableData.name = tgfDictionary.getText(consumableData.dictionaryKeys.name);
                var consumable = new Consumable(0, consumableData);
                consumableCollection[consumableIndex] = consumable;
            }

            Consumables._list = consumableCollection;
            EventSystem.Global.addEventListener(UI_Event.USED_CONSUMABLE, Consumables._consume, this);
            EventSystem.Global.addEventListener(UI_Event.BUY_CONSUMABLE, Consumables._purchase, this);
            Consumables._isInitialized = true;
            for (var consumableKey in gameData.consumableInventory) {
                var inventoryItem = gameData.consumableInventory[consumableKey];
                if (inventoryItem) {
                    var consumable = Consumables.get(inventoryItem.id);
                    var inventoryQuantity = inventoryItem.quantity;
                    if (consumable) {
                        consumable.setRemainingUses(inventoryQuantity);
                    }
                }
            }
            resolve();
        } else {
            reject("[Consumables] Already Initialized!");
        }
    });
}

Consumables.get = function (id) {
    Consumables._checkInitialization();
    var consumable = Consumables._list[id];
    if (consumable) {
        return consumable;
    }
}

Consumables.getByType = function (type) {
    Consumables._checkInitialization();
    var typedConsumables = {};
    for (var index in Consumables._list) {
        var consumable = Consumables._list[index];
        if (type === consumable.getType()) {
            typedConsumables[index] = consumable;
        }
    }
    return typedConsumables;
}

Consumables._checkInitialization = function () {
    if (!Consumables._isInitialized) {
        throw new Error("[Consumables] Not Initialized!");
    }
}

Consumables._purchase = function (id) {
    Consumables._checkInitialization();
    var consumable = Consumables.get(id);
    if (consumable) {

        if(id === ConsumableSettings.ENUM.HINT) {
            SudokuAnalytics.reportRewardHintsButtonClicked();
        }

        ConsumableReplenishSystem.replenishConsumable(consumable)
            .then(function () {
                EventSystem.Global.dispatchEvent(UI_Event.EXTERNAL_DIALOG_CLOSED);
            });
    }
}

Consumables._consume = function (id) {
    Consumables._checkInitialization();
    var consumable = Consumables.get(id);
    if (consumable) {
        if (consumable.canConsume()) {
            consumable.consume();
        }
    }
}
