tgfDialogs.InGameConsumeDialog.prototype.startAnimation = function () {
	"use strict";
	this.startAnim = true;
	this.time = 0;
};

tgfDialogs.InGameConsumeDialog.prototype.doPrepare = function () {
	"use strict";
	tgfDialogs.InGameConsumeDialog.uber.doPrepare.call(this);
	this._createPopup();
};

tgfDialogs.InGameConsumeDialog.prototype.show = function (consumable) {
	tgfDialogs.InGameConsumeDialog.uber.show.call(this);
	var headerText = this.unlockHeader.text;
	var descriptionText = this.unlockDescription.text;
	if (consumable) {
		headerText = consumable.getName();
		descriptionText = consumable.getDescription();
		this._consumable = consumable;
		this.consumableImage.image = consumable.getIcons().popup;

		this.useConsumableButton.icon = consumable.getIcons().button;
		this.useConsumableButton.iconTextDistance = -consumable.getIcons().button.width;

		this._updateInventoryChange();
	} else {
		throw new Error("Consumable is not present");
	}

	this.unlockHeader.text = headerText;
	this.unlockHeader.recreate();

	this.unlockDescription.text = descriptionText;
	this.unlockDescription.recreate();
	EventSystem.Global.addEventListener(Consumable_Event.CONSUMABLE_INVENTORY_CHANGE, this._updateInventoryChange, this);
}

tgfDialogs.InGameConsumeDialog.prototype._updateInventoryChange = function () {
	var remainingUses = this._consumable.getRemainingUses();
	this.buyConsumableButton.free();
	this.useConsumableButton.free();

	this.mode = tgfDialogs.InGameConsumeDialog.MODES.BUY;

	this.consumableUsageLabel.text = remainingUses.toString();
	this.consumableUsageLabel.recreate();

	this.remainingUsagesLabelBg.width = (this.consumableUsageLabel.textSurface.width / 2) + 20;

	if (remainingUses > 0) {
		this.mode = tgfDialogs.InGameConsumeDialog.MODES.CONSUME;
	}

	switch (this.mode) {
		case tgfDialogs.InGameConsumeDialog.MODES.BUY:
			this.buyConsumableButton.show();
			this.buyConsumableButton.activate();
			break;
		case tgfDialogs.InGameConsumeDialog.MODES.CONSUME:
			this.useConsumableButton.show();
			this.useConsumableButton.activate();
			break;
	}
}

tgfDialogs.InGameConsumeDialog.prototype.handleTouchDown = function (finger, x, y) {
	"use strict";
	tgfDialogs.InGameConsumeDialog.uber.handleTouchDown.call(this, finger, x, y);
	return true; // This makes sure we can't click something in the background
};

tgfDialogs.InGameConsumeDialog.prototype.handleTouchUp = function (finger, x, y) {
	"use strict";
	tgfDialogs.InGameConsumeDialog.uber.handleTouchUp.call(this, finger, x, y);
	return true; // This makes sure we can't click something in the background
};
