var HintSystem = function (deactivateEvents) {

    this._consumable = Consumables.get(Consumables.ENUM.HINT);

    this._consumable.onActivationStart.listen(this._handleActivationStart, this);

    this._eventActions = new EventSystem.EventActions(this);
    for (var i = 0; i < deactivateEvents.length; i++) {
        this._eventActions.add(deactivateEvents[i], this._remove);
    }

    this._eventActions.add(System_Event.AWARD_HINT_OPPORTUNITY, this._awardQueuedHints);
};

HintSystem.prototype._handleActivationStart = function () {

//    MessyAnalytics.hintsButtonClicked();

    SudokuAnalytics.reportUseHint();

    var openCells = this._getOpenCells();
    var index = Math.floor(Math.random() * openCells.length);
    var targetCell = openCells[index];
    sudokuField.place(targetCell.x, targetCell.y, targetCell.value, true);
    sudokuInterface.endGame();
    sudokuDraw.animationStartFly(
        targetCell.x,
        targetCell.y,
        tgfSettings.consumables.viewSettings.activationEffectSpawnPoint.x,
        tgfSettings.consumables.viewSettings.activationEffectSpawnPoint.y,
        0.6
    );
};

HintSystem.prototype._getOpenCells = function () {
    var cells = sudokuField.getFieldPart(0, 0, 9, 9);
    var amountOfCells = cells.length;
    for (var i = amountOfCells - 1; i >= 0; i--) {
        var currentCell = cells[i];

        if (currentCell.current == currentCell.value) {
            cells.splice(i, 1);
        }
    }
    return cells;
}

HintSystem.prototype._remove = function () {
    this._eventActions.deactivateAll();
    this._consumable.onActivationStart.stopListening(this._handleActivationStart, this);
};

HintSystem.prototype._awardQueuedHints = function () {
    ConsumableReplenishSystem.replenishQueuedConsumable(this._consumable);
};
//******************************************************
//*****    Script Resource: MultiHintSystem
//******************************************************

var MultiHintSystem = function (deactivateEvents) {
	this._consumable = Consumables.get(Consumables.ENUM.MAGIC_LAMP);

	this._consumable.onActivationStart.listen(this._handleActivationStart, this);
	this._queuedHintPlacements = [];

	this._eventActions = new EventSystem.EventActions(this);
	for (var i = 0; i < deactivateEvents.length; i++) {
		this._eventActions.add(deactivateEvents[i], this._remove);
	}
};

MultiHintSystem.prototype._handleActivationStart = function () {
	var cellsToOpen = [];
	for (var i = 0; i < 3; i++) {
		for (var j = 0; j < 3; j++) {
			var openCells = this._getOpenCellsForBlock(i, j);
			if (openCells.length == 0) continue;

			var index = Math.floor(Math.random() * openCells.length);
			var targetCell = openCells[index];

			cellsToOpen.push(targetCell);
		}
	}

	var effectSettings = this._consumable.getSettings().effects;
	
	for (var i = 0; i < cellsToOpen.length; i++) {
		var targetCell = cellsToOpen[i];
		var spawnDelay = effectSettings.spawnDelay * i;
		this._queuedHintPlacements[i] = this._delayHintPlacement(effectSettings.delay, spawnDelay, targetCell.x, targetCell.y, targetCell.value);
	}
};

MultiHintSystem.prototype._delayHintPlacement = function (initialDelay, spawnDelay, x, y, value) {
	var self = this;
	return setTimeout(function () {
		self._queuedHintPlacements.shift();
		sudokuField.place(x, y, value, false);
		sudokuInterface.endGame();
		sudokuDraw.animationStartFly(x, y, tgfSettings.consumables.viewSettings.activationEffectSpawnPoint.x, tgfSettings.consumables.viewSettings.activationEffectSpawnPoint.y);
	}, initialDelay + spawnDelay);
}

MultiHintSystem.prototype._getOpenCellsForBlock = function (x, y) {
	var cells = sudokuField.getBlock(x, y);
	var amountOfCells = cells.length;
	for (var i = amountOfCells - 1; i >= 0; i--) {
		var currentCell = cells[i];

		if (currentCell.current == currentCell.value) {
			cells.splice(i, 1);
		}
	}
	return cells;
}

MultiHintSystem.prototype._remove = function () {
	this._eventActions.deactivateAll();

	for (var i = 0; i < this._queuedHintPlacements.length; i++) {
		clearTimeout(this._queuedHintPlacements[i]);
	}

	this._consumable.onActivationStart.stopListening(this._handleActivationStart, this);

	this._consumable = null;
};
