//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

var ConsumableUnlockMethod = function (consumable) {
    this._resolveFunction = null;
    this._targetConsumable = Consumables.get(consumable);
    
    this._targetConsumable.onActivationStart.listen(this._consumableActivated, this);
    this._targetConsumable.onActivationRejected.listen(this._consumableActivationRejected, this);
};

ConsumableUnlockMethod.prototype.unlock = function () {

    var self = this;
    return new Promise(function (resolve, reject) {
        self._resolveFunction = resolve;
        self._rejectFunction = reject;

        EventSystem.Global.dispatchEvent(UI_Event.USED_CONSUMABLE, self._targetConsumable.getId());
    });
}

ConsumableUnlockMethod.prototype._consumableActivated = function () {
    this.stopListening();
    if (this._resolveFunction !== null) {
        this._resolveFunction();
    } else {
        throw new Error("[ConsumableUnlockMethod] target consumable was activated, but no one is listening.")
    }
}

ConsumableUnlockMethod.prototype._consumableActivationRejected = function () {
    this.stopListening();
    if (this._rejectFunction !== null) {
        this._rejectFunction();
    } else {
        throw new Error("[ConsumableUnlockMethod] target consumable was activated, but no one is listening.")
    }
}

ConsumableUnlockMethod.prototype.stopListening = function () {
    
    this._targetConsumable.onActivationStart.stopListening(this._consumableActivated, this);
    this._targetConsumable.onActivationRejected.stopListening(this._consumableActivationRejected, this);
}
