//*****    Script Resource: ConsumableEffects
//******************************************************

var ConsumableEffects = {
    _dialogs: {},
    _isInitialized: false
}

ConsumableEffects.initialize = function () {
    if (!ConsumableEffects._isInitialized) {
        ConsumableEffects._dialogs[Consumables.ENUM.HINT] = new tgfDialogs.EffectHintDialog;
        ConsumableEffects._dialogs[Consumables.ENUM.MAGIC_EYE] = new tgfDialogs.EffectMagicEyeDialog;
        ConsumableEffects._dialogs[Consumables.ENUM.MAGIC_LAMP] = new tgfDialogs.EffectMagicLampDialog;
        ConsumableEffects._dialogs[Consumables.ENUM.FREEZE] = new tgfDialogs.EffectFreezeDialog;
        ConsumableEffects._dialogs[Consumables.ENUM.REPLENISH_LIVES] = new tgfDialogs.EffectReplenishLives;
        ConsumableEffects._isInitialized = true;

        EventSystem.Global.addEventListener(Consumable_Event.CONSUMABLE_ACTIVATION_START, ConsumableEffects._show, this);

        EventSystem.Global.addEventListener(System_Event.LEVEL_END, ConsumableEffects._hideAll, this);
        EventSystem.Global.addEventListener(System_Event.LEVEL_QUIT, ConsumableEffects._hideAll, this);
    }
}

ConsumableEffects._show = function (id) {
    if (ConsumableEffects._isInitialized) {
        var effectView = ConsumableEffects._dialogs[id];
        if (effectView) {
            console.log("[Consumable Effects] Effect started!");
            effectView.free();
            effectView.show();
        } else {
            EventSystem.Global.dispatchEvent(Consumable_Event.CONSUMABLE_ACTIVATION_END, this);
        }
    }
}

ConsumableEffects._hideAll = function () {

    for (var key in ConsumableEffects._dialogs) {
        if (ConsumableEffects._dialogs.hasOwnProperty(key)) {
            var dialog = ConsumableEffects._dialogs[key];
            dialog.free();
        }
    }
}
