tgfSettings.dialogDefaults.effectReplenishLives = {
	width: 626,
	height: 312,
	depth: -10,
	_lifeTarget: {
		x: 285,
		y: 38
	},
	_livesAnimated:0
};

tgfDialogs.EffectReplenishLives = function (properties) {
	"use strict";
	this.name = "EffectReplenishLives";
	this.initialize({});
	this.setProperties(tgfSettings.dialogDefaults.effectReplenishLives);

	if (properties !== undefined) {
		this.setProperties(properties);
	}
};

tgfDialogs.inherit(tgfDialogs.EffectReplenishLives, tgfDialogs.Base);

tgfDialogs.EffectReplenishLives.prototype.doPrepare = function () {
	"use strict";

	var self = this;

	this._activationEffectAnimation = new tgfComponents.ConsumableActivationEffectAnimation(
		new ConsumableActivationEffectAnimationSettings(
			pu_lives_appear,
			pu_lives_disappear,
			2000
		)
	);

	var lifeEffect = {
		effect: tgfEffects.transform,
		duration: 0.2,
		startX: tgfScale(this._activationEffectAnimation.x),
		startY: tgfScale(this._activationEffectAnimation.y),
		endX: tgfScale(this._lifeTarget.x),
		endY: tgfScale(this._lifeTarget.y),
		startScale: 1,
		endScale: 0.1,
	};

	this._life = new tgfComponents.Picture({
		image: s_icon_powerup_live,
		height: s_icon_powerup_live.height * 0.85,
		width: s_icon_powerup_live.height * 0.85,
		effects: [lifeEffect],
		onEffectStart: function () {
			EventSystem.Global.dispatchEvent(UI_Event.LIFE_SPAWNED);
		},
		onEffectEnd: function () {

			//Set alpha to 0 next frame.
			setTimeout(function () {
				self._life.alpha = 0;
			}, 0);

			EventSystem.Global.dispatchEvent(UI_Event.LIFE_ARRIVED);
		},
		repeatEffect: tgfSettings.game.loseConditions.maxMistakesAllowed
	});
	
	this._activationEffectAnimation.onHideAnimationComplete.listen(this._onHideAnimationComplete, this);
	this.addComponent(this._activationEffectAnimation);
	this.addComponent(this._life);
};

tgfDialogs.EffectReplenishLives.prototype._onHideAnimationComplete = function () {
	"use strict";
	this._activationEffectAnimation.free();
};

tgfDialogs.EffectReplenishLives.prototype.doFree = function () {

	this._activationEffectAnimation.onHideAnimationComplete.stopListening(this._onHideAnimationComplete, this);
	this._activationEffectAnimation = null;
	this._life = null;
	this.removeAllComponents();
};
