var InGameUIController = function () {

    this.topUI = new tgfDialogs.InGameTopUI({
        width: tgfGraphics.visibleWidth,
        height: 60
    });

    var leftOffset = tgfScale(110);
    var rightOffset = tgfScale(0);

    this.bottomUI = new tgfDialogs.InGameBottomUI({
        width: tgfGraphics.visibleWidth - leftOffset - rightOffset,
        x: leftOffset,
        y: tgfGraphics.visibleHeight - tgfScale(135)
    });

/*    if(ABTestInstance.isFeatureSupported(tgfSettings.abtest.features.ONBOARDING)){
        this.howToPlayButton = new tgfDialogs.HowToPlayButton({});
    }*/

    this._inGameConsumableDialog = null;
    this._eventActions = new EventSystem.EventActions(this);
}

InGameUIController.prototype.show = function () {

    this.topUI.show();

    this.bottomUI.y = tgfGraphics.visibleHeight - tgfScale(135);
    this.bottomUI.show();

/*    if(ABTestInstance.isFeatureSupported(tgfSettings.abtest.features.ONBOARDING)){
        this.howToPlayButton.show();
    }*/

    this._activateUI();
}

InGameUIController.prototype.hide = function () {
    this.topUI.free();
    this.topUI = null;

    this.bottomUI.free();
    this.bottomUI = null;

/*    if(ABTestInstance.isFeatureSupported(tgfSettings.abtest.features.ONBOARDING)){
        this.howToPlayButton.free();
        this.howToPlayButton = null;
    }*/

    this._eventActions.deactivateAll();

    if (this._inGameConsumableDialog) {
        this._inGameConsumableDialog.free();
        this._inGameConsumableDialog = null;
    }
}

InGameUIController.prototype.configureDeactivationEvents = function (deactivationEvents) {
    for (var i = 0; i < deactivationEvents.length; i++) {
        this._eventActions.add(deactivationEvents[i], this._deactivateUI);
    }
}

InGameUIController.prototype._activateUI = function () {
    this.topUI.activate();
    this.bottomUI.activate();
/*    if(ABTestInstance.isFeatureSupported(tgfSettings.abtest.features.ONBOARDING)){
        this.howToPlayButton.activate();
    }*/
    EventSystem.Global.addEventListener(UI_Event.SETTINGS_BUTTON_CLICKED, this._openSettingsPopup, this);
}

InGameUIController.prototype._deactivateUI = function () {
    this.topUI.deactivate();
    this.bottomUI.deactivate();
/*    if(ABTestInstance.isFeatureSupported(tgfSettings.abtest.features.ONBOARDING)){
        this.howToPlayButton.deactivate();
    }*/
    EventSystem.Global.removeEventListener(UI_Event.SETTINGS_BUTTON_CLICKED, this._openSettingsPopup, this);
}

InGameUIController.prototype._openSettingsPopup = function () {
    this._settingsPopup = new tgfDialogs.SettingsDialog({
        y: tgfGraphics.visibleHeight/2
    });
    this._settingsPopup.show();
}

InGameUIController.prototype.addInGameConsumableDialog = function () {
    this._inGameConsumableDialog = new tgfDialogs.InGameConsumeDialog();

    this._eventActions.add(System_Event.PRE_GAMEOVER, this._triggerReplenishLivesPopup);
    this._eventActions.add(System_Event.ACTIVATED_REPLENISH_LIVES, this._onLivesReplenished);
    this._eventActions.add(UI_Event.REQUESTED_CONSUMABLE, this._showInGameConsumable);
}

InGameUIController.prototype._onLivesReplenished = function () {
    this._inGameConsumableDialog.closeButtonClicked.stopListening(this._closedLifeReplenishPopup, this);
}

InGameUIController.prototype._triggerReplenishLivesPopup = function () {
    this._inGameConsumableDialog.closeButtonClicked.listen(this._closedLifeReplenishPopup, this);
    EventSystem.Global.dispatchEvent(UI_Event.REQUESTED_CONSUMABLE, Consumables.get(Consumables.ENUM.REPLENISH_LIVES));
}

InGameUIController.prototype._closedLifeReplenishPopup = function () {
    this._inGameConsumableDialog.closeButtonClicked.stopListening(this._closedLifeReplenishPopup, this);
    EventSystem.Global.dispatchEvent(System_Event.LEVEL_LOST);
}

InGameUIController.prototype._showInGameConsumable = function (consumable) {
    this._inGameConsumableDialog.show(consumable);
}
