var TopUIBarComponentConfiguration = {
	weight: 1,
	height: 60,
	initialValue: null,
	updateValueEvent: null
}

tgfSettings.dialogDefaults.inGameTopUI = {
	backgroundImage: s_ui_game_top_bg,

	mistakesRendererWeight: 1,
	mistakesRendererHeight: 60,
	timeRendererWeight: 2,
	scoreRendererWeight: 2,
	difficultyRendererWeight: 2
};

tgfDialogs.InGameTopUI = function (properties) {
	"use strict";
	this.name = "InGameTopBar";

	this._topBarComponents = [];
	this._totalWeight = 0;

	this.initialize(tgfSettings.dialogDefaults.inGameTopUI);

	// Set user properties
	if (properties !== undefined) {
		this.setProperties(properties);
	}
}

tgfDialogs.inherit(tgfDialogs.InGameTopUI, tgfDialogs.Base);

tgfDialogs.InGameTopUI.prototype._addTopBarComponent = function (component, configuration) {

	if (this.isPrepared) {
		console.error("[InGameTopBar] Don't add components after the topbar is already prepared");
	}

	//Apply configured height to component.
	component.height = configuration.height;

	//Add the configured weight to the total for later calculation.
	this._totalWeight += configuration.weight;

	//Add the component to an array with the weight so we can correlate the two later in the position calculation.
	this._topBarComponents.push({
		component: component,
		configuration: configuration
	});
}

tgfDialogs.InGameTopUI.prototype.onPrepare = function () {

	if (this.backgroundImage) {
		this.background = new tgfComponents.Picture({
			image: this.backgroundImage,
			width: this.backgroundImage.width,
			x: this.x + this.width / 2,
			y: this.y + (this.height / 2) + 6
		});
		this.addComponent(this.background);
	}

	var cumulativeWidth = 0;

	for (var i = 0; i < this._topBarComponents.length; i++) {
		var component = this._topBarComponents[i].component;
		var weight = this._topBarComponents[i].configuration.weight;

		var actualWidth = this.width / (this._totalWeight / weight);

		component.x = cumulativeWidth + (actualWidth / 2);
		component.y = 0;
		component.width = actualWidth;
		this.addComponent(component);

		cumulativeWidth += actualWidth;
	}
}

tgfDialogs.InGameTopUI.prototype.addTimeRenderer = function () {

	var timeRendererSettings = Object.create(TopUIBarComponentConfiguration);
	timeRendererSettings.weight = this.timeRendererWeight;

	var component = new tgfComponents.TimeRenderer();
	component.configureEvents(Level_Event.LEVEL_TIME_CHANGED);
	this._addTopBarComponent(component, timeRendererSettings);
}

tgfDialogs.InGameTopUI.prototype.addScoreRenderer = function (initialValue) {

	var scoreRendererSettings = Object.create(TopUIBarComponentConfiguration);
	scoreRendererSettings.weight = this.scoreRendererWeight;

	var component = new tgfComponents.ScoreRenderer();
	component.configureEvents(Level_Event.LEVEL_SCORE_CHANGED);
	component.initialValue = initialValue;
	this._addTopBarComponent(component, scoreRendererSettings);
}

tgfDialogs.InGameTopUI.prototype.addMistakesRenderer = function (mistakesModel) {

	var mistakesRendererSettings = Object.create(TopUIBarComponentConfiguration);
	mistakesRendererSettings.weight = this.mistakesRendererWeight;
	mistakesRendererSettings.height = this.mistakesRendererHeight;

	var component = new tgfComponents.MistakesLeftRenderer(mistakesModel);
	component.configureEvents(UI_Event.LIFE_ARRIVED, Fail_Condition_Event.MISTAKES_LEFT_CHANGE);

	this._addTopBarComponent(component, mistakesRendererSettings);
}

tgfDialogs.InGameTopUI.prototype.addDateRenderer = function (date) {

	var dateRendererSettings = Object.create(TopUIBarComponentConfiguration);

	var component = new tgfComponents.DateRenderer();
	component.initialValue = date;
	this._addTopBarComponent(component, dateRendererSettings);
}

tgfDialogs.InGameTopUI.prototype.addDifficultyRenderer = function (diffictulty) {

	var difficultyRendererSettings = Object.create(TopUIBarComponentConfiguration);
	difficultyRendererSettings.weight = this.difficultyRendererWeight;

	var component = new tgfComponents.DifficultyRenderer();
	component.initialValue = diffictulty;
	this._addTopBarComponent(component, difficultyRendererSettings);
}

tgfDialogs.InGameTopUI.prototype.addBackButton = function () {
	// 

	var backButtonSettings = Object.create(TopUIBarComponentConfiguration);
	backButtonSettings.weight = this.difficultyRendererWeight;

	var component = new tgfComponents.BackButtonElement();

	this._addTopBarComponent(component, backButtonSettings);
}

tgfDialogs.InGameTopUI.prototype.doShow = function () {

	var targetY = this.y;
	this._animator = new tbAnimator(this);
	this._animatorTrack = this._animator.addTrack("y")

	this._animator.addKey(this._animatorTrack, 0, -100, tbEase.easeOutCircular);
	this._animator.addKey(this._animatorTrack, 1300, -100, tbEase.easeOutCircular);
	this._animator.addKey(this._animatorTrack, 1700, targetY);
}

tgfDialogs.InGameTopUI.prototype.handleBeginStep = function (timePassed) {
	this._animator.updateTime(timePassed);
}
