// The constructor for the dialog
/**
 * @constructor
 * @base tgfDialogs.Base
 */
tgfComponents.DateRenderer = function (properties) {
    "use strict";
    this.initialize(tgfSettings.dialogDefaults.dateRenderer);

    // Set user properties
    if (properties !== undefined) {
        this.setProperties(properties);
    }
};

// Inherit the base dialog
tgfComponents.inherit(tgfComponents.DateRenderer, tgfComponents.Base);

// Processing required when preparing the dialog for use
tgfComponents.DateRenderer.prototype.doPrepare = function () {
    "use strict";

    //Align to top;
    this.y += this.height / 2;

    if (this.backgroundImage) {
        this.background = new tgfComponents.Picture({
            image: this.backgroundImage,
            createFromSlices: true,
            width: this.width,
            height: this.height
        });
        this.addComponent(this.background);
    }

    var textValue = "Not Set";

    if (this.initialValue instanceof Date) {

        var dateToRender = this.initialValue;

        if (tgfSettings.theme.gameScreen.dateText.japaneseFormatting) {
            textValue = DateUtil.getMonthLabel(dateToRender.getMonth())  + " " + dateToRender.getDate() + tgfDictionary.getText("DayText");
        } else {
            textValue = DateUtil.getDayLabel(dateToRender.getDay()) + "\n" + dateToRender.getDate() + " " + DateUtil.getMonthLabel(dateToRender.getMonth());
        }
    } else {
        throw new Error("[DateRenderer] Can't render something that is not a date.");
    }
    
    this.dateLabel = new tgfComponents.Label({
        x: tgfScale(10),
        y: tgfScale(0),
        font: this.font,
        splitLines: false,
        text: textValue
    });
    this.dateLabel.font.fillColor = tgfSettings.theme.fontColor.light;
    this.addComponent(this.dateLabel);
};
