// *********************************
// CoolGames Builder JavaScript file
// *********************************


var BottomUIBarComponentConfiguration = {
    weight: 1
}

tgfDialogs.InGameBottomUI = function (properties) {
    "use strict";
    this.name = "InGameTopBar";
    this.initialize(tgfSettings.componentDefaults.base);

    // Set user properties
    if (properties !== undefined) {
        this.setProperties(properties);
    }

    this._totalWeight = 0;
    this._bottomBarComponents = [];
}

tgfDialogs.inherit(tgfDialogs.InGameBottomUI, tgfDialogs.Base);

tgfDialogs.InGameBottomUI.prototype._addBottomBarComponent = function (component, configuration) {

    if (this.isPrepared) {
        console.error("[InGameTopBar] Don't add components after the topbar is already prepared");
    }

    //Add the configured weight to the total for later calculation.
    this._totalWeight += configuration.weight;

    //Add the component to an array with the weight so we can correlate the two later in the position calculation.
    this._bottomBarComponents.push({
        component: component,
        configuration: configuration
    });
}

tgfDialogs.InGameBottomUI.prototype.onPrepare = function () {

    var cumulativeWidth = 0;

    for (var i = 0; i < this._bottomBarComponents.length; i++) {

        var component = this._bottomBarComponents[i].component;
        var weight = this._bottomBarComponents[i].configuration.weight;

        var actualWidth = this.width / (this._totalWeight / weight);

        component.x = cumulativeWidth + (actualWidth / 2);
        component.width = actualWidth;

        this.addComponent(component);

        cumulativeWidth += actualWidth;
    }
}

tgfDialogs.InGameBottomUI.prototype.addConsumablesBar = function () {

    var component = new tgfComponents.ConsumablesBar({
        y: -13
    });
    var consumablesBarSettings = Object.create(BottomUIBarComponentConfiguration);
    consumablesBarSettings.weight = 1;
    this._addBottomBarComponent(component, consumablesBarSettings);

    return component;
};

tgfDialogs.InGameBottomUI.prototype.addGetMoreHints = function () {

    var componentContainer = new tgfComponents.Base({
        y: -8
    });

    var component = new tgfComponents.Button({
        image: s_btn_hint_add,
        x: 9,
        onClick: function () {
            //down here is a nest of callbacks. It seems to just give the consumable though?
            BoosterSDK.showRewarded(function () {
                EventSystem.Global.dispatchEvent(UI_Event.BUY_CONSUMABLE, ConsumableSettings.ENUM.HINT);
            });
        },
        offsetYDown: 5,
        splitLines: true,
        width: 300,
        height: s_btn_hint_add.height,
        marginLeft: 50,
        text: tgfDictionary.getText("HintsAdButton"),
        fontUp: {
            fontFace: f_main_font.fontFace,
            fontSize: 22,
            fillColor: "#565656",
            baseline: "middle",
            align: "center"
        }
    });

    componentContainer.addComponent(component);

    var getMoreHintsButtonSettings = Object.create(BottomUIBarComponentConfiguration);
    getMoreHintsButtonSettings.weight = 3;

    this._addBottomBarComponent(componentContainer, getMoreHintsButtonSettings);

    return component;
}

tgfDialogs.InGameBottomUI.prototype.addSettingsButton = function () {

    var componentContainer = new tgfComponents.Base({
        y: -8
    });

    var component = new tgfComponents.Button({
        image: s_btn_settings,
        onClick: function () {
            EventSystem.Global.dispatchEvent(UI_Event.SETTINGS_BUTTON_CLICKED);
        }
    });
    componentContainer.addComponent(component);

    var settingsButtonSettings = Object.create(BottomUIBarComponentConfiguration);
    settingsButtonSettings.weight = 1;

    this._addBottomBarComponent(componentContainer, settingsButtonSettings);

    return component;
};

tgfDialogs.InGameBottomUI.prototype.handleBeginStep = function () {
    this.y = tgfGraphics.visibleHeight - 135;
};
//******************************************************
//*****    Script Resource: ConsumablesBar
//******************************************************

tgfComponents.ConsumablesBar = function (properties) {
    "use strict";
    this.initialize(tgfSettings.componentDefaults.Base);

    if (properties !== undefined) {
        this.setProperties(properties);
    }

    this._consumableBarButtons = [];
};

tgfComponents.inherit(tgfComponents.ConsumablesBar, tgfComponents.Base);

tgfComponents.ConsumablesBar.prototype.onPrepare = function () {
    "use strict";

    var amountOfButtons = this._consumableBarButtons.length;
    var deltaPerSlot = this.width / amountOfButtons;
    for (var i = 0; i < amountOfButtons; i++) {
        var current = this._consumableBarButtons[i];
        this.addComponent(current);
        current.x = (deltaPerSlot * i) + (deltaPerSlot / 4) - (this.width/2) + 18;
        current.y = 0;
    }
};

tgfComponents.ConsumablesBar.prototype.configureConsumables = function (consumableIds) {
    "use strict";
    for (var i = 0; i < consumableIds.length; i++) {
        var component = new tgfComponents.ConsumablesBarButton(Consumables.get(consumableIds[i]));
        this._consumableBarButtons.push(component);
    }
};

tgfComponents.ConsumablesBar.prototype.configureDeactivationEvents = function (disableInteractionOnEvents) {
    "use strict";
    this._eventActions = new EventSystem.EventActions(this);
    for (var i = 0; i < disableInteractionOnEvents.length; i++) {
        var event = disableInteractionOnEvents[i];
        this._eventActions.add(event, this._disableInteraction);
    }
};

tgfComponents.ConsumablesBar.prototype._disableInteraction = function () {
    this._eventActions.deactivateAll();

    for (var i = 0; i < this._consumableBarButtons.length; i++) {
        var consumableBarButton = this._consumableBarButtons[i];
        consumableBarButton.disableInteraction();
    }
};

tgfComponents.ConsumablesBar.prototype.doHide = function () {
    "use strict";
    for (var i = 0; i < this._consumableBarButtons.length; i++) {
        var component = this._consumableBarButtons[i];
        if (component.consumableBarButtonClicked) {
            component.consumableBarButtonClicked.stopListening(this._onconsumableBarButtonClicked, this);
        }
    }
};

tgfComponents.ConsumablesBar.prototype.doShow = function () {
    "use strict";
    for (var i = 0; i < this._consumableBarButtons.length; i++) {
        var component = this._consumableBarButtons[i];
        if (component.consumableBarButtonClicked) {
            component.consumableBarButtonClicked.listen(this._onconsumableBarButtonClicked, this);
        }
    }
};

tgfComponents.ConsumablesBar.prototype._onconsumableBarButtonClicked = function (consumable) {
    "use strict";

    if(consumable.getId() === ConsumableSettings.ENUM.HINT && consumable.getRemainingUses() === 0) {
        SudokuAnalytics.reportGetHintsButtonClicked();
        // MessyAnalytics.getHintsButtonClicked();
    }

    EventSystem.Global.dispatchEvent(UI_Event.REQUESTED_CONSUMABLE, consumable);
};
//******************************************************
//*****    Script Resource: ConsumablesBarButton
//******************************************************

tgfComponents.ConsumablesBarButton = function (model) {
    "use strict";
    this.initialize(tgfSettings.componentDefaults.base);

    this._consumable = model;
    this._interactive = true;
    this.consumableBarButtonClicked = new EventSystem.Local();
    this._isListeningToEventTimer = this._consumable.getDuration() > 0;
    if (this._isListeningToEventTimer) {
        this._consumable.onActivatedTimerChanged.listen(this._updateTimeOverlay, this);
        this._consumable.onActivationEnd.listen(this._disableTimeOverlay, this);
        this._consumable.onActivationStart.listen(this._enableTimeOverlay, this);
    }

    EventSystem.Global.addEventListener(Consumable_Event.CONSUMABLE_INVENTORY_CHANGE, this._updateRemainingUses, this);
};

// Inherit the base dialog
tgfComponents.inherit(tgfComponents.ConsumablesBarButton, tgfComponents.Base);

tgfComponents.ConsumablesBarButton.prototype.onPrepare = function () {

    var self = this;
    this._consumableBarButton = new tgfComponents.Button({
        image: s_button_default_gray,
        x: tgfScale(20),
        y: tgfScale(5),
        width: tgfScale(95),
        // height: tgfScale(82),
        onClick: function () {
            if (self._interactive) {
                self.consumableBarButtonClicked.trigger(self._consumable);
            }
        }
    });

    this.addComponent(this._consumableBarButton);

    this._consumableButtonIcon = new tgfComponents.Picture({
        image: this._consumable.getIcons().base,
        x: this._consumableBarButton.x,
        y: this._consumableBarButton.y - 6,
    })

    this.addComponent(this._consumableButtonIcon);

    this._remainingUsesBg = new tgfComponents.Picture({
        image: s_button_hint_amount_green,
        createFromSlices: true,
        x: this._consumableBarButton.x + tgfScale(33),
        y: this._consumableBarButton.y - tgfScale(27),
    })

    this.addComponent(this._remainingUsesBg);

    this._remainingUses = new tgfComponents.Label({
        x: this._remainingUsesBg.x,
        y: this._remainingUsesBg.y + tgfScale(2),
        font: tgfSettings.fonts.consumableAmountIndicatorNumber,
        text: ""
    });
    this.addComponent(this._remainingUses);

    this._overlaytimer = new tgfComponents.Picture({
        image: s_btn_overlay_timer,
        x: this._consumableBarButton.x,
        y: this._consumableBarButton.y,
        alpha: 0
    });
    this.addComponent(this._overlaytimer);

    this._overlaytimerLabel = new tgfComponents.Label({
        x: this._overlaytimer.x,
        y: this._overlaytimer.y,
        font: tgfSettings.fonts.blueButton,
        text: "",
        alpha: 0
    });
    this.addComponent(this._overlaytimerLabel);
    this._updateRemainingUses();
};

tgfComponents.ConsumablesBarButton.prototype._updateRemainingUses = function () {
    var remainingUses = this._consumable.getRemainingUses()
    if (remainingUses <= 0) {
        this._remainingUses.text = remainingUses.toString();
        this._remainingUsesBg.image = s_button_hint_amount_red;
    } else {
        this._remainingUses.text = remainingUses.toString();
        this._remainingUsesBg.image = s_button_hint_amount_green;
    }

    this._remainingUses.recreate();
    this._remainingUsesBg.width = Math.max(35, (this._remainingUses.textSurface.width / 2) + 14);

    this._updateTimeOverlay();
}

tgfComponents.ConsumablesBarButton.prototype._updateTimeOverlay = function () {
    if (this._isListeningToEventTimer) {
        var timer = this._consumable.getActivationTimer();
        if (timer) {
            var remaningMilliseconds = timer.getTimeRemaining();
            if (remaningMilliseconds >= 0) {
                var timeString = StringUtil.milliSecondsToHHMMSS(remaningMilliseconds)
                this._overlaytimerLabel.text = timeString.toString();
                this._overlaytimerLabel.recreate();
            }
        }
    }
}

tgfComponents.ConsumablesBarButton.prototype._enableTimeOverlay = function () {
    this._overlaytimer.alpha = 1;
    this._overlaytimerLabel.alpha = 1;
    this._interactive = false;
    this._overlaytimerLabel.text = StringUtil.milliSecondsToHHMMSS(this._consumable.getDuration());;
    this._overlaytimerLabel.recreate();
    this._updateTimeOverlay();
}

tgfComponents.ConsumablesBarButton.prototype._disableTimeOverlay = function () {
    this._overlaytimer.alpha = 0;
    this._overlaytimerLabel.alpha = 0;
    this._interactive = true;
}

tgfComponents.ConsumablesBarButton.prototype.disableInteraction = function () {
    this._interactive = false;
}

tgfComponents.ConsumablesBarButton.prototype.doHide = function () {
    if (this._isListeningToEventTimer) {
        this._consumable.onActivatedTimerChanged.stopListening(this._updateTimeOverlay, this);
        this._consumable.onActivationEnd.stopListening(this._disableTimeOverlay, this);
        this._consumable.onActivationStart.stopListening(this._enableTimeOverlay, this);
    }
    EventSystem.Global.removeEventListener(Consumable_Event.CONSUMABLE_INVENTORY_CHANGE, this._updateRemainingUses, this);
}
