var ThemeController = (function () {

    var _themes = {};
    var _calendarBackgroundImage = null;
    var _leaderboardBackgroundImage = null;
    var _membershipBackgroundImage = null;

    var _ThemeController = function () {}

    _ThemeController.prototype.initialize = function () {

        var self = this;

        return new Promise(function (resolve, reject) {
            for (var i = 0; i < tgfSettings.themeSettings.themes.length; i++) {
                _themes[tgfSettings.themeSettings.themes[i].id] = new Theme(tgfSettings.themeSettings.themes[i]);
            }

            self._addEventListeners();
            var active = self.getActiveTheme();
            active.loadInGameBgImage();

            if (tgfSettings.themeSettings.backgroundTarget === tgfSettings.themeSettings.backgroundTargets.CANVAS) {
                _calendarBackgroundImage = s_bg_calendar;
            }

            if (tgfSettings.themeSettings.backgroundTarget === tgfSettings.themeSettings.backgroundTargets.CANVAS) {
                _leaderboardBackgroundImage = s_bg_leaderboard;
            }

            if (tgfSettings.themeSettings.backgroundTarget === tgfSettings.themeSettings.backgroundTargets.CANVAS) {
                _membershipBackgroundImage = s_bg_calendar;
            }

            resolve();
        });
    }

    _ThemeController.prototype._addEventListeners = function () {
        EventSystem.Global.addEventListener(Theme_Event.THEME_COLLECTED, this._handleThemeCollection, this);
        EventSystem.Global.addEventListener(Theme_Event.THEME_ACTIVATION_REQUEST, this.setActive, this);
    }

    _ThemeController.prototype.getById = function (id) {

        if (!_themes[id]) {
            throw new Error("[ThemeController] No theme exists for id: " + id + ". The following theme ids have a theme: " + Object.keys(_themes));
        }

        return _themes[id];
    }

    _ThemeController.prototype.getDefault = function () {
        return _themes[tgfSettings.themeSettings.default];
    }

    _ThemeController.prototype.setActive = function (id) {

        var theme = this.getById(id);
        if (theme) {
            gameData.activeThemeId = id;
            saveDataService.savePlayerData(gameData.getSaveableGameData());
            theme.loadInGameBgImage();
            EventSystem.Global.dispatchEvent(Theme_Event.ACTIVE_THEME_CHANGED);
        }
    }

    _ThemeController.prototype.getActiveTheme = function () {
        return this.getById(gameData.activeThemeId);
    }

    _ThemeController.prototype.getCalendarBackgroundImage = function () {
        return _calendarBackgroundImage;
    }

    _ThemeController.prototype.getLeaderboardBackgroundImage = function () {
        return _leaderboardBackgroundImage;
    }

    _ThemeController.prototype.getMembeshipBackgroundImage = function () {
        return _membershipBackgroundImage;
    }

    _ThemeController.prototype._handleThemeCollection = function (theme) {

        EventSystem.Global.dispatchEvent()

        var rarity = RewardController.getByUnlockID(theme.getId()).getRarity();

        this._themeunlockAnimation = new tgfDialogs.ThemeUnlockAnimation({
                depth: -10002,
                x: (tgfGraphics.visibleWidth / 2) - 20,
                y: (tgfGraphics.visibleHeight / 2) - 82
            },
            rarity
        );

        this._themeUnlockPopup = new tgfDialogs.ThemeUnlockPopup(theme);
        this._themeUnlockPopup.onContinueClicked.listen(this._themeUnlockPopupContinueClicked, this);

        this._themeunlockAnimation.show();

        setTimeout(function () {
            this._themeUnlockPopup.show();
        }.bind(this), 2500);
    }

    _ThemeController.prototype._themeUnlockPopupContinueClicked = function () {

        if (this._themeUnlockPopup.getCheckBoxCheckedState() === true) {
            //Activate theme
            this.setActive(this._themeUnlockPopup.getTheme().getId());
        }

        this._themeUnlockPopup.disappear();
    }

    return new _ThemeController();
}());
