var BarModel = function (from, to, current) {
    "use strict";
    this.changeEvent = new EventSystem.Local();
    this.resetEvent = new EventSystem.Local();
    this.reset(from, to, current);
}

BarModel.prototype.getProgressValue = function (progressValue) {
    return this._current;
}

BarModel.prototype.reset = function (from, to, current) {
    this._from = from;
    this._to = to;
    this._current = current;
    this.resetEvent.trigger(this.getPercentageFilled());
}

BarModel.prototype.add = function (amount) {
    this._current += amount;
    if (this._current > this._to) {
        this._current = this._to;
    }
    this._onChange();
}

BarModel.prototype._onChange = function () {
    this.changeEvent.trigger(this.getPercentageFilled());
}

BarModel.prototype.getPercentageFilled = function () {
    var totaldelta = this._to - this._from;
    var currentDelta = this._current - this._from;
    var result = currentDelta / totaldelta;
    return result;
}

BarModel.prototype.getPercentageForValue = function (value) {
    var totaldelta = this._to - this._from;
    var result = value / totaldelta;
    return result;
}
