tgfComponents.ProfileComponent = function (properties, rank, scale) {
    "use strict";

    this.initialize(tgfSettings.componentDefaults.profileComponent);
    if (properties !== undefined) {
        this.setProperties(properties);
    }
    this._alphaMask = s_dest_in;
    this._rank = rank;
    this._profileSurface = null;
    this.profileImage = tgfSettings.player.image;
    this._frameImages = [];

    this.xScale = this.yScale = scale || 1;

}

tgfComponents.inherit(tgfComponents.ProfileComponent, tgfComponents.Base);


tgfComponents.ProfileComponent.prototype.doPrepare = function () {
    "use strict";

    this.profileSurface = new tbSurface(this._alphaMask.width, this._alphaMask.height);
    this._profileImage = tgfSettings.player.image;

    this.profilePicture = new tgfComponents.Picture({
        image: this.profileSurface
    });
    this.profilePicture.setProperties({
        x: tgfScale(0),
        y: tgfScale(0),
        width: tgfScale(100),
        height: tgfScale(100)
    });

    this.addComponent(this.profilePicture);
    this.changeRank(this._rank);
}

tgfComponents.ProfileComponent.prototype.changeRank = function (rank) {
    this._rank = rank;
    this._removeFrame();

    this.profileImage = DefaultProfilePictureHandler.getForUser(rank.level);
    tgfSettings.player.image = this.profileImage;

    this._addFrame();
   // this._addRankNumber();

    if (this.isPrepared) {
        this._render();
    }
};

tgfComponents.ProfileComponent.prototype._render = function () {

    this.profileSurface.clear();
    this.profileSurface.context.translate(this._alphaMask.xOrigin, this._alphaMask.yOrigin);
    this.profileSurface.xOrigin = this._alphaMask.xOrigin;
    this.profileSurface.yOrigin = this._alphaMask.yOrigin;

    this.profileSurface.setTarget();

    if (this.profileImage) {
        this.profileImage.drawStretched(0, -this._alphaMask.xOrigin, -this._alphaMask.yOrigin, this._alphaMask.width, this._alphaMask.height, 1);
    }

    tbGraphics.context.globalCompositeOperation = "destination-in";
    this._alphaMask.drawSimple(0, 0, 0);
    tbGraphics.context.globalCompositeOperation = "source-over";

    this.profileSurface.resetTarget();
}

tgfComponents.ProfileComponent.prototype._addFrame = function () {
    var images = this._rank.getRankImages();
    for (var i = 0; i < images.length; i++) {
        var image = images[i];
        this.addComponent(image);
        image.show();
        this._frameImages.push(image);
    }
}

tgfComponents.ProfileComponent.prototype._removeFrame = function () {

    for (var i = 0; i < this._frameImages.length; i++) {
        var image = this._frameImages[i];
        this.removeComponent(image);
    }
    this._frameImages = [];
}

tgfComponents.ProfileComponent.prototype._addRankNumber = function () {
    if (this.rankLabelProperties.display) {
        this.rankLabel = new tgfComponents.Label(this.rankLabelProperties);
        this.addComponent(this.rankLabel);
        this.rankLabel.text = "" + this.rankId;
    }
}
//******************************************************
//*****    Script Resource: Rank
//******************************************************

var Rank = function (level, from, to, materialRank, starRank) {
    "use strict";

    this.level = level ? level : 0;
    this.expFrom = from ? from : 0;
    this.expTo = to ? to : 0;
    this.material = materialRank ? materialRank : 0;
    this.starRank = starRank ? starRank : -1;

}

Rank.prototype.getRankImages = function () {

    if (this.level < 26) return this._getLowerRankImages();
    else if (this.level < 51) return this._getHigherRankImages(this.level);
}

// get the image componets of ranks before 25
Rank.prototype._getLowerRankImages = function () {
    var images = [];

    var prefix = "s_avatar";
    var materialName = RankConfig.rankMaterials[this.material];
    var starsData = RankConfig.starRanks[this.starRank];

    for (var i = 0; i < starsData.length; i++) {

        var currentStarData = starsData[i];
        var pictureComp = new tgfComponents.Picture({});

        var imageName = prefix + "_" + materialName + currentStarData.imageNamePostFix;
        var image = window[imageName];
        pictureComp.image = image;

        pictureComp.x += currentStarData.x;
        pictureComp.y += currentStarData.y;
        images.push(pictureComp);
    }

    return images;
}

// get the image componets of ranks after 25
Rank.prototype._getHigherRankImages = function (level) {
    var images = [];
    var pictureComp = new tgfComponents.Picture({
        y: 5
    });
    var image = window["s_ui_rankborder_0" + level];
    pictureComp.image = image;
    images.push(pictureComp);
    return images;
}
