//*****    Script Resource: RankUtility
//******************************************************

var RankUtility = function () {
    "use strict";
    this._curveData = [{
            levels: 5,
            experienceNeeded: 7500
        },
        {
            levels: 4,
            experienceNeeded: 15000
        },
        {
            levels: 5,
            experienceNeeded: 30000
        },
        {
            levels: 5,
            experienceNeeded: 60000
        },
        {
            levels: 4,
            experienceNeeded: 90000
        },
        {
            levels: 1,
            experienceNeeded: 92500
		},
		{
            levels: 5,
            experienceNeeded: 125000
		},
		{
            levels: 5,
            experienceNeeded: 162500
        },
		{
            levels: 5,
            experienceNeeded: 211250
		},
		{
            levels: 5,
            experienceNeeded: 274625
		},
		{
            levels: 6,
            experienceNeeded: 357013
        }
    ];

    this._maxStarRank = 4;
    this._ranks = [];
    this._lastRank = null;

}

RankUtility.prototype._getNextExpFromCurve = function () {
    var current = this._curveData[0];
    if (!current) {
        return 0;
    }
	current.levels--;
    if (current.levels == 0) {
		this._curveData.splice(0, 1);
    }
    return current.experienceNeeded;
}

RankUtility.prototype._addNextRank = function () {

    if (!this._lastRank) {
        this._lastRank = new Rank();
    }

    var expForPrevious = this._lastRank.expTo;
    var expToLevelUp = this._getNextExpFromCurve();
    var nextStarRank = this._lastRank.starRank + 1;
    var nextMaterialRank = this._lastRank.material;
    if (nextStarRank > this._maxStarRank) {
        nextStarRank = 0;
        nextMaterialRank++;
    }

    var newRank = new Rank();
    newRank.level = this._lastRank.level + 1;
    newRank.expFrom = expForPrevious;
    newRank.expTo = expForPrevious + expToLevelUp;
    newRank.material = nextMaterialRank;
    newRank.starRank = nextStarRank;

    this._ranks.push(newRank);
    this._lastRank = newRank;
    return newRank;
}

RankUtility.prototype.getRankFor = function (exp) {
    var maxIterations = 100;
    var iterationCount = 0;
    while (iterationCount < maxIterations) {
        var current = this._ranks[iterationCount];
        if (current == null) {
            current = this._addNextRank();
        }
        if (current.expTo > exp) {
            return current;
        }
        iterationCount++;
	}
	if (iterationCount == maxIterations - 1) throw "RankUtility.getRankFor ran into an endless loop";
}

RankUtility.prototype.getRankDataForRank = function (rank) {
    var maxIterations = 100;
    var iterationCount = 0;
    while (iterationCount < maxIterations) {
        var current = this._ranks[iterationCount];
        if (current == null) {
            current = this._addNextRank();
        }
        if (rank-1 == iterationCount) {
            return current;
        }
        iterationCount++;
	}
	if (iterationCount == maxIterations - 1) throw "RankUtility.getRankDataForRank ran into an endless loop";
}
//******************************************************
//*****    Script Resource: BarView
//******************************************************

tgfSettings.componentDefaults.barView = {


};

tgfComponents.BarView = function(properties, model, ease, fillImage, width, height, disableMask){
	"use strict";
	this.name = "BarView"; 
	
	this.initialize(tgfSettings.componentDefaults.barView);
	if (properties !== undefined) {
		this.setProperties(properties);
	}

	this._maxWidth = width;
	this._maxHeight = height;
	this._innerWidth = 0;

	this.barFill = new tgfComponents.Picture({
        image: fillImage,
		width: this._maxWidth,
		height:this._maxHeight,
		createFromSlices: true,
		anchor: {
			x: 0,
			y:.5
		}
	});
	
	var mask = new tgfComponents.RectMask({},disableMask);
	mask.setup(this._maxWidth, this._maxHeight, this.barFill);
	this.addComponent(mask);
	mask.show();
	mask.x = 0;
	mask.y = 0;

	this._targetScale = 0;
	this._currentScale = 0;
	this._ease = ease;

	this._barModel = model;
    this._barModel.changeEvent.listen(this.onBarChange,this);
	this._barModel.resetEvent.listen(this.onBarReset, this);
	this.idleEvent = new EventSystem.Local();

}

tgfComponents.inherit(tgfComponents.BarView, tgfComponents.Base);

tgfComponents.BarView.prototype.onBarChange = function (value) {
	this._targetScale = value;
}

tgfComponents.BarView.prototype.onBarReset = function (value) {
	this._targetScale = value;
	this.setFillScale(value);
}

tgfComponents.BarView.prototype.doDraw = function(){
	var scaleDelta = this._targetScale - this._currentScale;
	var nextScale = this._currentScale + (scaleDelta / this._ease);
	this.setFillScale(nextScale);
	if (nextScale > .99) {
		this.idleEvent.trigger();
	}
};

tgfComponents.BarView.prototype.setFillScale = function (amount) {
	this._innerWidth = this._maxWidth * (amount * 2);
	if (this._innerWidth < 1) {
		this._innerWidth = 1;
	}
	this.barFill.width = this._innerWidth;
	this._currentScale = amount;
}

tgfComponents.BarView.prototype.getOffsetForValue = function (value) {
    return this._maxWidth * this._barModel.getPercentageForValue(value);
}

tgfComponents.BarView.prototype.getFilloffset = function () {
	return this._innerWidth / 2;
}





//******************************************************
//*****    Script Resource: ExperienceController
//******************************************************

var ExperienceController = {}

ExperienceController.getExperiencePoints = function () {

	var scoreData = ScoreController.getTotalScore();
	var experiencePoints = this._convertToExperiencePoints(scoreData);
	return this._clampExperienceToVIPState(experiencePoints);
};

ExperienceController.getUnclampedExperiencePoints = function () {
	var scoreData = ScoreController.getTotalScore();
	var experiencePoints = this._convertToExperiencePoints(scoreData);
	return experiencePoints;
};

ExperienceController.getPreviousExperiencePoints = function () {

	var scoreData = ScoreController.getPreviousScore();
	var experiencePoints = this._convertToExperiencePoints(scoreData);
	return this._clampExperienceToVIPState(experiencePoints);
};

ExperienceController.isMaxNonVipRank = function (exp) {
	return exp >= tgfSettings.vip.nonVIPMaxEXP;
};

ExperienceController.isMaxRank = function (exp) {
	return exp >= tgfSettings.vip.VIPMaxEXP;
};

ExperienceController.getNonVipExpLeftUntilMax = function () {
	var scoreData = ScoreController.getTotalScore();
	return tgfSettings.vip.nonVIPMaxEXP - scoreData.score
};

ExperienceController._convertToExperiencePoints = function (experienceData) {
	var basepoints = Math.min(experienceData.score, tgfSettings.vip.nonVIPMaxEXP);
	return basepoints + experienceData.scoreVip;
};

ExperienceController._clampExperienceToVIPState = function (experiencePoints) {
	var returnValue;
	if (!VipMembership.isActive) {
	returnValue = Math.min(experiencePoints, tgfSettings.vip.nonVIPMaxEXP);
	} else {
		returnValue = Math.min(experiencePoints, tgfSettings.vip.VIPMaxEXP);
	}
	return returnValue;
};
