var BarCheckpointIcon = function (  progressValue, icon, locked, payload ) {
    "use strict";
    
    this.payload = payload;
    this._progressValue = progressValue;
    this._locked = locked;
    this.onClickedEvent = new EventSystem.Local();

    this.initialize({});

    this._iconLocked = new tgfComponents.Picture({
        image: icon
    });
    this._iconUnlocked = new tgfComponents.Picture({
        image: icon,
        startSubImage:1
    });


    this._counter = new tgfComponents.Picture({
		image: s_ui_theme_progress_counter
    });
    this._label = new tgfComponents.Label({
		text: progressValue.toString(),
		x: 0,
		y: 0,
		width: 230,
		height: 80,
		splitLines: true,
		fitToBox: true,
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 20,
			fontWeight: 400,
			fillColor: "#ffffff",
			baseline: "middle",
			align: "center"
		}
	});
}

tgfDialogs.inherit(BarCheckpointIcon, tgfComponents.Base);


BarCheckpointIcon.prototype.attach = function (barModel, barView) {
    this._barModel = barModel;
    this._offset = barView.getOffsetForValue(this._progressValue);

    this._iconLocked.show();
    this._iconUnlocked.show();
    this._counter.show();
    this._label.show();

    this._iconLocked.x = this._counter.x = this._label.x = this._offset;
    this._iconLocked.x += 32;
    this._iconLocked.y = 5;
    this._counter.y = 42;
    this._label.y = 44;

    this._iconUnlocked.x = this._iconLocked.x;
    this._iconUnlocked.y = this._iconLocked.y;

    if (this._locked) {
        this.showLock();
    } else {
        this.showUnlock();
    }

    this.onBarChange();
}

BarCheckpointIcon.prototype.getIconX = function () {
    return this._iconLocked.x;
}
BarCheckpointIcon.prototype.getIconY = function () {
    return this._iconLocked.y;
}


BarCheckpointIcon.prototype.onBarChange = function () {
    
    if (this._barModel.getProgressValue() >= this._progressValue) {

        if (this._locked) {
            this.showUnlock();
            this._locked = false;
            EventSystem.Global.dispatchEvent(Theme_Event.PRESENT_CHECKPOINT_REACHED, this);
        }
    }
}

BarCheckpointIcon.prototype.getProgress = function () {
    return this._progressValue;
}

BarCheckpointIcon.prototype.showUnlock = function () {
    this.addComponent(this._iconUnlocked);
    this.removeComponent(this._iconLocked);
    this.addComponent(this._counter);
    this.addComponent(this._label);
    this._iconUnlocked.x -= 15;
}

BarCheckpointIcon.prototype.showLock = function () {
    this.addComponent(this._iconLocked);
    this.removeComponent(this._iconUnlocked);
    this.addComponent(this._counter);
    this.addComponent(this._label);
}

BarCheckpointIcon.prototype.handleTouchUp = function (param, xMouse, yMouse) {
    var localCoordinate = this.screenToComponentVector(xMouse, yMouse);
    localCoordinate.x += this._iconLocked.image.width / 2;
    localCoordinate.y += this._iconLocked.image.height / 2;

    if (this._iconLocked.x < localCoordinate.x && this._iconLocked.x + this._iconLocked.image.width > localCoordinate.x) {
        if (this._iconLocked.y < localCoordinate.y && this._iconLocked.y + this._iconLocked.image.height > localCoordinate.y) {
            this.onClickedEvent.trigger(this);
            tbAudio.play(a_select);
        }
    }
}

BarCheckpointIcon.prototype.getRarity = function () {
    return this.payload._raw.rarity;
}

BarCheckpointIcon.prototype.isLocked = function () {
    return this._locked;
}
