var GiftBarProgressController = function (x, y, width, height) {
    "use strict";

    this._ghostBar = new BarModel();
    this._primaryBar = new BarModel();

    this._ghostBarDialog = new tgfDialogs.BarDialog({}, this._ghostBar, true, width, height);
    this._primaryBarDialog = new tgfDialogs.BarDialog({}, this._primaryBar, false, width, height);

    this._checkpoints = [];

    this._container = new tgfDialogs.Base();
    this._container.x = x;
    this._container.y = y;

    this._container.addComponent(this._ghostBarDialog);
    this._container.addComponent(this._primaryBarDialog);

    this._container.show();
}

GiftBarProgressController.prototype.initialize = function (barValueFrom, barValueTo, currentValue) {
    this._ghostBar.reset(barValueFrom, barValueTo, currentValue);
    this._primaryBar.reset(barValueFrom, barValueTo, currentValue);
    this._targetBarValue = currentValue;
    this._currentRankScore = currentValue;
}

GiftBarProgressController.prototype.hide = function () {
    this._ghostBarDialog.hide();
    this._primaryBarDialog.hide();
    this._container.hide();
}

GiftBarProgressController.prototype.show = function () {
    this._ghostBarDialog.show();
    this._primaryBarDialog.show();
    this._container.show();
}

GiftBarProgressController.prototype.free = function () {

    this._ghostBar.free();
    this._primaryBar.free();
    this._ghostBarDialog.free();
    this._primaryBarDialog.free();
    this._container.free();

    var checkpointsLength = this._checkpoints.length;
    for (var i = 0; i < checkpointsLength; i++) {
        this._checkpoints[i].free();
    }
}

GiftBarProgressController.prototype.addCheckpoint = function (checkpoint) {
    checkpoint.attach(this._primaryBar, this._primaryBarDialog);
    this._container.addComponent(checkpoint);
    this._checkpoints.push(checkpoint);
    checkpoint.show();
}
