tgfSettings.dialogDefaults.clubMembershipBought = {

	depth: -10001,

	backgroundImage: s_popup_default_bg,

	hasCloseButton: false,
	darkenerProperties: {
		height: 9001,
		width: 9001
	},

	width: 626,
	height: 800,

	grantedTextAnimationDuration: 500,
	grantedTextAnimationDelay: 1500,

	vipHeaderAnimationDuration: 200,
	vipHeaderAnimationDelay: 1060,

	rankUnlockAnimationDuration: 1500,
	rankUnlockDelay: 1500,

	remainingDaysAnimationDuration: 1000,
	remainingDaysDelay: 1500,

	_incrementalDelay: 0,
	_incrementalYOffset: 0,

	grantedStartY: -50,
	grantedEndY: 0,

	iconDistance: 40
};

// The constructor for the dialog
/**
 * @constructor
 * @base tgfDialogs.Base
 */
tgfDialogs.ClubMembershipBought = function (properties) {
	"use strict";
	this.name = "ClubMembershipBought";
	this.active = true;

	this.initialize(tgfSettings.dialogDefaults.buttonBox);
	this.setProperties(tgfSettings.dialogDefaults.clubMembershipBought);

	this.x = tgfGraphics.visibleWidth / 2;
	this.y = tgfGraphics.visibleHeight / 2;

	this._animators = [];

	if (properties !== undefined) {
		this.setProperties(properties);
	}
};

// Inherit the base dialog
tgfDialogs.inherit(tgfDialogs.ClubMembershipBought, tgfDialogs.ButtonBox);

tgfDialogs.ClubMembershipBought.prototype.doPrepare = function () {

	tgfDialogs.ClubMembershipBought.uber.doPrepare.call(this);

	this.container.addComponent(this._addHeaderAnimation());

	if (ExperienceController.isMaxNonVipRank(ExperienceController.getExperiencePoints())) {
		this._addUnlockRankAnimation();
		this._incrementalDelay += 500;
		this._incrementalYOffset += 100;
	}

	this.container.addComponent(this._addDaysRemaining());
	this._incrementalDelay += 500;

	this.container.addComponent(this._addContinueButton());
};

tgfDialogs.ClubMembershipBought.prototype._addHeaderAnimation = function () {

	var animationContainer = new tgfComponents.Base({});

	var spineAnimation = new tgfComponents.SpineComponent({
		spineAnimation: membership_status,
		animationClips: ["granted"],
		play: true,
		hasDelay: true,
		delay: 100,
		x: 0,
		y: -200,
		updateWhileUnactive: false
	});

	var vipBannerText = new tgfComponents.Label({
		font: tgfSettings.fonts.vipHeaderGrantedPopup,
		x: 0,
		y: -90,
		text: tgfDictionary.getText("VIP_header"),
	});
	this._setupBannerAnimation(vipBannerText);

	var vipMembershipDurationInDays = (VipMembership.expirationDate - TimeManager.getDate()) / 86400000;

	var grantedText = new tgfComponents.Label({
		font: tgfSettings.fonts.grantedText,
		x: 0,
		y: this.grantedStartY,
		text: vipMembershipDurationInDays <= 30 ? tgfDictionary.getText("VIPGranted_granted") : tgfDictionary.getText("VIP_extended")
	});
	this._setupGrantedTextAnimation(grantedText);

	animationContainer.addComponent(spineAnimation);
	animationContainer.addComponent(grantedText);
	animationContainer.addComponent(vipBannerText);

	return animationContainer;
};

tgfDialogs.ClubMembershipBought.prototype._setupBannerAnimation = function (targetComponent) {

	var bannerAnimator = new tbAnimator(this);

	var bannerXScaleTrack = bannerAnimator.addTrack("xScale", targetComponent);
	bannerAnimator.addKey(bannerXScaleTrack, 0, 0);
	bannerAnimator.addKey(bannerXScaleTrack, this.vipHeaderAnimationDelay, 0, tbEase.easeOutOvershoot);
	bannerAnimator.addKey(bannerXScaleTrack, this.vipHeaderAnimationDelay + this.vipHeaderAnimationDuration, 1);

	this._animators.push(bannerAnimator);
}

tgfDialogs.ClubMembershipBought.prototype._setupGrantedTextAnimation = function (targetComponent) {

	var grantedTextAnimator = new tbAnimator(this);

	var grantedTextYScaleTrack = grantedTextAnimator.addTrack("yScale", targetComponent);
	grantedTextAnimator.addKey(grantedTextYScaleTrack, 0, 0);
	grantedTextAnimator.addKey(grantedTextYScaleTrack, this.grantedTextAnimationDelay, 0, tbEase.easeOutOvershoot);
	grantedTextAnimator.addKey(grantedTextYScaleTrack, this.grantedTextAnimationDelay + this.grantedTextAnimationDuration, 1);

	var grantedTextYPosTrack = grantedTextAnimator.addTrack("y", targetComponent);
	grantedTextAnimator.addKey(grantedTextYPosTrack, 0, this.grantedStartY);
	grantedTextAnimator.addKey(grantedTextYPosTrack, this.grantedTextAnimationDelay, this.grantedStartY, tbEase.easeOutOvershoot);
	grantedTextAnimator.addKey(grantedTextYPosTrack, this.grantedTextAnimationDelay + this.grantedTextAnimationDuration, this.grantedEndY);

	this._animators.push(grantedTextAnimator);
}

tgfDialogs.ClubMembershipBought.prototype._addUnlockRankAnimation = function () {

	var self = this;

	this._rankBar = new AvatarRankDialog(80, this.y + 60, 500, 100, {
			image: s_ui_rank_results_progress_bar_middle_background,
			backgroundWidthOffset: 94
		},
		"#595959",
		this.depth - 1);

	this._rankBar.setAlpha(0);

	var animated = false;

	var rankBarAnimator = new tbAnimator(this);
	var rankbarTrack = rankBarAnimator.addTrack("function", this, function (value) {

		self._rankBar.setAlpha(value);

		if (value >= 1 && !animated) {
			animated = true;
			self._rankBar.animateUnlock();
		}
	});

	rankBarAnimator.addKey(rankbarTrack, 0, 0);
	rankBarAnimator.addKey(rankbarTrack, this.rankUnlockDelay, 0, tbEase.easeOutOvershoot);
	rankBarAnimator.addKey(rankbarTrack, this.rankUnlockDelay + this.rankUnlockAnimationDuration, 1);

	this._animators.push(rankBarAnimator);
};

tgfDialogs.ClubMembershipBought.prototype._addDaysRemaining = function () {

	var self = this;

	this._remainingLabel = new tgfComponents.Label({
		font: tgfSettings.fonts.timeRemainingText,
		x: s_endscreen_icon_time.width,
		y: 100 + this._incrementalYOffset,
		text: VipMembership.getRemainingText(),
	});

	this._timeIcon = new tgfComponents.Picture({
		x: 0,
		y: -3,
		image: s_endscreen_icon_time
	});

	var daysRemainingAnimator = new tbAnimator(this);

	var track = daysRemainingAnimator.addTrack("function", this, function (value) {
		self._setTimeIconPosition();
		self._remainingLabel.alpha = value;
	});

	daysRemainingAnimator.addKey(track, 0, 0);
	daysRemainingAnimator.addKey(track, this.remainingDaysDelay + this._incrementalDelay, 0, tbEase.easeOutCircular, 0.1);
	daysRemainingAnimator.addKey(track, this.remainingDaysDelay + this.remainingDaysAnimationDuration + this._incrementalDelay, 1);

	this._remainingLabel.addComponent(this._timeIcon);

	this._animators.push(daysRemainingAnimator);

	return this._remainingLabel;
};

tgfDialogs.ClubMembershipBought.prototype._addContinueButton = function () {
	var self = this;

	return new tgfComponents.Button({
		fontUp: {
			fontFace: f_main_font.fontFace,
			fontSize: 34,
			fillColor: "#ffffff",
			baseline: "middle",
			align: "center"
		},
		alpha: 0,
		effects: [{
			effect: tgfEffects.nothing,
			duration: 1.5 + (this._incrementalDelay / 1000)
		}, {
			effect: tgfEffects.fadeIn,
			duration: 1
		}],
		repeatEffect: 1,
		image: s_button_default_green,
		x: 0,
		y: 290,
		width: tgfScale(500),
		height: s_button_default_green.height,
		createFromSlices: true,
		text: tgfDictionary.getText("unlocked_theme_continue_button"),
		onClick: function (comp) {
			self.playDisappear();
			EventSystem.Global.dispatchEvent(UI_Event.GO_TO_SCREEN_CLICKED, mainMenuScreens.CALENDAR);

			SudokuAnalytics.reportClickingContinueMembershipBought();
//			MessyAnalytics.reportClickingContinueMembershipBought();
		}
	});
};

tgfDialogs.ClubMembershipBought.prototype._setTimeIconPosition = function () {
	this._timeIcon.x = this._remainingLabel.x - this.iconDistance - this._remainingLabel.textSurface.width / 2;
}

tgfDialogs.ClubMembershipBought.prototype.handleBeginStep = function (timePassed) {
	if (this.isVisible) {
		if (this._animators.length > 0) {
			for (var index = 0; index < this._animators.length; index++) {
				this._animators[index].updateTime(timePassed);
			}
		}
	}
}

tgfDialogs.ClubMembershipBought.prototype.doShow = function () {
	"use strict";
	if (this._rankBar) {
		this._rankBar.show();
	}
	setTimeout(function () {
		tbAudio.play(a_membership_granted_popup);
	}, 200);

	SudokuAnalytics.reportShowingMembershipBoughtPopup();
//	MessyAnalytics.popup(this.name, true);
}

tgfDialogs.ClubMembershipBought.prototype.doHide = function () {
	//MessyAnalytics.popup(this.name, false);
}

tgfDialogs.ClubMembershipBought.prototype.playDisappear = function () {
	"use strict";
	if (this._rankBar) {
		this._rankBar.hide();
	}
	this.deactivate();
	this.container.startSubEffect(2);
};

tgfDialogs.ClubMembershipBought.prototype.handleTouchDown = function (finger, x, y) {
	"use strict";

	tgfDialogs.ClubMembershipBought.uber.handleTouchDown.call(this, finger, x, y);
	return true; // This makes sure we can't click something in the background
};

tgfDialogs.ClubMembershipBought.prototype.handleTouchUp = function (finger, x, y) {
	"use strict";
	tgfDialogs.ClubMembershipBought.uber.handleTouchUp.call(this, finger, x, y);
	return true; // This makes sure we can't click something in the background
};

tgfDialogs.ClubMembershipBought.prototype.handleImmediateTouchDown = function (finger, x, y) {
	"use strict";

	tgfDialogs.ClubMembershipBought.uber.handleImmediateTouchDown.call(this, finger, x, y);
	return true; // This makes sure we can't click something in the background
};
