//******************************************************
//*****    Script Resource: VipMembership
//******************************************************

var VipMembership = {};
VipMembership.isActive = false;
VipMembership.expirationDate = new Date();
VipMembership.changeEvent = null;
VipMembership._activeProduct = null;
VipMembership.isInitialized = false;
VipMembership._purchaseInProgress = false;

VipMembership.buyButtonLocations = Object.freeze({
	EXPIRED_POPUP: "EXPIRED_POPUP",
	MEMBERSHIP_PAGE: "MEMBERSHIP_PAGE"
});

VipMembership.getRemainingText = function () {
	var now = TimeManager.getDate();
	var delta = this.expirationDate - now;
	var minute = 60000;
	var hour = 3600000;
	var day = 86400000;

	if(delta < 0) {
		return StringUtil.format(tgfDictionary.getText("VIP_daysRemainingMinutes"), 0);
	}

	if(delta < hour) {
		return StringUtil.format(tgfDictionary.getText("VIP_daysRemainingMinutes"), Math.ceil(delta / minute));
	}

	if(delta < day) {
		return StringUtil.format(tgfDictionary.getText("VIP_daysRemainingHours"), Math.ceil(delta / hour));
	}

	return StringUtil.format(tgfDictionary.getText("VIP_daysRemainingDay"), VipMembership.daysLeft());
};

VipMembership.daysLeft = function () {
	if (VipMembership.isActive) {
		var now = TimeManager.getDate();
		var delta = this.expirationDate - now;
		var days = 1 + parseInt(delta / 86400000);
		return days;
	}
	return 0;
}

VipMembership.initialize = function () {
	var self = this;

	return new Promise(function (resolve, reject) {
		self.changeEvent = new EventSystem.Local();

		EventSystem.Global.addEventListener(UI_Event.CALENDAR_SHOW, self._checkExpiration, self);
		EventSystem.Global.addEventListener(UI_Event.BUY_VIP_CLICKED, self._initiatePurchase, self);
		VipMembershipPopupController.initialize();

		self._popupThrobber = new tgfDialogs.ThrobberDialog({
			loadingText: tgfDictionary.getText("VIP_processing")
		});

		self.updateInventory().then(function () {
			self.isInitialized = true;
			resolve();
		}).catch(reject);
	});
}

VipMembership.setProduct = function (item) {
	this._activeProduct = item;
}

VipMembership.getProduct = function () {
	return this._activeProduct;
}

VipMembership.isFeatureActive = function () {
	return false;/*
	if (!shopService.arePaymentsSupported()) {
		return false;
	}

	return true;*/
}

VipMembership.updateInventory = function () {
	var self = this;
	return shopService.getInventory()
		.then(function (inventoryItems) {

			var amount = inventoryItems.length;

			var isMemberShipActive = false;

			for (var i = 0; i < amount; i++) {

				var currentItem = inventoryItems[i];

				if(currentItem.expirationDate > TimeManager.getDate()) {

					//Get latest expiration date when player has multiple items.
					self.expirationDate = new Date(Math.max(self.expirationDate.getTime(), currentItem.expirationDate.getTime()));

					isMemberShipActive = true;
				}
			}

			self.setActive(isMemberShipActive);
		})
		.catch(function (err) {
			errorLoggingService.sendError(err);
			console.error("[VipMembership] updateInventory Ran into an error. ->", err);
		});
};

VipMembership.setActive = function (isActive){

	if(this.isActive === isActive) {
		return;
	}

	this.isActive = isActive;

	if(this.isActive) {
		gameData.vipMembershipData.hasShownMembershipExpiredFeedback = false;
		gameData.vipMembershipData.hasOwnedVip = true;
		gameData.vipMembershipData.lastVIPStartTime = this.expirationDate.getTime();
		saveDataService.savePlayerData(gameData.getSaveableGameData());
	}

	this.changeEvent.trigger();
};

VipMembership._checkExpiration = function () {
	if (this.daysLeft() <= 0 && this.isActive) {
		this.isActive = false;
		this.changeEvent.trigger();
	}
}

VipMembership._initiatePurchase = function (location) {
	var self = this;

	if (!this._purchaseInProgress) {

		this._purchaseInProgress = true;
		self._popupThrobber.show();
		this._freezeGameTokens(true);

		shopService.purchaseItem(VipMembership._activeProduct)
			.then(function (purchaseStatus) {
				if (purchaseStatus === PurchaseStatus.Success) {
					SudokuAnalytics.reportBuySucceeded(VipMembership.getProduct().id, location);
//					MessyAnalytics.reportBuySucceeded(VipMembership.getProduct().id);
					if (VipMembership.isActive) {
						SudokuAnalytics.reportMembershipExtended(VipMembership.getProduct().id);
						MessyAnalytics.reportMembershipExtended(VipMembership.getProduct().id);
					}
					VipMembership.updateInventory();
				} else if (purchaseStatus === PurchaseStatus.Cancelled) {
					SudokuAnalytics.reportFBBuyScreenClosed();
				//	MessyAnalytics.reportFBBuyScreenClosed();
				}
			})
			.catch(function (err) {
				errorLoggingService.sendError(err);
				console.error("[VipMembership] _initiatePurchase Ran into an error. ->", err);
			})
			.finally(function () {
				self._freezeGameTokens(false);
				self._popupThrobber.hide();
				self._purchaseInProgress = false;
			});
	}
}

VipMembership._freezeGameTokens = function (shouldFreeze) {
	for (var i = 0; i < tbGame._tokens.length; i++) {
		if (!tbGame._tokens[i]) {
			continue;
		}

		if (tbGame._tokens[i].name === "ThrobberDialog") {
			continue;
		}
		tbGame._tokens[i].active = !shouldFreeze;
	}
};
