tgfDialogs.MembershipPage = function (properties) {
	"use strict";
	this.name = "MembershipPage";
	this.active = true;

	this.initialize(tgfSettings.dialogDefaults.membershipPage);

	if (properties !== undefined) {
		this.setProperties(properties);
	}

	this._animations = [];
};

tgfDialogs.inherit(tgfDialogs.MembershipPage, tgfDialogs.Base);


tgfDialogs.MembershipPage.prototype.doPrepare = function () {

	this.y = tgfGraphics.safeZoneHeight / 2;
	this.x = tgfGraphics.visibleWidth / 2;

	var backgroundImage = ThemeController.getMembeshipBackgroundImage()

	var offset = tgfSettings.graphics.areaHeight - tgfGraphics.safeZoneHeight;

	this._bg = new tgfComponents.Picture({
		image: backgroundImage,
		y: offset/2
	});

	EventSystem.Global.dispatchEvent(IAP_Event.PRODUCT_SHOWN);

	var buttonText = VipMembership.getProduct().price;

	var vipText = tgfDictionary.getText("VIP_subtitle");
	var belowButtonText = tgfDictionary.getText("VIP_duration");

	if (VipMembership.daysLeft() > 0) {
		vipText = VipMembership.getRemainingText();
		buttonText =  VipMembership.getProduct().price;
		belowButtonText = StringUtil.format(tgfDictionary.getText("VIP_addDays"), 30);
	}

	var productType = ActiveProductController.getActiveProductType();

	if (productType === ActiveProductController.productTypes.EXTENSIONDISCOUNT) {
		this._buyButton = this._createExtensionDiscountBuyButton();
	} else if (productType === ActiveProductController.productTypes.INITIALDISCOUNT) {
		this._buyButton = this._createInitialDiscountBuyButton();
	} else {
		this._buyButton = this._createBuyButton(buttonText);
	}
	this._buyButton.y = 245;

	var headerLabel = this._createHeaderLabel(tgfDictionary.getText("VIP_header"));
	this._vipLabel = this._createVipLabel(vipText);

	this._buyButton.onClick = function () {
		SudokuAnalytics.reportBuyButtonClicked(VipMembership.getProduct().id, VipMembership.buyButtonLocations.MEMBERSHIP_PAGE);
//		MessyAnalytics.reportBuyButtonClicked(VipMembership.getProduct().id);
		EventSystem.Global.dispatchEvent(UI_Event.BUY_VIP_CLICKED, VipMembership.buyButtonLocations.MEMBERSHIP_PAGE);
	}
	var belowButtonLabel = this._createLabelBelowButton(belowButtonText);

	headerLabel.y = -458 + 65;

	belowButtonLabel.y = this._buyButton.y + 70;

	this.addComponent(this._bg);
	this.addComponent(this._vipLabel);
	this.addComponent(this._buyButton);
	this.addComponent(belowButtonLabel);
	this.addComponent(headerLabel);
	this.addComponent(this._createVIPSupportButton());

	this._startTopEffect();
	this._createMiddleBlock();
	this._startCrownEffect(this._buyButton, 1); //4000);

	VipMembership.changeEvent.listen(this.free, this);
}

tgfDialogs.MembershipPage.prototype.doFree = function () {
	VipMembership.changeEvent.stopListening(this.free, this);
}

