tgfDialogs.MembershipPage.prototype._addAnimationBlock = function (image, y, textContainer, delay, index) {
	var animation = new tgfComponents.Picture({
		image: image,
		x: 0,
		y: y - 10,
		xScale: 0.9,
		yScale: 0.9
	});

	textContainer.y = y - 10;

	var animator = new tbAnimator(animation);
	var textAnimator = new tbAnimator(textContainer);

	var animatorPopupTrackX = animator.addTrack('x');
	var animatorPopupTrackAlpha = animator.addTrack('alpha');
	var textAnimatorPopupTrackX = textAnimator.addTrack('x');
	var textAnimatorPopupTrackAlpha = textAnimator.addTrack('alpha');

	animator.pause();
	animator.removeAllKeys();
	animator.removeEvents();

	var keyOne = delay + 300;
	var keyTwo = delay + 1000;

	var textDelay = 400;

	animator.addKey(animatorPopupTrackX, 0, -710, tbEase.easeOutCircular);
	animator.addKey(animatorPopupTrackX, delay, -710, tbEase.easeOutCircular);
	animator.addKey(animatorPopupTrackX, keyOne, -260, tbEase.easeOutCircular);
	animator.addKey(animatorPopupTrackX, keyTwo, -220, tbEase.easeOutCircular);
	animator.addKey(animatorPopupTrackAlpha, 0, 0, tbEase.easeOutCircular);
	animator.addKey(animatorPopupTrackAlpha, delay, 0, tbEase.easeOutCircular);
	animator.addKey(animatorPopupTrackAlpha, delay + 200, 0, tbEase.easeOutCircular);
	animator.addKey(animatorPopupTrackAlpha, delay + (keyTwo / 2), 1, tbEase.easeOutCircular);

	// delay
	textAnimator.addKey(textAnimatorPopupTrackX, 0, -260, tbEase.easeLinear);
	textAnimator.addKey(textAnimatorPopupTrackAlpha, 0, 0, tbEase.easeOutCircular);
	textAnimator.addKey(textAnimatorPopupTrackX, delay + textDelay, -260, tbEase.easeLinear);
	textAnimator.addKey(textAnimatorPopupTrackAlpha, delay + textDelay + 100, 0, tbEase.easeOutCircular);

	textAnimator.addKey(textAnimatorPopupTrackX, keyOne + textDelay, -160, tbEase.easeLinear);
	textAnimator.addKey(textAnimatorPopupTrackAlpha, keyOne + 300 + textDelay, 1, tbEase.easeOutCircular);

	textAnimator.addKey(textAnimatorPopupTrackX, keyTwo + textDelay + (index == 2 ? -textDelay : 0), -150, tbEase.easeOutCircular);
	textAnimator.addKey(textAnimatorPopupTrackAlpha, delay + (keyTwo / 2) + textDelay, 1, tbEase.easeOutCircular);

	animator.setTime(0);
	animator.resumeForced();
	textAnimator.setTime(0);
	textAnimator.resumeForced();

	this._animations.push(animator);
	this._animations.push(textAnimator);

	this.addComponent(animation);
	this.addComponent(textContainer);
}

tgfDialogs.MembershipPage.prototype.handleBeginStep = function (timePassed) {

	var animationsAmount = this._animations.length;
	for (var i = 0; i < animationsAmount; i++) {
		this._animations[i].updateTime(timePassed);
	}

	if (this._discountTimer) {
		this._discountTimerTime += timePassed;
		if (this._discountTimerTime > 1000) {
			this._discountTimerTime = 0;
			this._discountTimer.text = StringUtil.milliSecondsToHHMMSS((gameData.vipMembershipData.lastDiscountStartTime + tgfSettings.game.IAPSettings.discountDuration) - TimeManager.getDate().getTime());
			this._discountTimer.recreate();
		}
	}

	if (VipMembership.daysLeft() > 0 && this._vipLabel) {
		this._vipLabel.text = VipMembership.getRemainingText();
		this._vipLabel.recreate();
	}
}
