var ActiveProductController = {};
ActiveProductController._catalog = {};
ActiveProductController.priceRegexPattern = /([0-9]{1,3}(?:\.|\,)[0-9]{0,3})/g;

ActiveProductController.productTypes = Object.freeze({
	DEFAULT: "DEFAULT",
	INITIALDISCOUNT: "INITIALDISCOUNT",
	EXTENSIONDISCOUNT: "EXTENSIONDISCOUNT"
});

ActiveProductController.initialize = function () {
	return Promise.resolve();
	/*
	this._productIds = this._getProductIds();

	EventSystem.Global.addEventListener(IAP_Event.PRODUCT_SHOWN, this._setActiveProduct, this);

	if (!shopService.arePaymentsSupported()) {
		return Promise.resolve();
	}

	return this._getCatalog();
	*/
};

ActiveProductController._getProductIds = function () {
	var returnValue = {};

/*	var metadata = ABTestInstance.getMetadata();
	if(metadata.iapGroup){
		var products = tgfSettings.game.IAPSettings.productIds[metadata.iapGroup];
		for (var i = 0; i < products.length; i++) {
			var element = products[i];
			returnValue[element.key] = element.productId;
		}
	}*/

	return returnValue;
};


ActiveProductController._getCatalog = function () {
	var self = this;
	return new Promise(function (resolve, reject) {
		shopService.getCatalog().then(function (items) {
			self._setCatalog(items);
			resolve();
		});
	});
};

ActiveProductController._setCatalog = function (items) {
	var itemlength = items.length;
	for (var i = 0; i < itemlength; i++) {
		var item = items[i];
		this._catalog[item.id] = item;
	}
};

ActiveProductController._setActiveProduct = function (isVIPExpired) {

	this._isVIPExpiredDiscountActive = !!isVIPExpired;

	var activeProduct = ActiveProductController.productTypes.DEFAULT;

	if(this._isExtensionDiscountActive()) {
		activeProduct = ActiveProductController.productTypes.EXTENSIONDISCOUNT;
	} else if(this._isInitialDiscountActive()) {
		activeProduct = ActiveProductController.productTypes.INITIALDISCOUNT;
	} else if(this._canStartInitialDiscount()) {
		activeProduct = ActiveProductController.productTypes.INITIALDISCOUNT;

		var now = TimeManager.getDate();
		var startOfToday = TimeManager.getDate();
		startOfToday.setHours(0,0,0,0);

		gameData.vipMembershipData.lastDiscountStartTime = gameData.vipMembershipData.lastDiscountStartTime === 0 ? now.getTime() : startOfToday.getTime();

		SudokuAnalytics.reportDiscountStarted(activeProduct.id, tgfSettings.game.IAPSettings.discountDuration);
//		MessyAnalytics.reportDiscountStarted(activeProduct.id, tgfSettings.game.IAPSettings.discountDuration);
	}

	VipMembership.setProduct(ActiveProductController.getProductByType(activeProduct));

	gameData.vipMembershipData.activeProductId = this._productIds[activeProduct];

	saveDataService.savePlayerData(gameData.getSaveableGameData());
};

ActiveProductController._isExtensionDiscountActive = function () {
	return VipMembership.isActive || this._isVIPExpiredDiscountActive;
};

ActiveProductController._canStartInitialDiscount = function () {

	if(gameData.vipMembershipData.hasOwnedVip) {
		return false;
	}

	if(VipMembership.isActive) {
		return false;
	}

	if(gameData.vipMembershipData.lastDiscountStartTime === 0) {
		return true;
	}

	var millisecondsInDay = 60*60*24*1000;
	var millisecondsSinceLastDiscountExpired = TimeManager.getDate().getTime() - (gameData.vipMembershipData.lastDiscountStartTime + tgfSettings.game.IAPSettings.discountDuration);
	var daysSinceLastDiscount = Math.floor(millisecondsSinceLastDiscountExpired / millisecondsInDay);
	var discountCoolDown = (millisecondsInDay / tgfSettings.game.IAPSettings.discountCooldown);

	return daysSinceLastDiscount % discountCoolDown === 0;
};

ActiveProductController._isInitialDiscountActive = function () {
	if(gameData.vipMembershipData.activeProductId !== this._productIds[ActiveProductController.productTypes.INITIALDISCOUNT]) {
		return false;
	}

	return TimeManager.getDate().getTime() < (gameData.vipMembershipData.lastDiscountStartTime + tgfSettings.game.IAPSettings.discountDuration);
};

ActiveProductController.removeVIPExpiredDiscount = function () {
	this._isVIPExpiredDiscountActive = false;
};

ActiveProductController.getRegularPrice = function () {
    return this._catalog[this._productIds[ActiveProductController.productTypes.DEFAULT]].price;
};

ActiveProductController.getDiscountString = function () {
	var unparsedRegularPrice = this.getProductByType(ActiveProductController.productTypes.DEFAULT).price;
	var unparsedDiscountPrice = this.getProductByType(this.getActiveProductType()).price;

	var regularPriceMatch = unparsedRegularPrice.match(ActiveProductController.priceRegexPattern);
	var discountPriceSMatch = unparsedDiscountPrice.match(ActiveProductController.priceRegexPattern);

	var regularPrice = 1;
	var discountPrice = 0;
	if(regularPriceMatch.length > 0 && discountPriceSMatch.length > 0){
		regularPrice = parseFloat(regularPriceMatch[0].replace(",", "."));
		discountPrice = parseFloat(discountPriceSMatch[0].replace(",", "."));
	}

	return (100 - Math.round((discountPrice / regularPrice) * 100)) + "%";
};

ActiveProductController.getActiveProductType = function () {
	if (this._isExtensionDiscountActive()) {
		return ActiveProductController.productTypes.EXTENSIONDISCOUNT;
	}

	if (this._isInitialDiscountActive()) {
		return ActiveProductController.productTypes.INITIALDISCOUNT;
	}

	return ActiveProductController.productTypes.DEFAULT;
};

ActiveProductController.getProductById = function (productId) {
	return this._catalog[productId];
};

ActiveProductController.getProductByType = function (productType) {
	return this._catalog[this._productIds[productType]];
};

