var VipMembershipPopupController = {};

VipMembershipPopupController.initialize = function () {
    var self = this;

    VipMembership.changeEvent.listen(function () {
        if (VipMembership.isActive && VipMembership.isInitialized) {
            new tgfDialogs.ClubMembershipBought({}).show();
        }

        self.showExpiredFeedback();
    });

    EventSystem.Global.addEventListener(System_Event.SHOW_MAIN_MENU, this.showExpiredFeedback, this);
    EventSystem.Global.addEventListener(UI_Event.GO_TO_SCREEN_CLICKED, this._showPaymentsNotSupportedFeedback, this);
	EventSystem.Global.addEventListener(Icon_Bar_Events.ICON_SELECT, this._showPaymentsNotSupportedFeedback, this);
	
	EventSystem.Global.addEventListener(IAP_Event.OPEN_VIP_SUPPORT, this._openVIPSupportDialog, this);
};

VipMembershipPopupController._openVIPSupportDialog = function() {
	new tgfDialogs.VIPSupportDialog().show();
};

VipMembershipPopupController.isPaymentsNotSupportedFeedbackActive = function() {

    if(shopService.arePaymentsSupported()) {
        return false;
    }
    
    if(document.referrer.indexOf("messenger") === -1) {
        return false;
    }

    return true;
};

VipMembershipPopupController._showPaymentsNotSupportedFeedback = function(name) {

    if(name !== mainMenuScreens.MEMBERSHIP) {
        return;
    }

    if(!this.isPaymentsNotSupportedFeedbackActive()) {
        return;
    }

    new tgfDialogs.PaymentsNotSupportedDialog().show();
}; 

VipMembershipPopupController.showExpiredFeedback = function() {

    if(!VipMembership.isFeatureActive()) {
        return;
    }

    if(!VipMembership.isActive && gameData.vipMembershipData.hasOwnedVip && !gameData.vipMembershipData.hasShownMembershipExpiredFeedback) {
        new tgfDialogs.ClubMembershipExpired({}).show();

        gameData.vipMembershipData.hasShownMembershipExpiredFeedback = true;
        saveDataService.savePlayerData(gameData.getSaveableGameData());
    }
};
