var FreePuzzleTimer = (function () {

	var _FreePuzzleTimer = function () {};

	_FreePuzzleTimer.prototype.initialize = function () {
		this._lastPuzzleClaimedTime = gameData.lastPuzzleClaimed;
	};

	_FreePuzzleTimer.prototype.getTimeUntilFreePuzzleInMilliseconds = function () {

		return Math.max(0, (this._lastPuzzleClaimedTime + tgfSettings.game.freePuzzleInterval) - TimeManager.getDate().getTime());
	};

	_FreePuzzleTimer.prototype.registerFreePuzzleClaimed = function () {

		gameData.lastPuzzleClaimed = this._lastPuzzleClaimedTime = TimeManager.getDate().getTime();
		saveDataService.savePlayerData(gameData.getSaveableGameData());
	};

	return new _FreePuzzleTimer();
}());
//******************************************************
//*****    Script Resource: FreePuzzleLogic
//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

var FreePuzzleLogic = (function () {

	var _FreePuzzleLogic = function () {};

	_FreePuzzleLogic.prototype.initialize = function () {
		FreePuzzleTimer.initialize();

		return Promise.resolve();
	};

	_FreePuzzleLogic.prototype.hasFreePuzzleAvailable = function () {
		var freePuzzleAvailable = false;

		if (FreePuzzleTimer.getTimeUntilFreePuzzleInMilliseconds() <= 0) {
			freePuzzleAvailable = true;
		}

		if (gameData.freePuzzles > 0) {
			freePuzzleAvailable = true;
		}

		return freePuzzleAvailable;
	};

	_FreePuzzleLogic.prototype.queueFreePuzzle = function () {
		gameData.freePuzzles++;
		saveDataService.savePlayerData(gameData.getSaveableGameData());
	};

	_FreePuzzleLogic.prototype.freePuzzleClaimed = function () {
		if (gameData.freePuzzles > 0) {
			gameData.freePuzzles--;
			saveDataService.savePlayerData(gameData.getSaveableGameData());
		} else {
			FreePuzzleTimer.registerFreePuzzleClaimed();
		}
	};

	return new _FreePuzzleLogic();
}());
