// The constructor for the dialog
/**
 * @constructor
 * @base tgfComponents.Base
 */
tgfComponents.DifficultySelectUnlockedState = function (properties, parent) {
	"use strict";
	this.name = "DifficultySelectUnlockedState"; // The name of the dialog

	this._parent = parent;
	this._date = this._parent.getDate();
	this._dailyData = UnlockDataManager.getDailyDataForDate(this._date);

	this.initialize(tgfSettings.dialogDefaults.difficultySelectUnlockedState);

	this._unlockButtonSettings = UnlockButtonUtility.getUnlockButtonSettingsForMethod(this._parent.getCurrentUnlockMethod());

	this._buttonConfigs = [{
		text: tgfDictionary.getText("DifficultyButtonBeginner"),
		difficulty: tgfSettings.game.difficulties.BEGINNER,
		spawnEffect: null
	}, {
		text: tgfDictionary.getText("DifficultyButtonEasy"),
		difficulty: tgfSettings.game.difficulties.EASY,
		spawnEffect: null
	}, {
		text: tgfDictionary.getText("DifficultyButtonMedium"),
		difficulty: tgfSettings.game.difficulties.NORMAL,
		spawnEffect: null
	}, {
		text: tgfDictionary.getText("DifficultyButtonHard"),
		difficulty: tgfSettings.game.difficulties.HARD,
		spawnEffect: null
	}, {
		text: tgfDictionary.getText("DifficultyButtonExpert"),
		difficulty: tgfSettings.game.difficulties.EXPERT,
		spawnEffect: null
	}];

	this._configureSpawnEffects();

	if (properties !== undefined) {
		this.setProperties(properties);
	}
};

// Inherit the base dialog
tgfComponents.inherit(tgfComponents.DifficultySelectUnlockedState, tgfComponents.Base);

// Processing required when preparing the dialog for use
tgfComponents.DifficultySelectUnlockedState.prototype.doPrepare = function () {

	for (var index = 0; index < this._buttonConfigs.length; index++) {
		this.addComponent(this._createDifficultyButton(this._buttonConfigs[index], index));
	}
};

tgfComponents.DifficultySelectUnlockedState.prototype._configureSpawnEffects = function () {

	for (var i = 0; i < this._buttonConfigs.length; i++) {
		var spawnEffect = [];
		for (var j = 0; j < this.buttonSpawnEffect.length; j++) {
			spawnEffect.push(DataUtil.shallowObjectClone(this.buttonSpawnEffect[j]));
		}
		spawnEffect[0].duration += i * this.spawnDelayModifier;
		spawnEffect[1].duration += i * this.spawnDurationModifier;

		this._buttonConfigs[i].spawnEffect = spawnEffect;
	}

	this._puzzleRestrictionTextEffect = [];
	for (var j = 0; j < this.buttonSpawnEffect.length; j++) {
		this._puzzleRestrictionTextEffect.push(DataUtil.shallowObjectClone(this.buttonSpawnEffect[j]));
	}
	this._puzzleRestrictionTextEffect[0].duration += this._buttonConfigs.length * this.spawnDelayModifier;
	this._puzzleRestrictionTextEffect[1].duration += this._buttonConfigs.length * this.spawnDurationModifier;
}

tgfComponents.DifficultySelectUnlockedState.prototype._createDifficultyButton = function (buttonConfiguration, index) {

	//Copy effect so we can modify parameters without affecting the others.
	var difficultyButton = this._createButtonComponent(buttonConfiguration, index);

	difficultyButton.addComponent(this._createButtonIcon(buttonConfiguration));

	if (this._dailyData && this._dailyData.hasPointsForDifficulty(buttonConfiguration.difficulty)) {
		difficultyButton.addComponent(this._createCheckmark());
	}

	return difficultyButton;
};

tgfComponents.DifficultySelectUnlockedState.prototype._createButtonComponent = function (buttonConfiguration, index) {

	return difficultyButton = new tgfComponents.Button({
		effects: buttonConfiguration.spawnEffect,
		repeatEffect: 1,
		xScale: 0,
		yScale: 0,
		fitToBox: false,
		fontUp: tgfSettings.fonts.greyButton,
		image: s_btn_difficulty,
		x: 0,
		y: this.firstButtonY + (index * this.verticalButtonDistance),
		width: 500,
		createFromSlices: true,
		text: buttonConfiguration.text,
		onClick: function (comp) {
			EventSystem.Global.dispatchEvent(UI_Event.START_LEVEL_BUTTON_CLICKED, buttonConfiguration.difficulty);
		}
	});
};

tgfComponents.DifficultySelectUnlockedState.prototype._createButtonIcon = function (buttonConfiguration) {
	 var difficultySubImage = buttonConfiguration.difficulty === tgfSettings.game.difficulties.BEGINNER ? 0 :
        buttonConfiguration.difficulty === tgfSettings.game.difficulties.EASY ? 1 :
        buttonConfiguration.difficulty === tgfSettings.game.difficulties.NORMAL ? 2 :
        buttonConfiguration.difficulty === tgfSettings.game.difficulties.HARD ? 3 :
        4;

	return new tgfComponents.Picture({
		image: s_btn_icon_difficulty,
		startSubImage: difficultySubImage,
		x: -212,
		y: -3
	});
};

tgfComponents.DifficultySelectUnlockedState.prototype._createCheckmark = function () {
	"use strict";
	return new tgfComponents.Picture({
		image: s_check,
		x: -213,
		y: -2,
		startSubImage: s_check.number - 1
	});
};

tgfComponents.DifficultySelectUnlockedState.prototype._createPlayButton = function (buttonComponent) {

	var playButton = new tgfComponents.Picture({
		width: 250,
		x: buttonComponent.x + 119,
		y: 0,
		createFromSlices: true,
		image: FreePuzzleLogic.hasFreePuzzleAvailable() ? s_button_default_green : this._unlockButtonSettings.image
	});

	var playText = new tgfComponents.Label({
		text: tgfDictionary.getText("PlayButton"),
		x: 10 + playButton.x - (playButton.width / 2),
		y: playButton.y,
		font: {
			fontFace: f_main_font.fontFace,
			fontSize: 34,
			fillColor: "white",
			baseline: "middle",
			align: "center"
		},
	});

	playButton.addComponent(playText);
	return playButton;
};

tgfComponents.DifficultySelectUnlockedState.prototype._createUnlockIcon = function () {

	var animation = this._unlockButtonSettings.animation;
	if (animation == unlockbutton_video) {
		animation = unlockbutton_round;
	}

	return new tgfComponents.SpineComponent({
		spineAnimation: animation,
		animationClips: ["animation_small lock on button"], // The animation names from the spine json
		play: false,
		repeat: true,
		hasDelay: true,
		delay: 350,
		xScale: 0.9,
		yScale: 0.9,
		x: 28,
		y: -3,
		updateWhileUnactive: true,
	});
};

tgfComponents.DifficultySelectUnlockedState.prototype.unlockMethodChanged = function () {

	this.free();
	this._stateContainer.removeAllComponents();
	this.show();
};

tgfComponents.DifficultySelectUnlockedState.prototype._createPuzzleRestrictionText = function () {

	var text = "";
	var timeIconComponent = null;
	// var spawnEffect = this.buttonSpawnEffect;

	if (!FreePuzzleLogic.hasFreePuzzleAvailable()) {
		text = StringUtil.format(tgfDictionary.getText("time_until_next_puzzle"), StringUtil.milliSecondsToHHMMSS(FreePuzzleTimer.getTimeUntilFreePuzzleInMilliseconds()));

		this._updateTimeToPuzzleText = true;
		this._updateTimeToPuzzleTextUpdateTime = 0;

		timeIconComponent = new tgfComponents.Picture({
			x: -90,
			y: 20,
			image: s_endscreen_icon_time
		});

	} else {
		text = tgfDictionary.getText("free_puzzle_message");
	}

	this._timeUntilNextFreePuzzle = new tgfComponents.Label({
		text: text,
		x: 0,
		y: 10,
		xScale: 0,
		yScale: 0,
		width: 500,
		splitLines: true,
		repeatEffect: 1,
		font: tgfSettings.fonts.textInTextbox,
		effects: this._puzzleRestrictionTextEffect
	});

	if (timeIconComponent) {
		this._timeUntilNextFreePuzzle.addComponent(timeIconComponent);
	}

	return this._timeUntilNextFreePuzzle;
}

tgfComponents.DifficultySelectUnlockedState.prototype.handleBeginStep = function (timePassed) {
	"use strict";

	if (this._updateTimeToPuzzleText) {
		this._updateTimeToPuzzleTextUpdateTime += timePassed;
		if (this._updateTimeToPuzzleTextUpdateTime >= 1000) {
			this._timeUntilNextFreePuzzle.text = StringUtil.format(tgfDictionary.getText("time_until_next_puzzle"), StringUtil.milliSecondsToHHMMSS(FreePuzzleTimer.getTimeUntilFreePuzzleInMilliseconds()));
			this._updateTimeToPuzzleTextUpdateTime = 0;
			this._timeUntilNextFreePuzzle.recreate();
		}
	}
};
