tgfComponents.DifficultySelectAnimationState = function (properties, parent) {

    this.name = "DifficultySelectLockedState"; // The name of the dialog

    this.initialize(tgfSettings.dialogDefaults.difficultySelectAnimationState);

    this._parent = parent;

    this.onUnlockAnimationComplete = new EventSystem.Local();
    this.onChangeDateVisual = new EventSystem.Local();

    if (properties !== undefined) {
        this.setProperties(properties);
    }
}

// Inherit the base dialog
tgfComponents.inherit(tgfComponents.DifficultySelectAnimationState, tgfComponents.Base);

// Processing required when preparing the dialog for use
tgfComponents.DifficultySelectAnimationState.prototype.doPrepare = function () {

    var self = this;
    this.animation = new tgfComponents.SpineComponent({
        spineAnimation: popup_unlock_big,
        animationClips: ["unlocked puzzle"], // The animation names from the spine json
        play: true,
        hasDelay: true,
        delay: 1000,
        x: tgfScale(0),
        y: tgfScale(tgfSettings.theme.calendarSelectDialog.bigLockY),
        updateWhileUnactive: true,
    });

    // Because the spine isn't initialised yet, we have to overwrite the doPrepare
    this.animation.doPrepare = function () {
        tgfComponents.SpineComponent.prototype.doPrepare.call(this);

        this.spineClone.setEventCallback("lock_open", function () {
            self.onChangeDateVisual.trigger();
        });
    };

    this.animation.onComplete = function () {
        this.onUnlockAnimationComplete.trigger();
    }.bind(this);

    this.addComponent(this.animation);
}
