tgfSettings.dialogDefaults.DifficultySelectTwoPartState = {
    _difficultySelectButtons: []
}

tgfComponents.DifficultySelectTwoPartState = function (properties, parent) {
    this.name = "DifficultySelectLockedStateTwoParts";

    this._parent = parent;

    this.initialize(tgfSettings.dialogDefaults.DifficultySelectTwoPartState);

    if (properties !== undefined) {
        this.setProperties(properties);
    }
};

tgfComponents.DifficultySelectTwoPartState.swapEffectIndex = Object.freeze({
    SWAP_NEXT: 1,
    SWAP_PREVIOUS: 3
});

tgfComponents.DifficultySelectTwoPartState.page = Object.freeze({
    DIFFICULTIES: 1,
    GAME_MODE: 3
});

tgfComponents.DifficultySelectTwoPartState.fadeEffect = Object.freeze({
    FADE_IN: 3,
    FADE_OUT: 1
});

tgfComponents.inherit(tgfComponents.DifficultySelectTwoPartState, tgfComponents.Base);

tgfComponents.DifficultySelectTwoPartState.prototype._getFadeEffect = function() {
    return [
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        },
        {
            effect: tgfEffects.fadeOut,
            duration: 0.1,
        },
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        },
        {
            effect: tgfEffects.fadeIn,
            duration: 0.1,
        },
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        }
    ];
};

tgfComponents.DifficultySelectTwoPartState.prototype._getWobbleEffect = function() {
    return [{
        effect: tgfEffects.nothing,
        duration: 1
    }, {
        effect: tgfEffects.scale,
        startScale: 1,
        endScale: 0.8,
        duration: 0.1,
        ease: tbEase.easeOutQuadratic,
    }, {
        effect: tgfEffects.scale,
        startScale: 0.8,
        endScale: 1,
        duration: 0.6,
        ease: tbEase.easeOutElastic
    }];
};

tgfComponents.DifficultySelectTwoPartState.prototype._getCurrentPage = function() {

    //in transition from page to page.
    if(this.gameModeContainer.isActive && this.difficultiesContainer.isActive) {
        return -1;
    }

    if(this.gameModeContainer.isActive) {
        return tgfComponents.DifficultySelectTwoPartState.page.GAME_MODE;
    }

    return tgfComponents.DifficultySelectTwoPartState.page.DIFFICULTIES;
};

tgfComponents.DifficultySelectTwoPartState.prototype._isDifficultyAlreadyPlayed = function(difficulty) {

    var _dailyData = UnlockDataManager.getDailyDataForDate(this._parent.getDate());

    if(!_dailyData) {
        return false;
    }

    return _dailyData.hasPointsForDifficulty(difficulty);
};

tgfComponents.DifficultySelectTwoPartState.prototype._createPlayFriendlyButton = function (yPosition) {

    var self = this;
    var playFriendlyButton = new tgfComponents.Button({
        width: 450,
        height: 98,
        x: 0,
        y: yPosition,
        createFromSlices: true,
        image: s_button_default_green,
        onClick: function() {

            var difficulty = self._getSelectedDifficulty();

            EventSystem.Global.dispatchEvent(UI_Event.START_FRIENDLY_MATCH_BUTTON_CLICKED, difficulty);

            SudokuAnalytics.reportPlayFriendlyUXEvent(SudokuAnalytics.playFriendly.uxEvents.BUTTON_PLAY_FRIENDLY);
        }.bind(this),
        effects: this._getWobbleEffect()
    });

    var playText = new tgfComponents.Label({
        text: tgfDictionary.getText("difficulty_game_friendly_btn"),
        x: 0,
        y: 0,
        font: tgfSettings.fonts.playFriendlyButtonFont,
    });

    playFriendlyButton.addComponent(playText);

    var playIcon = new tgfComponents.Picture({
        image: s_btn_icon_playfriendly,
        x: (-playFriendlyButton.width * 0.5) + 46,
        y: -3,
    });

    playFriendlyButton.addComponent(playIcon);

    return playFriendlyButton;
};

tgfComponents.DifficultySelectTwoPartState.prototype._createPlaySoloButton = function (yPosition) {

    var self = this;
    var playSolo = new tgfComponents.Button({
        width: 450,
        height: 78,
        x: 0,
        y: yPosition,
        createFromSlices: true,
        image: s_button_default_gray,
        onClick: function() {

            var difficulty = self._getSelectedDifficulty();

            EventSystem.Global.dispatchEvent(UI_Event.START_LEVEL_BUTTON_CLICKED, difficulty);

            SudokuAnalytics.reportPlayFriendlyUXEvent(SudokuAnalytics.playFriendly.uxEvents.BUTTON_PLAY_SOLO);
        }.bind(this)
    });

    var playText = new tgfComponents.Label({
        text: tgfDictionary.getText("difficulty_game_solo_btn"),
        x: 0,
        y: 0,
        font: tgfSettings.fonts.playSoloButtonFont,
    });

    playSolo.addComponent(playText);

    var playSoloUnlockMethodPriorityConfig = this._parent.getPlaySoloUnlockMethodPriorityConfig();

    if(!VipMembership.isActive && ObjectUtil.hasValueInObject(playSoloUnlockMethodPriorityConfig, Unlock_Method.ADS)) {
        var videoIcon = new tgfComponents.Picture({
            image: s_icon_film_play,
            x: (-playSolo.width * 0.5) + 46,
            y: -2,
        });

        playSolo.addComponent(videoIcon);
    }

    return playSolo;
};

tgfComponents.DifficultySelectTwoPartState.prototype._createGameModeContainer = function (xOffset, yPosition) {
    var container = new tgfComponents.Container({
        x: xOffset,
        y: yPosition,
        effects: this._getFadeEffect()
    });

    var header = new tgfComponents.Label({
        font: tgfSettings.fonts.difficultySelectionScreenHeaders,
        text: tgfDictionary.getText("difficulty_game_header"),
        splitLines: false,
        fitToBox: false,
        x: 0,
        y: 90,
    });

    container.addComponent(header);

    container.addComponent(this._createPlayFriendlyButton(165));

    container.addComponent(this._createPlaySoloButton(264));

    return container;
};

tgfComponents.DifficultySelectTwoPartState.prototype._createDifficultyButton = function (yPosition, difficulty) {

    var difficultyButton = this._createButtonComponent(yPosition, difficulty);

    difficultyButton.isSelected = false;
    difficultyButton.difficulty = difficulty;

    difficultyButton.addComponent(this._createButtonIcon(difficulty));

    if (this._isDifficultyAlreadyPlayed(difficulty)) {
        difficultyButton.addComponent(this._createCheckmark());
    }

    return difficultyButton;
};

tgfComponents.DifficultySelectTwoPartState.prototype._getDifficultyText = function (difficulty) {
    var difficultyDictKey = difficulty === tgfSettings.game.difficulties.BEGINNER ? "DifficultyButtonBeginner" :
        difficulty === tgfSettings.game.difficulties.EASY ? "DifficultyButtonEasy" :
        difficulty === tgfSettings.game.difficulties.NORMAL ? "DifficultyButtonMedium" :
        difficulty === tgfSettings.game.difficulties.HARD ? "DifficultyButtonHard" :
        "DifficultyButtonExpert";

    return tgfDictionary.getText(difficultyDictKey);
};

tgfComponents.DifficultySelectTwoPartState.prototype._isDifficultyLocked = function (difficulty) {

    if(VipMembership.isActive) {
        return false;
    }

    if(difficulty !== tgfSettings.game.difficulties.EXPERT) {
        return false;
    }

    var hasPlayerPlayedHard = this._isDifficultyAlreadyPlayed(tgfSettings.game.difficulties.HARD);

    var hasPlayedExpert = this._isDifficultyAlreadyPlayed(tgfSettings.game.difficulties.EXPERT);

    return !hasPlayerPlayedHard && !hasPlayedExpert;
};

tgfComponents.DifficultySelectTwoPartState.prototype._createButtonComponent = function (yPosition, difficulty) {

    var self = this;

    if(difficulty === tgfSettings.game.difficulties.EXPERT && !this._isDifficultyAlreadyPlayed(difficulty) && !VipMembership.isActive) {
        var lock = new tgfComponents.SpineComponent({
            spineAnimation: unlock_button,
            animationClips: ["animation_unlock_button"],
            play: false,
            speed: 0,
            repeat: false,
            x: 200,
            y: 0,
        });
    }

    var container = new tgfComponents.Container({
        x: 0,
        y: yPosition,
        effects: [
            {
                effect: tgfEffects.nothing,
                duration: 1
            }
        ],
        onEffectEnd: function() {
            if(lock && lock.spineClone.speed === 0 && !self._isDifficultyLocked(difficulty)) {
                lock.spineClone.speed = 1;
            }
        }
    });

	var difficultyButton = new tgfComponents.Button({
        fitToBox: false,
        fontUp: tgfSettings.fonts.greyButton,
        image: s_btn_difficulty,
        x: 0,
        y: 0,
        width: 500,
        createFromSlices: true,
        text: this._getDifficultyText(difficulty),
        onClick: function (comp) {

            self._deselectedDifficulties();

            if(self._isDifficultyLocked(difficulty)) {
                self._parent.showToolTip();
                return;
            }

            if(lock) {
                lock.spineClone.speed = 20;
            }

            container.isSelected = true;
            self._swapNext();
            self._difficultyIndicator.setDifficulty(difficulty);
        }
    });

    container.addComponent(difficultyButton);

    if(lock) {
        container.addComponent(lock);
    }

    return container;
};

tgfComponents.DifficultySelectTwoPartState.prototype._createButtonIcon = function (difficulty) {

    var difficultySubImage = difficulty === tgfSettings.game.difficulties.BEGINNER ? 0 :
        difficulty === tgfSettings.game.difficulties.EASY ? 1 :
        difficulty === tgfSettings.game.difficulties.NORMAL ? 2 :
        difficulty === tgfSettings.game.difficulties.HARD ? 3 :
        4;

    return new tgfComponents.Picture({
        image: s_btn_icon_difficulty,
        startSubImage: difficultySubImage,
        x: -212,
        y: -3
    });
};

tgfComponents.DifficultySelectTwoPartState.prototype._createCheckmark = function () {

    return new tgfComponents.Picture({
        image: s_check,
        x: -213,
        y: -2,
        startSubImage: s_check.number - 1
    });
};


tgfComponents.DifficultySelectTwoPartState.prototype._createDifficultiesContainer = function (xOffset, yOffset) {

    var difficulties = DifficultyUtil.getDifficulties(this._parent.getDate());
    var totalDifficulties = ObjectUtil.getTotalProperties(difficulties);
    var difficultyHeight = 88;
    var yPosition = (difficultyHeight * (4 - totalDifficulties));

    var container = new tgfComponents.Container({
        x: xOffset,
        y: totalDifficulties === 5 ? yOffset : yOffset - 50,
        effects: this._getFadeEffect()
    });

    for(var difficultyKey in difficulties) {

        var difficulty = difficulties[difficultyKey];
        var difficultySelectButton = this._createDifficultyButton(yPosition, difficulty);

        container.addComponent(difficultySelectButton);
        this._difficultySelectButtons.push(difficultySelectButton);

        yPosition+= difficultyHeight;
    }

    return container;
};

tgfComponents.DifficultySelectTwoPartState.prototype._getSwapEffects = function (startX, endX, swapDuration) {
    return [
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        },
        {
            effect: tgfEffects.move,
            startX: startX,
            endX: endX,
            duration: swapDuration,
            swapEffect: tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_NEXT
        },
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        },
        {
            effect: tgfEffects.move,
            startX: endX,
            endX: startX,
            duration: swapDuration,
            swapEffect: tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_PREVIOUS
        },
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        }
    ];
};

tgfComponents.DifficultySelectTwoPartState.prototype._deselectedDifficulties = function () {
    for(var i = 0; i < this._difficultySelectButtons.length; i++){
        this._difficultySelectButtons[i].isSelected = false;
    }
};

tgfComponents.DifficultySelectTwoPartState.prototype._getSelectedDifficulty = function () {

    for(var i = 0; i < this._difficultySelectButtons.length; i++){
        if(this._difficultySelectButtons[i].isSelected) {
            return this._difficultySelectButtons[i].difficulty;
        }
    }

    return null;
};

tgfComponents.DifficultySelectTwoPartState.prototype._swapNext = function () {

    if(this._getCurrentPage() !== tgfComponents.DifficultySelectTwoPartState.page.DIFFICULTIES) {
        return;
    }

    this._parent.hideToolTip();

    this.swapContainer.startSubEffect(tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_NEXT);
};

tgfComponents.DifficultySelectTwoPartState.prototype._swapPrevious = function () {

    if(this._getCurrentPage() !== tgfComponents.DifficultySelectTwoPartState.page.GAME_MODE) {
        return
    }

    this._parent.hideToolTip();

    this.swapContainer.startSubEffect(tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_PREVIOUS);
};

tgfComponents.DifficultySelectTwoPartState.prototype._onSwapStart = function (comp, effect) {

    if(effect.swapEffect === tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_NEXT) {
        this.swapContainer.addComponent(this.gameModeContainer);
        this.gameModeContainer.activate(true);
        this.gameModeContainer.startSubEffect(tgfComponents.DifficultySelectTwoPartState.fadeEffect.FADE_IN);
        this.difficultiesContainer.startSubEffect(tgfComponents.DifficultySelectTwoPartState.fadeEffect.FADE_OUT);
        this._difficultyNode.setActive(false);
        this._gameModeNode.setActive(true);
    }

    if(effect.swapEffect === tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_PREVIOUS) {
        this.swapContainer.addComponent(this.difficultiesContainer);
        this.difficultiesContainer.activate(true);
        this.difficultiesContainer.startSubEffect(tgfComponents.DifficultySelectTwoPartState.fadeEffect.FADE_IN);
        this.gameModeContainer.startSubEffect(tgfComponents.DifficultySelectTwoPartState.fadeEffect.FADE_OUT);
        this._deselectedDifficulties();
        this._gameModeNode.setActive(false);
        this._difficultyNode.setActive(true);
        this._backButton.startSubEffect(tgfComponents.DifficultySelectTwoPartState.fadeEffect.FADE_OUT);
        this._difficultyIndicator.fadeOut();
    }
};

tgfComponents.DifficultySelectTwoPartState.prototype._onSwapEnd = function (comp, effect) {

    if(effect.swapEffect !== tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_NEXT &&
        effect.swapEffect !== tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_PREVIOUS) {
        return;
    }

    if(effect.swapEffect === tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_NEXT) {
        this.swapContainer.removeComponent(this.difficultiesContainer);
        this.difficultiesContainer.deactivate(true);
        this._backButton.startSubEffect(tgfComponents.DifficultySelectTwoPartState.fadeEffect.FADE_IN);
        this._difficultyIndicator.fadeIn();
    }

    if(effect.swapEffect === tgfComponents.DifficultySelectTwoPartState.swapEffectIndex.SWAP_PREVIOUS) {
        this.swapContainer.removeComponent(this.gameModeContainer);
        this.gameModeContainer.deactivate(true);
    }

    if(this._getCurrentPage() === tgfComponents.DifficultySelectTwoPartState.page.DIFFICULTIES) {
        SudokuAnalytics.reportPlayFriendlyScreen(SudokuAnalytics.playFriendly.screens.DIFFICULTY_SELECT_SCREEN);
    }

    if(this._getCurrentPage() === tgfComponents.DifficultySelectTwoPartState.page.GAME_MODE) {
        SudokuAnalytics.reportPlayFriendlyScreen(SudokuAnalytics.playFriendly.screens.GAME_MODE_SCREEN);
    }
};

tgfComponents.DifficultySelectTwoPartState.prototype._createBackButton = function () {

    var self = this;

    return new tgfComponents.Button({
        image: s_difficulty_back,
        x: (-this._parent.width * 0.5) + 70,
        y: (this._parent.height * 0.5) - 76,
        onClick: function() {

            self._swapPrevious();

            SudokuAnalytics.reportPlayFriendlyUXEvent(SudokuAnalytics.playFriendly.uxEvents.DIFFICULTY_SELECT_BUTTON_BACK);
        },
        alpha: 0,
        effects: this._getFadeEffect()
    });
};

tgfComponents.DifficultySelectTwoPartState.prototype._getDifficultiesPlayed = function () {
    var difficultiesPlayed = [];

    for(var difficultyKey in tgfSettings.game.difficulties) {

        if(!this._isDifficultyAlreadyPlayed(tgfSettings.game.difficulties[difficultyKey])) {
            continue;
        }

        difficultiesPlayed.push(tgfSettings.game.difficulties[difficultyKey]);
    }

    return difficultiesPlayed;
};

tgfComponents.DifficultySelectTwoPartState.prototype.doPrepare = function () {

    var betweenPages = tgfGraphics.visibleWidth;

    this.swapContainer = new tgfComponents.Container({
        effects: this._getSwapEffects(0, -betweenPages, 0.2),
        onSubEffectStart: this._onSwapStart.bind(this),
        onSubEffectEnd: this._onSwapEnd.bind(this)
    });

    this.addComponent(this.swapContainer);

    this.difficultiesContainer = this._createDifficultiesContainer(0, 20);
    this.swapContainer.addComponent(this.difficultiesContainer);

    this.gameModeContainer = this._createGameModeContainer(betweenPages, -52);
    this.swapContainer.addComponent(this.gameModeContainer);

    this._backButton = this._createBackButton();
    this.addComponent(this._backButton);

    this._difficultyIndicator = new tgfComponents.DifficultyIndicatorComponent({
        x: 0,
        y: -126,
        xScale: 0.9,
        yScale: 0.9,
        difficultiesPlayed: this._getDifficultiesPlayed()
    });

    this.addComponent(this._difficultyIndicator);

    this._difficultyNode = new tgfComponents.PageIndicatorComponent({
        x: -12,
        y: (this._parent.height * 0.5) - 60,
        isActive: true
    });

    this.addComponent(this._difficultyNode);

    this._gameModeNode = new tgfComponents.PageIndicatorComponent({
        x: 12,
        y:  (this._parent.height * 0.5) - 60,
        isActive: false
    });

    this.addComponent(this._gameModeNode);
};

tgfComponents.DifficultySelectTwoPartState.prototype.onShow = function() {
    this.swapContainer.removeComponent(this.gameModeContainer);

    if(this._getCurrentPage() === tgfComponents.DifficultySelectTwoPartState.page.DIFFICULTIES) {
        SudokuAnalytics.reportPlayFriendlyScreen(SudokuAnalytics.playFriendly.screens.DIFFICULTY_SELECT_SCREEN);
    }

    if(this._getCurrentPage() === tgfComponents.DifficultySelectTwoPartState.page.GAME_MODE) {
        SudokuAnalytics.reportPlayFriendlyScreen(SudokuAnalytics.playFriendly.screens.GAME_MODE_SCREEN);
    }
};
//******************************************************
//*****    Script Resource: DifficultyIndicatorComponent
//******************************************************

// *********************************
// CoolGames Builder JavaScript file
// *********************************

tgfSettings.componentDefaults.difficultyIndicatorComponent = {
    difficultiesPlayed: [],

    startAlpha: 0,

    startDifficulty: null
};

tgfComponents.DifficultyIndicatorComponent = function(properties) {

    this.initialize(tgfSettings.componentDefaults.difficultyIndicatorComponent);

    if (properties !== undefined) { 
        this.setProperties(properties); 
    }
};

// Inherit the base dialog
tgfComponents.inherit(tgfComponents.DifficultyIndicatorComponent, tgfComponents.Base);

tgfComponents.DifficultyIndicatorComponent.prototype._isDifficultyAlreadyPlayed = function(difficulty) {
    return ObjectUtil.hasValueInObject(this.difficultiesPlayed, difficulty);
};

tgfComponents.DifficultyIndicatorComponent.prototype._getFadeEffect = function() {
    return [
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        },
        {
            effect: tgfEffects.fadeOut,
            duration: 0.1,
        },
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        },
        {
            effect: tgfEffects.fadeIn,
            duration: 0.1,
        },
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        }
    ];
};

tgfComponents.DifficultyIndicatorComponent.prototype._getDifficultyImage = function (difficulty) {
    return difficulty === tgfSettings.game.difficulties.BEGINNER ? s_difficulty_blue : 
        difficulty === tgfSettings.game.difficulties.EASY ? s_difficulty_green : 
        difficulty === tgfSettings.game.difficulties.NORMAL ? s_difficulty_yellow :
        difficulty === tgfSettings.game.difficulties.HARD ? s_difficulty_red :
        s_difficulty_purple;
};

tgfComponents.DifficultyIndicatorComponent.prototype.doPrepare = function() {
    this._container = new tgfComponents.Container({
        x: 0,
        y: 0,
        alpha: this.startAlpha,
        effects: this._getFadeEffect()
    });

    this.addComponent(this._container);

    this.difficulties = [];

    for(var difficultyKey in tgfSettings.game.difficulties) {

        var difficulty = tgfSettings.game.difficulties[difficultyKey];

        this.difficulties[difficultyKey] = new tgfComponents.Picture({
            image: this._getDifficultyImage(difficulty),
            x: 0,
            y: 0,
            alpha: this.startDifficulty === difficulty ? 1 : 0
        });

        this._container.addComponent(this.difficulties[difficultyKey]);
    }

    this._checkMark = new tgfComponents.Picture({
        image: s_check,
        x: 0,
        y: 0,
        alpha: 0,
        startSubImage: s_check.number - 1
    });

    this._container.addComponent(this._checkMark);

    if(this.startDifficulty != null) {
        this.setDifficulty(this.startDifficulty);
    }
};

tgfComponents.DifficultyIndicatorComponent.prototype.fadeIn = function() {
    this._container.startSubEffect(3);
};

tgfComponents.DifficultyIndicatorComponent.prototype.fadeOut = function() {
    this._container.startSubEffect(1);
};

tgfComponents.DifficultyIndicatorComponent.prototype.setDifficulty = function(difficulty) {
    for(var difficultyKey in this.difficulties) {
        this.difficulties[difficultyKey].alpha = 0;
    }

    for(var difficultyKey in tgfSettings.game.difficulties) {
        if(tgfSettings.game.difficulties[difficultyKey] !== difficulty) {
            continue;
        }

        this.difficulties[difficultyKey].alpha = 1;
    }

    this._checkMark.alpha = this._isDifficultyAlreadyPlayed(difficulty) ? 1 : 0;
};
