tgfSettings.componentDefaults.pageIndicatorComponent = {
    isActive: true
};

tgfComponents.PageIndicatorComponent = function(properties) {

    this.initialize(tgfSettings.componentDefaults.pageIndicatorComponent);

    if (properties !== undefined) { 
        this.setProperties(properties); 
    }
};

// Inherit the base dialog
tgfComponents.inherit(tgfComponents.PageIndicatorComponent, tgfComponents.Base);

tgfComponents.PageIndicatorComponent.prototype._getFadeEffect = function() {
    return [
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        },
        {
            effect: tgfEffects.fadeOut,
            duration: 0.1,
        },
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        },
        {
            effect: tgfEffects.fadeIn,
            duration: 0.1,
        },
        {
            effect: tgfEffects.nothing,
            duration: 9999999
        }
    ];
};

tgfComponents.PageIndicatorComponent.prototype.doPrepare = function() {

    this._selected = new tgfComponents.Picture({
        image: s_difficulty_page_on,
        x: 0,
        y: 0,
        alpha: this.isActive ? 1 : 0,
        effects: this._getFadeEffect()
    });

    this.addComponent(this._selected);

    this._deselected = new tgfComponents.Picture({
        image: s_difficulty_page_off,
        x: 0,
        y: 0,
        alpha: !this.isActive ? 1 : 0,
        effects: this._getFadeEffect()
    });

    this.addComponent(this._deselected);
};

tgfComponents.PageIndicatorComponent.prototype.setActive = function(isActive) {
    this.isActive  = isActive;

    this._selected.startSubEffect(this.isActive ? 3 : 1);
    this._deselected.startSubEffect(!this.isActive ? 3 : 1);
};
