var HowToPlayController = {};
HowToPlayController._isInitialized = false;

HowToPlayController.initialize = function() {
    HowToPlayController._isInitialized = true;
    this._addEventListeners();
};

HowToPlayController.isInitialize = function() {
    return HowToPlayController._isInitialize;
};

HowToPlayController._addEventListeners = function() {
    EventSystem.Global.addEventListener(UI_Event.HOW_TO_PLAY_CLICKED, this._showHowToPlayPopup, this);
    EventSystem.Global.addEventListener(UI_Event.HOW_TO_PLAY_DIALOG_CLOSED, this._onHowToPlayDialogClosed, this);
};

HowToPlayController._showHowToPlayPopup = function() {

    EventSystem.Global.dispatchEvent(Level_Event.LEVEL_PAUSED);

    var howToPlay = new tgfDialogs.HowToPlayDialog({});

    howToPlay.show();
};

HowToPlayController._onHowToPlayDialogClosed = function(dialog) {
    EventSystem.Global.dispatchEvent(Level_Event.LEVEL_RESUMED);

    if(dialog.isTutorialCompleted()) {
        SudokuAnalytics.reportTutorialComplete("onboarding_lite", dialog.getCurrentPage());
//        MessyAnalytics.reportTutorialComplete("onboarding_lite", dialog.getCurrentPage());
    } else {
        SudokuAnalytics.reportTutorialSkip("onboarding_lite", dialog.getCurrentPage());
     //   MessyAnalytics.reportTutorialSkip("onboarding_lite", dialog.getCurrentPage());
    }
};
