// *********************************
// CoolGames Builder JavaScript file
// *********************************

var PlayFriendlyController = {};
PlayFriendlyController._currentMatchData = null;
PlayFriendlyController.isInitialized = false;

PlayFriendlyController.customUpdateTypes = Object.freeze({
    NEW_INVITE: "NEW_INVITE",
    GAME_END: "GAME_END"
});

PlayFriendlyController.initialize = function() {

    this._popupThrobber = new tgfDialogs.ThrobberDialog({
        loadingText: ""
    });

    return new Promise(function(resolve, reject){
            PlayFriendlyController._checkEntryPoint()
                .then(function() {
                    PlayFriendlyController._cleanupCreatedMatchesData();

                    PlayFriendlyController._setEvents();

                    PlayFriendlyController.isInitialized = true;
                    resolve();
                })
                .catch(function() {
                    reject();
                });
        });
};

PlayFriendlyController.getCurrentMatchData = function() {
    return PlayFriendlyController._currentMatchData;
};

PlayFriendlyController._setEvents = function() {
    EventSystem.Global.addEventListener(System_Event.LEVEL_START, this._prepareStartMatchAnimation, this);
    EventSystem.Global.addEventListener(Play_Friendly_Events.END_BEFORE_DOUBLE_SCORE, this._scheduleEndMatchUpdate, this);
    EventSystem.Global.addEventListener(Play_Friendly_Events.END_AFTER_DOUBLE_SCORE, this._prepareResults, this);
    EventSystem.Global.addEventListener(Play_Friendly_Events.SHARE, this._shareMatch, this);
    EventSystem.Global.addEventListener(System_Event.SHOW_MAIN_MENU, this._removeResultScreen, this);
    EventSystem.Global.addEventListener(System_Event.LEVEL_QUIT, this._deactivate, this);
};

PlayFriendlyController._shareMatch = function() {
    this._popupThrobber.show();

    var self = this;

    PlayFriendlyGameUpdateService.sendShare(PlayFriendlyController._currentMatchData)
        .then(function() {
            self._popupThrobber.hide();
        })
        .catch(function() {
            self._popupThrobber.hide();
        });
};

PlayFriendlyController._removeResultScreen = function() {
    if(this.playFriendlyResultDialog) {
        this.playFriendlyResultDialog.disappear();
        this._deactivate();
    }
};

PlayFriendlyController._deactivate = function() {
    PlayFriendlyController._currentMatchData = null;
};

PlayFriendlyController._prepareStartMatchAnimation = function() {

    if(!PlayFriendlyController.isFriendlyMatchActive()) {
        return;
    }

    EventSystem.Global.dispatchEvent(Level_Event.LEVEL_PAUSED);

    if(!PlayFriendlyController._currentMatchData.hasOpponentData()) {
        PlayFriendlyController._showStartMatchAnimation(null);
        return;
    }

    var self = this;

    var opponentId = PlayFriendlyController._currentMatchData.getOpponentId();

    LeaderboardManager.getConnectedPlayerDataById(opponentId)
        .then(function(playerData) {
            self._popupThrobber.hide();
            
            PlayFriendlyController._showStartMatchAnimation(playerData.getProfilePicture(false), playerData.getName(), playerData.getRank());
        }, function() {
            PlayFriendlyController._showStartMatchAnimation(null, null, null);
        });
};

PlayFriendlyController._showStartMatchAnimation = function(opponentProfilePicture, opponentName, opponentRank) {
    var playFriendlyStartDialog = new tgfDialogs.PlayFriendlyStartDialog({
        opponentProfilePicture: opponentProfilePicture,
        opponentName: opponentName,
        opponentRank: opponentRank,
        onAnimationEnd: function() {
            EventSystem.Global.dispatchEvent(Level_Event.LEVEL_RESUMED);

            playFriendlyStartDialog.hide();
            playFriendlyStartDialog.free();
        }
    });

    playFriendlyStartDialog.show();
};

PlayFriendlyController.createMatch = function(date, difficulty) {

    var self = this;

    this._popupThrobber.show();

    return new Promise(function (resolve, reject) {
        PlayFriendlyController._createMatchContext()
            .then(function(context) {
                var matchData = PlayFriendlyController._createAndSetMatch(context, date, difficulty);

                if(matchData) {
                    resolve(matchData);
                } else {
                    reject();
                }

                self._popupThrobber.hide();
            })
            .catch(function(reason) {

                if(reason.code === "SAME_CONTEXT") {
                    messagingPlatformService.getCurrentContext()
                        .then(function (context) {
                            var matchData = PlayFriendlyController._createAndSetMatch(context, date, difficulty);

                            if(matchData) {
                                resolve(matchData);
                            } else {
                                reject();
                            }

                            self._popupThrobber.hide();
                        });

                    return;
                }

                self._popupThrobber.hide();

                reject(reason);
            })
    });
};

PlayFriendlyController._createAndSetMatch = function(context, date, difficulty) {

    if(PlayFriendlyController._isContextAlreadyPlayedToday(context.getId())) {
        PlayFriendlyController._showPlayerAlreadyInvitedOpponentWarning();
        return null;
    }

    var matchData = new PlayFriendlyMatchData();
    matchData.createWithContext(context, date, difficulty);

    PlayFriendlyController._setMatchData(matchData);
    PlayFriendlyController._scheduleInvite();

    return matchData;
};

PlayFriendlyController.isFriendlyMatchActive = function() {
    return !!PlayFriendlyController._currentMatchData;
};

PlayFriendlyController.playActiveFriendlyMatch = function() {

    if(PlayFriendlyController._currentMatchData.getTurnOfMatch() === PlayFriendlyMatchData.turns.GAME_FINISHED) {
        EventSystem.Global.dispatchEvent(System_Event.SHOW_MAIN_MENU);
        PlayFriendlyController._prepareResults();
        return;
    }

    if(PlayFriendlyController._isMatchAlreadyPlayed(PlayFriendlyController._currentMatchData)){
        EventSystem.Global.dispatchEvent(System_Event.SHOW_MAIN_MENU);
        PlayFriendlyController._showMatchAlreadyPlayedWarning();
        PlayFriendlyController._deactivate();
        return;
    }

    var connectedFriend = PlayFriendlyController._currentMatchData.getOpponentId();

    messagingPlatformService.createContext([connectedFriend])
        .then(function (context) {

            PlayFriendlyController._currentMatchData.setContext(context);

            PlayFriendlyController._startMatch(PlayFriendlyController._currentMatchData);
        })
        .catch(function(reason) {

            if(reason === "SAME_CONTEXT") {

                if(!PlayFriendlyController._currentMatchData.hasContext()) {
                    messagingPlatformService.getCurrentContext()
                        .then(function (context) {
                            PlayFriendlyController._currentMatchData.setContext(context);
                            PlayFriendlyController._startMatch(PlayFriendlyController._currentMatchData);
                        });
                } else {
                    PlayFriendlyController._startMatch(PlayFriendlyController._currentMatchData);
                }

                return;
            }
            
            EventSystem.Global.dispatchEvent(System_Event.SHOW_MAIN_MENU);
        });
};

PlayFriendlyController._startMatch = function(matchData) {
    //Friend can send a day that you have locked, this will unlock the day for you
    if (!UnlockDataManager.getDailyDataForDate(matchData.getDate())) {
        UnlockDataManager.unlockDay(matchData.getDate());
    }

    EventSystem.Global.dispatchEvent(System_Event.START_PUZZLE_REQUESTED, matchData.getDate(), matchData.getDifficulty());
};

PlayFriendlyController._scheduleEndMatchUpdate = function(score, time, date, difficulty) {
    PlayFriendlyController._endMatch(PlayFriendlyController._currentMatchData, score, time, date, difficulty, GameUpdateStrategy.LAST)
        .then(function() {
            console.log("[PlayFriendlyController] Scheduled end match update");
        });
};

PlayFriendlyController._prepareResults = function(score, time, date, difficulty) {

    this._popupThrobber.show();

    var self = this;

    PlayFriendlyController._endMatch(PlayFriendlyController._currentMatchData, score, time, date, difficulty, GameUpdateStrategy.IMMEDIATE)
        .then(function(matchDataResult) {
            PlayFriendlyController._currentMatchData = matchDataResult;

            var opponentId = matchDataResult.getOpponentId();

            LeaderboardManager.getConnectedPlayerDataById(opponentId)
                .then(function(opponentPlayerData) {
                    self._showResult(matchDataResult, opponentPlayerData);

                    self._popupThrobber.hide();
                }, function() {
                    self._showResult(matchDataResult, null);

                    self._popupThrobber.hide();
                });
        });
};

PlayFriendlyController._showResult = function(matchDataResult, opponentPlayerData) {
    var headerDictionaryKey = "solo_result_header";
    var subHeaderDictionaryKey = "solo_result_sub_txt";

    if(matchDataResult.hasContext()) {
        headerDictionaryKey = "friendly_result_header";
        subHeaderDictionaryKey = "friendly_end_result_sub_txt";
    } 
    
    if(matchDataResult.getTurnOfMatch() === PlayFriendlyMatchData.turns.GAME_FINISHED) {
        headerDictionaryKey = matchDataResult.hasPlayerWon() ? "friendly_end_result_header1" : "friendly_end_result_header2";
        subHeaderDictionaryKey = "friendly_end_result_sub_txt";
    }

    var nextDayDailyData = UnlockDataManager.getNextDayDailyData(matchDataResult.getDate());

    this.playFriendlyResultDialog = new tgfDialogs.PlayFriendlyResultDialog({
        playFriendlyMatchData: matchDataResult,
        opponentPlayerData: opponentPlayerData,
        headerDictionaryKey: headerDictionaryKey,
        subHeaderDictionaryKey: subHeaderDictionaryKey,
        showLockAnimation: nextDayDailyData || VipMembership.isActive ? false : true,
    });

    this.playFriendlyResultDialog.show();
};

PlayFriendlyController._endMatch = function(matchData, score, time, date, difficulty, strategy) {

    if(!matchData){
        matchData = new PlayFriendlyMatchData();
        matchData.createWithoutContext(score, time, date, difficulty);
        return Promise.resolve(matchData);
    }

    var data = matchData.getData();
    data = JSON.parse(JSON.stringify(data));
    matchData = new PlayFriendlyMatchData(data);

    if(matchData.getTurnOfMatch() === PlayFriendlyMatchData.turns.GAME_FINISHED) {
        return Promise.resolve(matchData);
    }

    return new Promise(function(resolve) {
        matchData.setPlayersMatchData(score, time);

        var turn = matchData.getTurnOfMatch();

        if(turn === PlayFriendlyMatchData.turns.OPPONENT_TURN) {
            PlayFriendlyController._saveMatchIsCreatedToday(matchData);
        }

        PlayFriendlyController._saveMatchAsPlayed(matchData);

        var customUpdateType = turn === PlayFriendlyMatchData.turns.GAME_FINISHED ? 
            PlayFriendlyController.customUpdateTypes.GAME_END : 
            PlayFriendlyController.customUpdateTypes.NEW_INVITE;

        PlayFriendlyGameUpdateService.sendUpdate(matchData, customUpdateType, strategy)
            .then(function() {
                resolve(matchData);
            })
            .catch(function() {
                resolve(matchData);
            });
    });
    
};

PlayFriendlyController._setMatchData = function(friendlyMatchData) {
    PlayFriendlyController._currentMatchData = friendlyMatchData;
};

PlayFriendlyController._createMatchContext = function() {
    return new Promise(function (resolve, reject) {
        PlayFriendlyController._startMatchWithConnectedFriend()
            .then(function(context) {

                SudokuAnalytics.reportPlayFriendlyUXEvent(SudokuAnalytics.playFriendly.uxEvents.FRIENDLY_RANDOM_ACCEPT);

                if(PlayFriendlyController._isContextAlreadyPlayedToday(context.getId())) {
                    PlayFriendlyController._startMatchByPlayerChoosing()
                        .then(function(context) {
                            resolve(context);
                        })
                        .catch(function(reason) {
                            reject(reason);
                        });
                } else {
                    resolve(context);
                }

            })
            .catch(function(reason) {

                if (reason && reason.code === "USER_INPUT") {
                    SudokuAnalytics.reportPlayFriendlyUXEvent(SudokuAnalytics.playFriendly.uxEvents.FRIENDLY_RANDOM_CANCEL);
                }

                PlayFriendlyController._startMatchByPlayerChoosing()
                    .then(function(context) {
                        resolve(context);
                    })
                    .catch(function(reason) {
                        reject(reason);
                    });
            });
    });
};

PlayFriendlyController._startMatchWithConnectedFriend = function() {
    return new Promise(function (resolve, reject) {
        PlayFriendlyController._getRandomConnectedFriend()
            .then(function(connectedFriendId) {
                messagingPlatformService.createContext([connectedFriendId])
                    .then(function (context) {
                        SudokuAnalytics.reportChooseContextBy(SudokuAnalytics.playFriendly.chooseContextBy.FRIENDLY_RANDOM, true);

                        var connectedFriendInContext = false;
                        for(var i = 0; i < context._players.length; i++) {
                            if(context._players[i].id === connectedFriendId) {
                                connectedFriendInContext = true;
                            }
                        }

                        if(!connectedFriendInContext) {
                            context._players.push({
                                id: connectedFriendId
                            });
                        }

                        resolve(context);
                    })
                    .catch(function(reason) {
                        SudokuAnalytics.reportChooseContextBy(SudokuAnalytics.playFriendly.chooseContextBy.FRIENDLY_RANDOM, false);
                        reject(reason);
                    });
                })
                .catch(function() {
                    SudokuAnalytics.reportChooseContextBy(SudokuAnalytics.playFriendly.chooseContextBy.FRIENDLY_RANDOM, false);
                    reject();
                });
            });
};

PlayFriendlyController._getRandomConnectedFriend = function() {

    return new Promise(function (resolve, reject) {
        messagingPlatformService.getConnectedFriends()
            .then(function(connectedFriends) {

                ArrayUtil.shuffle(connectedFriends);

                for (var i = 0; i < connectedFriends.length; i++) { 
                    if(!PlayFriendlyController._isAlreadyPlayedTodayWithOpponent(connectedFriends[i].id)) {
                        resolve(connectedFriends[i].id);
                        return;
                    }
                }

                reject();
            })
            .catch(function(reason) {
                errorLoggingService.sendError(reason);
                console.error("[PlayFriendlyController] Ran into an error. ->", reason);
                reject(reason);
            });
        });
}

PlayFriendlyController._isContextAGroup = function() {
    var fbInstance = messagingPlatformService.getFBInstant();

    return !fbInstance.context.isSizeBetween(1, 2).answer;
};

PlayFriendlyController._startMatchByPlayerChoosing = function() {
    var self = this;
    return new Promise(function (resolve, reject) {
        messagingPlatformService.selectContext()
            .then(function (context) {

                if(self._isContextAGroup()) {
                    return resolve(self._startMatchByPlayerChoosing());
                }

                SudokuAnalytics.reportChooseContextBy(SudokuAnalytics.playFriendly.chooseContextBy.FRIENDLY_CHOOSE, true);
                SudokuAnalytics.reportPlayFriendlyUXEvent(SudokuAnalytics.playFriendly.uxEvents.FRIENDLY_CHOOSE_ACCEPT);

                resolve(context);
            })
            .catch(function (reason) {

                SudokuAnalytics.reportChooseContextBy(SudokuAnalytics.playFriendly.chooseContextBy.FRIENDLY_CHOOSE, false);

                if(reason.code === "SAME_CONTEXT") {
                    reject(reason);
                    return;
                }

                if (reason.code === "USER_INPUT") {

                    SudokuAnalytics.reportPlayFriendlyUXEvent(SudokuAnalytics.playFriendly.uxEvents.FRIENDLY_CHOOSE_CANCEL);

                    reject(reason);
                    return;
                }

                errorLoggingService.sendError(reason);
                console.error("[PlayFriendlyController] Ran into an error. ->", reason);
                reject(reason);
            });
    });
};

PlayFriendlyController._checkEntryPoint = function() {
    return new Promise(function(resolve, reject){
        messagingPlatformService.getEntryPointData()
            .then(function(entryData) {

                var data = entryData.data;

                if(!PlayFriendlyController._isPlayerInvitedByFriend(entryData)){
                    resolve();
                    return;
                }

                var matchData = new PlayFriendlyMatchData(data);

                PlayFriendlyController._setMatchData(matchData);

                resolve();
            })
            .catch(function (err) {
                errorLoggingService.sendError(err);
                console.error("[PlayFriendlyController] Ran into an error. ->", err);

                reject();
        });
    });
};

PlayFriendlyController._scheduleInvite = function() {

    var template = "play_friendly_invite";
    var strategy = GameUpdateStrategy.LAST;
    var payload = {
        analytics: ["custom_update", "play_friendly_invite"]
    }

    InviteService.sendUpdate(template, strategy, payload)
        .then(function() {
            console.log("[PlayFriendlyController] Game update invite sent");
        });
};

PlayFriendlyController._showMatchAlreadyPlayedWarning = function() {

    var analyticsScreen = SudokuAnalytics.playFriendly.screens.COMPLETED_CHALLENGE_POPUP;

    new tgfDialogs.PlayFriendlyWarningDialog({
        contentTopDictionaryKey: "popup_chal_done_description",
        contentBottomDictionaryKey: "popup_chal_done_subtext",
        buttonDictionaryKey: "popup_chal_done_cta",
        analyticsScreen: analyticsScreen,
        onClose: function() {
            SudokuAnalytics.reportPlayFriendlyUXEvent(SudokuAnalytics.playFriendly.uxEvents.BUTTON_CLOSE, analyticsScreen);
        }
    }).show();
};

PlayFriendlyController._showPlayerAlreadyInvitedOpponentWarning = function() {

    var analyticsScreen = SudokuAnalytics.playFriendly.screens.PLAYED_FRIEND_POPUP;

    var dialog = new tgfDialogs.PlayFriendlyWarningDialog({
        contentTopDictionaryKey: "cng_nogo_friend_header",
        contentBottomDictionaryKey: "cng_nogo_friend_description",
        buttonDictionaryKey: "cng_nogo_friend_cta",
        analyticsScreen: analyticsScreen,
        onClose: function() {
            SudokuAnalytics.reportPlayFriendlyUXEvent(SudokuAnalytics.playFriendly.uxEvents.BUTTON_CLOSE, analyticsScreen);
        }
    });

    dialog.show();
};

PlayFriendlyController._isPlayerInvitedByFriend = function(entryData) {
    if (!entryData) {
        return false;
    }

    if (!entryData.data) {
        return false;
    }

    return entryData.data.isFriendlyMatch;
};

PlayFriendlyController._isMatchAlreadyPlayed = function(matchData) {
    for (var i = 0; i < gameData.playFriendlyData.playedMatches.length; i++) { 
        if(gameData.playFriendlyData.playedMatches[i] === matchData.getUnixTimeStamp()) {
            return true;
        }
    }

    return false;
};

PlayFriendlyController._cleanupCreatedMatchesData = function() {

    var now = TimeManager.getDate();

    var createdMatchesToday = [];

    for (var i = 0; i < gameData.playFriendlyData.createdMatchesToday.length; i++) { 
        if(DateUtil.isSameDay(now, new Date(gameData.playFriendlyData.createdMatchesToday[i].unixTimeStamp))) {
            createdMatchesToday.push(gameData.playFriendlyData.createdMatchesToday[i]);
        }
    }

    gameData.playFriendlyData.createdMatchesToday = createdMatchesToday;
    saveDataService.savePlayerData(gameData.getSaveableGameData());
};

PlayFriendlyController._saveMatchAsPlayed = function(matchData) {

    gameData.playFriendlyData.playedMatches.push(matchData.getUnixTimeStamp());

    saveDataService.savePlayerData(gameData.getSaveableGameData());
};

PlayFriendlyController._saveMatchIsCreatedToday = function(matchData) {

    gameData.playFriendlyData.createdMatchesToday.push(matchData.getData());

    saveDataService.savePlayerData(gameData.getSaveableGameData());
};

PlayFriendlyController._isAlreadyPlayedTodayWithOpponent = function(opponentId) {

    var now = TimeManager.getDate();

    for (var i = 0; i < gameData.playFriendlyData.createdMatchesToday.length; i++) { 

        for (var j = 0; j < gameData.playFriendlyData.createdMatchesToday[i].players.length; j++) { 
            if(gameData.playFriendlyData.createdMatchesToday[i].players[j].id !== opponentId) {
                continue;
            }

            if(DateUtil.isSameDay(now, new Date(gameData.playFriendlyData.createdMatchesToday[i].unixTimeStamp))) {
                return true;
            }
        }
    }

    return false;
};

PlayFriendlyController._isContextAlreadyPlayedToday = function(contextId) {

    var now = TimeManager.getDate();

    for (var i = 0; i < gameData.playFriendlyData.createdMatchesToday.length; i++) { 
        if(contextId !== gameData.playFriendlyData.createdMatchesToday[i].contextId) {
            continue;
        }

        if(DateUtil.isSameDay(now, new Date(gameData.playFriendlyData.createdMatchesToday[i].unixTimeStamp))) {
            return true;
        }
    }

    return false;
};
