var PlayFriendlyGameUpdateService = {};

PlayFriendlyGameUpdateService._sendUpdate = function(matchData, customUpdateType, opponentProfilePicture, opponentRank, strategy) {
    return new Promise(function(resolve, reject) {
        new tgfDialogs.PlayFriendlyGameUpdate({
            customUpdate: customUpdateType,
            opponentProfilePicture: opponentProfilePicture,
            opponentRank: opponentRank,
            opponentsTime: matchData.getOpponentsTime(),
            opponentsScore: matchData.getOpponentsScore(),
            matchData: matchData,
            callback: function(dataURL) {

                var message = customUpdateType === PlayFriendlyController.customUpdateTypes.NEW_INVITE ?
                    SudokuAnalytics.playFriendly.message.FRIENDLY_INVITE : 
                    SudokuAnalytics.playFriendly.message.FRIENDLY_RESULT;

                var payload = matchData.getData();

                payload.analytics = [
                    SudokuAnalytics.playFriendly.messageType.CUSTOM_UPDATE,
                    message
                ]

                var gameUpdate = {
                    strategy: strategy || GameUpdateStrategy.IMMEDIATE,
                    payload: payload
                }
            
                if(customUpdateType === PlayFriendlyController.customUpdateTypes.NEW_INVITE) {
                    gameUpdate.text = StringUtil.format(tgfDictionary.getText("cu_friendly_invite_description"), messagingPlatformService.getPlayer().name);
                    gameUpdate.buttonText = tgfDictionary.getText("cu_friendly_invite_cta");
                    gameUpdate.image = dataURL;
                    gameUpdate.template = "friendly_match_new_invite";
                }
            
                if(customUpdateType === PlayFriendlyController.customUpdateTypes.GAME_END) {
                    gameUpdate.text = tgfDictionary.getText("cu_friendly_result_description");
                    gameUpdate.buttonText = tgfDictionary.getText("cu_friendly_result_cta");
                    gameUpdate.image = dataURL;
                    gameUpdate.template = "friendly_match_game_end";
                }
    
                messagingPlatformService.sendGameUpdate(gameUpdate)
                    .then(function () {

                        SudokuAnalytics.reportPlayFriendlyFBMessage(SudokuAnalytics.playFriendly.messageType.CUSTOM_UPDATE, message);

                        resolve();
                    })
                    .catch(function (err) {
                        errorLoggingService.sendError(err);
                        console.log("[InviteService] There was a problem sending the game update. Error: " + err + "\n" + err.stack);
                        reject();
                    });
            }
        }).show();
    });
};

PlayFriendlyGameUpdateService._sendShare = function(matchData, customUpdateType, opponentProfilePicture, opponentRank) {
    return new Promise(function(resolve, reject) {
        new tgfDialogs.PlayFriendlyGameUpdate({
            customUpdate: customUpdateType,
            opponentProfilePicture: opponentProfilePicture,
            opponentRank: opponentRank,
            opponentsTime: matchData.getOpponentsTime(),
            opponentsScore: matchData.getOpponentsScore(),
            matchData: matchData,
            callback: function(dataURL) {

                var message = customUpdateType === PlayFriendlyController.customUpdateTypes.NEW_INVITE ?
                    SudokuAnalytics.playFriendly.message.FRIENDLY_INVITE : 
                    SudokuAnalytics.playFriendly.message.FRIENDLY_RESULT;

                var payload = matchData.getData();

                payload.analytics = [
                    SudokuAnalytics.playFriendly.messageType.CUSTOM_SHARE,
                    message,
                ];

                var gameShare = {
                    payload: payload,
                    text: StringUtil.format(tgfDictionary.getText("cu_friendly_invite_description"), messagingPlatformService.getPlayer().name),
                    image: dataURL
                }
                    
                messagingPlatformService.shareContent(gameShare)
                    .then(function () {

                        SudokuAnalytics.reportPlayFriendlyFBMessage(SudokuAnalytics.playFriendly.messageType.CUSTOM_SHARE, message);

                        resolve();
                    })
                    .catch(function (err) {
                        errorLoggingService.sendError(err);
                        console.log("[InviteService] There was a problem sending the game update. Error: " + err + "\n" + err.stack);
                        reject();
                    });
            }
        }).show();
    });
};

PlayFriendlyGameUpdateService.sendShare = function(matchData) {

    if(!messagingPlatformService.isFeatureSupported(MessagingPlatformFeature.SHARE_CONTENT)) {
        return Promise.resolve();
    }

    var newMatchData = matchData.duplicateWithoutContext();

    var customUpdateType = PlayFriendlyController.customUpdateTypes.NEW_INVITE;

    var opponentId = matchData.getOpponentId();

    return new Promise(function(resolve, reject) {
        LeaderboardManager.getConnectedPlayerDataById(opponentId)
            .then(function(playerData) {
                PlayFriendlyGameUpdateService._sendShare(newMatchData, customUpdateType, playerData.getProfilePicture(true), playerData.getRank())
                    .then(function(){
                        resolve();
                    })
                    .catch(function() {
                        reject();
                    })
            })
            .catch(function() {
                PlayFriendlyGameUpdateService._sendShare(newMatchData, customUpdateType, null, null)
                    .then(function(){
                        resolve();
                    })
                    .catch(function() {
                        reject();
                    })
            });
    });
};

PlayFriendlyGameUpdateService.sendUpdate = function(matchData, customUpdateType, strategy) {

    if(!messagingPlatformService.isFeatureSupported(MessagingPlatformFeature.GAME_UPDATES)) {
        return Promise.resolve();
    }

    var opponentId = matchData.getOpponentId();

    if(!opponentId) {
        return PlayFriendlyGameUpdateService._sendUpdate(matchData, customUpdateType, null, null, strategy);
    }

    return new Promise(function(resolve, reject) {
        LeaderboardManager.getConnectedPlayerDataById(opponentId)
            .then(function(playerData) {
                PlayFriendlyGameUpdateService._sendUpdate(matchData, customUpdateType, playerData.getProfilePicture(true), playerData.getRank(), strategy)
                    .then(function(){
                        resolve();
                    })
                    .catch(function() {
                        reject();
                    })
            })
            .catch(function() {
                PlayFriendlyGameUpdateService._sendUpdate(matchData, customUpdateType, null, null, strategy)
                    .then(function(){
                        resolve();
                    })
                    .catch(function() {
                        reject();
                    })
            });
    });
}
