function PlayFriendlyMatchData(data) {
    this._data = data;
};

PlayFriendlyMatchData.turns = Object.freeze({
    PLAYER_TURN: "PLAYER_TURN",
    OPPONENT_TURN: "OPPONENT_TURN",
    GAME_FINISHED: "GAME_FINISHED"
});

PlayFriendlyMatchData.prototype.makeDummy = function(date, difficulty, isMatchOver) {
    //for testing purposes

    var playersInMatch = [];

    playersInMatch.push({
        id: messagingPlatformService.getPlayer().id,
        score: 1000,
        time: "13:37",
    });

    if(isMatchOver) {
        playersInMatch.push({
            id: "123456",
            score: 1200,
            time: "13:37",
        });
    }

    this._data = {
        contextId: "1",
        isFriendlyMatch: true,
        date: date.getTime(),
        difficulty: difficulty,
        unixTimeStamp: TimeManager.getDate().getTime(),
        players: playersInMatch,
    }

    return this;
};

PlayFriendlyMatchData.prototype.createWithoutContext = function(score, time, date, difficulty) {
    var playersInMatch = [];

    var playerData = {
        id: messagingPlatformService.getPlayer().id,
        score: score,
        time: time,
    }

    playersInMatch.push(playerData);

    this._data = {
        isFriendlyMatch: true,
        date: date.getTime(),
        difficulty: difficulty,
        unixTimeStamp: TimeManager.getDate().getTime(),
        players: playersInMatch,
        contextId: null
    }
};

PlayFriendlyMatchData.prototype.setContext = function(context) {
    var players = context.getPlayers();

    contextPlayers:
    for (var i = 0; i < players.length; i++) { 
        for (var j = 0; j < this._data.players.length; j++) { 
            if(this._data.players[j].id === players[i].id) {
                continue contextPlayers;
            } 
        }

        var playerData = {
            id: players[i].id,
            score: null,
            time: null,
        }

        this._data.players.push(playerData);

        this._data.contextId = context.getId();
    }
};

PlayFriendlyMatchData.prototype.hasContext = function() {
    return !!this._data.contextId;
};

PlayFriendlyMatchData.prototype.setUnixTimeStamp = function(unixTimeStamp) {
    this._data.unixTimeStamp = unixTimeStamp;
};

PlayFriendlyMatchData.prototype.duplicateWithoutContext = function() {

    var newMatch = new PlayFriendlyMatchData();

    var playersScore = 0;
    for(var i = 0; i < this._data.players.length; i++) {
        if(this._data.players[i].id === messagingPlatformService.getPlayer().id) {
            playersScore = this._data.players[i].score;
        }
    }

    newMatch.createWithoutContext(playersScore, 
        this.getPlayersTime(), 
        this.getDate(), 
        this.getDifficulty());

    newMatch.setUnixTimeStamp(this._data.unixTimeStamp);

    return newMatch;
};

PlayFriendlyMatchData.prototype.createWithContext = function(context, date, difficulty) {
    var players = context.getPlayers();
    var playersInMatch = [];

    for (var i = 0; i < players.length; i++) { 

        var playerData = {
            id: players[i].id,
            score: null,
            time: null,
        }

        playersInMatch.push(playerData);
    }

    this._data = {
        contextId: context.getId(),
        isFriendlyMatch: true,
        date: date.getTime(),
        difficulty: difficulty,
        unixTimeStamp: TimeManager.getDate().getTime(),
        players: playersInMatch,
    }
};

PlayFriendlyMatchData.prototype.hasOpponentWon = function() {
    if(this.getTurnOfMatch() !== PlayFriendlyMatchData.turns.GAME_FINISHED) {
        return false;
    }

    var playerScore = null;
    var opponentsScore = null;
    
    for(var i = 0; i < this._data.players.length; i++) {
        if(this._data.players[i].id === messagingPlatformService.getPlayer().id) {
            playerScore = this._data.players[i].score;
        }
        
        if(this._data.players[i].id !== messagingPlatformService.getPlayer().id) {
            opponentsScore = this._data.players[i].score;
        }
    }

    return playerScore < opponentsScore;
};

PlayFriendlyMatchData.prototype.hasPlayerWon = function() {

    if(this.getTurnOfMatch() !== PlayFriendlyMatchData.turns.GAME_FINISHED) {
        return false;
    }

    var playerScore = null;
    var opponentsScore = null;
    
    for(var i = 0; i < this._data.players.length; i++) {
        if(this._data.players[i].id === messagingPlatformService.getPlayer().id) {
            playerScore = this._data.players[i].score;
        }
        
        if(this._data.players[i].id !== messagingPlatformService.getPlayer().id) {
            opponentsScore = this._data.players[i].score;
        }
    }

    //Player wins with a draw
    return playerScore >= opponentsScore;
};

PlayFriendlyMatchData.prototype.hasOpponentData = function() {
    return this._data.players.length > 1;
};

PlayFriendlyMatchData.prototype.getUnixTimeStamp = function() {
    return this._data.unixTimeStamp;
};

PlayFriendlyMatchData.prototype.getData = function() {
    return this._data;
};

PlayFriendlyMatchData.prototype.getDifficulty = function() {
    return this._data.difficulty;
};

PlayFriendlyMatchData.prototype.getDate = function() {
    return new Date(this._data.date);
};

PlayFriendlyMatchData.prototype.getTurnOfMatch = function() {

    if(this.getPlayersTime() === null) {
        return PlayFriendlyMatchData.turns.PLAYER_TURN;
    }

    if(this.getOpponentsTime() === null) {
        return PlayFriendlyMatchData.turns.OPPONENT_TURN;
    }

    return PlayFriendlyMatchData.turns.GAME_FINISHED;
};

PlayFriendlyMatchData.prototype.getOpponentId = function () {
    for(var i = 0; i < this._data.players.length; i++) {
        if(this._data.players[i].id === messagingPlatformService.getPlayer().id) {
            continue;
        }

        return this._data.players[i].id;
    }

    return null;
};

PlayFriendlyMatchData.prototype.getOpponentsTime = function () {

    for(var i = 0; i < this._data.players.length; i++) {
        if(this._data.players[i].id === messagingPlatformService.getPlayer().id) {
            continue;
        }

        if(!this._data.players[i].time) {
            return null;
        }

        return this._data.players[i].time;
    }

    return null;
};

PlayFriendlyMatchData.prototype.getOpponentsScore = function () {

    for(var i = 0; i < this._data.players.length; i++) {
        if(this._data.players[i].id === messagingPlatformService.getPlayer().id) {
            continue;
        }

        if(!this._data.players[i].score) {
            return null;
        }

        return StringUtil.thousandsSeparator(this._data.players[i].score.toString(), ",");
    }

    return null;
};

PlayFriendlyMatchData.prototype.getPlayersTime = function () {

    for(var i = 0; i < this._data.players.length; i++) {
        if(this._data.players[i].id !== messagingPlatformService.getPlayer().id) {
            continue;
        }

        if(!this._data.players[i].time) {
            return null;
        }

        return this._data.players[i].time;
    }

    return null;
};

PlayFriendlyMatchData.prototype.getPlayersScore = function () {

    for(var i = 0; i < this._data.players.length; i++) {
        if(this._data.players[i].id !== messagingPlatformService.getPlayer().id) {
            continue;
        }

        if(!this._data.players[i].score) {
            return null;
        }

        var score = StringUtil.thousandsSeparator(this._data.players[i].score.toString(), ",");

        //During a draw the player wins
        if(this.getTurnOfMatch() === PlayFriendlyMatchData.turns.GAME_FINISHED && 
            this.getOpponentsScore() === score) {
            return StringUtil.thousandsSeparator((this._data.players[i].score + 1).toString(), ",");
        }

        return score;
    }

    return null;
};

PlayFriendlyMatchData.prototype.setPlayersMatchData = function(score, time) {
    
    var player = messagingPlatformService.getPlayer();
    
    for(var i = 0; i < this._data.players.length; i++) {
        if(this._data.players[i].id === player.id) {
            this._data.players[i].score = score;
            this._data.players[i].time = time;
            return;
        }
    }

    this._data.players.push({
        id: player.id,
        score: score,
        time: time,
    });
};
