tgfDialogs.PlayFriendlyResultDialog.prototype._isLastDayOfCurrentMonth = function(date) {
    var puzzleDay = new Date(date.getFullYear(), date.getMonth(), date.getDate());
    var dayOfMonthTomorrow = new Date(puzzleDay.getTime() + (24 * 60 * 60 * 1000)).getDate();
    var isCurrentMonth = puzzleDay.getMonth() == TimeManager.getDate().getMonth();

    return dayOfMonthTomorrow === 1 && isCurrentMonth;
};

