var InviteService = {};

InviteService.sendUpdate = function(template, strategy, payload) {

    if(!messagingPlatformService.isFeatureSupported(MessagingPlatformFeature.GAME_UPDATES)) {
        return Promise.reject();
    }

    return new Promise(function (resolve, reject) {
        var shareScreen = new tgfDialogs.ShareScreenInvite({
            callback: function(dataURL) {
                var shareTextLocalizableContent = LocalizationUtil.getLocalizableContent("InviteMessage", [messagingPlatformService.getPlayer().name]);
                var buttonTextLocalizableContent = LocalizationUtil.getLocalizableContent("CustomUpdateButtonText");

                messagingPlatformService.sendGameUpdate({
                        text: shareTextLocalizableContent,
                        buttonText: buttonTextLocalizableContent,
                        image: dataURL,
                        template: template,
                        strategy: strategy,
                        payload: payload
                    })
                    .then(function () {
                        resolve();
                    })
                    .catch(function (err) {
                        errorLoggingService.sendError(err);
                        console.log("[InviteService] There was a problem sending the game update. Error: " + err + "\n" + err.stack);
                        reject();
                    });

                shareScreen = undefined;
            }
        });

        shareScreen.show();
    });
};

InviteService.share = function(payload) {

    var shareText = StringUtil.format(tgfDictionary.getText('InviteMessage'), messagingPlatformService.getPlayer().name);

    return new Promise(function (resolve, reject) {
        var shareScreen = new tgfDialogs.ShareScreenInvite({
            callback: function (dataURL) {
                messagingPlatformService.shareContent({
                        text: shareText,
                        image: dataURL,
                        payload: payload
                    })
                    .then(function () {
                        resolve();
                    })
                    .catch(function (err) {
                        errorLoggingService.sendError(err);
                        console.error("[InviteService] Invite failed. Error: " + err + "\n" + err.stack);
                        reject();
                    });
                
                shareScreen = undefined;
            }
        });
    
        shareScreen.show();
    });
};

