var WhatIsNewController = {};

WhatIsNewController.initialize = function () {
    this.AddEvents();

    return Promise.resolve();
};

WhatIsNewController.AddEvents = function() {
    EventSystem.Global.addEventListener(System_Event.SHOW_MAIN_MENU, this._showWhatIsNewDialog, this);
};

WhatIsNewController._getWhatIsNewSettings = function() {

    if(!tgfSettings.whatIsNewDialogs) {
        return null;
    }

    for (var i = 0; i < tgfSettings.whatIsNewDialogs.length; i++) {

/*        if(ABTestInstance.isFeatureSupported(tgfSettings.whatIsNewDialogs[i].feature)) {

            return tgfSettings.whatIsNewDialogs[i];
        }*/
    }

    return null;
};

WhatIsNewController._shouldShowWhatIsNewDialog = function(feature) {

    if(gameData.sessionPlayCount === 1) {
        gameData.shownWhatIsNewFeatures.push(feature);
        saveDataService.savePlayerData(gameData.getSaveableGameData());
        return false;
    }

    for (var i = 0; i < gameData.shownWhatIsNewFeatures.length; i++) {
        if(gameData.shownWhatIsNewFeatures[i] === feature) {
            return false;
        }
    }

    return true;
};

WhatIsNewController._showWhatIsNewDialog = function() {

    var whatIsNewSettings = WhatIsNewController._getWhatIsNewSettings();

    if(!whatIsNewSettings) {
        return;
    }

    if(!WhatIsNewController._shouldShowWhatIsNewDialog(whatIsNewSettings.feature)) {
        return;
    }

    new tgfDialogs.WhatIsNewDialog({
        dictionaryKeyTitle: whatIsNewSettings.dictionaryKeyTitle,
        dictionaryKeySubTitle: whatIsNewSettings.dictionaryKeySubTitle,
        dictionaryKeyContent: whatIsNewSettings.dictionaryKeyContent,
        dictionaryKeyButton: whatIsNewSettings.dictionaryKeyButton,
        image: whatIsNewSettings.image
    }).show();

    gameData.shownWhatIsNewFeatures.push(whatIsNewSettings.feature);
    saveDataService.savePlayerData(gameData.getSaveableGameData());
};
