var _CoolAnalytics = function() {
    "use strict";

    this._ids = {
        //Game initialize events
        Initialize_loading: "Initialize-loading",
        Initialize_finished: "Initialize-finished",
        Game_loading: "Game-loading",
        Game_finished: "Game-finished",

        //Level events

        level_LEVELNUMBER_start: "level-[levelnumber]-start",
        level_LEVELNUMBER_won_AMOUNT_OF_STARS: "level-[levelnumber]-won-[amount of stars]",
        level_LEVELNUMBER_lost: "level-[levelnumber]-lost",
        level_LEVELNUMBER_completeonce: "level-[levelnumber]-completeonce",
        level_LEVELNUMBER_restart: "level-[levelnumber]-restart",

        //First time play events

        firsttime_initialize: "firsttime-initialize",
        firsttime_menu: "firsttime-menu",
        firsttime_play: "firsttime-play",
        firsttime_level_LEVELNUMBER_start: "firsttime-level-[levelnumber]-start",
        firsttime_tutorial_TUTORIALNUMBER_step_STEP_NUMBER: "firsttime-tutorial[tutorialnumber]-step[step number]",
        firsttime_level_LEVELNUMBER_won_AMOUNT_OF_STARS: "firsttime-level-[levelnumber]-won-[amount of stars]",

        //Stage events

        stage_STAGENUMBER_start: "stage-[stagenumber]-start",
        stage_STAGENUMBER_won: "stage-[stagenumber]-won",
        stage_STAGENUMBER_lost: "stage-[stagenumber]-lost",
        stage_STAGENUMBER_completeonce: "stage-[stagenumber]-completeonce",
        stage_STAGENUMBER_restart: "stage-[stagenumber]-restart",

        //First stage events

        firsttime_stage_STAGENUMBER_start: "firsttime-stage-[stagenumber]-start",
        firsttime_stage_STAGENUMBER_won: "firsttime-stage-[stagenumber]-won",
        firsttime_stage_STAGENUMBER_lost: "firsttime-stage-[stagenumber]-lost",

        ///////****Freemium events****///////

        //Daily spin

        dailyspin_counter_reset_day_NUMBER_OF_DAY: "dailyspin_counter reset_day[number of day]",
        dailyspin_day_NUMBER_OF_DAY: "dailyspin_day[number of day]	",
        reward_REWARDNAME: "reward_[rewardname]",
        reward_no_reward: "reward_no reward",
        reward_spin_again: "reward_spin again",
        premiumspin_day_NUMBER_OF_DAY: "premiumspin_day[number of day]",
        premiumreward_REWARDNAME: "premiumreward_[rewardname]",


        //Booster purchases

        purchase_booster_BOOSTERNAME_LEVELNUMBER: "purchase_booster_[booster name]_[levelnumber]",
        use_booster_BOOSTERNAME_LEVELNUMBER: "use_booster_[booster name]_[levelnumber]",

        ///////****Rewarding video****///////

        //Buy-more-moves

        purchase_extramoves_LEVELNUMBER: "purchase_extramoves_[levelnumber]",

        //Opening gates

        purchase_gate_unlock_GATENUMBER: "purchase_gate unlock_[gate number]",

        //Remove ads

        purchase_adremoval: "purchase_adremoval"

    }

    this.stringCheckPolyFill();

};

_CoolAnalytics.prototype.sendAnalytics = function(id, arg){
    "use strict";

    if(id === undefined){
        console.log("ANALYTICS WARNING: No ID passed");
        return;
    }

    var finalId = this.createId(id, arg);

    console.log("ID SEND TO ANALYTICS: " + finalId);

    try {
        analytics["customEvent"](finalId);
    } catch(e) {
        console.log("error calling analytics.menu: " + e);
    }
};


_CoolAnalytics.prototype.createId = function(_id, _arg){
    "use strict";

    var labels = [],
        labelsToCheck = ["[levelnumber]", "[amount of stars]", "[tutorialnumber]", "[number of day]", "[rewardname]", "[booster name]", "[gate number]", "[stagenumber]"],
        endId = _id;

    for(var i = 0; i < labelsToCheck.length; i++){
        if(_id.includes(labelsToCheck[i])){
            labels.push(labelsToCheck[i]);
        }
    }

    if(Object.prototype.toString.call(_arg) === '[object Array]' && _arg.length === labels.length){

        for(var i = 0; i < labels.length; i++){
            endId = endId.replace(labels[i], _arg[i].toString());
        }
    } else if(_arg !== undefined && Object.prototype.toString.call(_arg) !== '[object Array]' && labels.length === 1) {
        endId = _id.replace(labels[0], _arg.toString());
    } else if(_arg === undefined && labels.length === 0) {
        //No change has to be made
        return endId;
    } else {
        console.log("ANALYTICS WARNING: Some arguments are not correct!");
    }

    return endId;
};

_CoolAnalytics.prototype.stringCheckPolyFill = function(){
    if (!String.prototype.includes) {
        String.prototype.includes = function(search, start) {
            'use strict';
            if (typeof start !== 'number') {
                start = 0;
            }

            if (start + search.length > this.length) {
                return false;
            } else {
                return this.indexOf(search, start) !== -1;
            }
        };
    }
};

var tgfCoolAnalytics = new _CoolAnalytics();
