tgfHooks.playEnd = function(didQuit){
	"use strict";
	try { 
		var points = tgfStatus.getGlobalData().sumMaxScore;//TG.controller.getTotalScoreAllLevels();
		community["submitScore"]({
			"score": points, // This is an int value
			"callback": function () {
				// Call method(s) in the game that should happen after the high score popup is closed, like showing advertisement.
				if(_standardAdsShow){                   
					try{
						tgfHooks.pauseAll();
						adSense["showAdvertising"]({"callback": tgfHooks.resumeAll});
						_standardAdsShow = false;
					} catch(e){
						console.log("error calling adSense.showAdvertising: " + e);
						tgfHooks.resumeAll();
					}
				}
			}
		});
		analytics["customEvent"]("score: " + points);
	}catch(e){ 
		console.log("error submitting highscore: " + points +", " + e); 
	} 
	
	if(didQuit) {
		//also show advertisement on level quit
		if(_standardAdsShow){           
			try{
				tgfHooks.pauseAll();
				adSense["showAdvertising"]({"callback": function(){tgfHooks.resumeAll();}});
				_standardAdsShow = false;
			}catch(e){
				console.log("error calling adSense.showAdvertising: " + e);
				tgfHooks.resumeAll();
			}    
		}
	}
};

tgfHooks.gameCompleted = function(levelData){
	"use strict";
	if(levelData["failed"]){
		try {
			analytics["customEvent"]("levelFailed",(levelData["level"]));
		} catch(e){ 
			console.log("error calling analytics.levelFailed: " + e); 
		} 
	}else{
		try {
			analytics["customEvent"]("level",(levelData["level"]));
		} catch(e){ 
			console.log("error calling analytics.level: " + e);
		}       
	}
	//trigger ad if ad has not yet been shown 
	//to support showing ad after level restart (where no level end screen is shown)
	if(_standardAdsShow){
		try{
			tgfHooks.pauseAll();
			adSense["showAdvertising"]({"callback": function(){tgfHooks.resumeAll(); tgfHooks.resumeFlow();}});
			_standardAdsShow = false;
			
		} catch(e){
			console.log("error calling adSense.showAdvertising: " + e);
			tgfHooks.resumeAll();
			tgfHooks.resumeFlow();
		}
	}else{
		tgfHooks.resumeFlow();
	}
};

tgfHooks.showAd = function(callback){
	"use strict";
	if(_standardAdsShow){
		try{
			tgfHooks.pauseAll();
			adSense["showAdvertising"]({"callback": function(){
				tgfHooks.resumeAll();
				if(callback){
					callback();
				}
			}});
			_standardAdsShow = false;
		}catch(e){
			console.log("error calling adSense.showAdvertising: " + e);
			tgfHooks.resumeAll();
			if(callback){
				callback();
			}
		}
	}else{
		if(callback){
			callback();
		}
	}
};

