tgfHooks.stageAnalytics = function(state, stagenumber){
	"use strict";
	switch(state){
		case "start":
			tgfCoolAnalytics.sendAnalytics(tgfCoolAnalytics._ids.stage_STAGENUMBER_start, stagenumber);
			if(!TG.hooks.checkingStorageKey(tgfCoolAnalytics._ids.firsttime_stage_STAGENUMBER_start + " " + stagenumber)){
				tgfCoolAnalytics.sendAnalytics(tgfCoolAnalytics._ids.firsttime_stage_STAGENUMBER_start, stagenumber);
				TG.hooks.saveStorageData(tgfCoolAnalytics._ids.firsttime_stage_STAGENUMBER_start + " " + stagenumber);
			}
			break;
		case "won":
			tgfCoolAnalytics.sendAnalytics(tgfCoolAnalytics._ids.stage_STAGENUMBER_won, stagenumber);
			if(!TG.hooks.checkingStorageKey(tgfCoolAnalytics._ids.firsttime_stage_STAGENUMBER_won + " " + stagenumber)){
				tgfCoolAnalytics.sendAnalytics(tgfCoolAnalytics._ids.firsttime_stage_STAGENUMBER_won, stagenumber);
				TG.hooks.saveStorageData(tgfCoolAnalytics._ids.firsttime_stage_STAGENUMBER_won + " " + stagenumber);
			}
			break;
		case "lost":
			tgfCoolAnalytics.sendAnalytics(tgfCoolAnalytics._ids.stage_STAGENUMBER_lost, stagenumber);
			if(!TG.hooks.checkingStorageKey(tgfCoolAnalytics._ids.firsttime_stage_STAGENUMBER_lost + " " + stagenumber)){
				tgfCoolAnalytics.sendAnalytics(tgfCoolAnalytics._ids.firsttime_stage_STAGENUMBER_lost, stagenumber);
				TG.hooks.saveStorageData(tgfCoolAnalytics._ids.firsttime_stage_STAGENUMBER_lost + " " + stagenumber);
			}
			break;
		case "complete":
			if(!TG.hooks.checkingStorageKey(tgfCoolAnalytics._ids.stage_STAGENUMBER_completeonce + " " + stagenumber)){
				tgfCoolAnalytics.sendAnalytics(tgfCoolAnalytics._ids.stage_STAGENUMBER_completeonce, stagenumber);
				TG.hooks.saveStorageData(tgfCoolAnalytics._ids.stage_STAGENUMBER_completeonce + " " + stagenumber);
			}
			break;
		case "restart":
			tgfCoolAnalytics.sendAnalytics(tgfCoolAnalytics._ids.stage_STAGENUMBER_restart, stagenumber);
			break;
	}
};


